        [System.IO.File]::WriteAllText((Join-Path $presets 'GameA.conf'),'valid')
        [System.IO.File]::WriteAllText((Join-Path $presets 'Unknown.conf'),'invalid-name')
        [System.IO.File]::WriteAllText((Join-Path $presets 'notes.txt'),'unrelated')
