        @{ Scenario = 'ExistingDataRecovery'; Installed = $true; Recover = $true; BackupFails = $false; Profiles = 6; Install = 0; DatabaseBackup = 1; SaveConfig = 2; Setup = 1; Configured = 6 }
        @{ Scenario = 'ExistingDatabaseBackupFailure'; Installed = $true; Recover = $false; BackupFails = $true; Profiles = 6; Install = 0; DatabaseBackup = 1; SaveConfig = 0; Setup = 0; Configured = 0 }
        @{ Scenario = 'FreshInstall'; Installed = $false; Recover = $false; BackupFails = $false; Profiles = 6; Install = 1; DatabaseBackup = 1; SaveConfig = 1; Setup = 1; Configured = 6 }
        @{ Scenario = 'Postgres83Compatibility'; Installed = $false; Recover = $false; BackupFails = $false; Profiles = 1; Install = 1; DatabaseBackup = 1; SaveConfig = 1; Setup = 1; Configured = 1 }
        @{ Scenario = 'TopLevelBranchReturns'; Installed = $true; Recover = $false; BackupFails = $false; Profiles = 2; Install = 0; DatabaseBackup = 1; SaveConfig = 1; Setup = 1; Configured = 2 }
