        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        Should -Invoke Get-PostgresReinitializePlansFromProfiles -Times 0
        Should -Invoke Reset-PostgresDatabaseFromBackup -Times 0
