        $result = Invoke-PostgresReinitializeChoice -FailureDiagnoses @([pscustomobject]@{ Database = 'GameDbA' }) `
            -UserProfilesDir $TestDrive -ConfigPath (Join-Path $TestDrive 'config.json') `
