        $state = [pscustomobject]@{
            ConfigPath='config.json'; ScriptPath='manager.ps1'; TpRoot='TP'; UserProfilesDir='Profiles'
            Operation='Recovery'; PasswordPlain='Verified-Password-123'; AttemptId=2
