        It "restores a claimed state and reports the exact field when the expected package path is wrong" {
            $statePath = New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir -Operation Recovery -PasswordPlain 'Wrong-Parent-Test-123'
            $wrongConfig = Join-Path $TestDrive 'different-config.json'
            Set-Content -LiteralPath $wrongConfig -Value '{}' -Encoding utf8
            try {
                $failureMessage = $null
                try {
                    Read-PostgresRecoveryState -StatePath $statePath -ExpectedConfigPath $wrongConfig -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir | Out-Null
                } catch { $failureMessage = [string]$_.Exception.Message }
                $failureMessage | Should -Match 'Reason \[PACKAGE_MISMATCH\]'
                $recordedConfig = [System.IO.Path]::GetFullPath($script:stateConfigPath)
                $currentConfig = [System.IO.Path]::GetFullPath($wrongConfig)
                $failureMessage | Should -Match ([regex]::Escape("ConfigPath recorded='$recordedConfig' current='$currentConfig'"))
                (Test-Path -LiteralPath $statePath -PathType Leaf) | Should -BeTrue
                (Test-Path -LiteralPath ($statePath + '.claim') -PathType Leaf) | Should -BeFalse
                (Test-Path -LiteralPath ($statePath + '.used') -PathType Leaf) | Should -BeFalse
            } finally {
                [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
            }
        }

        It "allows the original envelope once and rejects a copied envelope in the reverse permutation" {
            $secret = 'Reverse-Copy-Replay-789'
            $statePath = New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir -Operation Recovery -PasswordPlain $secret
            $copyPath = Join-Path (Split-Path -Parent $statePath) '.tpm-postgres-recovery-cccccccccccccccccccccccccccccccc.json'
            try {
                [IO.File]::Copy($statePath, $copyPath)
                $original = Read-PostgresRecoveryState -StatePath $statePath -ExpectedConfigPath $script:stateConfigPath -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir
                $original.PasswordPlain | Should -Be $secret
                { Read-PostgresRecoveryState -StatePath $copyPath -ExpectedConfigPath $script:stateConfigPath -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir } | Should -Throw
            } finally {
                Remove-Item -LiteralPath $copyPath -Force -ErrorAction SilentlyContinue
                [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
            }
        }

        It "rejects an expired envelope and leaves no claim or used marker behind" {
            $statePath = Join-Path (Join-Path $TestDrive 'RecoveryState') '.tpm-postgres-recovery-dddddddddddddddddddddddddddddddd.json'
            New-Item -ItemType Directory -Path (Split-Path -Parent $statePath) -Force | Out-Null
            [IO.File]::WriteAllText($statePath, '{"SchemaVersion":3,"Purpose":"TeknoParrotManager.PostgresRecovery","CipherText":"fake"}', (New-Object Text.UTF8Encoding $false))
            $proc = Get-Process -Id $PID
            $script:fakeExpiredPayload = [ordered]@{
                SchemaVersion = 3; Purpose = 'TeknoParrotManager.PostgresRecovery'; IssuanceId = 'dddddddddddddddddddddddddddddddd'; Operation = 'Recovery'; Nonce = 'eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee'; AttemptId = 1
                CreatedUtc = (Get-Date).ToUniversalTime().AddMinutes(-10).ToString('o'); ExpiresUtc = (Get-Date).ToUniversalTime().AddMinutes(-5).ToString('o')
                ParentPid = [int]$PID; ParentStartTicks = [int64]$proc.StartTime.ToUniversalTime().Ticks; ParentProcessPath = [string]$proc.Path; ParentProcessSha256 = (Get-FileHash -LiteralPath $proc.Path -Algorithm SHA256).Hash
                OriginUserSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value; MachineName = [Environment]::MachineName
                ScriptPath = [System.IO.Path]::GetFullPath($script:stateScriptPath); ScriptSha256 = (Get-FileHash -LiteralPath $script:stateScriptPath -Algorithm SHA256).Hash
                ConfigPath = [System.IO.Path]::GetFullPath($script:stateConfigPath); ConfigSha256 = (Get-FileHash -LiteralPath $script:stateConfigPath -Algorithm SHA256).Hash
                TpRoot = [System.IO.Path]::GetFullPath($script:stateTpRoot); UserProfilesDir = [System.IO.Path]::GetFullPath($script:stateUserProfilesDir); PasswordPlain = 'expired'; PasswordOriginEncrypted = 'encrypted'
            }
            Mock Unprotect-PostgresRecoveryEnvelope { $script:fakeExpiredPayload | ConvertTo-Json -Depth 6 }
            try {
                { Read-PostgresRecoveryState -StatePath $statePath -ExpectedConfigPath $script:stateConfigPath -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir } | Should -Throw
                (Test-Path -LiteralPath $statePath -PathType Leaf) | Should -BeTrue
                (Test-Path -LiteralPath ($statePath + '.claim') -PathType Leaf) | Should -BeFalse
                (Test-Path -LiteralPath ($statePath + '.used') -PathType Leaf) | Should -BeFalse
            } finally {
                Remove-Item -LiteralPath $statePath -Force -ErrorAction SilentlyContinue
            }
        }

        It "rejects and diagnoses a configuration hash mutation after issuance" {
            $statePath = New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir -Operation Recovery -PasswordPlain 'Hash-Test-123'
            $outer = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json
            $payload = Unprotect-PostgresRecoveryEnvelope -ProtectedText ([string]$outer.CipherText) | ConvertFrom-Json
            $recordedHash = [string]$payload.ConfigSha256
            try {
                Add-Content -LiteralPath $script:stateConfigPath -Value 'changed'
                $currentHash = (Get-FileHash -LiteralPath $script:stateConfigPath -Algorithm SHA256).Hash
                $failureMessage = $null
                try {
                    Read-PostgresRecoveryState -StatePath $statePath -ExpectedConfigPath $script:stateConfigPath -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir | Out-Null
                } catch { $failureMessage = [string]$_.Exception.Message }
                $failureMessage | Should -Match 'Reason \[PACKAGE_MISMATCH\]'
                $failureMessage | Should -Match ([regex]::Escape("ConfigSha256 recorded='$recordedHash' current='$currentHash'"))
            } finally {
                [void](Remove-PostgresRecoveryState -Path $statePath -ClaimPath ($statePath + '.claim'))
            }
        }
        It "rejects schema4 reinitialize state without a selection plan before issuance" {
            { New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath `
                -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir `
                -Operation Reinitialize -PasswordPlain 'Reinitialize-State-Secret' } |
                Should -Throw '*requires a verified selection plan*'
        }

        It "rejects schema4 reinitialize state with a missing selection hash before issuance" {
            $selection = ConvertTo-PostgresReinitializePlanJson -Plans @([pscustomobject]@{
                GameLabel = 'Game A'; ProfileName = 'GameA'; Database = 'GameDbA'; BackupFile = 'backup'; Encoding = 'UTF8'
            })
            { New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath `
                -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir `
                -Operation Reinitialize -PasswordPlain 'Reinitialize-State-Secret' `
                -SelectionPlanJson $selection -SelectionPlanHash '' } |
                Should -Throw '*requires a verified selection plan*'
        }

        It "rejects schema4 reinitialize state with a tampered selection hash before issuance" {
            $selection = ConvertTo-PostgresReinitializePlanJson -Plans @([pscustomobject]@{
                GameLabel = 'Game A'; ProfileName = 'GameA'; Database = 'GameDbA'; BackupFile = 'backup'; Encoding = 'UTF8'
            })
            { New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath `
                -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir `
                -Operation Reinitialize -PasswordPlain 'Reinitialize-State-Secret' `
                -SelectionPlanJson $selection -SelectionPlanHash ('0' * 64) } |
                Should -Throw '*selection hash is invalid*'
        }
        It "rejects schema4 resume state with missing selection or invalid selection hash" {
            $proc = Get-Process -Id $PID
            $makeState = {
                param([string]$SelectionPlanJson, [string]$SelectionPlanHash)
                $id = [guid]::NewGuid().ToString('N')
                $statePath = Join-Path (Join-Path $TestDrive 'RecoveryState') ('.tpm-postgres-recovery-{0}.json' -f $id)
                $now = (Get-Date).ToUniversalTime()
                $script:fakeResumePayload = [ordered]@{
                    SchemaVersion = 4; Purpose = 'TeknoParrotManager.PostgresRecovery'; IssuanceId = $id; Operation = 'Reinitialize'; Nonce = ([guid]::NewGuid().ToString('N')); AttemptId = 1
                    CreatedUtc = $now.AddMinutes(-1).ToString('o'); ExpiresUtc = $now.AddMinutes(4).ToString('o')
                    ParentPid = [int]$PID; ParentStartTicks = [int64]$proc.StartTime.ToUniversalTime().Ticks; ParentProcessPath = [string]$proc.Path; ParentProcessSha256 = (Get-FileHash -LiteralPath $proc.Path -Algorithm SHA256).Hash
                    OriginUserSid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value; MachineName = [Environment]::MachineName
                    ScriptPath = [System.IO.Path]::GetFullPath($script:stateScriptPath); ScriptSha256 = (Get-FileHash -LiteralPath $script:stateScriptPath -Algorithm SHA256).Hash
                    ConfigPath = [System.IO.Path]::GetFullPath($script:stateConfigPath); ConfigSha256 = (Get-FileHash -LiteralPath $script:stateConfigPath -Algorithm SHA256).Hash
                    TpRoot = [System.IO.Path]::GetFullPath($script:stateTpRoot); UserProfilesDir = [System.IO.Path]::GetFullPath($script:stateUserProfilesDir)
                    PasswordPlain = 'resume-secret'; PasswordOriginEncrypted = 'encrypted'; SelectionPlanJson = $SelectionPlanJson; SelectionPlanHash = $SelectionPlanHash
                }
                [void][IO.Directory]::CreateDirectory((Split-Path -Parent $statePath))
                [IO.File]::WriteAllText($statePath, '{"SchemaVersion":4,"Purpose":"TeknoParrotManager.PostgresRecovery","CipherText":"fake"}', (New-Object Text.UTF8Encoding $false))
                return $statePath
            }
            Mock Unprotect-PostgresRecoveryEnvelope { $script:fakeResumePayload | ConvertTo-Json -Depth 8 }
            $missingPath = & $makeState '' ''
            try {
                { Read-PostgresRecoveryState -StatePath $missingPath -ExpectedConfigPath $script:stateConfigPath -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir } | Should -Throw '*could not safely resume*'
                (Test-Path -LiteralPath $missingPath -PathType Leaf) | Should -BeTrue
            } finally {
                Remove-Item -LiteralPath $missingPath -Force -ErrorAction SilentlyContinue
            }
            $selection = ConvertTo-PostgresReinitializePlanJson -Plans @([pscustomobject]@{
                GameLabel = 'Game A'; ProfileName = 'GameA'; Database = 'GameDbA'; BackupFile = 'backup'; Encoding = 'UTF8'
            })
            $invalidHashPath = & $makeState $selection ('0' * 64)
            try {
                { Read-PostgresRecoveryState -StatePath $invalidHashPath -ExpectedConfigPath $script:stateConfigPath -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir } | Should -Throw '*could not safely resume*'
                (Test-Path -LiteralPath $invalidHashPath -PathType Leaf) | Should -BeTrue
            } finally {
                Remove-Item -LiteralPath $invalidHashPath -Force -ErrorAction SilentlyContinue
            }
        }
        It 'reports recovery-state discovery while selecting the matching later retry attempt' {
            $previousPath=$null
            $retryPath=$null
            try {
                $previousPath=New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir -Operation Recovery -PasswordPlain 'Previous-Retry-Secret' -AttemptId 2
                $retryPath=New-PostgresRecoveryState -ConfigPath $script:stateConfigPath -ScriptPath $script:stateScriptPath -TpRoot $script:stateTpRoot -UserProfilesDir $script:stateUserProfilesDir -Operation Recovery -PasswordPlain 'Next-Retry-Secret' -AttemptId 3
                $script:recoveryRetryDiscoveryProgress=New-Object System.Collections.Generic.List[object]
                Mock Write-TpmCompactExtractionProgress {
                    [void]$script:recoveryRetryDiscoveryProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
                }

                $selected=Find-PostgresRecoveryRetryState -PreviousStatePath $previousPath -ExpectedConfigPath $script:stateConfigPath -ExpectedScriptPath $script:stateScriptPath -ExpectedTpRoot $script:stateTpRoot -ExpectedUserProfilesDir $script:stateUserProfilesDir -ExpectedParentPid $PID -PreviousAttemptId 2

                $selected | Should -Be $retryPath
                (@($script:recoveryRetryDiscoveryProgress | Where-Object { -not $_.Complete } | ForEach-Object Current) -join ',') | Should -Be '0,1,2'
                @($script:recoveryRetryDiscoveryProgress | Where-Object { $_.Complete -and $_.Current -eq 2 -and $_.Total -eq 0 }).Count | Should -Be 1
            } finally {
                if ($previousPath) { [void](Remove-PostgresRecoveryState -Path $previousPath) }
                if ($retryPath) { [void](Remove-PostgresRecoveryState -Path $retryPath) }
            }
        }

    }
}

Describe "BepInEx authorized-root and transaction guards" {
    BeforeEach {
        Mock Write-Log {}
        Mock Write-Host {}
    }

    It "reports unknown and unsupported executable architectures separately and as actionable skips" {
        $approved = Join-Path $TestDrive 'ArchitectureApproved'
        $profiles = Join-Path $TestDrive 'ArchitectureProfiles'
        $unknownRoot = Join-Path $approved 'UnreadableGame'
        $unsupportedRoot = Join-Path $approved 'UnsupportedGame'
        New-Item -ItemType Directory -Path $unknownRoot,$unsupportedRoot,$profiles -Force | Out-Null
        $unknownExe = Join-Path $unknownRoot 'game.exe'
        $unsupportedExe = Join-Path $unsupportedRoot 'game.exe'
        [IO.File]::WriteAllBytes($unknownExe,(New-Object byte[] 0))
        $pe = New-Object byte[] 128
        $pe[0] = 0x4D; $pe[1] = 0x5A
        [Array]::Copy([BitConverter]::GetBytes([int]64),0,$pe,0x3C,4)
        $pe[64] = 0x50; $pe[65] = 0x45; $pe[66] = 0; $pe[67] = 0
        $pe[68] = 0x64; $pe[69] = 0xAA
        [IO.File]::WriteAllBytes($unsupportedExe,$pe)
        $unknownEscaped = [System.Security.SecurityElement]::Escape($unknownExe)
        $unsupportedEscaped = [System.Security.SecurityElement]::Escape($unsupportedExe)
        Set-Content -LiteralPath (Join-Path $profiles 'UNREADABLE.xml') -Value ("<GameProfile><GameName>Unreadable Game</GameName><GamePath>$unknownEscaped</GamePath></GameProfile>")
        Set-Content -LiteralPath (Join-Path $profiles 'UNSUPPORTED.xml') -Value ("<GameProfile><GameName>Unsupported Game</GameName><GamePath>$unsupportedEscaped</GamePath></GameProfile>")
        Mock Get-BepInExLatestRelease { throw 'release discovery must not run without a supported architecture' }
        Mock Read-HostSafe { throw 'the setup prompt must not run for unclassified architecture' }

        $unknown = Get-BepInExPeArchitectureEvidence -Path $unknownExe
        $unsupported = Get-BepInExPeArchitectureEvidence -Path $unsupportedExe
        $result = Invoke-BepInExUpdateCheck -UserProfilesDir $profiles -CacheDir (Join-Path $TestDrive 'ArchitectureCache') -ApprovedGamesRoot $approved

        $unknown.State | Should -Be 'UNKNOWN'
        $unsupported.State | Should -Be 'UNSUPPORTED'
        $result.Outcome | Should -Be 'ACTION_REQUIRED'
        $result.Skipped | Should -Be 2
        $result.UnknownArchitecture | Should -Be 1
        $result.UnsupportedArchitecture | Should -Be 1
        $result.ReasonCode | Should -Be 'ACTION_REQUIRED'
        $failureRecords = @($result.TechnicalDetails.FailureRecords)
        @($failureRecords | Where-Object { $_.ReasonKey -eq 'UNKNOWN_ARCHITECTURE' }).Count | Should -Be 1
        @($failureRecords | Where-Object { $_.ReasonKey -eq 'UNSUPPORTED_ARCHITECTURE' }).Count | Should -Be 1
        @($failureRecords | Where-Object { $_.GameLabel -eq 'Unreadable Game' }).Count | Should -Be 1
        @($failureRecords | Where-Object { $_.GameLabel -eq 'Unsupported Game' }).Count | Should -Be 1
        Should -Invoke Get-BepInExLatestRelease -Times 0 -Exactly
        Should -Invoke Read-HostSafe -Times 0 -Exactly
        { Assert-TpmTransactionResult -Result $result } | Should -Not -Throw
    }

    It "classifies unreadable architecture evidence as unknown rather than unsupported" {
        $classification = Get-BepInExInspectionFailure -ErrorRecord ([System.Exception]::new('PE header is incomplete')) -ArchitectureState 'UNKNOWN'
        $classification.Code | Should -Be 'UNKNOWN_ARCHITECTURE'
        $classification.Summary | Should -Match 'could not read'
        $classification.NextAction | Should -Match 'Verify the game executable'
    }
    It "attributes a release-query failure only to affected games and keeps other candidates unattempted" {
        $approved = Join-Path $TestDrive 'ReleaseApproved'
        $outside = Join-Path $TestDrive 'ReleaseOutside'
        $profiles = Join-Path $TestDrive 'ReleaseProfiles'
        $x64Root = Join-Path $approved 'X64Game'
        $x86Root = Join-Path $approved 'X86Game'
        $unknownRoot = Join-Path $approved 'UnknownGame'
        $unsupportedRoot = Join-Path $approved 'UnsupportedGame'
        # The outside game gets a BepInEx folder: a game outside the Games folder with no BepInEx files is not part of the setup and is not counted.
        New-Item -ItemType Directory -Path $x64Root,$x86Root,$unknownRoot,$unsupportedRoot,$outside,$profiles,(Join-Path $outside 'BepInEx') -Force | Out-Null
        $x64Exe = Join-Path $x64Root 'game.exe'
        $x86Exe = Join-Path $x86Root 'game.exe'
        $unknownExe = Join-Path $unknownRoot 'game.exe'
        $unsupportedExe = Join-Path $unsupportedRoot 'game.exe'
        $outsideExe = Join-Path $outside 'game.exe'
        foreach ($path in @($x64Exe,$x86Exe,$unknownExe,$unsupportedExe,$outsideExe)) { Set-Content -LiteralPath $path -Value 'fixture' }
        foreach($entry in @(@('X64GAME','X64 Game',$x64Exe),@('X86GAME','X86 Game',$x86Exe),@('UNKNOWN','Unreadable Game',$unknownExe),@('UNSUPPORTED','Unsupported Game',$unsupportedExe),@('OUTSIDE','Outside Game',$outsideExe))) {
            $escaped=[System.Security.SecurityElement]::Escape([string]$entry[2])
            Set-Content -LiteralPath (Join-Path $profiles ($entry[0]+'.xml')) -Value ("<GameProfile><GameName>{0}</GameName><GamePath>{1}</GamePath></GameProfile>" -f $entry[1],$escaped)
        }
        Mock Get-BepInExPeArchitectureEvidence {
            param([string]$Path)
            if ([IO.Path]::GetFileName($Path) -eq 'winhttp.dll') { return [pscustomobject]@{ State='UNKNOWN'; Architecture=$null; Reason='No installed shim.' } }
            if ($Path -match 'X64Game') { return [pscustomobject]@{ State='SUPPORTED'; Architecture='x64'; Reason='supported fixture' } }
            if ($Path -match 'X86Game') { return [pscustomobject]@{ State='SUPPORTED'; Architecture='x86'; Reason='supported fixture' } }
            if ($Path -match 'UnsupportedGame') { return [pscustomobject]@{ State='UNSUPPORTED'; Architecture=$null; Reason='ARM64 machine type is not supported.' } }
            return [pscustomobject]@{ State='UNKNOWN'; Architecture=$null; Reason='PE architecture could not be read.' }
        }
        Mock Get-BepInExLatestRelease {
            if ($Architecture -eq 'x86') { return $null }
            return [pscustomobject]@{ Version='5.4.23'; DownloadUrl='https://example.invalid/bep.zip'; FileName='BepInEx_win_x64_5.4.23.zip'; SizeBytes=1; ExpectedSha256=$null }
        }
        Mock Invoke-TpmDownload { throw 'download must not run after a release-query failure' }

        $result=Invoke-BepInExUpdateCheck -UserProfilesDir $profiles -CacheDir (Join-Path $TestDrive 'ReleaseCache') -ApprovedGamesRoot $approved

        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        $result.Succeeded | Should -BeFalse
        $result.Errors | Should -Be 1
        $result.Skipped | Should -Be 3
        $result.Protected | Should -Be 1
        $result.UnsupportedArchitecture | Should -Be 1
        $result.UnknownArchitecture | Should -Be 1
        $result.MissingDevice | Should -Be 0
        $result.MissingPath | Should -Be 0
        (@($result.Items | Sort-Object) -join ',') | Should -Be 'OUTSIDE,UNKNOWN,UNSUPPORTED,X64GAME,X86GAME'
        @($result.Mutation.FailedItems) | Should -Be @('X86GAME')
        (@($result.Mutation.SkippedItems | Sort-Object) -join ',') | Should -Be 'OUTSIDE,UNKNOWN,UNSUPPORTED'
        @($result.Mutation.UnattemptedItems) | Should -Be @('X64GAME')
        @($result.Mutation.ChangedItems).Count | Should -Be 0
        @($result.Mutation.CompletedItems).Count | Should -Be 0
        $result.PathReasonCounts['RELEASE_QUERY_FAILED'] | Should -Be $null
        $result.PathReasonCounts['PROTECTED_OR_REPARSE_ROOT'] | Should -Be 1
        $result.PathReasonCounts['UNSUPPORTED_ARCHITECTURE'] | Should -Be 1
        $result.PathReasonCounts['UNKNOWN_ARCHITECTURE'] | Should -Be 1
        @($result.TechnicalDetails.FailureRecords | Where-Object { $_.GameLabel -eq 'X86 Game' -and $_.ReasonKey -eq 'RELEASE_QUERY_FAILED' }).Count | Should -Be 1
        @($result.TechnicalDetails.FailureRecords | Where-Object { $_.Game -eq 'OUTSIDE' -and $_.ReasonKey -eq 'PROTECTED_OR_REPARSE_ROOT' }).Count | Should -Be 1
        @($result.TechnicalDetails.FailureRecords | Where-Object { $_.Game -eq 'UNKNOWN' -and $_.ReasonKey -eq 'UNKNOWN_ARCHITECTURE' }).Count | Should -Be 1
        @($result.TechnicalDetails.FailureRecords | Where-Object { $_.Game -eq 'UNSUPPORTED' -and $_.ReasonKey -eq 'UNSUPPORTED_ARCHITECTURE' }).Count | Should -Be 1
        Should -Invoke Get-BepInExLatestRelease -Times 2
        Should -Invoke Invoke-TpmDownload -Times 0 -Exactly
        { Assert-TpmTransactionResult -Result $result } | Should -Not -Throw
    }
    It "accepts an existing BepInEx child path under the canonical game root" {
        $root = Join-Path $TestDrive 'ChildPathGame'
        New-Item -ItemType Directory -Path (Join-Path $root 'BepInEx\core') -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'BepInEx\core\0Harmony.dll') -Value 'dll'

        Test-BepInExNoReparsePath -Root $root -Path (Join-Path $root 'BepInEx\core\0Harmony.dll') | Should -BeTrue
        Test-PathInside -child (Join-Path $root 'BepInEx\core\0Harmony.dll') -parent $root | Should -BeTrue
    }

    It "classifies inspection failures without exposing generic failure-only output" {
        $classification = Get-BepInExInspectionFailure -ErrorRecord ([System.Exception]::new('unsupported architecture'))

        $classification.Code | Should -Be 'UNSUPPORTED_ARCHITECTURE'
        $classification.Summary | Should -Match 'architecture'
        $classification.NextAction | Should -Not -BeNullOrEmpty
        $classification.Technical | Should -Match 'unsupported architecture'

        $errorRecord = [System.Management.Automation.ErrorRecord]::new(
            [System.Exception]::new('unsupported architecture'),
            'UnsupportedArchitecture',
            [System.Management.Automation.ErrorCategory]::InvalidData,
            $null
        )
        $errorRecordClassification = Get-BepInExInspectionFailure -ErrorRecord $errorRecord
        $errorRecordClassification.Code | Should -Be 'UNSUPPORTED_ARCHITECTURE'
    }

    It "uses the full game name and visibly offers Back in the update prompt source" {
        $script:ProductionSource | Should -Match 'Get-BepInExGameLabel'
        $script:ProductionSource | Should -Match '\[B\] Back'
        $script:ProductionSource | Should -Match 'TeknoParrot Manager could not safely update BepInEx'
        $script:ProductionSource | Should -Not -Match 'Write-Host .*TPM could not safely update BepInEx'
    }

    It "reports compact progress while checking each BepInEx path before release query, prompt, or download" {
        $approved = Join-Path $TestDrive 'ApprovedGames'
        $outside = Join-Path $TestDrive 'OutsideGame'
        $profiles = Join-Path $TestDrive 'BepProfiles'
        New-Item -ItemType Directory -Path $approved, $outside, $profiles -Force | Out-Null
        $exe = Join-Path $outside 'game.exe'
        New-Item -ItemType File -Path $exe -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $profiles 'Outside.xml') -Value ("<GameProfile><GamePath>$exe</GamePath></GameProfile>")
        $script:bepPathProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:bepPathProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
        }
        Mock Get-BepInExLatestRelease { throw 'release query should not run' }
        Mock Read-HostSafe { 'N' }
        Mock Invoke-TpmDownload { throw 'download should not run' }
        $result = Invoke-BepInExUpdateCheck -UserProfilesDir $profiles -CacheDir (Join-Path $TestDrive 'BepCache') -ApprovedGamesRoot $approved
        $result.Reason | Should -Be 'NO_ELIGIBLE_GAMES'
        @($script:bepPathProgress | Where-Object { $_.Label -eq 'BepInEx path preflight' -and $_.Total -eq 1 -and $_.Current -eq 1 -and -not $_.Complete }).Count | Should -Be 1
        @($script:bepPathProgress | Where-Object { $_.Label -eq 'BepInEx path preflight' -and $_.Total -eq 1 -and $_.Complete }).Count | Should -Be 1
        @($script:bepPathProgress | Where-Object { $_.Label -eq 'BepInEx profile discovery' -and -not $_.Complete -and $_.Current -eq 1 -and $_.Total -eq 0 }).Count | Should -Be 1
        @($script:bepPathProgress | Where-Object { $_.Label -eq 'BepInEx profile discovery' -and $_.Complete -and $_.Current -eq 1 -and $_.Total -eq 0 }).Count | Should -Be 1
        Should -Invoke Get-BepInExLatestRelease -Times 0
        Should -Invoke Read-HostSafe -Times 0
        Should -Invoke Invoke-TpmDownload -Times 0
    }

    It "reports per-file BepInEx promotion progress and preserves promoted output" {
        $stage = Join-Path $TestDrive 'BepProgressStage'
        $dest = Join-Path $TestDrive 'BepProgressDest'
        New-Item -ItemType Directory -Path (Join-Path $stage 'BepInEx'), (Join-Path $dest 'BepInEx') -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $stage 'BepInEx\core.dll') -Value 'new-core'
        Set-Content -LiteralPath (Join-Path $stage 'winhttp.dll') -Value 'new-shim'
        Set-Content -LiteralPath (Join-Path $dest 'BepInEx\core.dll') -Value 'old-core'
        $script:bepPromoteProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:bepPromoteProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
        }

        $result = Invoke-TpmTransactionalTreePromote -StagingDir $stage -DestDir $dest -RelativeFiles @('BepInEx\core.dll', 'winhttp.dll')

        $result | Should -BeTrue
        (Get-Content -LiteralPath (Join-Path $dest 'BepInEx\core.dll') -Raw) | Should -Be ('new-core' + [Environment]::NewLine)
        (Get-Content -LiteralPath (Join-Path $dest 'winhttp.dll') -Raw) | Should -Be ('new-shim' + [Environment]::NewLine)
        @($script:bepPromoteProgress | Where-Object { $_.Label -eq 'BepInEx destination preflight' -and $_.Current -eq 2 -and $_.Total -eq 2 -and -not $_.Complete }).Count | Should -Be 1
        @($script:bepPromoteProgress | Where-Object { $_.Label -eq 'BepInEx file promotion' -and $_.Current -eq 2 -and $_.Total -eq 2 -and -not $_.Complete }).Count | Should -Be 1
        @($script:bepPromoteProgress | Where-Object { $_.Label -eq 'BepInEx file promotion' -and $_.Complete }).Count | Should -Be 1
    }

