    It "does not alter a live BepInEx file when backup verification fails" {
        $game = Join-Path $TestDrive 'BackupGame'
        New-Item -ItemType Directory -Path (Join-Path $game 'BepInEx') -Force | Out-Null
        $file = Join-Path $game 'BepInEx\core.dll'
        Set-Content -LiteralPath $file -Value 'original'
        # RC8 #366: backup verification is the inventory/byte comparison of the payload against the pre-copy source inventory
        # (the former Test-BepInExBackupEntry no longer exists). Present a payload that differs from the source so verification must
        # refuse; the directory R-oplock guards are not involved in this path.
        $script:bepBackupInventoryCalls = 0
        Mock Get-BepInExRecoveryInventory {
            $script:bepBackupInventoryCalls++
            [pscustomobject]@{ Items = @(); Streams = @{}; Guards = @(); GuardDetails = @(); InventoryHash = $(if ($script:bepBackupInventoryCalls -eq 1) { 'SOURCE-INVENTORY' } else { 'DIFFERENT-PAYLOAD-INVENTORY' }) }
        }
        Mock Copy-BepInExRecoveryInventory {}

        { New-BepInExUpdateBackup -GameRoot $game } | Should -Throw '*BepInEx backup failed; no reset was authorized*inventory/byte verification failed*'
        (Get-Content -LiteralPath $file -Raw) | Should -Be ('original' + [Environment]::NewLine)
        $evidence = @(Get-ChildItem -LiteralPath $game -Directory -Filter 'BepInEx_Backup_*' -ErrorAction SilentlyContinue)
        $evidence.Count | Should -Be 1
        # A failed verification must never leave an authorizing receipt behind.
        Test-Path -LiteralPath (Join-Path $evidence[0].FullName 'inventory.json') | Should -BeFalse
        Should -Invoke Get-BepInExRecoveryInventory -Times 2 -Exactly
    }
