    Context "post-promotion staging cleanup reporting" {
        BeforeEach {
            # Private TestDrive-owned TEMP: the staging paths below (fixed-name production stages included)
            # never land in the shared real TeknoParrotManagerStaging folder.
            $script:bepSavedTemp = $env:TEMP
            $env:TEMP = Join-Path $TestDrive ('own-temp-' + [guid]::NewGuid().ToString('N'))
            [void][System.IO.Directory]::CreateDirectory($env:TEMP)
            $script:bepApproved = Join-Path $TestDrive 'BepApproved'
            $script:bepGame = Join-Path $script:bepApproved 'CleanupGame'
            $script:bepProfiles = Join-Path $TestDrive 'BepCleanupProfiles'
            $script:bepCache = Join-Path $TestDrive 'BepCleanupCache'
            $script:bepStage = Join-Path (Join-Path $env:TEMP 'TeknoParrotManagerStaging') ('BepInEx-test-' + [guid]::NewGuid().ToString('N'))
            New-Item -ItemType Directory -Path $script:bepApproved, $script:bepGame, $script:bepProfiles -Force | Out-Null
            $gameExe = Join-Path $script:bepGame 'game.exe'
            New-Item -ItemType File -Path $gameExe -Force | Out-Null
            $safeGameExe = [System.Security.SecurityElement]::Escape($gameExe)
            Set-Content -LiteralPath (Join-Path $script:bepProfiles 'CLEANUPGAME.xml') -Value ("<GameProfile><GamePath>$safeGameExe</GamePath></GameProfile>")

            Mock Test-BepInExGameRootSafe { $true }
            Mock Test-BepInExNoReparsePath { $true }
            Mock Test-BepInExExistingTreeSafe { $true }
            Mock Get-BepInExPeArchitectureEvidence { [pscustomobject]@{ State='SUPPORTED'; Architecture='x64'; Reason='supported fixture' } }
            Mock Get-BepInExLatestRelease { [pscustomobject]@{ Version = '5.4.23'; DownloadUrl = 'https://github.com/BepInEx/BepInEx/releases/download/v5.4.23/BepInEx_win_x64_5.4.23.zip'; FileName = 'BepInEx_win_x64_5.4.23.zip'; SizeBytes = 1; ExpectedSha256 = $null } }
            Mock Get-BepInExInstalledVersion { '5.4.22' }
            Mock Get-BepInExInstalledArch { 'x64' }
            Mock Get-BepInExInstallationHealth { [pscustomobject]@{ Installed = $true; Complete = $true; Version = '5.4.22'; Architecture = 'x64'; Reason = 'Complete' } }
            Mock Read-HostSafe { 'Y' }
            Mock Invoke-TpmDownload {
                param([string]$DestinationPath)
                Set-Content -LiteralPath $DestinationPath -Value 'verified package' -NoNewline
                $true
            }
            Mock New-TpmStagingDirectory {
                New-Item -ItemType Directory -Path $script:bepStage -Force | Out-Null
                return $script:bepStage
            }
            Mock Expand-ZipFileSafe { $script:bepExpandedZipPath = [string]$ZipPath }
            Mock Get-BepInExStagedFiles { @('BepInEx\core.dll') }
            Mock New-BepInExUpdateBackup { $script:bepBackupRoot = [string]$GameRoot; Join-Path $script:bepGame 'BepInEx_Backup_test' }
            Mock Invoke-TpmTransactionalTreePromote { $true }
        }

        AfterEach {
            try {
                if ($script:bepStage -and (Test-Path -LiteralPath $script:bepStage)) {
                    [System.IO.Directory]::Delete($script:bepStage, $true)
                }
            }
            finally {
                $env:TEMP = $script:bepSavedTemp
            }
        }

        It "counts a promoted update only after controlled staging cleanup succeeds" {
            Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved
            $script:bepExpandedZipPath | Should -Be (Join-Path $script:bepCache 'BepInEx_win_x64_5.4.23.zip')
            $script:bepBackupRoot | Should -Be $script:bepGame

            Test-Path -LiteralPath $script:bepStage | Should -BeFalse
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match '^  Updated cleanly: 1 game\(s\)$' } -Times 1 -Exactly
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match 'Updated with cleanup failure' } -Times 0 -Exactly
            Should -Invoke Write-Log -ParameterFilter { [string]$msg -eq 'BepInEx update check: updatedCleanly=1 updatedWithCleanupFailure=0 skippedMissingDevice=0 skippedMissingPath=0 skippedProtected=0 skippedUnsupportedArchitecture=0 skippedUnknownArchitecture=0 errors=0 cleanupFailures=0' } -Times 1 -Exactly
        }

        It "reports action required and excludes a promoted update from the clean count when staging cleanup fails" {
            Mock Remove-BepInExStagingDirectory { throw "TPM BEPINEX STAGING CLEANUP FAILED for '$script:bepStage' -- residue remains at '$script:bepStage'." }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved
            $result.PSTypeNames | Should -Contain 'TPM.TransactionResult.v1'
            $result.Outcome | Should -Be 'CLEANUP_RESIDUE'
            $result.UnderlyingOutcome | Should -Be 'SUCCEEDED'
            $result.ProductState | Should -Be 'INTENDED'
            $result.Succeeded | Should -BeFalse
            $result.Mutation.Started | Should -BeTrue
            $result.Mutation.AffectedItemCount | Should -Be 1
            $result.Mutation.CompletedItemCount | Should -Be 1
            $result.FinalVerification.Attempted | Should -BeTrue
            $result.FinalVerification.Passed | Should -BeTrue
            $result.Cleanup.Attempted | Should -BeTrue
            $result.Cleanup.Completed | Should -BeFalse
            $result.Cleanup.ResiduePresent | Should -BeTrue
            $result.Cleanup.ResiduePaths | Should -Contain $script:bepStage
            $result.ChangedItems | Should -Contain 'CLEANUPGAME'

            Test-Path -LiteralPath $script:bepStage -PathType Container | Should -BeTrue
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match '^  Updated cleanly: 0 game\(s\)$' } -Times 1 -Exactly
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match '^  Updated with cleanup failure: 1 -- ACTION REQUIRED$' } -Times 1 -Exactly
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match 'preserved staging evidence before retrying' } -Times 1 -Exactly
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match [regex]::Escape($script:bepStage) } -Times 0 -Exactly
            Should -Invoke Write-Log -ParameterFilter { [string]$msg -match 'update applied.*staging cleanup failed' -and [string]$msg -match [regex]::Escape($script:bepStage) } -Times 1 -Exactly
            Should -Invoke Write-Log -ParameterFilter { [string]$msg -eq 'BepInEx update check: updatedCleanly=0 updatedWithCleanupFailure=1 skippedMissingDevice=0 skippedMissingPath=0 skippedProtected=0 skippedUnsupportedArchitecture=0 skippedUnknownArchitecture=0 errors=0 cleanupFailures=1' } -Times 1 -Exactly
        }
        It "does not offer repair-reset: R is not a choice, and nothing is downloaded or staged for it" {
            # Mutation: offer R (repair-reset) again in the install/update prompt -> the answer R is accepted, the package is downloaded and staged, and the game is refused only then.
            $script:bepChoicePrompts = New-Object System.Collections.Generic.List[string]
            $script:bepChoiceAnswers = New-Object System.Collections.Generic.Queue[string]
            foreach ($answer in @('R', 'B')) { $script:bepChoiceAnswers.Enqueue($answer) }
            Mock Read-HostSafe { [void]$script:bepChoicePrompts.Add([string]$Prompt); $script:bepChoiceAnswers.Dequeue() }
            Mock Invoke-TpmDownload { throw 'download must not run when no install was approved' }
            Mock Invoke-TpmTransactionalTreePromote { throw 'promotion must not run when no install was approved' }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved

            $result.Outcome | Should -Be 'NO_OP'
            $script:bepChoicePrompts.Count | Should -Be 2 -Because 'R is not a choice, so it is asked again until B is typed'
            $script:bepChoicePrompts[0] | Should -Match '\[Y\] Install/update'
            $script:bepChoicePrompts[0] | Should -Not -Match '(?i)repair|\[R\]'
            Should -Invoke Invoke-TpmDownload -Times 0 -Exactly
            Should -Invoke New-TpmStagingDirectory -Times 0 -Exactly
            Should -Invoke New-BepInExUpdateBackup -Times 0 -Exactly
            Should -Invoke Invoke-TpmTransactionalTreePromote -Times 0 -Exactly
        }
        It "lets the user take a game off the list before anything is installed" {
            # Mutation: install without asking, or ignore the removal -> a download starts for a game the user took off the list.
            $script:bepChoiceAnswers = New-Object System.Collections.Generic.Queue[string]
            foreach ($answer in @('E', '1')) { $script:bepChoiceAnswers.Enqueue($answer) }
            Mock Read-HostSafe { $script:bepChoiceAnswers.Dequeue() }
            Mock Invoke-TpmDownload { throw 'download must not run when the list is empty' }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved

            $result.Outcome | Should -Be 'NO_OP'
            @($result.PickedItems).Count | Should -Be 0
            Should -Invoke Invoke-TpmDownload -Times 0 -Exactly
            Should -Invoke Invoke-TpmTransactionalTreePromote -Times 0 -Exactly
        }
        It "leaves the installed BepInEx tree and unrelated game files unchanged when the install is declined" {
            [void][System.IO.Directory]::CreateDirectory((Join-Path $script:bepGame 'BepInEx\core'))
            [System.IO.File]::WriteAllText((Join-Path $script:bepGame 'BepInEx\core\one.dll'), 'one')
            [System.IO.File]::WriteAllText((Join-Path $script:bepGame 'winhttp.dll'), 'shim')
            [System.IO.File]::WriteAllText((Join-Path $script:bepGame 'unrelated.txt'), 'keep')
            $before = Get-TpmDirSnapshot -Dir $script:bepGame
            Mock Read-HostSafe { 'B' }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved

            $result.Outcome | Should -Be 'NO_OP'
            Assert-TpmDirSnapshotUnchanged -Before $before -After (Get-TpmDirSnapshot -Dir $script:bepGame)
            [System.IO.File]::ReadAllText((Join-Path $script:bepGame 'unrelated.txt')) | Should -Be 'keep'
            Should -Invoke New-BepInExUpdateBackup -Times 0 -Exactly
            Should -Invoke Invoke-TpmTransactionalTreePromote -Times 0 -Exactly
        }
        It "keeps transactional rollback failure ahead of device classification" {
            Mock Invoke-TpmTransactionalTreePromote { throw 'ROLLBACK FAILED: A device which does not exist was specified.' }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved

            $result.Succeeded | Should -BeFalse
            $result.Errors | Should -Be 1
            $result.MissingDevice | Should -Be 0
            $result.PathReasonCounts['ROLLBACK_FAILED'] | Should -Be 1
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match 'transaction rollback could not be verified' } -Times 1 -Exactly
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match 'update blocked:' } -Times 0 -Exactly
        }
        It "keeps cleanup failure ahead of device classification" {
            Mock Invoke-TpmTransactionalTreePromote { throw 'CLEANUP FAILED: staging path became unavailable on device' }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved

            $result.Succeeded | Should -BeFalse
            $result.Errors | Should -Be 1
            $result.MissingDevice | Should -Be 0
            $result.MissingPath | Should -Be 0
            $result.PathReasonCounts['DEVICE_UNAVAILABLE'] | Should -Be $null
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match 'cleanup was not completed' } -Times 1 -Exactly
            Should -Invoke Write-Host -ParameterFilter { [string]$Object -match 'game path became unavailable' } -Times 0 -Exactly
            Should -Invoke Write-Log -ParameterFilter { [string]$msg -match 'cleanupFailures=1' -and [string]$msg -match 'errors=0' } -Times 1 -Exactly
        }
        It "stops production candidate processing after the second same-cause rollback failure" {
            $roots = @('One', 'Two', 'Three') | ForEach-Object { Join-Path $script:bepApproved $_ }
            $codes = @('AAA', 'BBB', 'CCC')
            for ($i = 0; $i -lt $roots.Count; $i++) {
                New-Item -ItemType Directory -Path $roots[$i] -Force | Out-Null
                $exe = Join-Path $roots[$i] 'game.exe'
                New-Item -ItemType File -Path $exe -Force | Out-Null
                $escaped = [System.Security.SecurityElement]::Escape($exe)
                Set-Content -LiteralPath (Join-Path $script:bepProfiles ($codes[$i] + '.xml')) -Value ("<GameProfile><GamePath>$escaped</GamePath></GameProfile>")
            }
            $script:productionPromoteCalls = 0
            $script:productionStageNumber = 0
            Mock New-TpmStagingDirectory {
                $script:productionStageNumber++
                $path = Join-Path (Join-Path $env:TEMP 'TeknoParrotManagerStaging') ('BepInEx-production-' + $script:productionStageNumber)
                New-Item -ItemType Directory -Path $path -Force | Out-Null
                $path
            }
            Mock New-BepInExUpdateBackup {
                Join-Path $GameRoot ('BepInEx_Backup_' + [System.IO.Path]::GetFileName($GameRoot))
            }
            Mock Invoke-TpmTransactionalTreePromote {
                $script:productionPromoteCalls++
                if ($script:productionPromoteCalls -le 2) {
                    throw [System.IO.IOException]::new("TPM TRANSACTION ROLLBACK FAILED for '$DestDir'; evidence remains at '$StagingDir'.")
                }
            }
            # Repair-reset is not offered (FIX110 S-10), so the production batch-stop rule is exercised through the ordinary install/update choice.
            Mock Read-HostSafe { 'Y' }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved

            $script:productionPromoteCalls | Should -Be 2
            $result.BatchStopped | Should -BeTrue
            @($result.FailureRecords).Count | Should -Be 2
            $result.FailureRecords[0].GameRoot | Should -Not -Be $result.FailureRecords[1].GameRoot
            $result.FailureRecords[0].StagingPath | Should -Not -Be $result.FailureRecords[1].StagingPath
            $result.FailureRecords[0].BackupPath | Should -Not -Be $result.FailureRecords[1].BackupPath
            $result.FailureRecords[0].ReasonKey | Should -Be $result.FailureRecords[1].ReasonKey
            $result.FailureRecords[0].Exception | Should -Match 'One'
            $result.FailureRecords[1].Exception | Should -Match 'Two'
        }
        It "distinguishes a downloaded package from a failed per-game install" {
            $script:bepOutput = @()
            Mock Write-Host { $script:bepOutput += [string]$Object }
            Mock Invoke-TpmTransactionalTreePromote { throw 'simulated install failure at C:\technical\destination' }

            $result = Invoke-BepInExUpdateCheck -UserProfilesDir $script:bepProfiles -CacheDir $script:bepCache -ApprovedGamesRoot $script:bepApproved
            $output = $script:bepOutput -join [Environment]::NewLine

            $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
            $output | Should -Match 'verified BepInEx package was downloaded'
            $output | Should -Not -Match '(?i)C:\\|System\\.|StackTrace|technical'
            $output | Should -Not -Match 'update blocked:'
        }
    }
    It "uses actual selected, changed, failed, and skipped game IDs in the transaction" {
        Mock Invoke-BepInExUpdateCheckLegacy {
            [pscustomobject]@{
                Succeeded = $false
                Updated = 1
                UpdatedWithCleanupFailure = 0
                Errors = 1
                SelectedItems = @('SafeGame', 'BrokenGame', 'ProtectedGame')
                ChangedItems = @('SafeGame')
                FailedItems = @('BrokenGame')
                SkippedItems = @('ProtectedGame')
                FailureRecords = @([pscustomobject]@{ Game = 'BrokenGame'; ReasonKey = 'UPDATE_FAILED'; Exception = 'technical evidence' })
            }
        }

        $result = Invoke-BepInExUpdateCheck -UserProfilesDir (Join-Path $TestDrive 'unrelated-profiles') -CacheDir (Join-Path $TestDrive 'unused-cache')

        $result.Outcome | Should -Be 'PARTIAL_APPLIED'
        @($result.Items) | Should -Be @('SafeGame', 'BrokenGame', 'ProtectedGame')
        @($result.Mutation.ChangedItems) | Should -Be @('SafeGame')
        @($result.Mutation.FailedItems) | Should -Be @('BrokenGame')
        @($result.Mutation.SkippedItems) | Should -Be @('ProtectedGame')
        $result.TechnicalDetails.FailureRecords[0].Game | Should -Be 'BrokenGame'
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
    }
It "preserves accumulated item outcomes and skip totals on each package acquisition failure: <Failure>" -TestCases @(
        @{ Failure = 'unsafe release filename'; ExpectedReason = 'UNSAFE_RELEASE_FILENAME' }
        @{ Failure = 'download failure'; ExpectedReason = 'DOWNLOAD_FAILED' }
    ) {
        $approved = Join-Path $TestDrive 'AcquisitionApproved'
        $outside = Join-Path $TestDrive 'AcquisitionOutside'
        $profiles = Join-Path $TestDrive 'AcquisitionProfiles'
        $gamePaths = @{
            X64GAME = Join-Path (Join-Path $approved 'X64Game') 'game.exe'
            X86GAME = Join-Path (Join-Path $approved 'X86Game') 'game.exe'
            UNKNOWN = Join-Path (Join-Path $approved 'UnknownGame') 'game.exe'
            UNSUPPORTED = Join-Path (Join-Path $approved 'UnsupportedGame') 'game.exe'
            OUTSIDE = Join-Path $outside 'game.exe'
            MISSINGPATH = Join-Path (Join-Path $approved 'MissingPathGame') 'game.exe'
            MISSINGDEVICE = 'X:\BepInExMissingDevice\game.exe'
        }
        New-Item -ItemType Directory -Path $approved,$outside,$profiles -Force | Out-Null
        foreach ($entry in @(
            @{ Code='X64GAME'; Label='X64 Game' }
            @{ Code='X86GAME'; Label='X86 Game' }
            @{ Code='UNKNOWN'; Label='Unreadable Game' }
            @{ Code='UNSUPPORTED'; Label='ARM64 Game' }
            @{ Code='OUTSIDE'; Label='Protected Game' }
            @{ Code='MISSINGPATH'; Label='Missing Path Game' }
            @{ Code='MISSINGDEVICE'; Label='Missing Device Game' }
        )) {
            $path = [string]$gamePaths[$entry.Code]
            if ($entry.Code -notin @('MISSINGPATH','MISSINGDEVICE')) {
                [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path))
                Set-Content -LiteralPath $path -Value 'fixture'
            }
            $escaped = [System.Security.SecurityElement]::Escape($path)
            Set-Content -LiteralPath (Join-Path $profiles ($entry.Code + '.xml')) -Value ("<GameProfile><GameName>{0}</GameName><GamePath>{1}</GamePath></GameProfile>" -f $entry.Label,$escaped)
        }
        Mock Test-TpmGameMutationPath {
            param([string]$GamePath)
            if ($GamePath -eq $gamePaths.MISSINGDEVICE) { return [pscustomobject]@{ Valid=$false; ReasonCode='DEVICE_UNAVAILABLE'; Reason='fixture device unavailable'; ResolvedPath=$null; GameDirectory=$null } }
            if ($GamePath -eq $gamePaths.MISSINGPATH) { return [pscustomobject]@{ Valid=$false; ReasonCode='GAME_PATH_MISSING'; Reason='fixture path missing'; ResolvedPath=$null; GameDirectory=[System.IO.Path]::GetDirectoryName($GamePath) } }
            return [pscustomobject]@{ Valid=$true; ReasonCode=$null; Reason=$null; ResolvedPath=$GamePath; GameDirectory=[System.IO.Path]::GetDirectoryName($GamePath) }
        }
        Mock Test-BepInExGameRootSafe { param([string]$GameRoot,[string]$ApprovedRoot) return ($GameRoot -notlike '*AcquisitionOutside*') }
        Mock Test-BepInExNoReparsePath { param([string]$Root,[string]$Path) return $true }
        Mock Get-BepInExPeArchitectureEvidence {
            param([string]$Path)
            if ([System.IO.Path]::GetFileName($Path) -eq 'winhttp.dll') { return [pscustomobject]@{ State='UNKNOWN'; Architecture=$null; Reason='No installed shim.' } }
            if ($Path -match 'X64Game') { return [pscustomobject]@{ State='SUPPORTED'; Architecture='x64'; Reason='supported fixture' } }
            if ($Path -match 'X86Game') { return [pscustomobject]@{ State='SUPPORTED'; Architecture='x86'; Reason='supported fixture' } }
            if ($Path -match 'UnsupportedGame') { return [pscustomobject]@{ State='UNSUPPORTED'; Architecture=$null; Reason='ARM64 machine type is not supported.' } }
            return [pscustomobject]@{ State='UNKNOWN'; Architecture=$null; Reason='PE architecture could not be read.' }
        }
        Mock Get-BepInExLatestRelease {
            param([string]$Architecture)
            $fileName = if ($Architecture -eq 'x64' -and $Failure -eq 'unsafe release filename') { '..' } else { "BepInEx_win_{0}_5.4.23.zip" -f $Architecture }
            return [pscustomobject]@{ Version='5.4.23'; DownloadUrl='https://example.invalid/bep.zip'; FileName=$fileName; SizeBytes=1; ExpectedSha256=$null }
        }
        Mock Get-BepInExInstallationHealth { [pscustomobject]@{ Installed=$false; Complete=$false; Version=$null; Reason='not installed' } }
        Mock Read-TpmChoice { 'Y' }
        Mock Read-TpmMultiGameChoice { @(0, 1) }
        Mock Invoke-TpmDownload { return ($Failure -ne 'download failure') }

        $result = Invoke-BepInExUpdateCheck -UserProfilesDir $profiles -CacheDir (Join-Path $TestDrive 'AcquisitionCache') -ApprovedGamesRoot $approved

        $result.ReasonCode | Should -Be $ExpectedReason
        $result.Errors | Should -Be 1
        # The user picked only X64GAME and X86GAME. The other five games were not picked, so they are not counted, skipped or failed.
        $result.MissingDevice | Should -Be 0
        $result.MissingPath | Should -Be 0
        $result.Protected | Should -Be 0
        $result.Skipped | Should -Be 0
        $result.UnsupportedArchitecture | Should -Be 0
        $result.UnknownArchitecture | Should -Be 0
        (@($result.Items | Sort-Object) -join ',') | Should -Be 'X64GAME,X86GAME'
        @($result.Mutation.SkippedItems).Count | Should -Be 0
        @($result.Mutation.FailedItems) | Should -Be @('X64GAME')
        @($result.Mutation.UnattemptedItems) | Should -Be @('X86GAME')
        @($result.Mutation.ChangedItems).Count | Should -Be 0
        @($result.Mutation.CompletedItems).Count | Should -Be 0
        $result.PathReasonCounts.ContainsKey('DEVICE_UNAVAILABLE') | Should -BeFalse
        $result.PathReasonCounts.ContainsKey('UNKNOWN_ARCHITECTURE') | Should -BeFalse
        @($result.TechnicalDetails.FailureRecords | Where-Object { $_.Game -eq 'X64GAME' -and $_.ReasonKey -eq $ExpectedReason }).Count | Should -Be 1
        if ($Failure -eq 'unsafe release filename') { Should -Invoke Invoke-TpmDownload -Times 0 -Exactly }
        else { Should -Invoke Invoke-TpmDownload -Times 1 -Exactly }
        { Assert-TpmTransactionResult -Result $result } | Should -Not -Throw
    }
}
Describe "Read-PathWithBrowse" {
    # This is UI code (it can launch a real WinForms file/folder picker), which
    # is outside this project's stated Pester scope the same way other menu/UI
    # code already is -- these tests only cover the manual-entry passthrough
    # (mocking Read-Host, the one real cmdlet involved), never the actual
    # dialog-showing branch, which has no practical way to assert against in an
    # automated run without clicking through a real modal window.
    It "returns whatever was typed, unchanged, when the user does not type B" {
        Mock Read-Host { "C:\Some\Typed\Path" }
        Read-PathWithBrowse "Enter a path" | Should -Be "C:\Some\Typed\Path"
    }
    It "returns a typed path that merely starts with B instead of opening the browse dialog" {
        Mock Read-Host { "B:\SomeDrive" }
        # A typed path literally starting with the letter B must NOT be misread as
        # the browse trigger -- only an exact "B" (after Trim) should be.
        Read-PathWithBrowse "Enter a path" | Should -Be "B:\SomeDrive"
    }
    It "returns an empty string passthrough when the user presses Enter with nothing typed" {
        Mock Read-Host { "" }
        Read-PathWithBrowse "Enter a path" | Should -Be ""
    }
}

Describe "Get-ReShadeLatestVersion retry behavior" {
    BeforeAll {
        Mock Invoke-TpmWebRequestSilently {}
    }

    It "makes only a single attempt and returns null on failure -- no retry, unlike Invoke-TpmDownload's HttpClient/Invoke-WebRequest tiers" {
        Mock Invoke-TpmWebRequestSilently { throw "site unreachable" }
        $result = Get-ReShadeLatestVersion
        $result | Should -BeNullOrEmpty
        Should -Invoke Invoke-TpmWebRequestSilently -Times 1
    }
    It "parses the version out of a successful response" {
        Mock Invoke-TpmWebRequestSilently { [pscustomobject]@{ Content = "...ReShade_Setup_6.7.3.exe..." } }
        Get-ReShadeLatestVersion | Should -Be "6.7.3"
    }
    It "discovers ReShade 6.8.0 and builds the official plain installer URL" {
        Mock Invoke-TpmWebRequestSilently { [pscustomobject]@{ Content = "ReShade_Setup_6.8.0.exe" } }
        Get-ReShadeLatestVersion | Should -Be '6.8.0'
        Get-ReShadeSetupDownloadUrl -Version '6.8.0' | Should -Be 'https://reshade.me/downloads/ReShade_Setup_6.8.0.exe'
    }
    It "rejects Addon, lookalike-host, and malformed installer versions" {
        Get-ReShadeSetupDownloadUrl -Version '6.8.0-Addon' | Should -BeNullOrEmpty
        Get-ReShadeSetupDownloadUrl -Version '6.8.0.exe' | Should -BeNullOrEmpty
        Get-ReShadeSetupDownloadUrl -Version '6.8.0/../../evil' | Should -BeNullOrEmpty
    }
}
Describe "ReShade 6.8 architecture and direct extraction compatibility" {
    It "selects x86 and x64 from PE machine headers without mixing DLL identities" {
        $x86=Join-Path $TestDrive 'game-x86.exe'; $x64=Join-Path $TestDrive 'game-x64.exe'
        foreach ($case in @([pscustomobject]@{Path=$x86;Machine=0x014C;Expected='x86'},[pscustomobject]@{Path=$x64;Machine=0x8664;Expected='x64'})) {
            $bytes=New-Object byte[] 160; $bytes[0]=0x4D; $bytes[1]=0x5A; [Array]::Copy([BitConverter]::GetBytes([int32]0x80),0,$bytes,0x3C,4); $bytes[0x80]=0x50; $bytes[0x81]=0x45; [Array]::Copy([BitConverter]::GetBytes([uint16]$case.Machine),0,$bytes,0x84,2); [IO.File]::WriteAllBytes($case.Path,$bytes)
            Get-ExeArchitecture -ExePath $case.Path | Should -Be $case.Expected
        }
    }
}

