Describe "Expand-ManagerUpdateAsset and Test-ManagerUpdateExtractedScript" {
    BeforeAll {
        function New-CheckForUpdatesFixtureZip {
            param(
                [string]$EntryName = 'TeknoParrot-Manager.ps1',
                [string]$EntryContent = "# TeknoParrot Manager`n`$ScriptVersion = `"0.99.99`"`n"
            )
            $zipPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-menu-fixture-" + [guid]::NewGuid().ToString('N') + '.zip')
            $stagingDir = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-menu-staging-" + [guid]::NewGuid().ToString('N'))
            New-Item -ItemType Directory -Path $stagingDir -Force | Out-Null
            try {
                Set-Content -LiteralPath (Join-Path $stagingDir $EntryName) -Value $EntryContent -Encoding ascii -NoNewline
                [System.IO.Compression.ZipFile]::CreateFromDirectory($stagingDir, $zipPath)
            } finally {
                Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction SilentlyContinue
            }
            return $zipPath
        }
    }

    It "extracts the named entry and it passes content validation" {
        $zipPath = New-CheckForUpdatesFixtureZip
        $destPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-menu-extracted-" + [guid]::NewGuid().ToString('N') + '.ps1')
        try {
            Expand-ManagerUpdateAsset -ZipPath $zipPath -EntryName 'TeknoParrot-Manager.ps1' -DestinationPath $destPath
            Test-ManagerUpdateExtractedScript -Path $destPath | Should -BeTrue
        } finally {
            Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $destPath -Force -ErrorAction SilentlyContinue
        }
    }

    It "throws when the zip does not contain the expected entry" {
        $zipPath = New-CheckForUpdatesFixtureZip -EntryName 'SomethingElse.ps1'
        $destPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-menu-extracted-" + [guid]::NewGuid().ToString('N') + '.ps1')
        try {
            { Expand-ManagerUpdateAsset -ZipPath $zipPath -EntryName 'TeknoParrot-Manager.ps1' -DestinationPath $destPath } | Should -Throw
        } finally {
            Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
        }
    }

    It "rejects an extracted file that begins with a raw zip (PK) signature" {
        $path = Join-Path $TestDrive 'zipbytes.ps1'
        [System.IO.File]::WriteAllBytes($path, [byte[]](0x50, 0x4B, 0x03, 0x04, 0x00, 0x00))
        { Test-ManagerUpdateExtractedScript -Path $path } | Should -Throw '*zip signature*'
    }

    It "rejects a valid UTF-8 candidate containing non-ASCII source bytes" {
        $path = Join-Path $TestDrive 'non-ascii-candidate.ps1'
        $prefixText = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = "0.99.99"' + "`n" + '$decoy = "'
        $prefix = [System.Text.Encoding]::ASCII.GetBytes($prefixText)
        $suffix = [System.Text.Encoding]::ASCII.GetBytes('"' + "`n")
        $nonAscii = [System.Text.UTF8Encoding]::new($false).GetBytes([string][char]0x2014)
        [System.IO.File]::WriteAllBytes($path, [byte[]]($prefix + $nonAscii + $suffix))
        { Test-ManagerUpdateExtractedScript -Path $path } | Should -Throw '*non-ASCII bytes*'
    }


    It "rejects an extracted file missing the TeknoParrot Manager marker" {
        $path = Join-Path $TestDrive 'nomarker.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.99.99"' -Encoding ascii
        { Test-ManagerUpdateExtractedScript -Path $path } | Should -Throw '*TeknoParrot Manager*'
    }

    It "rejects an extracted file with no ScriptVersion assignment" {
        $path = Join-Path $TestDrive 'noversion.ps1'
        Set-Content -LiteralPath $path -Value '# TeknoParrot Manager' -Encoding ascii
        { Test-ManagerUpdateExtractedScript -Path $path } | Should -Throw '*ScriptVersion*'
    }
    It "[UVO-08] rejects a candidate with a cast-parenthesized scoped version overwrite" {
        $path = Join-Path $TestDrive 'cast-parenthesized-scoped-version-candidate.ps1'
        $content = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = "1.0"' + "`n" +
            '[string]($script:ScriptVersion) = "1.1"' + "`n" + '$ReleaseCandidateLabel = "RC8"'
        Set-Content -LiteralPath $path -Value $content -Encoding ascii

        { Test-ManagerUpdateExtractedScript -Path $path } | Should -Throw
    }
    It "[UVO-08] rejects an attributed scoped version overwrite in an extracted candidate" {
        $path = Join-Path $TestDrive 'attributed-scoped-version-candidate.ps1'
        $content = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = "1.0"' + "`n" +
            '[ValidateNotNull()]$script:ScriptVersion = "1.1"' + "`n" + '$ReleaseCandidateLabel = "RC8"'
        $tokens = $null
        $parseErrors = $null
        [System.Management.Automation.Language.Parser]::ParseInput($content, [ref]$tokens, [ref]$parseErrors) | Out-Null
        @($parseErrors).Count | Should -Be 0
        Set-Content -LiteralPath $path -Value $content -Encoding ascii

        { Test-ManagerUpdateExtractedScript -Path $path } | Should -Throw
    }
}

Describe "Invoke-CheckForUpdates" {
    BeforeAll {
        function New-CheckForUpdatesReleaseJson {
            param([string]$TagName = 'v0.99.99', [string]$AssetName = 'TeknoParrot.Manager.v0.99.99.BETA.zip')
            return (@{
                tag_name = $TagName
                name     = $TagName
                body     = 'Test release notes.'
                assets   = @(@{
                    name                  = $AssetName
                    browser_download_url = "https://github.com/Jumpstile/teknoparrot-manager/releases/download/$TagName/$AssetName"
                    size                  = 1
                    digest                = ('sha256:' + (Get-F35FixtureHash -Bytes ([Text.Encoding]::ASCII.GetBytes('metadata fixture'))))
                })
            } | ConvertTo-Json -Depth 5)
        }
    }

    It "offers RC8 to an installation running RC7" {
        $originalVersion = $ScriptVersion
        $originalLabel = $ReleaseCandidateLabel
        $originalDisplay = $DisplayVersion
        try {
            $ScriptVersion = '1.0'
            $ReleaseCandidateLabel = 'RC7'
            $DisplayVersion = 'v1.0 RC7'
            Mock Get-ManagerUpdateRelease {
                [pscustomobject]@{ TagName = 'v1.0-RC8'; Name = 'v1.0 RC8'; Body = 'Test notes.'; AssetName = 'x.zip'; DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0-RC8/x.zip'; SizeBytes = 1; Digest = ('sha256:' + (Get-F35FixtureHash -Bytes ([Text.Encoding]::ASCII.GetBytes('download-not-reached')))) }
            }
            Mock Read-Host { 'N' }

            $path = Join-Path $TestDrive 'rc7-current.ps1'
            Set-Content -LiteralPath $path -Value ('$ScriptVersion = "1.0"' + "`n" + '$ReleaseCandidateLabel = "RC7"') -Encoding ascii
            Get-ManagerDisplayVersion | Should -Be 'v1.0 RC7'
            $result = Invoke-CheckForUpdates -ScriptPath $path

            $result.ReasonCode | Should -Be 'UPDATE_DECLINED'
            Should -Invoke Read-Host -Times 1
        } finally {
            $ScriptVersion = $originalVersion
            $ReleaseCandidateLabel = $originalLabel
            $DisplayVersion = $originalDisplay
        }
    }

    It "returns a verified NO_OP without prompting when there is no newer release" {
        Mock Invoke-WebRequest { [pscustomobject]@{ Content = (New-CheckForUpdatesReleaseJson -TagName ("v{0}-{1}" -f $ScriptVersion, $ReleaseCandidateLabel)) } }

        Mock Read-Host { throw "Read-Host should not be called when already current" }

        $path = Join-Path $TestDrive 'current.ps1'
        Set-Content -LiteralPath $path -Value ("`$ScriptVersion = `"$ScriptVersion`"`n`$ReleaseCandidateLabel = `"$ReleaseCandidateLabel`"") -Encoding ascii

        $result = Invoke-CheckForUpdates -ScriptPath $path
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'NO_OP'
        $result.Succeeded | Should -BeTrue
    }

    It "returns a verified NO_OP and makes no changes when the user declines the update" {
        Mock Invoke-WebRequest { [pscustomobject]@{ Content = (New-CheckForUpdatesReleaseJson) } }
        Mock Read-Host { "N" }

        $path = Join-Path $TestDrive 'decline.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii
        $originalContent = Get-Content -LiteralPath $path -Raw

        $result = Invoke-CheckForUpdates -ScriptPath $path
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'NO_OP'
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
    }

    It "clears the target attribute only for the approved update transaction and restores it on failure" {
        $root = Join-Path $TestDrive ("readonlyroot-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii
        Set-ItemProperty -LiteralPath $path -Name IsReadOnly -Value $true
        # A single-script ZIP: the package check comes first, so only a package that passes it reaches the read-only change and the backup.
        Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue
        $zipStream = New-Object System.IO.MemoryStream
        $zipArchive = New-Object System.IO.Compression.ZipArchive($zipStream, [System.IO.Compression.ZipArchiveMode]::Create, $true)
        $zipEntryStream = $zipArchive.CreateEntry('TeknoParrot-Manager.ps1').Open()
        $zipEntryBytes = [Text.Encoding]::ASCII.GetBytes('verified download before backup failure')
        $zipEntryStream.Write($zipEntryBytes, 0, $zipEntryBytes.Length)
        $zipEntryStream.Dispose()
        $zipArchive.Dispose()
        $verifiedBytes = $zipStream.ToArray()
        $zipStream.Dispose()
        $script:f35ReadOnlyAtBackup = $null
        $script:f35ReadOnlyPath = $path
        $script:f35VerifiedBytes = $verifiedBytes
        Mock New-ManagerUpdateBackup {
            $script:f35ReadOnlyAtBackup = (Get-Item -LiteralPath $script:f35ReadOnlyPath -Force).IsReadOnly
            throw 'Simulated backup failure after the approved attribute change.'
        }
        Mock Invoke-TpmDownload {
            [IO.File]::WriteAllBytes($DestinationPath, $script:f35VerifiedBytes)
            return $true
        }
        try {
            $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release ([pscustomobject]@{ AssetName = 'x.zip'; DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v0.99.99/x.zip'; SizeBytes = $verifiedBytes.Length; TagName = 'v0.99.99'; Digest = ('sha256:' + (Get-F35FixtureHash -Bytes $verifiedBytes)) })
            (Test-TpmTransactionResult -Result $result) | Should -BeTrue
            $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
            (Get-Item -LiteralPath $path -Force).IsReadOnly | Should -BeTrue
            Should -Invoke New-ManagerUpdateBackup -Times 1 -Exactly
            $script:f35ReadOnlyAtBackup | Should -BeFalse
        } finally {
            Set-ItemProperty -LiteralPath $path -Name IsReadOnly -Value $false -ErrorAction SilentlyContinue
        }
    }
}

