Describe "Invoke-ManagerUpdateInstall" {
    BeforeAll {
        function New-StartupCheckFixtureZipBytes {
            param(
                [string]$EntryName = 'TeknoParrot-Manager.ps1',
                [string]$EntryContent = "# TeknoParrot Manager`n`$ScriptVersion = `"0.99.99`"`n"
            )
            $zipPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-startup-fixture-" + [guid]::NewGuid().ToString('N') + '.zip')
            $stagingDir = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-startup-staging-" + [guid]::NewGuid().ToString('N'))
            New-Item -ItemType Directory -Path $stagingDir -Force | Out-Null
            try {
                Set-Content -LiteralPath (Join-Path $stagingDir $EntryName) -Value $EntryContent -Encoding ascii -NoNewline
                [System.IO.Compression.ZipFile]::CreateFromDirectory($stagingDir, $zipPath)
                return , ([System.IO.File]::ReadAllBytes($zipPath))
            } finally {
                Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction SilentlyContinue
                Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
            }
        }

        function New-StartupCheckRelease {
            param([byte[]]$Bytes = ([Text.Encoding]::ASCII.GetBytes('download-not-reached')))
            [pscustomobject]@{
                TagName     = 'v0.99.99'
                Name        = 'v0.99.99 BETA'
                Body        = 'Test release notes.'
                AssetName   = 'TeknoParrot.Manager.v0.99.99.BETA.zip'
                DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v0.99.99/TeknoParrot.Manager.v0.99.99.BETA.zip'
                SizeBytes   = 1
                Digest      = ('sha256:' + (Get-F35FixtureHash -Bytes $Bytes))
            }
        }

        # Destructive-path fixture helpers -- mirrors
        # Tests/TpmAutoUpdate.DestructivePath.Tests.ps1's fixtures for the
        # standalone tools/TpmAutoUpdate.Core.psm1 module, so the in-script
        # Invoke-ManagerUpdateInstall gets the same failure-mode coverage as
        # that module already has (release-certification gap closed).
        function Get-DestructiveCorruptedEntryZipBytes {
            # Same technique as the standalone suite: a large, repetitive
            # (compressible) entry so Deflate is actually used, then flip bits
            # only within the compressed payload region so the central
            # directory / EOCD stay intact and only decompression fails.
            $entryContent = "# TeknoParrot Manager`n`$ScriptVersion = `"0.99.99`"`n" + (("X" * 200 + "`n") * 300)
            $zipBytes = New-StartupCheckFixtureZipBytes -EntryContent $entryContent
            $bytes = [byte[]]$zipBytes.Clone()

            $probeZipPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-destructive-probe-" + [guid]::NewGuid().ToString('N') + '.zip')
            [System.IO.File]::WriteAllBytes($probeZipPath, $bytes)
            try {
                $zip = [System.IO.Compression.ZipFile]::OpenRead($probeZipPath)
                $compressedLength = $zip.Entries[0].CompressedLength
                $zip.Dispose()
            } finally {
                Remove-Item -LiteralPath $probeZipPath -Force -ErrorAction SilentlyContinue
            }
            if ($compressedLength -eq $entryContent.Length) {
                throw 'Test fixture error: entry was stored rather than deflated -- corruption offsets would be wrong.'
            }

            $filenameLen = [System.BitConverter]::ToUInt16($bytes, 26)
            $extraLen = [System.BitConverter]::ToUInt16($bytes, 28)
            $dataStart = 30 + $filenameLen + $extraLen
            for ($i = $dataStart; $i -lt ($dataStart + $compressedLength); $i++) {
                $bytes[$i] = $bytes[$i] -bxor 0xFF
            }
            return , $bytes
        }
    }

    BeforeEach {
        # Private TEMP/TMP per test: the cleanup assertions below look at the temporary folder, so another run's files must never be in it.
        $script:updInstallSavedTemp = $env:TEMP
        $script:updInstallSavedTmp = $env:TMP
        $env:TEMP = Join-Path $TestDrive ('upd-own-temp-' + [guid]::NewGuid().ToString('N'))
        [void][System.IO.Directory]::CreateDirectory($env:TEMP)
        $env:TMP = $env:TEMP
    }

    AfterEach {
        $env:TEMP = $script:updInstallSavedTemp
        $env:TMP = $script:updInstallSavedTmp
    }

    It "rejects a candidate whose here-string spoofs its RC tag" {
        $entryContent = @'
# TeknoParrot Manager
$decoy = @"
$ScriptVersion = "1.0"
$ReleaseCandidateLabel = "RC8"
"@
$ScriptVersion = "1.0"
$ReleaseCandidateLabel = "RC7"
'@
        $zipBytes = New-StartupCheckFixtureZipBytes -EntryContent $entryContent
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()

        $path = Join-Path $TestDrive 'rc-here-string-spoof.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.99.99"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $release = [pscustomobject]@{
            TagName = 'v1.0-RC8'
            Name = 'v1.0 RC8'
            Body = 'Test release notes.'
            AssetName = 'TeknoParrot.Manager.v1.0.RC8.zip'
            DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0-RC8/TeknoParrot.Manager.v1.0.RC8.zip'
            SizeBytes = 1
            Digest = ('sha256:' + (Get-F35FixtureHash -Bytes $zipBytes))
        }

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release $release

        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        $result.ReasonCode | Should -Be 'UPDATE_VERSION_MISMATCH'
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
    }

    It "rejects a candidate RC label that does not match the approved release tag" {
        $entryContent = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = "1.0"' + "`n" + '$ReleaseCandidateLabel = "RC7"' + "`n"
        $zipBytes = New-StartupCheckFixtureZipBytes -EntryContent $entryContent
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()

        $path = Join-Path $TestDrive 'rc-candidate-mismatch.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.99.99"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $release = [pscustomobject]@{
            TagName = 'v1.0-RC8'
            Name = 'v1.0 RC8'
            Body = 'Test release notes.'
            AssetName = 'x.zip'
            DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0-RC8/x.zip'
            SizeBytes = 1
            Digest = ('sha256:' + (Get-F35FixtureHash -Bytes $zipBytes))
        }

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release $release

        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        $result.ReasonCode | Should -Be 'UPDATE_VERSION_MISMATCH'
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
    }
    It "[UVO-08] rejects cast-parenthesized scoped version writes before replacing the TPM script" {
        $entryContent = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = "1.0"' + "`n" +
            '[string]($script:ScriptVersion) = "1.1"' + "`n" + '$ReleaseCandidateLabel = "RC8"'
        $zipBytes = New-StartupCheckFixtureZipBytes -EntryContent $entryContent
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()

        $path = Join-Path $TestDrive 'typed-scoped-version-install.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.99.99"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $release = [pscustomobject]@{
            TagName = 'v1.0-RC8'
            Name = 'v1.0 RC8'
            Body = 'Test release notes.'
            AssetName = 'TeknoParrot.Manager.v1.0.RC8.zip'
            DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0-RC8/TeknoParrot.Manager.v1.0.RC8.zip'
            SizeBytes = 1
            Digest = ('sha256:' + (Get-F35FixtureHash -Bytes $zipBytes))
        }
        Mock Move-Item { throw 'Replacement must not run for an invalid candidate identity.' }

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release $release

        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        # The transaction result carries mutation state under .Mutation; the earlier top-level MutationStarted field never existed, so the old assertion tested $null.
        $result.Mutation.Started | Should -BeFalse
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
        Should -Invoke Move-Item -Times 0 -Exactly
    }
    It "[UVO-08] rejects an attributed scoped overwrite before replacing the TPM script" {
        $entryContent = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = "1.0"' + "`n" +
            '[ValidateNotNull()]$script:ScriptVersion = "1.1"' + "`n" + '$ReleaseCandidateLabel = "RC8"'
        $tokens = $null
        $parseErrors = $null
        [System.Management.Automation.Language.Parser]::ParseInput($entryContent, [ref]$tokens, [ref]$parseErrors) | Out-Null
        @($parseErrors).Count | Should -Be 0
        $zipBytes = New-StartupCheckFixtureZipBytes -EntryContent $entryContent
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()

        $path = Join-Path $TestDrive 'attributed-scoped-version-install.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.99.99"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $release = [pscustomobject]@{
            TagName = 'v1.0-RC8'
            Name = 'v1.0 RC8'
            Body = 'Test release notes.'
            AssetName = 'TeknoParrot.Manager.v1.0.RC8.zip'
            DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0-RC8/TeknoParrot.Manager.v1.0.RC8.zip'
            SizeBytes = 1
            Digest = ('sha256:' + (Get-F35FixtureHash -Bytes $zipBytes))
        }
        Mock Move-Item { throw 'Replacement must not run for an invalid candidate identity.' }

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release $release

        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        # The transaction result carries mutation state under .Mutation; the earlier top-level MutationStarted field never existed, so the old assertion tested $null.
        $result.Mutation.Started | Should -BeFalse
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
        Should -Invoke Move-Item -Times 0 -Exactly
    }
    It "installs an RC8 candidate and verifies the installed full version identity" {
        $entryContent = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = ''1.0''' + "`n" + '$ReleaseCandidateLabel = ''RC8''' + "`n"
        $zipBytes = New-StartupCheckFixtureZipBytes -EntryContent $entryContent
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()

        $path = Join-Path $TestDrive 'RC8-install-target.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.99.99"' -Encoding ascii -NoNewline
        $release = [pscustomobject]@{
            TagName = 'v1.0-RC8'
            Name = 'v1.0 RC8'
            Body = 'Test release notes.'
            AssetName = 'TeknoParrot.Manager.v1.0.RC8.zip'
            DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0-RC8/TeknoParrot.Manager.v1.0.RC8.zip'
            SizeBytes = 1
            Digest = ('sha256:' + (Get-F35FixtureHash -Bytes $zipBytes))
        }

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release $release

        $result.Outcome | Should -Be 'SUCCEEDED'
        $result.ReasonCode | Should -Be 'UPDATE_INSTALLED_VERIFIED'
        (Get-ManagerUpdatePreState -Path $path).Version | Should -Be '1.0-RC8'
    }
    It "rejects an installed RC mismatch despite a matching validated candidate hash" {
        $entryContent = '# TeknoParrot Manager' + "`n" + '$ScriptVersion = "1.0"' + "`n" + '$ReleaseCandidateLabel = "RC8"' + "`n"
        $zipBytes = New-StartupCheckFixtureZipBytes -EntryContent $entryContent
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()

        $path = Join-Path $TestDrive 'rc8-readback-mismatch.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.99.99"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $preStateHash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
        $candidateZipPath = Join-Path $TestDrive 'rc8-readback-candidate.zip'
        [System.IO.File]::WriteAllBytes($candidateZipPath, $zipBytes)
        $candidatePath = Join-Path $TestDrive 'rc8-readback-candidate.ps1'
        Expand-ManagerUpdateAsset -ZipPath $candidateZipPath -EntryName 'TeknoParrot-Manager.ps1' -DestinationPath $candidatePath | Out-Null
        $candidateHash = (Get-FileHash -LiteralPath $candidatePath -Algorithm SHA256).Hash
        # Fault-inject an inconsistent readback: the candidate hash matches, but
        # the version identity is RC7. This exercises the defensive identity
        # check that ordinary single-read file contents cannot reach.
        $readbackCounter = [pscustomobject]@{ Value = 0 }
        Mock Get-ManagerUpdatePreState {
            $readbackCounter.Value++
            switch ($readbackCounter.Value) {
                1 { [pscustomobject]@{ Captured = $true; Sha256 = $preStateHash; Version = '0.99.99'; IsReadOnly = $false } }
                2 { [pscustomobject]@{ Captured = $true; Sha256 = $candidateHash; Version = '1.0-RC7'; IsReadOnly = $false } }
                3 { [pscustomobject]@{ Captured = $true; Sha256 = $candidateHash; Version = '1.0-RC8'; IsReadOnly = $false } }
                default { [pscustomobject]@{ Captured = $true; Sha256 = $preStateHash; Version = '0.99.99'; IsReadOnly = $false } }
            }
        }.GetNewClosure()
        $release = [pscustomobject]@{
            TagName = 'v1.0-RC8'
            Name = 'v1.0 RC8'
            Body = 'Test release notes.'
            AssetName = 'TeknoParrot.Manager.v1.0.RC8.zip'
            DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0-RC8/TeknoParrot.Manager.v1.0.RC8.zip'
            SizeBytes = 1
            Digest = ('sha256:' + (Get-F35FixtureHash -Bytes $zipBytes))
        }

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release $release

        $result.Outcome | Should -Be 'ROLLED_BACK_VERIFIED'
        $result.Errors | Should -Contain 'The installed manager script version did not match the approved release.'
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
    }



    It "installs successfully and returns a verified SUCCEEDED result" {
        $zipBytes = New-StartupCheckFixtureZipBytes
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()

        $path = Join-Path $TestDrive 'install-target.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $zipBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'SUCCEEDED'
        $result.Installed | Should -BeTrue
        (Get-Content -LiteralPath $path -Raw) | Should -Match 'ScriptVersion = "0.99.99"'
    }

    It "stages the new script in the script's own folder so the final replace is one rename on the same drive (audit 11)" {
        # Mutation: stage in the temp folder again -> on another drive Move-Item is copy-then-delete and a crash can leave a half-written script.
        $zipBytes = New-StartupCheckFixtureZipBytes
        Mock Invoke-TpmDownload { param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version) [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); return $true }.GetNewClosure()
        $script:m2RealExpand = ${function:Expand-ManagerUpdateAsset}
        $script:m2StagedPath = $null
        Mock Expand-ManagerUpdateAsset { $script:m2StagedPath = $DestinationPath; & $script:m2RealExpand @PesterBoundParameters }
        $root = Join-Path $TestDrive ('m2-stage-' + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $zipBytes)

        $result.Outcome | Should -Be 'SUCCEEDED'
        [System.IO.Path]::GetDirectoryName($script:m2StagedPath) | Should -BeExactly $root
        Test-Path -LiteralPath $script:m2StagedPath | Should -BeFalse
    }

    It "returns a verified failure and leaves the original untouched when the target is read-only" {
        $path = Join-Path $TestDrive 'readonly-install-target.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        Set-ItemProperty -LiteralPath $path -Name IsReadOnly -Value $true
        try {
            Mock Invoke-TpmDownload { throw "download should not be called when the target is read-only" }
            $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease)
            (Test-TpmTransactionResult -Result $result) | Should -BeTrue
            $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
            (Get-Content -LiteralPath $path -Raw) | Should -Be '$ScriptVersion = "0.0.1"'
        } finally {
            Set-ItemProperty -LiteralPath $path -Name IsReadOnly -Value $false -ErrorAction SilentlyContinue
        }
    }

    # Destructive-path parity with Tests/TpmAutoUpdate.DestructivePath.Tests.ps1
    # (issue: in-script Invoke-ManagerUpdateInstall had only success/read-only
    # coverage versus the standalone module's 9 dedicated failure scenarios --
    # release-certification gap, see release-readiness review). Each of these
    # deliberately induces a failure and asserts the original installation
    # survives untouched, a completed backup is preserved, and no temp
    # artifacts leak -- "never leave the user with a broken installation."
    It "corrupt ZIP download: leaves the original intact and writes no backup" {
        $root = Join-Path $TestDrive ("destructive-corrupt-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $corruptBytes = [byte[]](1..64)

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            [System.IO.File]::WriteAllBytes($DestinationPath, $corruptBytes)
            return $true
        }.GetNewClosure()

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $corruptBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent

        # The package is read before anything is written, so a ZIP that cannot be read leaves no backup folder behind.
        Test-Path -LiteralPath (Join-Path $root 'UpdateBackups') | Should -BeFalse
    }

    It "ZIP missing TeknoParrot-Manager.ps1: leaves the original intact and writes no backup" {
        $root = Join-Path $TestDrive ("destructive-missing-entry-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $wrongEntryBytes = New-StartupCheckFixtureZipBytes -EntryName 'SomethingElse.ps1'

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            [System.IO.File]::WriteAllBytes($DestinationPath, $wrongEntryBytes)
            return $true
        }.GetNewClosure()

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $wrongEntryBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent

        Test-Path -LiteralPath (Join-Path $root 'UpdateBackups') | Should -BeFalse
    }

    It "content validation failure (missing ScriptVersion): leaves the original intact and preserves the backup" {
        $root = Join-Path $TestDrive ("destructive-noversion-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $badContentBytes = New-StartupCheckFixtureZipBytes -EntryContent "# TeknoParrot Manager`nsome unrelated content, no version here`n"

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            [System.IO.File]::WriteAllBytes($DestinationPath, $badContentBytes)
            return $true
        }.GetNewClosure()

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $badContentBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent

        $backupFiles = @(Get-ChildItem -LiteralPath (Join-Path $root 'UpdateBackups') -Recurse -Filter 'TeknoParrot-Manager.ps1' -ErrorAction SilentlyContinue)
        $backupFiles.Count | Should -Be 1
        @(Get-ChildItem -LiteralPath (Split-Path -Parent $path) -Filter 'tpm-update-extracted-*.ps1' -ErrorAction SilentlyContinue).Count | Should -Be 0
    }

    It "content validation failure (extracted file is itself raw zip bytes): leaves the original intact" {
        $root = Join-Path $TestDrive ("destructive-nestedzip-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw

        # A zip whose single entry's *content* is itself zip bytes -- a
        # packaging mistake where the wrong artifact landed inside the
        # expected entry name.
        $innerZipBytes = New-StartupCheckFixtureZipBytes
        $stagingDir = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-nested-staging-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $stagingDir -Force | Out-Null
        $outerZipPath = Join-Path ([System.IO.Path]::GetTempPath()) ("tpm-nested-" + [guid]::NewGuid().ToString('N') + '.zip')
        try {
            [System.IO.File]::WriteAllBytes((Join-Path $stagingDir 'TeknoParrot-Manager.ps1'), $innerZipBytes)
            [System.IO.Compression.ZipFile]::CreateFromDirectory($stagingDir, $outerZipPath)
            $outerBytes = [System.IO.File]::ReadAllBytes($outerZipPath)
        } finally {
            Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction SilentlyContinue
            Remove-Item -LiteralPath $outerZipPath -Force -ErrorAction SilentlyContinue
        }

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            [System.IO.File]::WriteAllBytes($DestinationPath, $outerBytes)
            return $true
        }.GetNewClosure()

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $outerBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
        (Get-Content -LiteralPath $path -Raw).StartsWith('PK') | Should -BeFalse
    }

    It "truncated/partial download: treated as corrupt, leaves the original intact" {
        $root = Join-Path $TestDrive ("destructive-truncated-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $fullBytes = New-StartupCheckFixtureZipBytes
        $truncatedBytes = $fullBytes[0..([int]($fullBytes.Length / 2))]

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            [System.IO.File]::WriteAllBytes($DestinationPath, $truncatedBytes)
            return $true
        }.GetNewClosure()

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $truncatedBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent

        Test-Path -LiteralPath (Join-Path $root 'UpdateBackups') | Should -BeFalse
    }

    It "backup creation failure: aborts after verified download, original untouched, no backup folder" {
        $root = Join-Path $TestDrive ("destructive-backupfail-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw

        Mock New-ManagerUpdateBackup { throw "Access to the path is denied (simulated backup failure)." }
        $zipBytes = New-StartupCheckFixtureZipBytes
        Mock Invoke-TpmDownload { [System.IO.File]::WriteAllBytes($DestinationPath, $zipBytes); $true }.GetNewClosure()

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $zipBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
        Test-Path -LiteralPath (Join-Path $root 'UpdateBackups') | Should -BeFalse
        Should -Invoke Invoke-TpmDownload -Times 1
    }

    It "extraction failure (valid ZIP, corrupted entry payload): leaves the original intact and preserves the backup" {
        $root = Join-Path $TestDrive ("destructive-extractfail-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $corruptedEntryBytes = Get-DestructiveCorruptedEntryZipBytes

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            [System.IO.File]::WriteAllBytes($DestinationPath, $corruptedEntryBytes)
            return $true
        }.GetNewClosure()

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $corruptedEntryBytes)
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent

        $backupFiles = @(Get-ChildItem -LiteralPath (Join-Path $root 'UpdateBackups') -Recurse -Filter 'TeknoParrot-Manager.ps1' -ErrorAction SilentlyContinue)
        $backupFiles.Count | Should -Be 1
        @(Get-ChildItem -LiteralPath (Split-Path -Parent $path) -Filter 'tpm-update-extracted-*.ps1' -ErrorAction SilentlyContinue).Count | Should -Be 0
    }

    It "replacement failure after successful backup (locked destination): preserves backup and the locked, unmodified original" {
        # This is the literal "never leave the user with a broken
        # installation" case: backup/download/extract/validate all succeed
        # and only the final Move-Item fails -- what an AV scanner or another
        # process holding the file open looks like in practice.
        $root = Join-Path $TestDrive ("destructive-locked-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii -NoNewline
        $originalContent = Get-Content -LiteralPath $path -Raw
        $validBytes = New-StartupCheckFixtureZipBytes

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            [System.IO.File]::WriteAllBytes($DestinationPath, $validBytes)
            return $true
        }.GetNewClosure()

        $lockHandle = [System.IO.File]::Open($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
        try {
            $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release (New-StartupCheckRelease -Bytes $validBytes)
            (Test-TpmTransactionResult -Result $result) | Should -BeTrue
            $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
        } finally {
            $lockHandle.Dispose()
        }

        # Original must be exactly what it was -- no partial/truncated write.
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent

        $backupFiles = @(Get-ChildItem -LiteralPath (Join-Path $root 'UpdateBackups') -Recurse -Filter 'TeknoParrot-Manager.ps1' -ErrorAction SilentlyContinue)
        $backupFiles.Count | Should -Be 1
        (Get-Content -LiteralPath $backupFiles[0].FullName -Raw) | Should -Be $originalContent

        @(Get-ChildItem -LiteralPath (Split-Path -Parent $path) -Filter 'tpm-update-extracted-*.ps1' -ErrorAction SilentlyContinue).Count | Should -Be 0
        @(Get-ChildItem -LiteralPath ([System.IO.Path]::GetTempPath()) -Filter 'tpm-update-*.zip' -ErrorAction SilentlyContinue).Count | Should -Be 0
    }
}

Describe "Invoke-StartupUpdateCheck" {
    It "offers final v1.0 to an installation running RC8" {
        $originalVersion = $ScriptVersion
        $originalLabel = $ReleaseCandidateLabel
        $originalDisplay = $DisplayVersion
        try {
            $ScriptVersion = '1.0'
            $ReleaseCandidateLabel = 'RC8'
            $DisplayVersion = 'v1.0 RC8'
            Mock Get-ManagerUpdateRelease {
                [pscustomobject]@{ TagName = 'v1.0'; Name = 'v1.0'; Body = 'Final release.'; AssetName = 'x.zip'; DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v1.0/x.zip'; Digest = ('sha256:' + (Get-F35FixtureHash -Bytes ([Text.Encoding]::ASCII.GetBytes('download-not-reached')))) }
            }
            Mock Read-Host { 'N' }

            $path = Join-Path $TestDrive 'rc8-startup.ps1'
            Set-Content -LiteralPath $path -Value ('$ScriptVersion = "1.0"' + "`n" + '$ReleaseCandidateLabel = "RC8"') -Encoding ascii
            Get-ManagerDisplayVersion | Should -Be 'v1.0 RC8'
            $result = Invoke-StartupUpdateCheck -ScriptPath $path

            $result.ReasonCode | Should -Be 'UPDATE_REMIND_LATER'
            Should -Invoke Read-Host -Times 1
        } finally {
            $ScriptVersion = $originalVersion
            $ReleaseCandidateLabel = $originalLabel
            $DisplayVersion = $originalDisplay
        }
    }

    It "returns a verified NO_OP and does not prompt when already current" {
        Mock Get-ManagerUpdateRelease { [pscustomobject]@{ TagName = "v$ScriptVersion-$ReleaseCandidateLabel"; Name = $null; Body = $null; AssetName = 'x'; DownloadUrl = "https://github.com/Jumpstile/teknoparrot-manager/releases/download/v$ScriptVersion-$ReleaseCandidateLabel/x"; Digest = ('sha256:' + (Get-F35FixtureHash -Bytes ([Text.Encoding]::ASCII.GetBytes('download-not-reached')))) } }
        Mock Read-Host { throw "Read-Host should not be called when already current" }

        $path = Join-Path $TestDrive 'startup-current.ps1'
        Set-Content -LiteralPath $path -Value ("`$ScriptVersion = `"$ScriptVersion`"`n`$ReleaseCandidateLabel = `"$ReleaseCandidateLabel`"") -Encoding ascii

        $result = Invoke-StartupUpdateCheck -ScriptPath $path
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'NO_OP'
    }

    It "returns a verified failure without prompting again when the release check fails (e.g. offline)" {
        Mock Get-ManagerUpdateRelease { $null }
        Mock Read-Host { throw "Read-Host should not be called when the release check fails" }

        $path = Join-Path $TestDrive 'startup-offline.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii

        $result = Invoke-StartupUpdateCheck -ScriptPath $path
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
    }

    It "returns a verified NO_OP and makes no changes when the user chooses N (remind me later)" {
        Mock Get-ManagerUpdateRelease {
            [pscustomobject]@{ TagName = 'v0.99.99'; Name = 'v0.99.99'; Body = 'Notes.'; AssetName = 'x.zip'; DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v0.99.99/x.zip'; Digest = ('sha256:' + (Get-F35FixtureHash -Bytes ([Text.Encoding]::ASCII.GetBytes('download-not-reached')))) }
        }
        Mock Read-Host { "N" }

        $path = Join-Path $TestDrive 'startup-decline.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii
        $originalContent = Get-Content -LiteralPath $path -Raw

        $result = Invoke-StartupUpdateCheck -ScriptPath $path
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'NO_OP'
        (Get-Content -LiteralPath $path -Raw) | Should -Be $originalContent
    }

    It "shows release notes on V and then still lets the user decline with N" {
        Mock Get-ManagerUpdateRelease {
            [pscustomobject]@{ TagName = 'v0.99.99'; Name = 'v0.99.99'; Body = 'Detailed notes here.'; AssetName = 'x.zip'; DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v0.99.99/x.zip'; Digest = ('sha256:' + (Get-F35FixtureHash -Bytes ([Text.Encoding]::ASCII.GetBytes('download-not-reached')))) }
        }
        $script:readHostCallCount = 0
        Mock Read-Host {
            $script:readHostCallCount++
            if ($script:readHostCallCount -eq 1) { return "V" }
            return "N"
        }

        $path = Join-Path $TestDrive 'startup-view-notes.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii

        $result = Invoke-StartupUpdateCheck -ScriptPath $path
        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'NO_OP'
        Should -Invoke Read-Host -Times 2
    }

    It "automatically clears and restores the target read-only attribute on startup failure" {
        Mock Get-ManagerUpdateRelease {
            [pscustomobject]@{ TagName = 'v0.99.99'; Name = 'v0.99.99'; Body = 'Notes.'; AssetName = 'x.zip'; DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v0.99.99/x.zip'; Digest = ('sha256:' + (Get-F35FixtureHash -Bytes ([Text.Encoding]::ASCII.GetBytes('download-not-reached')))) }
        }
        Mock Read-Host { "Y" }
        Mock Invoke-TpmDownload { $false }

        $root = Join-Path $TestDrive ("startup-readonly-" + [guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Path $root -Force | Out-Null
        $path = Join-Path $root 'TeknoParrot-Manager.ps1'
        Set-Content -LiteralPath $path -Value '$ScriptVersion = "0.0.1"' -Encoding ascii
        Set-ItemProperty -LiteralPath $path -Name IsReadOnly -Value $true

        try {
            $result = Invoke-StartupUpdateCheck -ScriptPath $path
            (Test-TpmTransactionResult -Result $result) | Should -BeTrue
            $result.Outcome | Should -BeIn @('FAILED_BEFORE_MUTATION','ROLLED_BACK_VERIFIED','ACTION_REQUIRED')
            Test-Path -LiteralPath (Join-Path $root 'UpdateBackups') | Should -BeFalse
            (Get-Item -LiteralPath $path -Force).IsReadOnly | Should -BeTrue
        } finally {
            Set-ItemProperty -LiteralPath $path -Name IsReadOnly -Value $false -ErrorAction SilentlyContinue
        }
    }
}

Describe "Main menu source-level drift check" {
    # Issue #104: the menu display is now data-driven (Get-MainMenuSections /
    # Get-MainMenuItems), but the switch statement dispatching $modeChoice to
    # a $mode string is still hand-written top-level code, not extracted by
    # the AST function-extraction. This cross-checks the data model's item
    # numbers against the switch statement's case labels, preserving the
    # original intent of this test (a future edit to one without the other --
    # the exact drift class documented in LESSONS_LEARNED.md for
    # v0.99.25/v0.99.28 -- fails CI instead of shipping) against the new
    # architecture.
    BeforeAll {
        $script:mainScriptContent = Get-Content -LiteralPath $scriptPath -Raw
    }

    It "has a switch case for every menu item number in the data model except Exit, which the line after the switch handles, with no gaps" {
        $itemNumbers = Get-MainMenuItems | ForEach-Object { $_.Number } | Sort-Object -Unique

        $switchBlockStart = $script:mainScriptContent.IndexOf('switch ($modeChoice) {')
        # The switch block's own cases each have their own "{ ... }" (e.g.
        # "1" { $mode = "AutoSync" }), so IndexOf('}', ...) would only find
        # the first case's closing brace. "if ($modeChoice -eq" reliably
        # appears immediately after the whole switch statement closes.
        $switchBlockEnd   = $script:mainScriptContent.IndexOf('if ($modeChoice -eq', $switchBlockStart)
        $switchBlockText  = $script:mainScriptContent.Substring($switchBlockStart, $switchBlockEnd - $switchBlockStart)
        $switchNumbers    = [regex]::Matches($switchBlockText, '"(\d+)"\s*\{') |
            ForEach-Object { [int]$_.Groups[1].Value } | Sort-Object -Unique

        # @() wrap: not currently reachable with $null (18 menu items always
        # collapse to more than one unique number), but the same unguarded
        # .Count-on-a-possibly-scalar-pipeline-result pattern that broke the
        # Ultra-tier banner test under PS 5.1 above -- fixed defensively for
        # consistency with that lesson rather than waiting for it to fail.
        @($itemNumbers).Count | Should -BeGreaterThan 0
        # Join to strings for comparison -- piping an array directly into
        # Should -Be iterates it element-by-element against the whole
        # right-hand side instead of comparing the collections as a whole.
        # The Exit option is not a switch case: the "if ($modeChoice -eq ...)" after the switch leaves the loop.
        $script:mainScriptContent | Should -Match ('if \(\$modeChoice -eq "{0}"\) \{{ break \}}' -f $itemNumbers[-1])
        $caseNumbers = @($itemNumbers | Select-Object -SkipLast 1)
        ($caseNumbers -join ',') | Should -Be ($switchNumbers -join ',')

        $expectedSequence = 1..($itemNumbers[-1])
        ($itemNumbers -join ',') | Should -Be ($expectedSequence -join ',')
    }

    It "quotes in Help exactly the option numbers that the menu model (and so the dispatch above) uses (FIX29 SCAN2-06)" {
        $help = (Get-MainMenuHelpLines) -join "`n"
        $byMode = @{}
        foreach ($item in (Get-MainMenuItems)) { $byMode[[string]$item.Mode] = [int]$item.Number }
        $expected = [ordered]@{
            AutoSync = 'AutoSync:'; RegisterOnly = 'Register only:'; LaunchBoxSetup = 'LaunchBox integration:'; HealthCheck = 'Library health check:'
            Restore = 'Restore from a trusted backup.'
            CheckForUpdates = 'Check for updates.'; Support = 'Create a support package.'; Exit = 'Exit.'
        }
        foreach ($mode in $expected.Keys) {
            $help | Should -Match ('(?m)(?:^|\s){0} {1}' -f $byMode[$mode], [regex]::Escape($expected[$mode])) -Because "Help must quote option $($byMode[$mode]) for $mode"
        }
        $help | Should -Match ('(?m)^\s+{0}-{1} .*PostgreSQL setup and repair' -f $byMode['Controls'], $byMode['RequiredPatch'])
        # PostgreSQL setup sits inside that range, so its number is covered by it.
        $byMode['PostgresSetup'] | Should -BeGreaterOrEqual $byMode['Controls']
        $byMode['PostgresSetup'] | Should -BeLessOrEqual $byMode['RequiredPatch']
        $help | Should -Match ('trying option {0} again' -f $byMode['PostgresSetup'])
        foreach ($quoted in @([regex]::Matches($help, '(?m)(?:^\s+|\.\s+|option\s)(\d+)\b') | ForEach-Object { [int]$_.Groups[1].Value })) {
            @($byMode.Values) | Should -Contain $quoted
        }
    }

    It "every menu item has a distinct Mode string used by exactly one switch case" {
        $items = Get-MainMenuItems
        foreach ($item in $items) {
            if ($item.Number -eq 18) { continue } # Exit has no $mode assignment
            $script:mainScriptContent | Should -Match ([regex]::Escape('"{0}"' -f $item.Number) + '\s*\{\s*\$mode\s*=\s*"' + [regex]::Escape($item.Mode) + '"')
        }
    }

    It "Show-MainMenu's Enter prompt uses the highest item number from the data model" {
        $itemNumbers = Get-MainMenuItems | ForEach-Object { $_.Number } | Sort-Object -Unique
        $script:mainScriptContent.Contains('Read-MainMenuChoiceResponsive -Prompt ("Enter 1-{0}: " -f $menuMaxNumber)') | Should -Be $true
        $script:mainScriptContent.Contains('$menuMaxNumber = (Get-MainMenuItems | Measure-Object -Property Number -Maximum).Maximum') | Should -Be $true
        $itemNumbers[-1] | Should -Be 18
    }

    It "actual menu loop passes current viewport dimensions into Show-MainMenu" {
        $script:mainScriptContent.Contains('$consoleWidth  = Get-ConsoleContentWidth') | Should -Be $true
        $script:mainScriptContent.Contains('$consoleHeight = Get-ConsoleContentHeight') | Should -Be $true
        $script:mainScriptContent.Contains('Show-MainMenu -Tier $menuTier -Width $consoleWidth -Height $consoleHeight') | Should -Be $true
    }
}

Describe "Get-MainMenuSections / Get-MainMenuItems" {
    It "every section has at least one item" {
        Get-MainMenuSections | ForEach-Object { $_.Items.Count | Should -BeGreaterThan 0 }
    }
    It "flattens every section's items into one number-ordered list with no duplicate numbers" {
        $items = Get-MainMenuItems
        $numbers = $items | ForEach-Object { $_.Number }
        ($numbers | Sort-Object -Unique).Count | Should -Be $numbers.Count
