Describe "Console resize safety" {
    It "sets the buffer before the window and suppresses repeated resize attempts" {
        if (-not ('TpmResizeRawUi' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Management.Automation.Host;
public sealed class TpmResizeRawUi {
    private Size bufferSize;
    private Size windowSize;
    public Size MaxPhysicalWindowSize { get; set; }
    public Size BufferSize {
        get { return bufferSize; }
        set { bufferSize = value; }
    }
    public Size WindowSize {
        get { return windowSize; }
        set {
            if (value.Width > bufferSize.Width || value.Height > bufferSize.Height) {
                throw new InvalidOperationException("Window cannot be wider than the screen buffer.");
            }
            windowSize = value;
        }
    }
}
'@
        }
        $rawUi = New-Object TpmResizeRawUi
        $rawUi.MaxPhysicalWindowSize = [System.Management.Automation.Host.Size]::new(120, 40)
        $rawUi.BufferSize = [System.Management.Automation.Host.Size]::new(80, 25)
        $rawUi.WindowSize = [System.Management.Automation.Host.Size]::new(80, 25)
        $script:TpmConsoleResizeAttempted = $false
        try {
            Set-ConsoleMaximizedIfSupported -RawUi $rawUi -TerminalManaged $false
            $rawUi.BufferSize.Width | Should -BeGreaterOrEqual 120
            $rawUi.BufferSize.Height | Should -BeGreaterOrEqual 40
            $rawUi.WindowSize.Width | Should -Be 120
            $rawUi.WindowSize.Height | Should -Be 40
            $rawUi.WindowSize.Width | Should -BeLessOrEqual $rawUi.BufferSize.Width
            $rawUi.WindowSize.Height | Should -BeLessOrEqual $rawUi.BufferSize.Height
            $firstWindow = $rawUi.WindowSize
            $rawUi.MaxPhysicalWindowSize = [System.Management.Automation.Host.Size]::new(160, 50)
            Set-ConsoleMaximizedIfSupported -RawUi $rawUi -TerminalManaged $false
            $rawUi.WindowSize.Width | Should -Be $firstWindow.Width
            $rawUi.WindowSize.Height | Should -Be $firstWindow.Height
        } finally {
            $script:TpmConsoleResizeAttempted = $false
        }
    }
}

Describe "Manager banner rendering" {
    It "uses the compact plain-text banner for narrow widths" {
        $lines = @(Get-ManagerBannerRows -Width 80 | ForEach-Object { $_.Text })

        ($lines -join "`n") | Should -Match 'TeknoParrot Manager'
        ($lines -join "`n") | Should -Match 'Version 1.0 RC3'
        ($lines -join "`n") | Should -Not -Match '/_  __/__.*___'
    }
    It "selects responsive branding modes by viewport width" {
        Get-ManagerBannerMode -Width 80 | Should -Be 'PlainText'
        Get-ManagerBannerMode -Width 120 | Should -Be 'PlainText'
        Get-ManagerBannerMode -Width 150 | Should -Be 'PlainText'
        Get-ManagerBannerMode -Width 180 | Should -Be 'AnsiShadow'
    }
    It "centers ANSI Shadow branding and includes the canonical display version" {
        $lines = @(Get-ManagerBannerRows -Width 180 | ForEach-Object { $_.Text })
        $joined = $lines -join "`n"
        $block = [string][char]0x2588

        $joined.Contains($block) | Should -BeTrue
        $joined | Should -Match 'Developed and maintained by Jumpstile'
        $joined | Should -Match 'Version 1.0 RC3'
        $lines | ForEach-Object { $_.Length | Should -BeLessOrEqual 180 }
    }
    It "keeps each branding mode inside its target width" {
        foreach ($width in @(80, 120, 150, 180)) {
            Get-ManagerBannerRows -Width $width | ForEach-Object {
                $_.Text.Length | Should -BeLessOrEqual $width
            }
        }
    }
    It "assigns console-safe colors to responsive banner rows" {
        $rows = Get-ManagerBannerRows -Width 180
        $block = [string][char]0x2588

        $figletRow = $rows | Where-Object { $_.Text.Contains($block) } | Select-Object -First 1
        ($figletRow.Segments | ForEach-Object { $_.Color }) | Should -Contain 'Cyan'
        ($rows | Where-Object { $_.Text -match 'Developed and maintained by Jumpstile' }).Segments.Color | Should -Contain 'Yellow'
        ($rows | Where-Object { $_.Text -match 'Version 1.0 RC3' }).Color | Should -Be 'Cyan'
    }
}

Describe "Split-TextForMenuWidth" {
    It "keeps text on one line when the menu column is wide enough" {
        $lines = Split-TextForMenuWidth -Text 'Alpha beta gamma delta' -Width 80
        $lines.Count | Should -Be 1
        $lines[0] | Should -Be 'Alpha beta gamma delta'
    }
    It "wraps at the 20-character minimum when the menu column is narrower than that" {
        $lines = Split-TextForMenuWidth -Text 'Alpha beta gamma delta' -Width 12
        $lines.Count | Should -BeGreaterThan 1
        @($lines | Where-Object { $_.Length -gt 20 }).Count | Should -Be 0
        ($lines -join '|') | Should -Be 'Alpha beta gamma|delta'
    }
}

Describe "RC8 main-menu command routing and visibility" {
    It "accepts only advertised hotkeys and exact numeric choices" {
        (Resolve-MainMenuCommand -InputText 'L' -MaxNumber 18) | Should -Be 'L'
        (Resolve-MainMenuCommand -InputText 'l' -MaxNumber 18) | Should -Be 'L'
        (Resolve-MainMenuCommand -InputText 'H' -MaxNumber 18) | Should -Be 'H'
        (Resolve-MainMenuCommand -InputText 'h' -MaxNumber 18) | Should -Be 'H'
        (Resolve-MainMenuCommand -InputText 'Q' -MaxNumber 18) | Should -Be 'Q'
        (Resolve-MainMenuCommand -InputText '1' -MaxNumber 18) | Should -Be '1'
        (Resolve-MainMenuCommand -InputText '18' -MaxNumber 18) | Should -Be '18'
        (Resolve-MainMenuCommand -InputText '19' -MaxNumber 18) | Should -Be $null
        (Resolve-MainMenuCommand -InputText '01' -MaxNumber 18) | Should -Be $null
        (Resolve-MainMenuCommand -InputText 'N' -MaxNumber 18) | Should -Be $null
        (Resolve-MainMenuCommand -InputText 'U' -MaxNumber 18) | Should -Be $null
    }
    It "routes help and log before numeric workflow dispatch" {
        $script:ProductionSource | Should -Match '(?s)if \(\$modeChoice -eq ''H''\).*Show-MainMenuHelp'
        $script:ProductionSource | Should -Match '(?s)if \(\$modeChoice -eq ''L''\).*Open-TpmLogsAndReports'
        $script:ProductionSource | Should -Match 'Open-TpmLogsAndReports -LogsPath \$script:TpmOwnedLayout\.Logs -ReportsPath \$script:TpmOwnedLayout\.Reports'
        $script:ProductionSource | Should -Not -Match "Run in PREVIEW mode first\?.*\(Y/N"
    }
    It "does not advertise unattended mode in the normal footer" {
        $footer = Get-MainMenuFooterRows -Geometry (Get-MainMenuGeometry -Tier Compact -ViewportWidth 80 -ViewportHeight 25)
        (($footer | ForEach-Object Text) -join "`n") | Should -Not -Match 'Unattended'
    }
    It "suppresses the prompt when the rendered body is incomplete" {
        $screen = Render-MainMenuScreen -Tier Compact -Width 60 -Height 8
        $screen.PromptAllowed | Should -BeFalse
        # Mutation: allow the prompt while the options do not fit, or drop the resize hint -> the flags or the hint text below fail.
        $screen.AllOptionsVisible | Should -BeFalse
        (($screen.Rows | ForEach-Object { $_.Text }) -join "`n") | Should -Match 'The menu options do not fit in this window'
        (($screen.Rows | ForEach-Object { $_.Text }) -join "`n") | Should -Match 'Resize the PowerShell window and press Enter to redraw'
    }
    It "renders every constrained-width option and command footer before allowing the prompt" {
        $screen = Render-MainMenuScreen -Tier Compact -Width 80 -Height 25
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
        foreach ($item in (Get-MainMenuItems)) {
            $output | Should -Match ([regex]::Escape("$($item.Number)) $($item.Label)"))
        }
        $output | Should -Match 'H\s*=\s*Help'
        $output | Should -Match 'L\s*=\s*(View )?Log'
        $output | Should -Match 'Q\s*=\s*Quit'
        $screen.PromptAllowed | Should -BeTrue
        (Resolve-MainMenuCommand -InputText 'invalid' -MaxNumber 18) | Should -Be $null
        (Resolve-MainMenuCommand -InputText 'H' -MaxNumber 18) | Should -Be 'H'
        (Resolve-MainMenuCommand -InputText 'L' -MaxNumber 18) | Should -Be 'L'
        (Resolve-MainMenuCommand -InputText 'Q' -MaxNumber 18) | Should -Be 'Q'
    }
    It "keeps an invalid-choice notice visible through the next constrained redraw" {
        $notice = 'Invalid choice. Enter 1-18. Commands: H = Help, L = View Log, Q = Quit.'
        $screen = Render-MainMenuScreen -Tier Compact -Width 80 -Height 25 -Notice $notice
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
        $output | Should -Match 'Invalid choice'
        $output | Should -Match 'H = Help'
        $output | Should -Match 'L = View Log'
        $output | Should -Match 'Q = Quit'
        $script:ProductionSource.Contains('-Notice $menuNotice -ReturnScreen') | Should -BeTrue
        $script:ProductionSource.Contains('$menuNotice = "Invalid choice.') | Should -BeTrue
    }
    It "uses a dedicated help title and a safe return path" {
        $help = Get-Command Show-MainMenuHelp
        $help.Definition | Should -Match 'TeknoParrot Manager Help'
        $help.Definition | Should -Match 'Press Enter to return'
    }
    It "uses explicit safe preview choices" {
        $script:ProductionSource | Should -Match '\[P\] Preview \(default\) -- show what would change; no game or profile changes'
        $script:ProductionSource | Should -Match '\[R\] Run now -- back up UserProfiles first, then make the changes'
        $script:ProductionSource | Should -Match '\[B\] Back'
        $script:ProductionSource | Should -Match "Choice, default P"
    }
    It "decides Preview or Back before AutoSync/Register writes or preflight probes" {
        $source = $script:ProductionSource
        $dispatch = $source.IndexOf('switch ($modeChoice)')
        $preview = $source.IndexOf('[P] Preview (default) -- show what would change')
        $capture = $source.IndexOf('$zipPathsJustCaptured = $false', $dispatch)
        $save = $source.IndexOf('Save-Config', $capture)
        $benchmark = $source.IndexOf('Measure-PathWriteThroughput $gamesInstallFolder', $capture)
        $create = $source.IndexOf('[System.IO.Directory]::CreateDirectory($gamesInstallFolder)', $capture)
        $preview | Should -BeGreaterThan $dispatch
        $preview | Should -BeLessThan $capture
        $preview | Should -BeLessThan $save
        $preview | Should -BeLessThan $benchmark
        $preview | Should -BeLessThan $create
        $source | Should -Match '\$previewChoice -eq ''B''\) \{ continue \}'
    }
    It "renders the compact one-column menu by default at ordinary terminal dimensions" {
        $width = 120
        $height = 80
        $tier = Get-ConsoleLayoutTier -Width $width -Height $height
        $screen = Render-MainMenuScreen -Tier $tier -Width $width -Height $height
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
        $screen.Geometry.Layout | Should -Be 'Compact'
        $screen.Geometry.ColumnCount | Should -Be 1
        $output | Should -Match 'TeknoParrot Manager'
        $output | Should -Match ([regex]::Escape((Get-ManagerVersionLine)))
        $numbers = @([regex]::Matches($output, '(?m)^\s*(\d+)\)\s') | ForEach-Object { [int]$_.Groups[1].Value })
        ($numbers -join ',') | Should -Be ((1..18) -join ',')
        $output | Should -Match 'H\s*=\s*Help'
        $output | Should -Match 'L\s*=\s*View Log'
        $output | Should -Match 'Q\s*=\s*Quit'
        $screen.PromptAllowed | Should -BeTrue
        ($screen.VisibleOptionNumbers -join ',') | Should -Be ((1..18) -join ',')
        $screen.Rows[-2].Text | Should -Match '18\)\s+Exit\s*$'
        $screen.Rows[-1].Text | Should -Match 'Enter number.*H\s*=\s*Help.*L\s*=\s*View Log.*Q\s*=\s*Quit'
        $showCall = $script:ProductionSource.IndexOf('$screen = Show-MainMenu')
        $promptCall = $script:ProductionSource.IndexOf('$choiceResult = Read-MainMenuChoiceResponsive', $showCall)
        $promptCall | Should -BeGreaterThan $showCall
        $script:ProductionSource | Should -Match 'function Show-MainMenu \{(?s:.*?)Write-ConsoleRenderRows -Rows \$screen\.Rows'
    }
    It "uses two columns without wrapping or clipping at the minimum and large safe wide thresholds" {
        foreach ($viewport in @(
            @{ Width = 200; Height = 50 }
            @{ Width = 240; Height = 80 }
        )) {
            $tier = Get-ConsoleLayoutTier -Width $viewport.Width -Height $viewport.Height
            $screen = Render-MainMenuScreen -Tier $tier -Width $viewport.Width -Height $viewport.Height
            $screen.Geometry.Layout | Should -Be 'UltraTwoColumn'
            $screen.Geometry.ColumnCount | Should -Be 2
            $screen.PromptAllowed | Should -BeTrue
            $screen.Rows.Count | Should -BeLessOrEqual $viewport.Height
            foreach ($row in $screen.Rows) {
                $row.Text.Length | Should -BeLessOrEqual $viewport.Width
            }
            foreach ($item in (Get-MainMenuItems)) {
                @($screen.Rows | Where-Object { $_.Text.Contains("$($item.Number)) $($item.Label)") }).Count | Should -Be 1
            }
        }
    }

    It "keeps every actionable item and the prompt inside a constrained-height fallback" {
        $tier = Get-ConsoleLayoutTier -Width 200 -Height 20
        $screen = Render-MainMenuScreen -Tier $tier -Width 200 -Height 20
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
        $screen.Geometry.ColumnCount | Should -Be 1
        $screen.Rows.Count | Should -BeLessOrEqual 18
        $screen.PromptAllowed | Should -BeTrue
        ($screen.VisibleOptionNumbers -join ',') | Should -Be ((1..18) -join ',')
        $lastOptionIndex = 0
        foreach ($item in (Get-MainMenuItems)) {
            $lastOptionIndex = [Math]::Max($lastOptionIndex, $output.IndexOf("$($item.Number)) $($item.Label)"))
        }
        $output.IndexOf('Enter number') | Should -BeGreaterThan $lastOptionIndex
    }

    It "keeps required-patch and shifted maintenance actions on their documented options" {
        $expected = @(
            @{ Number = 3; Mode = 'LaunchBoxSetup'; Label = 'LaunchBox integration' },
            @{ Number = 11; Mode = 'RegionSetup'; Label = 'Region setup' },
            @{ Number = 13; Mode = 'RequiredPatch'; Label = 'Required game patches' },
            @{ Number = 14; Mode = 'HealthCheck'; Label = 'Library health check' },
            @{ Number = 15; Mode = 'Restore'; Label = 'Restore backup' },
            @{ Number = 12; Mode = 'PostgresSetup'; Label = 'Postgres setup' },
            @{ Number = 16; Mode = 'CheckForUpdates'; Label = 'Check for Updates' },
            @{ Number = 17; Mode = 'Support'; Label = 'Create Support Package' },
            @{ Number = 18; Mode = 'Exit'; Label = 'Exit' }
        )
        $items = @(Get-MainMenuItems)
        foreach ($wanted in $expected) {
            $actual = @($items | Where-Object Number -eq $wanted.Number)
            $actual.Count | Should -Be 1
            $actual[0].Mode | Should -Be $wanted.Mode
            $actual[0].Label | Should -Be $wanted.Label
        }
    }


}


Describe "Render-MainMenuScreen / Show-MainMenu" {
    It "renders Ultra as separate bounded rows instead of one collapsed line" {
        $screen = Render-MainMenuScreen -Tier 'Ultra' -Width 160 -Height 80

        $screen.AllOptionsVisible | Should -BeTrue
        (($screen.Rows | ForEach-Object { $_.Text.Length }) | Measure-Object -Maximum).Maximum | Should -BeLessOrEqual 160
        # @() wrap is required, not stylistic: PowerShell 7 added an intrinsic
        # scalar .Count member (a lone PSCustomObject reports Count=1), but
        # Windows PowerShell 5.1 -- this project's actual target runtime, and
        # what CI's "shell: powershell" step actually runs -- does not have
        # it, so .Count on a single (non-array) Where-Object match is $null
        # there. Exactly one row matches each of these two filters, so this
        # passed under PS7 (this dev environment's default) but failed on
        # every real PS 5.1 run, including CI, even though the actual
        # rendering was always correct on both. See LESSONS_LEARNED.md,
        # "PowerShell return @() gotcha."
        @($screen.Rows | Where-Object { $_.Text -match 'AutoSync' }).Count | Should -BeGreaterThan 0
        @($screen.Rows | Where-Object { $_.Text -match 'Crosshair setup' }).Count | Should -BeGreaterThan 0
    }
    It "returns a flat row buffer for the production writer" {
        $screen = Render-MainMenuScreen -Tier 'Ultra' -Width 160 -Height 30

        $screen.AllOptionsVisible | Should -BeTrue
        foreach ($row in $screen.Rows) {
            $row | Should -Not -BeOfType ([object[]])
            $row.PSObject.Properties.Name | Should -Contain 'Text'
            $row.PSObject.Properties.Name | Should -Contain 'Color'
        }
    }
    It "Compact tier renders labels without advertising unsupported commands" {
        $screen = Render-MainMenuScreen -Tier 'Compact' -Width 80 -Height 80
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
        $output | Should -Match 'TeknoParrot Manager'
        $output | Should -Match 'Version 1.0 RC3'
        $output | Should -Not -Match '/_  __/'
        $output | Should -Not -Match 'Type \? for descriptions'
        $output | Should -Not -Match 'U\s*='
        $output | Should -Match 'H\s*=\s*Help'
        $output | Should -Match 'L\s*=\s*View Log'
        $output | Should -Match 'Q\s*=\s*Quit'
        $script:ProductionSource | Should -Not -Match 'Type \? for descriptions'
        $script:ProductionSource | Should -Not -Match 'Compact.{0,80}\? for descriptions'
    }
    It "Ultra tier renders menu groups side-by-side instead of a narrow left-column menu" {
        $screen = Render-MainMenuScreen -Tier 'Ultra' -Width 160 -Height 80
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
        $output | Should -Match ([regex]::Escape("13) Required game patches"))
        $screen.AllOptionsVisible | Should -BeTrue
        $screen.Geometry.ColumnCount | Should -Be 2
        $screen.Geometry.MenuWidth | Should -BeGreaterThan 145
    }
    It "keeps selectable menu items visible at medium widths" {
        foreach ($case in @(
            @{ Tier = 'Compact'; Width = 100 },
            @{ Tier = 'Ultra'; Width = 150 }
        )) {
            $screen = Render-MainMenuScreen -Tier $case.Tier -Width $case.Width -Height 25
            $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
            $output | Should -Match '1\)'
            $output | Should -Match '18\)'
            $screen.Rows.Count | Should -BeGreaterThan 0
        }
    }

    It "rendered rows never exceed the detected viewport width" {
        foreach ($case in @(
            @{ Tier = 'Compact'; Width = 80; Height = 25 },
            @{ Tier = 'Ultra'; Width = 160; Height = 40 }
        )) {
            $screen = Render-MainMenuScreen -Tier $case.Tier -Width $case.Width -Height $case.Height
            foreach ($row in $screen.Rows) {
                $row.Text.Length | Should -BeLessOrEqual $case.Width
            }
        }
    }
    It "small viewport keeps the footer and Exit visible without scrolling, even if it must drop earlier sections (issue #104 RC3 correction)" {
        # Prior behavior flattened banner+body+footer and kept only the
        # first N rows top-to-bottom -- at a short height that silently
        # dropped the entire footer (Quit/Help controls) and the
        # Application section (option 18, Exit), which a real user could
        # never reach without resizing or scrolling. This asserted that
        # loss as "expected" (`Should -Not -Match 'Exit'`); the corrected
        # behavior below is the opposite: the footer and Exit must survive,
        # and it is earlier body content that gets trimmed first if
        # something has to give.
        $screen = Render-MainMenuScreen -Tier 'Compact' -Width 80 -Height 12
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"

        $screen.Rows.Count | Should -BeLessOrEqual 10
        $output | Should -Match 'TeknoParrot Manager'
        $output | Should -Match '18\) Exit'
        $output | Should -Match 'Enter number'
    }

    It "reserves footer rows unconditionally so they are never truncated away, across every tier at a short height" {
        foreach ($case in @(
            @{ Tier = 'Compact'; Width = 80 },
            @{ Tier = 'Ultra'; Width = 160 }
        )) {
            $screen = Render-MainMenuScreen -Tier $case.Tier -Width $case.Width -Height 12
            $normalFooterRows = @(Get-MainMenuFooterRows -Geometry $screen.Geometry)
            $minimalFooterRows = @(Get-MainMenuMinimalFooterRows -Geometry $screen.Geometry)

            # At this height, a narrow-enough tier may now legitimately fall
            # into the emergency compact presentation (issue #104 RC3-B),
            # which uses a single-line minimal footer instead of the normal
            # framed one -- either is acceptable here, since the point of
            # this test is that the footer is never truncated away
            # entirely, not that one specific footer variant is used.
            $screen.Rows.Count | Should -BeGreaterOrEqual 1
            $lastRowText = $screen.Rows[-1].Text
            $matchesNormalTail = ($normalFooterRows.Count -gt 0) -and ($lastRowText -eq $normalFooterRows[-1].Text)
            $matchesMinimalTail = ($minimalFooterRows.Count -gt 0) -and ($lastRowText -eq $minimalFooterRows[-1].Text)
            ($matchesNormalTail -or $matchesMinimalTail) | Should -BeTrue
        }
    }

    It "keeps option 18 (Exit) visible at every tier when the viewport is short, single-column layouts" {
        foreach ($case in @(
            @{ Tier = 'Compact'; Width = 80 }
        )) {
            $screen = Render-MainMenuScreen -Tier $case.Tier -Width $case.Width -Height 12
            $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
            $output | Should -Match '18\) Exit'
        }
    }

    It "keeps option 18 (Exit) visible at the Ultra two-column tier when the viewport is short" {
        # Two-column layouts distribute all sections between the columns,
        # then join rows by index; Exit can appear earlier in the flat list
        # than in a single-column layout, so it must remain visible here too.
        foreach ($case in @(
            @{ Tier = 'Ultra'; Width = 160 }
        )) {
            $screen = Render-MainMenuScreen -Tier $case.Tier -Width $case.Width -Height 12
            $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
            $output | Should -Match '18\) Exit'
        }
    }
    It "Show-MainMenu delegates to the stateless render-clear-write pipeline" {
        $mainScriptContent = Get-Content -LiteralPath (Join-Path $PSScriptRoot '..\TeknoParrot-Manager.ps1') -Raw

        $mainScriptContent.Contains('$screen = Render-MainMenuScreen -Tier $Tier -Width $Width -Height $Height') | Should -Be $true
        $mainScriptContent.Contains('Clear-ConsoleForFreshRender') | Should -Be $true
        $mainScriptContent.Contains('Set-ConsoleRenderOrigin') | Should -Be $true
        $mainScriptContent.Contains('Limit-MainMenuRowsToViewport') | Should -Be $true
        $mainScriptContent.Contains('Write-ConsoleRenderRows -Rows $screen.Rows') | Should -Be $true
    }
    It "Show-MainMenu's actual output includes visible menu items" {
        $output = & { Show-MainMenu -Tier 'Ultra' -Width 160 -Height 40 } 6>&1 | Out-String

        $output | Should -Match '13\) Required game patches'
        $output | Should -Match '18\) Exit'
        $output | Should -Match 'Enter number'
    }
    It "responsive menu input falls back when stdin is redirected" {
        $mainScriptContent = Get-Content -LiteralPath (Join-Path $PSScriptRoot '..\TeknoParrot-Manager.ps1') -Raw

        $mainScriptContent | Should -Match '\[Console\]::IsInputRedirected'
        $mainScriptContent | Should -Match 'Read-Host \$displayPrompt'
    }
}

Describe "Compact main menu section colors and color key (RC9.4)" {
    BeforeAll {
        # Reference packing: the plain-text greedy packer the compact menu used before colors were added.
        function script:Get-OldPackedText {
            param([int]$Width)
            $wrap = [Math]::Max(20, $Width)
            $lines = New-Object System.Collections.Generic.List[string]
            $current = ''
            foreach ($item in (Get-MainMenuItems)) {
                $token = '{0}) {1}' -f $item.Number, $item.Label
                if ($current.Length -eq 0) { $current = $token }
                elseif (($current.Length + 2 + $token.Length) -le $wrap) { $current = "$current  $token" }
                else { [void]$lines.Add($current); $current = $token }
            }
            if ($current.Length -gt 0) { [void]$lines.Add($current) }
            return @($lines)
        }
        $script:KeyText = 'Library | Enhancements | Requirements | Recovery | App'
    }

    It "packed rows have the same text as before at width <Width>" -TestCases @(
        @{ Width = 20 }, @{ Width = 40 }, @{ Width = 58 }, @{ Width = 80 }, @{ Width = 120 }
    ) {
        param($Width)
        $geometry = Get-MainMenuGeometry -Tier 'Compact' -ViewportWidth 200 -ViewportHeight 30
        $rows = @(Get-MainMenuFlowPackedItemRows -Width $Width -Geometry $geometry)
        $expected = @(Get-OldPackedText -Width $Width)
        $rows.Count | Should -Be $expected.Count
        for ($i = 0; $i -lt $expected.Count; $i++) {
            $rows[$i].Text.TrimStart() | Should -BeExactly $expected[$i]
            $rows[$i].Text | Should -Not -Match "\x1b"
        }
    }

    It "every packed item carries the same color the wide tier gives its section" {
        $geometry = Get-MainMenuGeometry -Tier 'Compact' -ViewportWidth 200 -ViewportHeight 30
        $rows = @(Get-MainMenuFlowPackedItemRows -Width 80 -Geometry $geometry)
        $segments = @($rows | ForEach-Object { $_.Segments })
        foreach ($section in (Get-MainMenuSections)) {
            $expectedColor = Get-MainMenuSectionColor -Header $section.Header
            foreach ($item in $section.Items) {
                $segment = @($segments | Where-Object { $_.Text -eq ('{0}) {1}' -f $item.Number, $item.Label) })
                $segment.Count | Should -Be 1
                $segment[0].Color | Should -Be $expectedColor
            }
        }
        (Get-MainMenuSectionColor -Header 'Library Management') | Should -Be 'Cyan'
        (Get-MainMenuSectionColor -Header 'Maintenance and Recovery') | Should -Be 'Magenta'
        (Get-MainMenuSectionColor -Header 'Application') | Should -Be 'Yellow'
        (Get-MainMenuSectionColor -Header 'Game Enhancements (optional -- not every game needs them)') | Should -Be 'Green'
        (Get-MainMenuSectionColor -Header 'Game Requirements (only for some games)') | Should -Be 'DarkYellow'
    }

    It "the key is added only when one more row fits, and adds exactly one line" {
        $geometry = Get-MainMenuGeometry -Tier 'Compact' -ViewportWidth 100 -ViewportHeight 30
        $plain = @(Get-MainMenuFlowPackedItemRows -Width 78 -Geometry $geometry)
        $atLimit = @(Get-MainMenuFlowPackedItemRows -Width 78 -Geometry $geometry -AvailableRows $plain.Count)
        $withKey = @(Get-MainMenuFlowPackedItemRows -Width 78 -Geometry $geometry -AvailableRows ($plain.Count + 1))
        $atLimit.Count | Should -Be $plain.Count
        $withKey.Count | Should -Be ($plain.Count + 1)
        for ($i = 0; $i -lt $plain.Count; $i++) { $withKey[$i].Text | Should -BeExactly $plain[$i].Text }
        $withKey[-1].Text.Trim() | Should -BeExactly $script:KeyText
        $keySegments = @($withKey[-1].Segments | Where-Object { $_.Text.Trim() -notin @('', '|') })
        @($keySegments | ForEach-Object { $_.Color }) | Should -Be @('Cyan', 'Green', 'DarkYellow', 'Magenta', 'Yellow')
    }

    It "the key is skipped when it would wrap" {
        $geometry = Get-MainMenuGeometry -Tier 'Compact' -ViewportWidth 100 -ViewportHeight 30
        $narrow = @(Get-MainMenuFlowPackedItemRows -Width ($script:KeyText.Length - 1) -Geometry $geometry -AvailableRows 99)
        @($narrow | Where-Object { $_.Text -match 'Enhancements' }).Count | Should -Be 0
        $exact = @(Get-MainMenuFlowPackedItemRows -Width $script:KeyText.Length -Geometry $geometry -AvailableRows 99)
        @($exact | Where-Object { $_.Text -match 'Enhancements' }).Count | Should -Be 1
    }

    It "at <Width>x<Height> the key is <Expect> and the screen still fits with its prompt, Exit and footer" -TestCases @(
        @{ Width = 80; Height = 20; Expect = 'shown' }
        @{ Width = 120; Height = 24; Expect = 'shown' }
        @{ Width = 80; Height = 9; Expect = 'absent' }
        @{ Width = 60; Height = 10; Expect = 'absent' }
        @{ Width = 50; Height = 20; Expect = 'absent' }
    ) {
        param($Width, $Height, $Expect)
        $screen = Render-MainMenuScreen -Tier (Get-ConsoleLayoutTier -Width $Width -Height $Height) -Width $Width -Height $Height
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
        $screen.Rows.Count | Should -BeLessOrEqual ([Math]::Max(5, $Height - 2))
        if ($Expect -eq 'shown') {
            $output | Should -Match ([regex]::Escape($script:KeyText))
            $screen.PromptAllowed | Should -BeTrue
            $output | Should -Match '18\) Exit'
            $output | Should -Match 'Q=Quit'
            $screen.Rows[-1].Text | Should -Match 'Enter number'
        } else {
            $output | Should -Not -MatchExactly 'Enhancements'
        }
    }

    It "the wide tier prints no key" {
        $screen = Render-MainMenuScreen -Tier 'Ultra' -Width 200 -Height 50
        (($screen.Rows | ForEach-Object { $_.Text }) -join "`n") | Should -Not -Match 'Library \| Enhancements'
    }
}

Describe "Minimum supported 60x10 viewport and nearby boundaries (issue #104 RC3-B correction)" {
    # A full categorized layout cannot fit every option beside the banner and
    # footer. Emergency packing drops headings and descriptions, keeping every
    # numbered action visible. The prompt remains disabled below the 60x10 minimum.
    # Using -TestCases (Pester's own parameterized-test mechanism) rather
    # than `foreach ($height in ...) { It ... { ...$height... } }`: a plain
    # PowerShell foreach-loop variable closed over by an It scriptblock is
    # NOT visible inside that scriptblock's body when Pester actually runs
    # it (confirmed by isolated repro -- the value reads as $null/empty at
    # Run time even though it renders correctly in the It's own title,
    # which is built separately at Discovery time). -TestCases passes each
    # case's values in as real bound parameters instead, which does work.
    It "at the supported 60x<Height> minimum and its immediate boundaries, every option 1-18 is visible, Exit and the footer are present, and nothing scrolls off the viewport" -TestCases @(
        @{ Height = 10 }, @{ Height = 11 }, @{ Height = 12 }
    ) {
        param($Height)
        $screen = Render-MainMenuScreen -Tier (Get-ConsoleLayoutTier -Width 60 -Height $Height) -Width 60 -Height $Height
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"

        $screen.Rows.Count | Should -BeLessOrEqual ([Math]::Max(5, $Height - 2))
        $allItemNumbers = @((Get-MainMenuItems) | ForEach-Object { $_.Number })
        foreach ($n in $allItemNumbers) {
            $output | Should -Match ([regex]::Escape("$n)"))
        }
        $output | Should -Match '18\) Exit'
        $output | Should -Match 'Enter number'
        $output | Should -Match 'Q=Quit'
    }

    It "blocks the prompt below the supported viewport height instead of showing a partial menu" {
        $screen = Render-MainMenuScreen -Tier (Get-ConsoleLayoutTier -Width 60 -Height 8) -Width 60 -Height 8
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"

        $screen.Rows.Count | Should -BeLessOrEqual 8
        $screen.PromptAllowed | Should -BeFalse
        $output | Should -Match 'Resize the PowerShell window'
        $output | Should -Not -Match '18\) Exit'
        $output | Should -Not -Match 'Enter number'
    }

    It "every flow-packed 'N) Label' token matches Get-MainMenuItems exactly (no drift between the emergency presentation and the real dispatch data)" {
        $geometry = Get-MainMenuGeometry -Tier 'Compact' -ViewportWidth 60 -ViewportHeight 10
        $rows = Get-MainMenuFlowPackedItemRows -Width 58 -Geometry $geometry
        $flatText = ($rows | ForEach-Object { $_.Text }) -join ' '

        foreach ($item in (Get-MainMenuItems)) {
            $flatText | Should -Match ([regex]::Escape("$($item.Number)) $($item.Label)"))
        }
    }

    # Using -TestCases (Pester's own parameterized-test mechanism), not a
    # `foreach ($case in ...) { ... }` loop bundled inside a single `It`
    # body: a bundled loop reports as exactly one pass/fail for all four
    # cases combined, so a reviewer reading Pester's output cannot tell
    # whether all four widths/heights actually ran, whether they ran with
    # their own distinct values, or whether an early failure silently
    # skipped the remaining cases (`Should` throws, which stops the loop).
    # -TestCases gives each case its own named, independently-reported
    # result instead. (Note: a bundled loop entirely INSIDE one It body is
    # not the same closure defect as a loop that WRAPS separate `It` calls
    # -- confirmed by isolated repro that the bundled form here did receive
    # correct per-iteration values -- but it still doesn't prove independent
    # per-case execution/reporting, which is what this rewrite is for.)
    It "at <Width>x<Height>, Exit and the footer stay visible without scrolling, using this case's own dimensions" -TestCases @(
        @{ Width = 80;  Height = 8;  ExpectedTier = 'Compact' }
        @{ Width = 100; Height = 8;  ExpectedTier = 'Compact' }
        @{ Width = 150; Height = 8;  ExpectedTier = 'Compact' }
        @{ Width = 100; Height = 20; ExpectedTier = 'Compact' }
    ) {
        param($Width, $Height, $ExpectedTier)
        $tier = Get-ConsoleLayoutTier -Width $Width -Height $Height

        # Proves the WIDTH bound into this case actually drove tier
        # selection under the production width-and-height policy -- a
        # cross-case value swap would flip this and fail.
        $tier | Should -Be $ExpectedTier

        $screen = Render-MainMenuScreen -Tier $tier -Width $Width -Height $Height
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"

        # Proves this case actually ran with ITS OWN Width, not a value
        # shared or duplicated from another case -- the specific
        # "accidental duplicate binding" this rewrite guards against. The
        # geometry object is threaded all the way through from the -Width
        # parameter passed into Render-MainMenuScreen above, so a mismatch
        # here would mean cross-case value bleed. (ViewportWidth, not
        # Height, because Get-MainMenuGeometry internally clamps
        # ViewportHeight to a floor of 10 for its own column-width math --
        # see the real-height budgeting note in ARCHITECTURE.md -- so it
        # would not reflect this case's own Height value for the two 8-row
        # cases here even when everything is working correctly.)
        $screen.Geometry.ViewportWidth | Should -Be $Width

        # This case's own Height still matters even though the two
        # Width=100 cases (100x8 and 100x20) share a tier: the row-count
        # ceiling is derived from THIS case's real Height (Max(5,
        # Height-2) = 6 for height 8, 18 for height 20), so a cross-case
        # Height swap between those two would change which bound applies.
        $screen.Rows.Count | Should -BeLessOrEqual ([Math]::Max(5, $Height - 2))
        if ($Height -lt 10) {
            $screen.PromptAllowed | Should -BeFalse
            $output | Should -Match 'Resize the PowerShell window'
            $output | Should -Not -Match '18\) Exit'
            $output | Should -Not -Match 'Enter number'
        } else {
            $screen.PromptAllowed | Should -BeTrue
            $output | Should -Match '18\) Exit'
            $output | Should -Match 'Q=Quit'
            foreach ($n in @((Get-MainMenuItems) | ForEach-Object { $_.Number })) {
                $output | Should -Match ([regex]::Escape("$n)"))
            }
        }
    }

    It "a generously tall Compact-width window (60x30) still uses the normal framed presentation, not the emergency fallback" {
        # Confirms the emergency mode is gated correctly -- it must not
        # trigger just because the width is narrow, only when the height
        # genuinely can't fit every option any other way.
        $screen = Render-MainMenuScreen -Tier 'Compact' -Width 60 -Height 30
        $output = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"

        $screen.AllOptionsVisible | Should -BeTrue
        $output | Should -Match '18\) Exit'
    }

    It "every numbered option in the emergency presentation still maps to the same Mode the live switch statement dispatches on" {
        # Cross-checks against the same source-of-truth used by "Main menu
        # source-level drift check" elsewhere in this file: the emergency
        # presentation's numbers come directly from Get-MainMenuItems, the
        # same data the switch statement's case labels are generated from,
        # so there is no separate hand-maintained number-to-mode mapping
        # that could drift.
        $mainScriptContent = Get-Content -LiteralPath $scriptPath -Raw
        foreach ($item in (Get-MainMenuItems)) {
            if ($item.Mode -eq 'Exit') { continue }
            $mainScriptContent | Should -Match ([regex]::Escape('"{0}"' -f $item.Number) + '\s*\{\s*\$mode\s*=\s*"' + [regex]::Escape($item.Mode) + '"')
        }
    }
}


Describe "Menu layout debug script" {
    It "prints host dimensions and the same ordinary-width layout as production" {
        $debugScript = Join-Path $PSScriptRoot '..\scripts\Debug-TPM-MenuLayout.ps1'
        $output = & $debugScript -Width 200 -Height 30 6>&1 | Out-String

        $output | Should -Match 'Host type'
        $output | Should -Match 'Host\.RawUI\.WindowSize\.Width'
        $output | Should -Match 'Host\.RawUI\.BufferSize\.Height'
        $output | Should -Match 'Selected viewport width\s+:\s+200'
        $output | Should -Match 'Selected viewport height\s+:\s+30'
        $output | Should -Match 'Selected layout tier\s+:\s+Compact'
        $output | Should -Match 'Selected layout mode\s+:\s+Compact\s'
        $output | Should -Match 'Constrained by\s+:\s+width,height'
    }
    # The two tests above invoke the diagnostic via `& $debugScript` from
    # INSIDE this same Pester process -- that call runs in a child scope of
    # the current session, which already has every production function
    # (including Limit-MainMenuBodyRowsToBudget) dot-sourced into it by this
    # file's own top-level BeforeAll. That let a real regression pass
    # invisibly: the packaged script itself only loaded a hand-maintained
    # allowlist of function names and never defined
    # Limit-MainMenuBodyRowsToBudget (added for the RC3 short-viewport
    # truncation fix), so running the actual, unmodified .ps1 file as a
    # user would -- a fresh process with nothing pre-loaded -- crashed with
    # "the term 'Limit-MainMenuBodyRowsToBudget' is ... not recognized" the
    # moment -Render exercised the render pipeline. `& $debugScript` here
    # never caught it because the missing function was already present from
    # this file's own BeforeAll, not from the diagnostic script itself.
    # These tests launch a genuinely separate PROCESS instead, so nothing
    # from this test session's scope can leak in and mask a missing
    # dependency in the packaged script.
    It "runs successfully as a genuinely isolated process (not just a child scope) under pwsh, with -Render exercising the full pipeline" {
        $debugScript = Join-Path $PSScriptRoot '..\scripts\Debug-TPM-MenuLayout.ps1'
        $pwshCmd = Get-Command pwsh -ErrorAction SilentlyContinue
        if (-not $pwshCmd) { Set-ItResult -Skipped -Because 'pwsh is not available on this machine'; return }

        $output = & $pwshCmd.Source -NoProfile -NonInteractive -File $debugScript -Width 150 -Height 40 -Render 2>&1 | Out-String
        $exitCode = $LASTEXITCODE

        $exitCode | Should -Be 0
        $output | Should -Not -Match 'is not recognized as the name of a cmdlet'
        $output | Should -Not -Match 'CommandNotFoundException'
        $output | Should -Match '18\) Exit'
        $output | Should -Match 'Enter number'
    }

    It "runs successfully as a genuinely isolated process under real Windows PowerShell 5.1, with -Render exercising the full pipeline" {
        $debugScript = Join-Path $PSScriptRoot '..\scripts\Debug-TPM-MenuLayout.ps1'
        $ps51Path = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if (-not (Test-Path -LiteralPath $ps51Path)) { Set-ItResult -Skipped -Because 'Windows PowerShell 5.1 is not available on this machine'; return }

        $output = & $ps51Path -NoProfile -File $debugScript -Width 150 -Height 40 -Render 2>&1 | Out-String
        $exitCode = $LASTEXITCODE

        $exitCode | Should -Be 0
        $output | Should -Not -Match 'is not recognized as the name of a cmdlet'
        $output | Should -Not -Match 'CommandNotFoundException'
        $output | Should -Match '18\) Exit'
        $output | Should -Match 'Enter number'
    }
}

