    It "uses the real host capability path without writing cursor controls when the host is redirected" {
        # The real (non-injected) capability path must not depend on whether the suite was launched from a
        # redirected pipe or an interactive console, so force its non-interactive branch via the same
        # $Unattended flag the product consults before probing the Console/RawUI.
        $Unattended = $true
        $capability = Get-TpmWorkflowConsoleCapability
        $capability.Mode | Should -Be 'None'
        $capability.Reason | Should -Be 'redirected-or-unattended'
        $ctx = New-TpmWorkflowStatusContext -WorkflowKey 'real-host' -Title 'Real host' -Steps @('one')
        { Render-TpmWorkflowStatus -Context $ctx } | Should -Not -Throw
        $ctx.RendererMode | Should -Be 'None'
    }

    It "draws, updates, and clears through the supported RawUI overloads in a real ConsoleHost" {
        if ($Host.Name -ne 'ConsoleHost') {
            Set-ItResult -Skipped -Because 'A ConsoleHost is required to exercise native RawUI rendering.'
            return
        }
        # The product (correctly) falls back to append-only output when stdout is redirected, e.g. when
        # the test run is piped to a file; a footer can only be drawn on a live console.
        if ([Console]::IsOutputRedirected) {
            Set-ItResult -Skipped -Because 'Console output is redirected, so the footer renderer correctly uses append-only mode.'
            return
        }
        $raw = $Host.UI.RawUI
        $window = $raw.WindowSize
        $buffer = $raw.BufferSize
        if ($window.Width -lt 40 -or $window.Height -lt 10 -or $buffer.Width -lt $window.Width -or $buffer.Height -lt $window.Height) {
            Set-ItResult -Skipped -Because 'The console geometry is too small or inconsistent for a reversible footer test.'
            return
        }
        $savedCursor = $raw.CursorPosition
        try {
            $raw.CursorPosition = $savedCursor
        } catch {
            if ($_.Exception.Message -match 'handle is invalid') {
                Set-ItResult -Skipped -Because 'This ConsoleHost process has no live console handle for native RawUI operations.'
                return
            }
            throw
        }
        $savedTop = [Math]::Max(0, [int]$raw.WindowPosition.Y + [int]$window.Height - 8)
        $savedBottom = [Math]::Min([int]$buffer.Height - 1, $savedTop + 7)
        $savedRectangle = [System.Management.Automation.Host.Rectangle]::new(0, $savedTop, ([int]$buffer.Width - 1), $savedBottom)
        $savedCells = $raw.GetBufferContents($savedRectangle)
        try {
            $nativeStep = 'create context'
            $facts = [pscustomobject]@{
                NoRender = $false; Unattended = $false; InputRedirected = $false; OutputRedirected = $false
                Certification = $false; CanCursor = $true; Width = [int]$window.Width; Height = [int]$window.Height
                BufferWidth = [int]$buffer.Width; BufferHeight = [int]$buffer.Height; Adapter = $null
            }
            $ctx = New-TpmWorkflowStatusContext -WorkflowKey 'native-rawui' -Title 'Native RawUI footer' -Steps @('one','two') -ConsoleFacts $facts
            $nativeStep = 'start workflow status'
            $raw.CursorPosition = [System.Management.Automation.Host.Coordinates]::new(0, [int]$raw.WindowPosition.Y)
            [void](Start-TpmWorkflowStatus -Context $ctx)
            [void](Start-TpmWorkflowStep -Context $ctx -StepId 'one' -Activity 'Native RawUI drawing')
            $ctx.RendererMode | Should -Be 'CursorFooter'
            $nativeStep = 'read drawn footer'
            $drawLeft = 0
            $drawTop = [int]$ctx.FooterBounds.Top
            $drawRight = [int]$ctx.FooterBounds.Width - 1
            $drawBottom = [int]$ctx.FooterBounds.Top + [int]$ctx.FooterBounds.Height - 1
            $drawRectangle = [System.Management.Automation.Host.Rectangle]::new($drawLeft, $drawTop, $drawRight, $drawBottom)
            $drawnCells = $raw.GetBufferContents($drawRectangle)
            $drawnText = ''
            for ($y = 0; $y -lt $drawnCells.GetLength(0); $y++) {
                for ($x = 0; $x -lt $drawnCells.GetLength(1); $x++) { $drawnText += [string]$drawnCells[$y,$x].Character }
            }
            $drawnText | Should -Match 'Native RawUI drawing'
            $nativeStep = 'update footer'
            [void](Update-TpmWorkflowActivity -Context $ctx -Activity 'Native RawUI updated activity')
            $updatedCells = $raw.GetBufferContents($drawRectangle)
            $updatedText = ''
            for ($y = 0; $y -lt $updatedCells.GetLength(0); $y++) {
                for ($x = 0; $x -lt $updatedCells.GetLength(1); $x++) { $updatedText += [string]$updatedCells[$y,$x].Character }
            }
            $updatedText | Should -Match 'Native RawUI updated activity'
            $nativeStep = 'clear footer'
            Clear-TpmWorkflowFooter -Context $ctx
            $ctx.FooterBounds | Should -BeNullOrEmpty
            $clearedCells = $raw.GetBufferContents($drawRectangle)
            $nonBlankCells = 0
            for ($y = 0; $y -lt $clearedCells.GetLength(0); $y++) {
                for ($x = 0; $x -lt $clearedCells.GetLength(1); $x++) {
                    if ([string]$clearedCells[$y,$x].Character -ne ' ') { $nonBlankCells++ }
                }
            }
            $nonBlankCells | Should -Be 0
        } catch {
            throw ("Native RawUI regression test failed during {0}: {1}" -f $nativeStep, $_.Exception.Message)
        } finally {
            $raw.SetBufferContents([System.Management.Automation.Host.Coordinates]::new(0, $savedTop), $savedCells)
            $raw.CursorPosition = $savedCursor
        }
    }

