    It "says the real reason native FFB setup stopped: <Case>" -ForEach @(
        @{ Case = 'a profile cannot be read, no backup tried'; BackupFails = $false; Expect = 'could not be read'; Reject = 'backup failed' }
        @{ Case = 'the backup itself failed'; BackupFails = $true; Expect = 'profile backup failed'; Reject = 'could not be read' }
    ) {
        # Mutation: pick "profile backup failed" from BackupSucceeded alone -> a run that never tried a backup sends the user hunting a backup problem.
        # Mutation: leave out -FinalPassed on the review result -> the run throws instead of showing the screen.
        $userProfiles = Join-Path $TestDrive ('ffb-native-stop-' + $(if ($BackupFails) { 'backup' } else { 'review' }))
        New-Item -ItemType Directory -Path $userProfiles -Force | Out-Null
        if ($BackupFails) {
            Set-Content -LiteralPath (Join-Path $userProfiles 'Existing.xml') -Value '<GameProfile><EmulationProfile>Daytona3</EmulationProfile><ConfigValues><FieldInformation><CategoryName>FFB Blaster</CategoryName><FieldName>Enable</FieldName><FieldType>Bool</FieldType><FieldValue>0</FieldValue></FieldInformation></ConfigValues></GameProfile>'
            Mock Copy-Item { throw 'simulated profile backup copy failure' }
        } else {
            Set-Content -LiteralPath (Join-Path $userProfiles 'Unreadable.xml') -Value '<GameProfile>'
        }
        Mock Get-FFBBlasterFieldNames { @('FFB Blaster') }
        Mock Invoke-FFBPluginSetup { throw 'plugin must not be called after native failure' }
        Mock Read-HostSafe { 'Y' }
        $script:nativeStopMessages = New-Object System.Collections.Generic.List[string]
        Mock Set-TpmWorkflowFailure { [void]$script:nativeStopMessages.Add([string]$Message) }
        Mock Acknowledge-TpmWorkflowFailure {}
        $null = Invoke-TpmFfbSetupMode -UserProfilesDir $userProfiles -TpRoot $TestDrive -ScriptRoot $TestDrive
        $script:nativeStopMessages.Count | Should -Be 1
        $script:nativeStopMessages[0] | Should -Match ([regex]::Escape($Expect))
        $script:nativeStopMessages[0] | Should -Not -Match ([regex]::Escape($Reject))
    }
