        Mock Save-Xml { param($Doc,$Path) $Doc.Save($Path); throw 'simulated post-write failure' }
        $script:ffbOverlapProgress=New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress { [void]$script:ffbOverlapProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete }) }

        $result=Disable-FFBBlasterForOverlap -UserProfilesDir $profiles -TpRoot $tpRoot -ProfileCodes @('Overlap')

        $result.Succeeded | Should -BeFalse
        [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes((Join-Path $profiles 'Overlap.xml'))) | Should -Be $before
        @($script:ffbOverlapProgress | Where-Object { $_.Label -eq 'FFB overlap safety snapshot discovery' -and $_.Complete -and $_.Current -eq 2 -and $_.Total -eq 0 }).Count | Should -Be 1
        @($script:ffbOverlapProgress | Where-Object { $_.Label -eq 'FFB overlap safety snapshot' -and -not $_.Complete -and $_.Total -eq 1 }).Count | Should -Be 1
        @($script:ffbOverlapProgress | Where-Object { $_.Label -eq 'FFB overlap profile preflight' -and -not $_.Complete -and $_.Total -eq 1 }).Count | Should -Be 1
        @($script:ffbOverlapProgress | Where-Object { $_.Label -eq 'FFB overlap profile preflight' -and $_.Complete -and $_.Current -eq 1 -and $_.Total -eq 1 }).Count | Should -Be 1
        (@($script:ffbOverlapProgress | Where-Object { $_.Label -eq 'FFB overlap profile discovery' -and -not $_.Complete } | ForEach-Object Current) -join ',') | Should -Be '0,1'
        @($script:ffbOverlapProgress | Where-Object { $_.Label -eq 'FFB overlap profile discovery' -and $_.Complete -and $_.Current -eq 1 -and $_.Total -eq 0 }).Count | Should -Be 1
        @($script:ffbOverlapProgress | Where-Object { $_.Label -eq 'FFB overlap backup verification' -and -not $_.Complete -and $_.Total -eq 1 }).Count | Should -Be 1
    }
    It "does not copy an unverified half-made FFB snapshot over live profiles when the snapshot copy fails" {
        $root=Join-Path $TestDrive 'ffb-overlap-snapshot-fails'
        $profiles=Join-Path $root 'UserProfiles'
        $tpRoot=Join-Path $root 'TeknoParrot'
        New-Item -ItemType Directory -Path $profiles,(Join-Path $tpRoot 'GameProfiles') -Force | Out-Null
        $profileXml='<GameProfile><GamePath>fixture.exe</GamePath><ConfigValues><FieldInformation><CategoryName>FFB Blaster</CategoryName><FieldName>Enable</FieldName><FieldType>Bool</FieldType><FieldValue>1</FieldValue></FieldInformation></ConfigValues></GameProfile>'
        [System.IO.File]::WriteAllText((Join-Path $profiles 'Overlap.xml'),$profileXml)
        [System.IO.File]::WriteAllText((Join-Path $profiles 'Other.xml'),$profileXml)
        [System.IO.File]::WriteAllText((Join-Path $tpRoot 'GameProfiles\Canonical.xml'),$profileXml)
        # The snapshot copy is cut short and leaves a truncated copy of Other.xml in the snapshot folder.
        Mock Copy-Item {
            [System.IO.File]::WriteAllText((Join-Path $Destination 'Other.xml'),'<Game')
            throw 'simulated disk full'
        }
        $result=Disable-FFBBlasterForOverlap -UserProfilesDir $profiles -TpRoot $tpRoot -ProfileCodes @('Overlap')
        $result.Succeeded | Should -BeFalse
        [System.IO.File]::ReadAllText((Join-Path $profiles 'Other.xml')) | Should -Be $profileXml
        [System.IO.File]::ReadAllText((Join-Path $profiles 'Overlap.xml')) | Should -Be $profileXml
    }
    It "rejects an invalid overlap owner response and accepts a safe follow-up" {
        $root = Join-Path $TestDrive 'ffb-invalid-overlap'
        $userProfiles = Join-Path $root 'UserProfiles'
        $tpRoot = Join-Path $root 'TeknoParrot'
        $gameDir = Join-Path $root 'OverlapGame'
        $cacheDir = Join-Path $root 'FFBPlugin'
        New-Item -ItemType Directory -Path $userProfiles, (Join-Path $tpRoot 'GameProfiles'), $gameDir, $cacheDir -Force | Out-Null
        $gamePath = Join-Path $gameDir 'overlap.exe'
        [System.IO.File]::WriteAllBytes($gamePath, [System.Text.Encoding]::ASCII.GetBytes('MZ-overlap'))
        $profileXml = @"
<GameProfile>
  <EmulationProfile>Daytona3</EmulationProfile>
  <GamePath>$gamePath</GamePath>
  <ConfigValues>
    <FieldInformation><CategoryName>FFB Blaster</CategoryName><FieldName>Enable</FieldName><FieldType>Bool</FieldType><FieldValue>1</FieldValue></FieldInformation>
  </ConfigValues>
</GameProfile>
"@
        $encoding = New-Object System.Text.UTF8Encoding $false
        [System.IO.File]::WriteAllText((Join-Path $userProfiles 'Overlap.xml'), $profileXml, $encoding)
        [System.IO.File]::WriteAllText((Join-Path $tpRoot 'GameProfiles\Canonical.xml'), $profileXml, $encoding)
        [System.IO.File]::WriteAllBytes((Join-Path $cacheDir 'MAME64.dll'), [System.Text.Encoding]::ASCII.GetBytes('plugin'))
        Mock Get-FFBPluginGameMap { [ordered]@{ OverlapGame = 'd3d9.dll' } }
        Mock Invoke-FFBPluginDownload {
            param([string]$destDir, [object]$Release)
            New-FFBDownloadFixtureResult -destDir $destDir -Release $Release
        }
        Mock Get-ExeArchitecture { 'x64' }
        $script:ffbOverlapAnswers = [System.Collections.Generic.Queue[string]]::new()
        [void]$script:ffbOverlapAnswers.Enqueue('Q')
        [void]$script:ffbOverlapAnswers.Enqueue('Y')
        Mock Read-HostSafe { $script:ffbOverlapAnswers.Dequeue() }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $userProfiles -CacheDir $cacheDir -TpRoot $tpRoot -NativeEnabledCodes @('Overlap')
        $result.Succeeded | Should -BeTrue
        $result.Reason | Should -Be 'NATIVE_PREFERRED'
        $field = (Read-Xml (Join-Path $userProfiles 'Overlap.xml')).SelectSingleNode('/GameProfile/ConfigValues/FieldInformation/FieldValue')
        $field.InnerText | Should -Be '1'
        (Test-Path -LiteralPath (Join-Path $gameDir 'd3d9.dll') -PathType Leaf) | Should -BeFalse
        Should -Invoke Read-HostSafe -Times 2 -Exactly
    }
    It "reports missing saved paths separately from unsupported FFB games" {
        $userProfiles = Join-Path $TestDrive 'ffb-missing-path'
        $cacheDir = Join-Path $TestDrive 'ffb-missing-cache'
        New-Item -ItemType Directory -Path $userProfiles, $cacheDir -Force | Out-Null
        $profileXml = @"
<GameProfile>
  <EmulationProfile>MissingFfbGame</EmulationProfile>
  <GamePath>C:\missing\MissingFfbGame.exe</GamePath>
</GameProfile>
"@
        [System.IO.File]::WriteAllText((Join-Path $userProfiles 'MissingFfbGame.xml'), $profileXml, (New-Object System.Text.UTF8Encoding $false))
        $unmatchedExe = Join-Path $TestDrive 'UnmatchedFfbFolder\unmatched.exe'
        New-Item -ItemType Directory -Path ([System.IO.Path]::GetDirectoryName($unmatchedExe)) -Force | Out-Null
        [System.IO.File]::WriteAllText($unmatchedExe, 'unmatched')
        [System.IO.File]::WriteAllText((Join-Path $userProfiles 'UnmatchedFfbGame.xml'), '<GameProfile><EmulationProfile>UnmatchedFfbGame</EmulationProfile><GamePath>{0}</GamePath></GameProfile>' -f $unmatchedExe)
        Mock Get-FFBPluginGameMap { [ordered]@{ MissingFfbGame = 'd3d9.dll' } }
        Mock Invoke-FFBPluginDownload {
            param([string]$destDir, [object]$Release)
            New-FFBDownloadFixtureResult -destDir $destDir -Release $Release
        }
        $script:ffbShown = New-Object 'System.Collections.Generic.List[string]'
        Mock Write-Host { [void]$script:ffbShown.Add([string]($Object -join ' ')) }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $userProfiles -CacheDir $cacheDir
        ($script:ffbShown -join "`n") | Should -Not -Match 'Accounted'
        $result.Succeeded | Should -BeFalse
        $result.MissingPath | Should -Be 1
        @($result.MissingPathGames) | Should -Contain 'MissingFfbGame'
        $result.Deployed | Should -Be 0
        $result.Errors | Should -Be 0
        $result.Accounted | Should -Be 2
        $result.AccountingComplete | Should -BeTrue
        $result.SkippedNoMatch | Should -Be 1
        $result.MissingDevice | Should -Be 0
    }
    It "classifies an unavailable device separately from a missing saved path" {
        $userProfiles = Join-Path $TestDrive 'ffb-device-unavailable'
        $cacheDir = Join-Path $TestDrive 'ffb-device-cache'
        New-Item -ItemType Directory -Path $userProfiles, $cacheDir -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $userProfiles 'DeviceFfbGame.xml') -Value '<GameProfile><EmulationProfile>DeviceFfbGame</EmulationProfile><GamePath>Z:\missing\DeviceFfbGame.exe</GamePath></GameProfile>'
        Mock Get-FFBPluginGameMap { [ordered]@{ DeviceFfbGame = 'd3d9.dll' } }
        Mock Invoke-FFBPluginDownload {
            param([string]$destDir, [object]$Release)
            New-FFBDownloadFixtureResult -destDir $destDir -Release $Release
        }
        Mock Test-TpmGameMutationPath { [pscustomobject]@{ Valid = $false; ReasonCode = 'DEVICE_UNAVAILABLE'; Reason = 'A device which does not exist was specified.' } }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $userProfiles -CacheDir $cacheDir
        $result.Succeeded | Should -BeFalse
        $result.MissingPath | Should -Be 0
        $result.MissingDevice | Should -Be 1
        @($result.MissingDeviceGames) | Should -Contain 'DeviceFfbGame'
        $result.PathReasonCounts['DEVICE_UNAVAILABLE'] | Should -Be 1
    }
    It "preserves path metadata when optional plugin deployment fails" {
        $script:ffbAnswerIndex = 0
        Mock Invoke-FFBBlasterSetup { @() }
        Mock Invoke-FFBPluginSetup {
            [pscustomobject]@{
                Succeeded = $false
                MissingPath = 1
                MissingDevice = 1
                MissingPathGames = @('MissingFfbGame')
                MissingDeviceGames = @('DeviceFfbGame')
                PathReasonCounts = @{ GAME_PATH_MISSING = 1; DEVICE_UNAVAILABLE = 1 }
            }
        }
        Mock Read-HostSafe { @('Y', '')[$script:ffbAnswerIndex++] }
        Mock Select-FFBPluginWheel { [pscustomobject]@{ Cancelled = $false; DeviceGuid = ''; Name = '' } }
        $result = Invoke-TpmFfbSetupMode -UserProfilesDir $TestDrive -TpRoot $TestDrive -ScriptRoot $TestDrive
        $result.Completed | Should -BeFalse
        $result.MissingPath | Should -Be 1
        $result.MissingDevice | Should -Be 1
        @($result.MissingPathGames) | Should -Contain 'MissingFfbGame'
        @($result.MissingDeviceGames) | Should -Contain 'DeviceFfbGame'
    }
    It "routes FFB missing-path results to Health Check from the main dispatch" {
        $source = $script:ProductionSource
        $source | Should -Match '\$ffbModeResult\.MissingPath -gt 0'
        $source | Should -Match '\$pendingApplyMode = ''HealthCheck'''
        $source | Should -Match "Choose H or B"
    }
    It "refuses a plugin download whose release tag is not plain, and downloads nothing" {
        # Mutation: build the download from any text the release answer holds -> a tag such as ../master reaches the address and the file name.
        $cache = Join-Path $TestDrive 'ffb-bad-tag'
        New-Item -ItemType Directory -Path $cache -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $cache 'keep.txt') -Value 'existing'
        Mock Invoke-TpmDownload { throw 'a download must not run' }
        $result = Invoke-FFBPluginDownload -destDir $cache -Release (New-FfbTestRelease -Tag '../master')
        Should -Invoke Invoke-TpmDownload -Times 0 -Exactly
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'SOURCE_REVISION_UNAVAILABLE'
        (Get-Content -LiteralPath (Join-Path $cache 'keep.txt') -Raw) | Should -Be "existing`r`n"
    }
    It "keeps other cache files while staging the new plugin ZIP under its own name" {
        $cache = Join-Path $TestDrive 'ffb-custom-cache'
        New-Item -ItemType Directory -Path $cache -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $cache 'keep.txt') -Value 'custom'
        $script:ffbSourceZip = Join-Path $TestDrive 'ffb-source-keep.zip'
        New-FfbTestZip -Path $script:ffbSourceZip -Games @{ FixtureGame = 'd3d9.dll' }
        $hash = (Get-FileHash -LiteralPath $script:ffbSourceZip -Algorithm SHA256).Hash
        $script:ffbAskedDigest = $null
        Mock Invoke-TpmDownload {
            param([string]$DownloadUrl, [string]$DestinationPath, [string]$ExpectedBytes, [string]$Label, [string]$Version, [string]$ExpectedSha256)
            $script:ffbAskedDigest = $ExpectedSha256
            Copy-Item -LiteralPath $script:ffbSourceZip -Destination $DestinationPath -Force
            $true
        }
        $result = Invoke-FFBPluginDownload -destDir $cache -Release (New-FfbTestRelease -Tag 'v.1.2.3.4' -Sha256 $hash)
        $result.Succeeded | Should -BeTrue
        $result.Staged | Should -BeTrue
        $result.Sha256 | Should -Be $hash
        $script:ffbAskedDigest | Should -Be $hash -Because 'the digest GitHub published is what the download is held to'
        @($result.Evidence).Count | Should -Be 1
        $result.Evidence[0].DigestChecked | Should -BeTrue
        $result.Evidence[0].SourceRevision | Should -Be 'v.1.2.3.4'
        (Get-Content -LiteralPath (Join-Path $cache 'keep.txt') -Raw) | Should -Be "custom`r`n"
        $result.ZipPath | Should -Not -Be (Join-Path $cache 'TPM-FFB-Plugin-Release.zip')
        Test-Path -LiteralPath $result.ZipPath -PathType Leaf | Should -BeTrue
    }
}

Describe 'FFB plugin release source and transaction invariants' {
    BeforeAll {
        function New-FFBTransactionFixture {
            param([string]$Root)
            $profiles = Join-Path $Root 'UserProfiles'
            $gameRoot = Join-Path $Root 'FixtureGame'
            $cache = Join-Path $Root 'FFBPlugin'
            New-Item -ItemType Directory -Path $profiles, $gameRoot, $cache -Force | Out-Null
            $exe = Join-Path $gameRoot 'FixtureGame.exe'
            [System.IO.File]::WriteAllBytes($exe, [byte[]](0x4d,0x5a,1,2,3,4))
            $profile = '<GameProfile><EmulationProfile>FixtureGame</EmulationProfile><GamePath>{0}</GamePath></GameProfile>' -f $exe
            [System.IO.File]::WriteAllText((Join-Path $profiles 'FixtureGame.xml'), $profile, (New-Object System.Text.UTF8Encoding($false)))
            return [pscustomobject]@{ Root=$Root; Profiles=$profiles; GameRoot=$gameRoot; Cache=$cache; Exe=$exe }
        }

        function Mock-FFBTransactionDependencies {
            param([string]$Revision)
            $script:ffbTestTag = $Revision
            Mock Get-FFBPluginLatestRelease { New-FfbTestRelease -Tag $script:ffbTestTag }
            Mock Get-FFBPluginGameMap { [ordered]@{ FixtureGame='d3d9.dll' } }
            Mock Invoke-FFBPluginDownload {
                param([string]$destDir, [object]$Release)
                New-FFBDownloadFixtureResult -destDir $destDir -Release $Release
            }
            Mock Get-ExeArchitecture { 'x64' }
            Mock Read-TpmYesNo { 'Y' }
        }
    }

    It 'asks for the latest release and picks the plugin ZIP with its published digest' {
        # Mutation: take the first asset, or a pinned old tag -> a source ZIP or an old release is installed.
        $script:ffbReleaseUris = @()
        $assetUrl = 'https://github.com/mightymikem/FFBArcadePlugin/releases/download/v.2.0.0.51/FFB.Arcade.Plugin.v2.0.0.51.zip'
        $script:ffbReleaseJson = (@{ tag_name = 'v.2.0.0.51'; assets = @(
            @{ name = 'Source code.zip'; browser_download_url = 'https://github.com/mightymikem/FFBArcadePlugin/archive/v.2.0.0.51.zip' },
            @{ name = 'FFB.Arcade.Plugin.v2.0.0.51.zip'; size = 93040003; browser_download_url = $assetUrl; digest = ('sha256:' + ('ab' * 32)) }) } | ConvertTo-Json -Depth 5)
        Mock Invoke-TpmWebRequestSilently {
            param([string]$Uri)
            $script:ffbReleaseUris += $Uri
            [pscustomobject]@{ Content = $script:ffbReleaseJson }
        }
        $release = Get-FFBPluginLatestRelease
        $release.Revision | Should -Be 'v.2.0.0.51'
        $release.AssetName | Should -Be 'FFB.Arcade.Plugin.v2.0.0.51.zip'
        $release.AssetUrl | Should -Be $assetUrl
        $release.Sha256 | Should -Be (('AB') * 32)
        $release.Bytes | Should -Be 93040003
        $release.Trust | Should -Be 'ReleaseDigestVerified'
        @($script:ffbReleaseUris) | Should -HaveCount 1
        $script:ffbReleaseUris[0] | Should -Match '/repos/mightymikem/FFBArcadePlugin/releases/latest$'
    }

    It 'still returns a release that has no published digest, and says the digest is missing' {
        $assetUrl = 'https://github.com/mightymikem/FFBArcadePlugin/releases/download/v.2.0.0.51/FFB.Arcade.Plugin.v2.0.0.51.zip'
        $release = Select-FFBPluginReleaseAsset -Release ((@{ tag_name = 'v.2.0.0.51'; assets = @(@{ name = 'FFB.Arcade.Plugin.v2.0.0.51.zip'; browser_download_url = $assetUrl }) } | ConvertTo-Json -Depth 5) | ConvertFrom-Json)
        $release.Sha256 | Should -BeNullOrEmpty
        $release.Trust | Should -Be 'ReleaseNoDigest'
    }

    It 'refuses a release answer it cannot trust: <Case>' -ForEach @(
        @{ Case = 'two plugin ZIPs'; Json = '{"tag_name":"v.1","assets":[{"name":"FFB.Arcade.Plugin.a.zip","browser_download_url":"https://github.com/mightymikem/FFBArcadePlugin/releases/download/v.1/a.zip"},{"name":"FFB.Arcade.Plugin.b.zip","browser_download_url":"https://github.com/mightymikem/FFBArcadePlugin/releases/download/v.1/b.zip"}]}' }
        @{ Case = 'no plugin ZIP'; Json = '{"tag_name":"v.1","assets":[{"name":"notes.txt","browser_download_url":"https://github.com/mightymikem/FFBArcadePlugin/releases/download/v.1/notes.txt"}]}' }
        @{ Case = 'a download address outside the plugin project'; Json = '{"tag_name":"v.1","assets":[{"name":"FFB.Arcade.Plugin.a.zip","browser_download_url":"https://example.com/FFB.Arcade.Plugin.a.zip"}]}' }
        @{ Case = 'a checksum that is not SHA-256'; Json = '{"tag_name":"v.1","assets":[{"name":"FFB.Arcade.Plugin.a.zip","digest":"md5:abc","browser_download_url":"https://github.com/mightymikem/FFBArcadePlugin/releases/download/v.1/a.zip"}]}' }
        @{ Case = 'a version tag with a path in it'; Json = '{"tag_name":"../v.1","assets":[{"name":"FFB.Arcade.Plugin.a.zip","browser_download_url":"https://github.com/mightymikem/FFBArcadePlugin/releases/download/v.1/a.zip"}]}' }
    ) {
        # Mutation: take whatever the answer holds -> a wrong or foreign file is downloaded and installed.
        { Select-FFBPluginReleaseAsset -Release ($Json | ConvertFrom-Json) } | Should -Throw
        Mock Write-Log {}
        Mock Invoke-TpmWebRequestSilently { [pscustomobject]@{ Content = $Json } }
        Get-FFBPluginLatestRelease | Should -BeNullOrEmpty
    }

    It 'uses the release tag in the support-table address' {
        $revision = 'v.2.0.0.51'
        $script:ffbTableUris = @()
        Mock Invoke-TpmWebRequestSilently {
            param([string]$Uri)
            $script:ffbTableUris += $Uri
            [pscustomobject]@{ Content = "cd FixtureGame`r`nrename dinput8.dll d3d9.dll`r`ncd.." }
        }
        $map = Get-FFBPluginGameMap -SourceRevision $revision
        $map['FixtureGame'] | Should -Be 'd3d9.dll'
        @($script:ffbTableUris | Where-Object { $_ -notmatch [regex]::Escape($revision) -or $_ -match '/master/' }) | Should -HaveCount 0
    }

    It 'fails before mutation when the resolver cannot return a valid revision' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-resolver-failure')
        Mock Get-FFBPluginLatestRelease { $null }
        Mock Get-FFBPluginGameMap { throw 'map should not be fetched' }
        Mock Invoke-FFBPluginDownload { throw 'DLLs should not be fetched' }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'SOURCE_REVISION_UNAVAILABLE'
        Should -Invoke Get-FFBPluginGameMap -Times 0 -Exactly
        Should -Invoke Invoke-FFBPluginDownload -Times 0 -Exactly
        (Test-Path -LiteralPath (Join-Path $fixture.GameRoot 'd3d9.dll') -PathType Leaf) | Should -BeFalse
    }

    It 'fails before mutation when the resolver response is malformed' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-malformed-resolver')
        Mock Invoke-TpmWebRequestSilently {
            [pscustomobject]@{ Content = '{"tag_name":"v.1","assets":[]}' }
        }
        Mock Get-FFBPluginGameMap { throw 'map should not be fetched' }
        Mock Invoke-FFBPluginDownload { throw 'DLLs should not be fetched' }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'SOURCE_REVISION_UNAVAILABLE'
        Should -Invoke Get-FFBPluginGameMap -Times 0 -Exactly
        Should -Invoke Invoke-FFBPluginDownload -Times 0 -Exactly
        (Test-Path -LiteralPath (Join-Path $fixture.GameRoot 'd3d9.dll') -PathType Leaf) | Should -BeFalse
    }
    It 'fails before mutation when the pinned support table is unavailable' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-table-failure')
        $revision = ('a' * 40)
        Mock Get-FFBPluginLatestRelease { New-FfbTestRelease -Tag $revision }
        Mock Get-FFBPluginGameMap { @{} }
        Mock Invoke-FFBPluginDownload { throw 'DLLs should not be fetched after table failure' }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'GAME_MAP_FAILED'
        Should -Invoke Invoke-FFBPluginDownload -Times 0 -Exactly
        (Test-Path -LiteralPath (Join-Path $fixture.GameRoot 'd3d9.dll') -PathType Leaf) | Should -BeFalse
    }

    It 'fails before mutation when DLL acquisition does not produce a verified set' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-dll-failure')
        $revision = ('b' * 40)
        Mock Get-FFBPluginLatestRelease { New-FfbTestRelease -Tag $revision }
        Mock Get-FFBPluginGameMap { [ordered]@{ FixtureGame='d3d9.dll' } }
        Mock Invoke-FFBPluginDownload {
            [pscustomobject]@{ Succeeded=$false; Files=@{}; Evidence=@(); ResiduePaths=@(); Reason='DLL_ACQUISITION_FAILED' }
        }
        $script:ffbPluginDiscoveryProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:ffbPluginDiscoveryProgress.Add([pscustomobject]@{
                Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete
            })
        }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'DLL_ACQUISITION_FAILED'
        (Test-Path -LiteralPath (Join-Path $fixture.GameRoot 'd3d9.dll') -PathType Leaf) | Should -BeFalse
        @($script:ffbPluginDiscoveryProgress | Where-Object { $_.Label -eq 'FFB plugin profile discovery' -and -not $_.Complete -and $_.Total -eq 0 }).Count | Should -BeGreaterThan 0
        @($script:ffbPluginDiscoveryProgress | Where-Object { $_.Label -eq 'FFB plugin profile discovery' -and $_.Complete -and $_.Total -eq 0 }).Count | Should -Be 1
    }

    It 'throws away a download whose hash differs from the published digest' {
        # Mutation: skip the digest comparison -> a tampered or truncated ZIP is unpacked and installed.
        $cache = Join-Path $TestDrive 'ffb-digest-mismatch'
        New-Item -ItemType Directory -Path $cache -Force | Out-Null
        $script:ffbSourceZip = Join-Path $TestDrive 'ffb-source-mismatch.zip'
        New-FfbTestZip -Path $script:ffbSourceZip -Games @{ FixtureGame = 'd3d9.dll' }
        Mock Invoke-TpmDownload {
            param([string]$DownloadUrl, [string]$DestinationPath)
            Copy-Item -LiteralPath $script:ffbSourceZip -Destination $DestinationPath -Force
            $true
        }
        $result = Invoke-FFBPluginDownload -destDir $cache -Release (New-FfbTestRelease -Tag 'v.3.0' -Sha256 ('0' * 64))
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'HASH_MISMATCH'
        @(Get-ChildItem -LiteralPath $cache -Filter 'TPM-FFB-Plugin-Release*' -Force).Count | Should -Be 0
    }

    It 'reuses the saved ZIP for the same release without downloading it again' {
        $cache = Join-Path $TestDrive 'ffb-reuse-cache'
        New-Item -ItemType Directory -Path $cache -Force | Out-Null
        $saved = Join-Path $cache 'TPM-FFB-Plugin-Release.zip'
        New-FfbTestZip -Path $saved -Games @{ FixtureGame = 'd3d9.dll' }
        $hash = (Get-FileHash -LiteralPath $saved -Algorithm SHA256).Hash
        [void](Save-FFBPluginCache -CacheDir $cache -ZipPath $saved -Tag 'v.4.0' -AssetName 'FFB.Arcade.Plugin.test.zip' -Sha256 $hash -GameMap @{ FixtureGame = 'd3d9.dll' })
        Mock Invoke-TpmDownload { throw 'the saved ZIP must be reused' }
        $result = Invoke-FFBPluginDownload -destDir $cache -Release (New-FfbTestRelease -Tag 'v.4.0' -Sha256 $hash)
        Should -Invoke Invoke-TpmDownload -Times 0 -Exactly
        $result.Succeeded | Should -BeTrue
        $result.Staged | Should -BeFalse
        $result.ZipPath | Should -Be $saved
    }

    It 'does not trust a saved ZIP whose hash no longer matches its record' {
        # Mutation: trust the record without hashing the ZIP -> a damaged saved copy is offered as the offline fallback.
        $cache = Join-Path $TestDrive 'ffb-damaged-cache'
        New-Item -ItemType Directory -Path $cache -Force | Out-Null
        $saved = Join-Path $cache 'TPM-FFB-Plugin-Release.zip'
        New-FfbTestZip -Path $saved -Games @{ FixtureGame = 'd3d9.dll' }
        $hash = (Get-FileHash -LiteralPath $saved -Algorithm SHA256).Hash
        [void](Save-FFBPluginCache -CacheDir $cache -ZipPath $saved -Tag 'v.4.0' -AssetName 'x.zip' -Sha256 $hash -GameMap @{ FixtureGame = 'd3d9.dll' })
        Get-FFBPluginCachedRelease -CacheDir $cache | Should -Not -BeNullOrEmpty
        [System.IO.File]::AppendAllText($saved, 'damage')
        Get-FFBPluginCachedRelease -CacheDir $cache | Should -BeNullOrEmpty
    }

    It 'preserves an existing collision and reports zero deployment with complete accounting' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-collision')
        $destination = Join-Path $fixture.GameRoot 'd3d9.dll'
        [System.IO.File]::WriteAllText($destination, 'pre-existing-hook', (New-Object System.Text.UTF8Encoding($false)))
        $revision = ('f' * 40)
        Mock-FFBTransactionDependencies -Revision $revision
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        Should -Invoke Get-FFBPluginLatestRelease -Times 1 -Exactly
        $result.Succeeded | Should -BeTrue
        $result.Reason | Should -Be 'NO_PLUGIN_CHANGES_NEEDED'
        $result.Deployed | Should -Be 0
        $result.SkippedCollision | Should -Be 1
        $result.Accounted | Should -Be 1
        $result.AccountingComplete | Should -BeTrue
        [System.IO.File]::ReadAllText($destination) | Should -Be 'pre-existing-hook'
    }

    It 'does not place a guessed 64-bit plugin when the game bit-ness cannot be read' {
        # Mutation: treat an unreadable game as 64-bit (the old else branch) -> MAME64.dll is placed for a 32-bit game and counted as installed.
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-unknown-arch')
        $revision = ('7' * 40)
        Mock-FFBTransactionDependencies -Revision $revision
        Mock Get-ExeArchitecture { $null }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        $result.Succeeded | Should -BeFalse
        $result.Deployed | Should -Be 0
        $result.SkippedDllMissing | Should -Be 1
        (Test-Path -LiteralPath (Join-Path $fixture.GameRoot 'd3d9.dll') -PathType Leaf) | Should -BeFalse
    }

    It 'tells an answer from GitHub apart from no answer when the support table cannot be used' {
        # Mutation: return the same empty table for a 4xx or empty file and for a dead connection -> the caller cannot say which one happened.
        Mock Write-Log {}
        Mock Start-Sleep {}
        $revision = ('4' * 40)
        Mock Invoke-TpmWebRequestSilently { throw 'The remote server returned an error: (404) Not Found.' }
        $missing = Get-FFBPluginGameMap -SourceRevision $revision
        ($null -eq $missing) | Should -BeFalse
        $missing.Count | Should -Be 0
        Mock Invoke-TpmWebRequestSilently { [pscustomobject]@{ Content = 'nothing the parser knows' } }
        $empty = Get-FFBPluginGameMap -SourceRevision $revision
        ($null -eq $empty) | Should -BeFalse
        $empty.Count | Should -Be 0
        Mock Invoke-TpmWebRequestSilently { throw 'Unable to connect to the remote server' }
        ($null -eq (Get-FFBPluginGameMap -SourceRevision $revision)) | Should -BeTrue
    }

    It 'says what really happened when the support table is unusable: <Reply>' -ForEach @(
        @{ Reply = 'answered'; Expect = 'GitHub answered, but'; Reject = 'Could not reach GitHub' }
        @{ Reply = 'unreachable'; Expect = 'Could not reach GitHub'; Reject = 'GitHub answered' }
    ) {
        # Mutation: print "Could not reach GitHub ... check your internet" for every empty table -> a user whose connection works is told to fix it.
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive ('ffb-table-' + $Reply))
        $revision = ('5' * 40)
        Mock-FFBTransactionDependencies -Revision $revision
        $script:ffbMapReply = $Reply
        Mock Get-FFBPluginGameMap { if ($script:ffbMapReply -eq 'answered') { @{} } else { $null } }
        $script:ffbMapHost = New-Object System.Collections.Generic.List[string]
        Mock Write-Host { [void]$script:ffbMapHost.Add([string]($Object -join ' ')) }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        $result.Reason | Should -Be 'GAME_MAP_FAILED'
        ($script:ffbMapHost -join "`n") | Should -Match ([regex]::Escape($Expect))
        ($script:ffbMapHost -join "`n") | Should -Not -Match ([regex]::Escape($Reject))
    }
    It 'reports FFB plugin profile-planning progress without changing accounting' {
        $fixture=New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-planning-progress')
        $revision=('9' * 40)
        Mock-FFBTransactionDependencies -Revision $revision
        $script:ffbPlanningProgress=New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress { [void]$script:ffbPlanningProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete }) }

        $result=Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache

        $result.Succeeded | Should -BeTrue
        $result.Accounted | Should -Be 1
        $result.Eligible | Should -Be 1
        $result.Deployed | Should -Be 1
        @($script:ffbPlanningProgress | Where-Object { $_.Label -eq 'FFB plugin profile matching' -and -not $_.Complete -and $_.Total -eq 1 }).Count | Should -Be 1
        @($script:ffbPlanningProgress | Where-Object { $_.Label -eq 'FFB plugin deployment planning' -and -not $_.Complete -and $_.Total -eq 1 }).Count | Should -Be 1
    }

    It 'rolls back a hook when ownership persistence fails' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-ownership-rollback')
        $revision = ('1' * 40)
        Mock-FFBTransactionDependencies -Revision $revision
        Mock Write-FFBPluginOwnership { throw 'ownership persistence failure' }
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache
        $result.Succeeded | Should -BeFalse
        $result.Deployed | Should -Be 0
        (Test-Path -LiteralPath (Join-Path $fixture.GameRoot 'd3d9.dll') -PathType Leaf) | Should -BeFalse
        (Test-Path -LiteralPath (Join-Path $fixture.Cache 'TPM-FFB-Plugin-Ownership.json') -PathType Leaf) | Should -BeFalse
    }

    It 'rolls back deployed hooks when final evidence persistence fails' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-evidence-rollback')
        $revision = ('2' * 40)
        Mock-FFBTransactionDependencies -Revision $revision
        $script:ffbEvidenceWriteCount = 0
        Mock Write-FFBPluginEvidence {
            $script:ffbEvidenceWriteCount++
            if ($script:ffbEvidenceWriteCount -gt 1) { throw 'final evidence persistence failure' }
        }
        $evidencePath = Join-Path $fixture.Root 'Reports\TPM-FFB-Plugin-Evidence.json'
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache -EvidencePath $evidencePath
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'EVIDENCE_WRITE_FAILED'
        $result.RollbackSucceeded | Should -BeTrue
        $result.Deployed | Should -Be 0
        (Test-Path -LiteralPath (Join-Path $fixture.GameRoot 'd3d9.dll') -PathType Leaf) | Should -BeFalse
        (Test-Path -LiteralPath (Join-Path $fixture.Cache 'TPM-FFB-Plugin-Ownership.json') -PathType Leaf) | Should -BeFalse
        $script:ffbEvidenceWriteCount | Should -Be 2
    }
    It 'restores a native-owned hook removed before evidence failure' {
        $fixture = New-FFBTransactionFixture -Root (Join-Path $TestDrive 'ffb-native-evidence-rollback')
        $revision = ('4' * 40)
        $destination = Join-Path $fixture.GameRoot 'd3d9.dll'
        [System.IO.File]::WriteAllText($destination, 'native-owned-hook', (New-Object System.Text.UTF8Encoding($false)))
        $hash = (Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash
        $ownershipPath = Join-Path $fixture.Cache 'TPM-FFB-Plugin-Ownership.json'
        $ownershipText = (@{
            SchemaVersion = 1
            Entries = @([pscustomobject]@{
                ProfileCode='FixtureGame'; GameRoot=$fixture.GameRoot; Destination=$destination
                DeployedSha256=$hash; SourceSha256=$hash; SourceRevision=$revision; SourceTrust='SourcePinnedAuditHash'
            })
        } | ConvertTo-Json -Depth 5)
        [System.IO.File]::WriteAllText($ownershipPath, $ownershipText, (New-Object System.Text.UTF8Encoding($false)))
        Mock-FFBTransactionDependencies -Revision $revision
        Mock Read-HostSafe { 'Y' }
        $script:ffbEvidenceWriteCount = 0
        Mock Write-FFBPluginEvidence {
            $script:ffbEvidenceWriteCount++
            if ($script:ffbEvidenceWriteCount -gt 1) { throw 'final evidence persistence failure' }
        }
        $evidencePath = Join-Path $fixture.Root 'Reports\TPM-FFB-Plugin-Evidence.json'
        $result = Invoke-FFBPluginSetup -UserProfilesDir $fixture.Profiles -CacheDir $fixture.Cache -NativeEnabledCodes @('FixtureGame') -EvidencePath $evidencePath
        $result.Succeeded | Should -BeFalse
        $result.Reason | Should -Be 'EVIDENCE_WRITE_FAILED'
        $result.RollbackSucceeded | Should -BeTrue
        [System.IO.File]::ReadAllText($destination) | Should -Be 'native-owned-hook'
        (Get-Content -LiteralPath $ownershipPath -Raw) | Should -Be $ownershipText
    }

    It 'reports progress while restoring a UserProfiles overlap snapshot' {
        $root=Join-Path $TestDrive 'ffb-overlap-snapshot-rollback'
        $profiles=Join-Path $root 'UserProfiles'
        $cache=Join-Path $root 'Cache'
        $backup=Join-Path $root 'Snapshot'
        New-Item -ItemType Directory -Path $profiles,$cache,$backup -Force | Out-Null
        [System.IO.File]::WriteAllText((Join-Path $profiles 'Game.xml'),'changed')
        [System.IO.File]::WriteAllText((Join-Path $backup 'Game.xml'),'original')
        Mock Restore-FFBPluginOwnershipSnapshot {}
        $script:ffbSnapshotRollbackProgress=New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress { [void]$script:ffbSnapshotRollbackProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete }) }

        $result=Restore-FFBPluginDeploymentTransaction -CacheDir $cache -OwnershipSnapshot ([pscustomobject]@{ Entries=@() }) -UserProfilesDir $profiles -OverlapBackupPath $backup

        $result.Succeeded | Should -BeTrue
        [System.IO.File]::ReadAllText((Join-Path $profiles 'Game.xml')) | Should -Be 'original'
        @($script:ffbSnapshotRollbackProgress | Where-Object { $_.Label -eq 'FFB plugin overlap rollback' -and -not $_.Complete -and $_.Total -eq 1 }).Count | Should -Be 1
        @($script:ffbSnapshotRollbackProgress | Where-Object { $_.Label -eq 'FFB plugin overlap rollback' -and $_.Complete -and $_.Current -eq 1 }).Count | Should -Be 1
        @($script:ffbSnapshotRollbackProgress | Where-Object { $_.Label -eq 'FFB plugin overlap rollback discovery' -and $_.Complete -and $_.Current -eq 1 -and $_.Total -eq 0 }).Count | Should -Be 1
    }
}
Describe "Issue #300 workflow ownership and transition guards" {
    It "rejects unknown workflow steps without emitting an event" {
        $events = New-Object System.Collections.Generic.List[object]
        $facts = [pscustomobject]@{ NoRender = $true }
        $ctx = New-TpmWorkflowStatusContext -WorkflowKey 'unknown-step' -Title 'Unknown step' -Steps @('one','two') -ConsoleFacts $facts -EventSink { param($event) [void]$events.Add($event) }
        [void](Start-TpmWorkflowStatus $ctx)
        { Start-TpmWorkflowStep -Context $ctx -StepId 'missing' } | Should -Throw '*Unknown workflow step*'
        $events.Count | Should -Be 1
        $ctx.ActiveStepId | Should -BeNullOrEmpty
        [void](Stop-TpmWorkflowStatus -Context $ctx -Reason 'test stop')
        [void](Close-TpmWorkflowStatus -Context $ctx)
    }

    It "routes reviewed PostgreSQL and optional-flow failures through lifecycle cleanup" {
        foreach ($failureId in @('postgres-service-state','postgres-install-failed','postgres-backup-unverified','postgres-profile-recovery','postgres-profile-errors','postgres-service-restore','reshade-file-missing','reshade-file-type','dgv-acquisition-canceled','dgv-deployment-failed')) {
            $script:ProductionSource | Should -Match ([regex]::Escape("Resolve-TpmWorkflowFailure -Context"))
            $script:ProductionSource | Should -Match ([regex]::Escape("-FailureId '$failureId'"))
        }
        $script:ProductionSource | Should -Match 'Complete-TpmWorkflowStatus -Context \$postgresStatus'
        $script:ProductionSource | Should -Match 'Close-TpmWorkflowStatus -Context \$postgresStatus'
        $script:ProductionSource | Should -Match 'Close-TpmWorkflowStatus -Context \$reShadeStatus'
        $script:ProductionSource | Should -Match 'Close-TpmWorkflowStatus -Context \$dgStatus'
    }

    It "rejects a second active workflow and releases the first on close" {
        $facts = [pscustomobject]@{ NoRender = $true }
        $first = New-TpmWorkflowStatusContext -WorkflowKey 'first' -Title 'First' -Steps @('one') -ConsoleFacts $facts
        $second = New-TpmWorkflowStatusContext -WorkflowKey 'second' -Title 'Second' -Steps @('one') -ConsoleFacts $facts
        [void](Start-TpmWorkflowStatus $first)
        { Start-TpmWorkflowStatus $second } | Should -Throw '*already active*'
        [void](Stop-TpmWorkflowStatus -Context $first -Reason 'test stop')
        [void](Close-TpmWorkflowStatus -Context $first)
        [void](Start-TpmWorkflowStatus $second)
        [void](Stop-TpmWorkflowStatus -Context $second -Reason 'test stop')
        [void](Close-TpmWorkflowStatus -Context $second)
    }
}

Describe "Issue #300 FFB ownership cleanup" {
    It "removes only an unchanged TPM-owned hook and preserves a backup" {
        $root = Join-Path $TestDrive 'FfbOwnedGame'
        $cache = Join-Path $TestDrive 'FfbCache'
        New-Item -ItemType Directory -Path $root, $cache -Force | Out-Null
        $dest = Join-Path $root 'd3d9.dll'
        Set-Content -LiteralPath $dest -Value 'TPM plugin'
        $hash = (Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash
        Write-FFBPluginOwnership -CacheDir $cache -Entries @([pscustomobject]@{
            ProfileCode = 'OwnedGame'; GameRoot = $root; Destination = $dest
            SourceSha256 = $hash; DeployedSha256 = $hash; CreatedUtc = (Get-Date).ToUniversalTime().ToString('o')
        })
        Remove-FFBPluginOwnedDeployment -CacheDir $cache -ProfileCode 'OwnedGame' | Should -BeTrue
        Test-Path -LiteralPath $dest | Should -BeFalse
        @(Get-ChildItem -LiteralPath (Join-Path $root 'FullBackup') -Recurse -File).Count | Should -Be 1
    }

    It "rolls back ownership deletion when the manifest write fails" {
        $root = Join-Path $TestDrive 'FfbManifestFailureGame'
        $cache = Join-Path $TestDrive 'FfbManifestFailureCache'
        New-Item -ItemType Directory -Path $root, $cache -Force | Out-Null
        $dest = Join-Path $root 'd3d9.dll'
        Set-Content -LiteralPath $dest -Value 'owned-hook'
        $hash = (Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash
        Write-FFBPluginOwnership -CacheDir $cache -Entries @([pscustomobject]@{ ProfileCode = 'FailureGame'; GameRoot = $root; Destination = $dest; SourceSha256 = $hash; DeployedSha256 = $hash; CreatedUtc = (Get-Date).ToUniversalTime().ToString('o') })
        Mock Write-FFBPluginOwnership { throw 'simulated manifest write failure' }

        { Remove-FFBPluginOwnedDeployment -CacheDir $cache -ProfileCode 'FailureGame' } | Should -Throw '*rolled back*'
        (Test-Path -LiteralPath $dest -PathType Leaf) | Should -BeTrue
        (Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash | Should -Be $hash
    }

    It "preserves a changed owned path instead of deleting it" {
        $root = Join-Path $TestDrive 'FfbChangedGame'
        $cache = Join-Path $TestDrive 'FfbChangedCache'
        New-Item -ItemType Directory -Path $root, $cache -Force | Out-Null
        $dest = Join-Path $root 'd3d9.dll'
        Set-Content -LiteralPath $dest -Value 'changed by another tool'
        Write-FFBPluginOwnership -CacheDir $cache -Entries @([pscustomobject]@{
            ProfileCode = 'ChangedGame'; GameRoot = $root; Destination = $dest
            SourceSha256 = ('a' * 64); DeployedSha256 = ('b' * 64); CreatedUtc = (Get-Date).ToUniversalTime().ToString('o')
        })
        Remove-FFBPluginOwnedDeployment -CacheDir $cache -ProfileCode 'ChangedGame' | Should -BeFalse
        Test-Path -LiteralPath $dest | Should -BeTrue
    }
}

Describe "RC8 menu and ReShade regressions" {
    It "does not retain a description-only row after front trimming" {
        $rows = @(
            (New-ConsoleRenderRow -Text '      orphan description'),
            (New-ConsoleRenderRow -Text '  4) Crosshair Setup'),
            (New-ConsoleRenderRow -Text '      Deploy lightgun crosshairs.'),
            (New-ConsoleRenderRow -Text '  5) ReShade Setup')
        )
        $kept = @(Limit-MainMenuBodyRowsToBudget -BodyRows $rows -BodyBudget 3)
        $kept[0].Text | Should -Be '  4) Crosshair Setup'
        @($kept | Where-Object { $_.Text -match 'orphan' }).Count | Should -Be 0
    }

    It "keeps every numbered choice in the supported compact boundary matrix" {
        foreach ($height in @(10, 11, 12)) {
            $tier = Get-ConsoleLayoutTier -Width 60 -Height $height
            $screen = Render-MainMenuScreen -Tier $tier -Width 60 -Height $height
            $text = ($screen.Rows | ForEach-Object { $_.Text }) -join "`n"
            foreach ($number in 1..17) {
                ([regex]::Matches($text, ("(?m)(?<!\d){0}\)" -f $number))).Count | Should -Be 1
            }
        }
    }

    It "normal ReShade setup does not require a preset path" {
        $source = Get-Content -LiteralPath (Join-Path $PSScriptRoot '..\TeknoParrot-Manager.ps1') -Raw
        $source | Should -Match 'Read-TpmReShadeTerminalProfile'
        $source | Should -Not -Match 'Use the selected ReShade profile\?'
        $source | Should -Not -Match 'Get it at\s+https://reshade\.me'
        $source | Should -Not -Match 'replace ReShade\\ReShade64\.dll'
    }
    It "provides a visible terminal fallback chooser with explicit selection and Back" {
        $profiles = @(Get-TpmReShadeProfiles)
        $script:chooserInputs = [System.Collections.Generic.Queue[string]]::new()
        # Mutation: move CrtGlow away from the 7th entry of Get-TpmReShadeProfiles (arcade order) -> typing 7 selects another profile.
        [void]$script:chooserInputs.Enqueue('7')
        [void]$script:chooserInputs.Enqueue('U')
        Mock Test-TpmConsoleInputRedirected { $true }
        Mock Read-HostSafe { $script:chooserInputs.Dequeue() }
        Mock Write-Host {}
        Mock Write-Log {}
        $selected = Read-TpmReShadeTerminalProfile -Profiles $profiles
        $selected.Cancelled | Should -BeFalse
        $selected.SelectedProfile.ProfileId | Should -Be 'CrtGlow'

        $script:chooserInputs = [System.Collections.Generic.Queue[string]]::new()
        [void]$script:chooserInputs.Enqueue('B')
        $back = Read-TpmReShadeTerminalProfile -Profiles $profiles
        $back.Cancelled | Should -BeTrue
        $back.SelectedProfile | Should -BeNullOrEmpty
    }
    # RPSI-SELECTION-008
    It "selects the seventeenth (last) profile, Levels, by its two-digit number in the terminal and synchronizes the preview" {
        # Mutation: drop or add a profile so Levels is no longer number 17 (the list is Original plus 16 profiles).
        $profiles = @(Get-TpmReShadeProfiles)
        $profileSelector = [pscustomobject]@{ SelectedIndex = 0 }
        $session = [hashtable]::Synchronized(@{
            Initialized = $true
            Closed = $false
            PreviewEnabled = $true
            SelectedProfileId = 'Original'
            Profiles = $profiles
            ProfileSelector = $profileSelector
            Refresh = $null
        })
        $previewRefreshSelections = New-Object System.Collections.Generic.List[string]
        $session.Refresh = {
            [void]$previewRefreshSelections.Add([string]$session['SelectedProfileId'])
            return $true
        }.GetNewClosure()
        $script:chooserInputs = [System.Collections.Generic.Queue[string]]::new()
        [void]$script:chooserInputs.Enqueue('17')
        [void]$script:chooserInputs.Enqueue('U')
        [void]$script:chooserInputs.Enqueue('B')
        Mock Read-TpmReShadeTerminalInput { $script:chooserInputs.Dequeue() }
        Mock Write-Host {}
        Mock Write-Log {}

        $result = Read-TpmReShadeTerminalProfile -Profiles $profiles -PreviewSession $session

        $result.SelectedProfile.ProfileId | Should -Be 'Levels'
        $session.SelectedProfileId | Should -Be 'Levels'
        $previewRefreshSelections.Count | Should -Be 1
        $previewRefreshSelections[0] | Should -Be 'Levels'
        $profileSelector.SelectedIndex | Should -Be (Get-TpmReShadeProfileSelectorIndex -Rows (Get-TpmReShadeProfileSelectorRows -Profiles $profiles) -ProfileId 'Levels')
        $session.ProfileSelectorUpdating | Should -BeFalse
    }
    It "selects a profile directly in the preview and synchronizes canonical state" {
        $profiles = @(Get-TpmReShadeProfiles)
        # Mutation: change the profile list or effect catalog size (17 profiles, 25 effects).
        $profiles.Count | Should -Be 17
        @(Get-TpmReShadeEffectCatalog).Count | Should -Be 25
        $profileSelector = [pscustomobject]@{ SelectedIndex = 0 }
        $refreshed = New-Object System.Collections.Generic.List[string]
        $session = [hashtable]::Synchronized(@{
            Initialized = $true
            Closed = $false
            PreviewEnabled = $true
            SelectedProfileId = 'Original'
            ViewMode = 'Slider'
            SliderPosition = 30
            Profiles = $profiles
            ProfileIds = @($profiles | ForEach-Object ProfileId)
            ProfileSelector = $profileSelector
            Refresh = $null
        })
        $session.Refresh = {
            [void]$refreshed.Add([string]$session['SelectedProfileId'])
            return $true
        }.GetNewClosure()
        Mock Write-Log {}
        Mock Write-Host {}
        $handlers = New-TpmReShadeGalleryEventHandlers -State $session
        $vignette = @($profiles | Where-Object ProfileId -eq 'ArcadeGlow')[0]

        & $handlers.ProfileSelection ([pscustomobject]@{ SelectedItem = $vignette }) $null

        $session.PreviewEnabled | Should -BeTrue
        $session['PreviewFailureStage'] | Should -BeNullOrEmpty
        $session.SelectedProfileId | Should -Be 'ArcadeGlow'
        $refreshed.Count | Should -Be 1
        $refreshed[0] | Should -Be 'ArcadeGlow'
        $profileSelector.SelectedIndex | Should -Be (Get-TpmReShadeProfileSelectorIndex -Rows (Get-TpmReShadeProfileSelectorRows -Profiles $profiles) -ProfileId 'ArcadeGlow')
        $session.ProfileSelectorUpdating | Should -BeFalse
        $session.ViewMode | Should -Be 'Slider'
        $session.SliderPosition | Should -Be 30
    }
    It "fails closed for a non-catalog profile selected in the preview" {
        $profiles = @(Get-TpmReShadeProfiles)
        $session = [hashtable]::Synchronized(@{
            Initialized = $true
            Closed = $false
            PreviewEnabled = $true
            SelectedProfileId = 'Original'
            Profiles = $profiles
            Refresh = { return $true }.GetNewClosure()
        })
        Mock Write-Log {}
        $handlers = New-TpmReShadeGalleryEventHandlers -State $session

        & $handlers.ProfileSelection ([pscustomobject]@{ SelectedItem = [pscustomobject]@{ ProfileId = 'Unapproved' } }) $null

        $session.PreviewEnabled | Should -BeFalse
        $session.PreviewFailureStage | Should -Be 'profile-selection-handler'
    }
    It "ignores direct profile changes before initialization and after closure" {
        $profiles = @(Get-TpmReShadeProfiles)
        foreach ($state in @(
            [hashtable]::Synchronized(@{ Initialized = $false; Closed = $false; PreviewEnabled = $true; SelectedProfileId = 'Original'; Profiles = $profiles }),
            [hashtable]::Synchronized(@{ Initialized = $true; Closed = $true; PreviewEnabled = $true; SelectedProfileId = 'Original'; Profiles = $profiles })
        )) {
            $handlers = New-TpmReShadeGalleryEventHandlers -State $state
            & $handlers.ProfileSelection ([pscustomobject]@{ SelectedItem = @($profiles | Where-Object ProfileId -eq 'ArcadeGlow')[0] }) $null
            $state.SelectedProfileId | Should -Be 'Original'
            $state.PreviewEnabled | Should -BeTrue
        }
    }
    It "accepts the latest preview selection when terminal input returns" {
        $profiles = @(Get-TpmReShadeProfiles)
        $session = [hashtable]::Synchronized(@{
            Initialized = $true
            Closed = $false
            PreviewEnabled = $true
            SelectedProfileId = 'Original'
            Profiles = $profiles
            ProfileIds = @($profiles | ForEach-Object ProfileId)
            Refresh = { return $true }.GetNewClosure()
        })
        Mock Write-Log {}
        Mock Write-Host {}
        Mock Read-TpmReShadeTerminalInput {
            $session.SelectedProfileId = 'ArcadeGlow'
            return 'U'
        }

        $result = Read-TpmReShadeTerminalProfile -Profiles $profiles -DefaultProfileId 'Original' -PreviewSession $session

