        Add-Member -InputObject $selector -MemberType ScriptProperty -Name SelectedIndex -Value { $this.Backing } -SecondValue {
            param($value)
            $this.FlagAtAssignment = [bool]$this.Owner['ProfileSelectorUpdating']
            $this.Backing = $value
        }
        $session = [hashtable]::Synchronized(@{
