        Should -Invoke Write-Log -Times 1 -ParameterFilter { $msg -like '*SourceDll was empty or did not resolve*' }
        Should -Invoke Show-TpmReShadeProfileGalleryWindow -Times 0 -Exactly
        Should -Invoke Read-TpmReShadeTerminalProfile -Times 0 -Exactly
        Should -Invoke Read-TpmChoice -Times 0 -Exactly
        Should -Invoke Install-TpmReShadeProfileDeployment -Times 0 -Exactly
    }
    It "returns Acquired for a valid Browse DLL and Skipped for an intentional Skip" {
        $dllPath = Join-Path $TestDrive 'existing-reshade.dll'
        [System.IO.File]::WriteAllText($dllPath, 'fixture')

        $acquired = Resolve-ReShadeDllAcquisition -Choice 'B' -InputPath $dllPath
        $acquired.State | Should -Be 'Acquired'
        $acquired.Path | Should -Be $dllPath

        $skipped = Resolve-ReShadeDllAcquisition -Choice 'N' -InputPath $null
        $skipped.State | Should -Be 'Skipped'
        $skipped.Path | Should -BeNullOrEmpty
    }

    It "returns Invalid for missing, non-leaf, and non-DLL Browse paths" {
        $missing = Resolve-ReShadeDllAcquisition -Choice 'B' -InputPath (Join-Path $TestDrive 'missing.dll')
        $missing.State | Should -Be 'Invalid'
        $missing.Reason | Should -Be 'FileMissing'

        $directory = Join-Path $TestDrive 'directory.dll'
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
        $nonLeaf = Resolve-ReShadeDllAcquisition -Choice 'B' -InputPath $directory
        $nonLeaf.State | Should -Be 'Invalid'
        $nonLeaf.Reason | Should -Be 'FileMissing'

        $textPath = Join-Path $TestDrive 'not-a-dll.txt'
        [System.IO.File]::WriteAllText($textPath, 'fixture')
        $wrongType = Resolve-ReShadeDllAcquisition -Choice 'B' -InputPath $textPath
        $wrongType.State | Should -Be 'Invalid'
        $wrongType.Reason | Should -Be 'FileType'
    }


    It "wires the ReShade acquisition result into the existing cancellation guard" {
        $source = $script:ProductionSource
        $acquisitionCall = $source.IndexOf('$rsAcquisition = Resolve-ReShadeDllAcquisition -Choice $rsGetChoice -InputPath $inp')
        $acquisitionCall | Should -BeGreaterThan -1
        $stateIndex = $source.IndexOf('$rsGotDll    = $true', $acquisitionCall)
        $cancelIndex = $source.IndexOf("Write-Host '  ReShade setup canceled. No unverified DLL was used.'", $acquisitionCall)
        $stateIndex | Should -BeGreaterThan $acquisitionCall
        $cancelIndex | Should -BeGreaterThan $stateIndex
        $source.Substring($acquisitionCall, $cancelIndex - $acquisitionCall) | Should -Match '(?s)\$rsSourceDll\s*=\s*\$rsAcquisition\.Path\s*\r?\n\s*\$rsGotDll\s*=\s*\$true'
        $source | Should -Match 'if \(\$rsAcquisition\.State -eq ''Acquired''\)'
    }

    It "keeps source-level validation and Skip handling supplemental to acquisition behavior tests" {
        $source = $script:ProductionSource
        $helperStart = $source.IndexOf('function Resolve-ReShadeDllAcquisition')
        $helperEnd = $source.IndexOf('function Invoke-ReShadeSetup', $helperStart)
        $helper = $source.Substring($helperStart, $helperEnd - $helperStart)
        $helper | Should -Match 'Test-Path -LiteralPath \$InputPath -PathType Leaf'
        $helper | Should -Match 'GetExtension\(\$InputPath\)\.ToLowerInvariant\(\) -ne ''.dll'''
        $helper | Should -Match "State  = 'Skipped'"
        $source | Should -Match "FailureId 'reshade-file-missing'"
        $source | Should -Match "FailureId 'reshade-file-type'"
    }

    It "keeps ReShade DLL signature inspection and disclosure before deployment" {
        $source = $script:ProductionSource
        $invokeStart = $source.IndexOf('function Invoke-ReShadeSetup')
        $signatureCheck = $source.IndexOf('Get-TpmReShadeDllCheck -Path $SourceDll -Label', $invokeStart)
        $reviewWarning = $source.IndexOf('Get-TpmReShadeDllNoticeLines -Checks $dllChecks', $signatureCheck)
        $deployment = $source.IndexOf('Installing ReShade into', $signatureCheck)
        $signatureCheck | Should -BeGreaterThan $invokeStart
        $reviewWarning | Should -BeGreaterThan $signatureCheck
        $deployment | Should -BeGreaterThan $reviewWarning
        $checkHelper = [regex]::Match($source, '(?s)function Get-TpmReShadeDllCheck \{.*?\r?\n\}\r?\n').Value
        $checkHelper | Should -Match 'Test-ReShadeDllSignature -Path \$Path'
        $checkHelper | Should -Match 'Get-FileHash -LiteralPath \$Path -Algorithm SHA256'
    }
    It "preserves the requested ReShade profile when reopening the gallery" {
        $source = $script:ProductionSource
        $galleryStart = $source.IndexOf('function Show-TpmReShadeProfileGalleryWindow')
        $selectedAssignment = $source.IndexOf('$state[''SelectedProfileId''] = [string]$defaultProfile.ProfileId', $galleryStart)
        $galleryStart | Should -BeGreaterOrEqual 0
        $selectedAssignment | Should -BeGreaterThan $galleryStart
        $source.Substring($galleryStart, $selectedAssignment - $galleryStart) | Should -Match 'DefaultProfileId'
        $source | Should -Match 'Show-TpmReShadeProfileGalleryWindow -Profiles \$selectable -DefaultProfileId \$reopenId -Show -NonModal'
        $galleryBody = [regex]::Match($source, '(?s)function Show-TpmReShadeProfileGalleryWindow \{.*?function Close-TpmReShadeProfileGallerySession').Value

    }
}
Describe "ReShade removal safety and workflow" {
    It "emits separate scan records for removable, protected, missing, malformed, changed, and clean games" {
        $root = Join-Path $TestDrive 'reshade-removal-scan'
        $profilesDir = Join-Path $root 'UserProfiles'
        $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        $makeProfile = {
            param($name, $gamePath, $xml = $null)
            if ($null -eq $xml) { $xml = '<GameProfile><GamePath>' + $gamePath + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>' }
            [IO.File]::WriteAllText((Join-Path $profilesDir ($name + '.xml')), $xml)
        }
        $ownedDir = Join-Path $root 'owned'; [IO.Directory]::CreateDirectory($ownedDir) | Out-Null
        $ownedGame = Join-Path $ownedDir 'game.exe'; [IO.File]::WriteAllText($ownedGame, 'game')
        $ownedHook = Join-Path $ownedDir 'dxgi.dll'; [IO.File]::WriteAllText($ownedHook, 'owned')
        & $makeProfile 'Owned' $ownedGame
        $ownedHash = (Get-FileHash -LiteralPath $ownedHook -Algorithm SHA256).Hash
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$ownedHook; ExpectedSHA256=$ownedHash; ActualSHA256=$ownedHash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId Owned -StateRoot $stateRoot)
        $bundleDir = Join-Path $root 'bundled'; [IO.Directory]::CreateDirectory($bundleDir) | Out-Null
        $bundleGame = Join-Path $bundleDir 'game.exe'; $bundleHook = Join-Path $bundleDir 'dxgi.dll'; [IO.File]::WriteAllText($bundleGame, 'game'); [IO.File]::WriteAllText($bundleHook, 'preinstalled')
        & $makeProfile 'Bundled' $bundleGame
        $bundleHash = (Get-FileHash -LiteralPath $bundleHook -Algorithm SHA256).Hash
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$bundleHook; ExpectedSHA256=$bundleHash; ActualSHA256=$bundleHash; TPMManaged=$false; Kind='ReShadeDll' }) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId Bundled -StateRoot $stateRoot)
        $changedDir = Join-Path $root 'changed'; [IO.Directory]::CreateDirectory($changedDir) | Out-Null
        $changedGame = Join-Path $changedDir 'game.exe'; $changedHook = Join-Path $changedDir 'dxgi.dll'; [IO.File]::WriteAllText($changedGame, 'game'); [IO.File]::WriteAllText($changedHook, 'changed')
        & $makeProfile 'Changed' $changedGame
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$changedHook; ExpectedSHA256=('0' * 64); ActualSHA256=('0' * 64); TPMManaged=$true; Kind='ReShadeDll' }) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId Changed -StateRoot $stateRoot)
        $cleanDir = Join-Path $root 'clean'; [IO.Directory]::CreateDirectory($cleanDir) | Out-Null
        $cleanGame = Join-Path $cleanDir 'game.exe'; [IO.File]::WriteAllText($cleanGame, 'game'); & $makeProfile 'Clean' $cleanGame
        & $makeProfile 'Missing' (Join-Path $root 'missing.exe')
        & $makeProfile 'Malformed' '' '<NotGameProfile />'
        $outsideDir = Join-Path $root 'outside'; [IO.Directory]::CreateDirectory($outsideDir) | Out-Null
        $outsideGame = Join-Path $outsideDir 'game.exe'; $outsideFile = Join-Path $root 'must-not-delete.txt'; [IO.File]::WriteAllText($outsideGame, 'game'); [IO.File]::WriteAllText($outsideFile, 'outside')
        & $makeProfile 'Outside' $outsideGame
        $outsideHash = (Get-FileHash -LiteralPath $outsideFile -Algorithm SHA256).Hash
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='outside.txt'; DestinationPath=$outsideFile; ExpectedSHA256=$outsideHash; ActualSHA256=$outsideHash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId Outside -StateRoot $stateRoot)
        $unownedDir = Join-Path $root 'unowned'; [IO.Directory]::CreateDirectory($unownedDir) | Out-Null
        $unownedGame = Join-Path $unownedDir 'game.exe'; $unownedHook = Join-Path $unownedDir 'dxgi.dll'; [IO.File]::WriteAllText($unownedGame, 'game'); [IO.File]::WriteAllText($unownedHook, 'unowned'); & $makeProfile 'Unowned' $unownedGame
        $script:reshadeScanProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:reshadeScanProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
        }
        $scan = Get-TpmReShadeRemovalScan -UserProfilesDir $profilesDir -StateRoot $stateRoot
        ($scan.Records | Where-Object GameId -eq 'Owned').Status | Should -Be 'Removable'
        @($script:reshadeScanProgress | Where-Object { $_.Label -eq 'ReShade removal scan' -and $_.Total -eq 8 -and -not $_.Complete }).Count | Should -Be 8
        @($script:reshadeScanProgress | Where-Object { $_.Label -eq 'ReShade removal scan' -and $_.Complete }).Count | Should -Be 1
        $discovery = @($script:reshadeScanProgress | Where-Object { $_.Label -eq 'ReShade removal profile discovery' })
        (@($discovery | Where-Object { -not $_.Complete } | ForEach-Object Current) -join ',') | Should -Be '0,1,2,3,4,5,6,7,8'
        @($discovery | Where-Object { $_.Complete -and $_.Current -eq 8 -and $_.Total -eq 0 }).Count | Should -Be 1
        ($scan.Records | Where-Object GameId -eq 'Bundled').Status | Should -Be 'ProtectedBundled'
        ($scan.Records | Where-Object GameId -eq 'Changed').Status | Should -Be 'Changed'
        ($scan.Records | Where-Object GameId -eq 'Missing').Status | Should -Be 'MissingPath'
        ($scan.Records | Where-Object GameId -eq 'Malformed').Status | Should -Be 'MalformedMetadata'
        ($scan.Records | Where-Object GameId -eq 'Clean').Status | Should -Be 'AlreadyClean'
        ($scan.Records | Where-Object GameId -eq 'Outside').Status | Should -Be 'ProtectedAmbiguous'
        @($scan.Reviewable | ForEach-Object GameId) | Should -Contain 'Owned'
        @($scan.Reviewable | ForEach-Object GameId) | Should -Contain 'Bundled'
        ($scan.Records | Where-Object GameId -eq 'Unowned').Status | Should -Be 'ProtectedAmbiguous'
        @((($scan.Records | Where-Object GameId -eq 'Unowned').ProtectedFiles | ForEach-Object DestinationPath)) | Should -Contain $unownedHook
        @((($scan.Records | Where-Object GameId -eq 'Owned').RemovableFiles | ForEach-Object DestinationPath)) | Should -Contain $ownedHook
        @($scan.Reviewable | ForEach-Object GameId) | Should -Not -Contain 'Clean'
        @($scan.Reviewable | ForEach-Object GameId) | Should -Not -Contain 'Missing'
        $script:summaryPrompt = 0
        Mock Read-HostSafe { if ($script:summaryPrompt++ -eq 0) { 'A' } else { 'REMOVE' } }
        $summary = Invoke-TpmReShadeRemoval -UserProfilesDir $profilesDir -StateRoot $stateRoot -BackupRoot (Join-Path $profilesDir 'FullBackup')
        $summary.Removed | Should -Be 1
        $summary.AlreadyClean | Should -Be 1
        $summary.MissingPath | Should -Be 1
        $summary.ProtectedBundled | Should -Be 1
        $summary.ProtectedAmbiguous | Should -Be 2
        $summary.Changed | Should -Be 1
        $summary.MalformedMetadata | Should -Be 1
        $summary.RolledBack | Should -Be 0
        $summary.Failed | Should -Be 0
        $summary.Results.Count | Should -Be 5
        Test-Path -LiteralPath $bundleHook -PathType Leaf | Should -BeTrue
        Test-Path -LiteralPath $unownedHook -PathType Leaf | Should -BeTrue
    }
    It "passes only filtered reviewable profiles through the existing chooser" {
        $root = Join-Path $TestDrive 'reshade-filtered-chooser'
        [IO.Directory]::CreateDirectory($root) | Out-Null
        $fullBackup = Join-Path $root 'FullBackup'; [IO.Directory]::CreateDirectory($fullBackup) | Out-Null
        foreach ($name in @('A','B','C')) { [IO.File]::WriteAllText((Join-Path $root ($name + '.xml')), '<GameProfile />') }
        [IO.File]::WriteAllText((Join-Path $fullBackup 'Hidden.xml'), '<GameProfile />')
        $filtered = @(Get-ChildItem -LiteralPath $root -Filter '*.xml' -File | Where-Object BaseName -in @('A','C'))
        Mock Read-HostSafe { 'A' }
        $selected = @(Select-RegisteredGamesInteractive -UserProfilesDir $root -Profiles $filtered)
        @($selected | ForEach-Object BaseName) | Should -Be @('A','C')
        $selected | Should -Not -Contain (Get-Item -LiteralPath (Join-Path $root 'B.xml'))
        $selected | Should -Not -Contain (Get-Item -LiteralPath (Join-Path $fullBackup 'Hidden.xml'))
    }
    It "requires confirmation and removes only verified owned files with a backup" {
        $root = Join-Path $TestDrive 'reshade-removal-flow'; $profilesDir = Join-Path $root 'UserProfiles'; $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        $game = Join-Path $root 'game.exe'; $hook = Join-Path $root 'dxgi.dll'; [IO.File]::WriteAllText($game, 'game'); [IO.File]::WriteAllText($hook, 'owned')
        [IO.File]::WriteAllText((Join-Path $profilesDir 'Flow.xml'), '<GameProfile><GamePath>' + $game + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>')
        $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$hook; ExpectedSHA256=$hash; ActualSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId Flow -StateRoot $stateRoot)
        $script:reshadeRemovalProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:reshadeRemovalProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
        }
        $scan = Get-TpmReShadeRemovalScan -UserProfilesDir $profilesDir -StateRoot $stateRoot
        $notConfirmed = Remove-TpmReShadeOwnedDeployment -ScanRecord @($scan.Records | Where-Object { $_.Status -eq 'Removable' })[0] -UserProfilesDir $profilesDir -BackupRoot (Join-Path $profilesDir 'FullBackup') -StateRoot $stateRoot
        $notConfirmed.Status | Should -Be 'ConfirmationRequired'; Test-Path -LiteralPath $hook -PathType Leaf | Should -BeTrue
        $script:removePrompt = 0
        Mock Read-HostSafe { if ($script:removePrompt++ -eq 0) { 'A' } else { 'REMOVE' } }
        $result = Invoke-TpmReShadeRemoval -UserProfilesDir $profilesDir -StateRoot $stateRoot
        $result.Removed | Should -Be 1
        Test-Path -LiteralPath $hook -PathType Leaf | Should -BeFalse
        @((Get-ChildItem -LiteralPath (Join-Path $profilesDir 'FullBackup') -Recurse -File -ErrorAction SilentlyContinue)).Count | Should -BeGreaterThan 0
        @($result.Scan.Records | Where-Object { $_.Status -eq 'MissingPath' }).Count | Should -Be 0
        foreach ($label in @('ReShade removal scan','ReShade removal validation','ReShade removal backup','ReShade removal')) {
            $expectedRows = if ($label -eq 'ReShade removal scan') { 2 } else { 1 }
            @($script:reshadeRemovalProgress | Where-Object { $_.Label -eq $label -and $_.Current -eq 1 -and $_.Total -eq 1 -and -not $_.Complete }).Count | Should -Be $expectedRows
            @($script:reshadeRemovalProgress | Where-Object { $_.Label -eq $label -and $_.Complete }).Count | Should -Be $expectedRows
        }
    }
    It "rejects a manifest destination moved outside target before backup" {
        $root = Join-Path $TestDrive 'reshade-removal-moved-destination'; $profilesDir = Join-Path $root 'UserProfiles'; $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        $game = Join-Path $root 'game.exe'; $hook = Join-Path $root 'dxgi.dll'; $outside = Join-Path $root 'outside.txt'
        [IO.File]::WriteAllText($game, 'game'); [IO.File]::WriteAllText($hook, 'owned'); [IO.File]::WriteAllText($outside, 'outside')
        [IO.File]::WriteAllText((Join-Path $profilesDir 'Moved.xml'), '<GameProfile><GamePath>' + $game + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>')
        $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash
        $ownership = Get-TpmReShadeProfileOwnershipPath -GameId Moved -StateRoot $stateRoot
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$hook; ExpectedSHA256=$hash; ActualSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path $ownership
        $scan = Get-TpmReShadeRemovalScan -UserProfilesDir $profilesDir -StateRoot $stateRoot
        $removable = @($scan.Records | Where-Object { $_.Status -eq 'Removable' })[0]
        $removable.RemovableFiles[0].DestinationPath = $outside
        $result = Remove-TpmReShadeOwnedDeployment -ScanRecord $removable -UserProfilesDir $profilesDir -BackupRoot (Join-Path $profilesDir 'FullBackup') -StateRoot $stateRoot -ConfirmRemoval
        $result.Status | Should -Be 'RolledBack'
        Test-Path -LiteralPath $hook -PathType Leaf | Should -BeTrue
        Test-Path -LiteralPath $outside -PathType Leaf | Should -BeTrue
        Test-Path -LiteralPath $ownership -PathType Leaf | Should -BeTrue
    }
    It "rejects changed profile metadata before backup" {
        $root = Join-Path $TestDrive 'reshade-removal-profile-change'; $profilesDir = Join-Path $root 'UserProfiles'; $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        $game = Join-Path $root 'game.exe'; $hook = Join-Path $root 'dxgi.dll'; [IO.File]::WriteAllText($game, 'game'); [IO.File]::WriteAllText($hook, 'owned')
        $profilePath = Join-Path $profilesDir 'ProfileChange.xml'
        $defaultXml = '<GameProfile><GamePath>' + $game + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>'
        [IO.File]::WriteAllText($profilePath, $defaultXml)
        $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$hook; ExpectedSHA256=$hash; ActualSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId ProfileChange -StateRoot $stateRoot)
        $scan = Get-TpmReShadeRemovalScan -UserProfilesDir $profilesDir -StateRoot $stateRoot
        [IO.File]::WriteAllText($profilePath, $defaultXml.Replace('<EmulatorType>Default</EmulatorType>','<EmulatorType>BudgieLoader</EmulatorType>'))
        $result = Remove-TpmReShadeOwnedDeployment -ScanRecord @($scan.Records | Where-Object { $_.Status -eq 'Removable' })[0] -UserProfilesDir $profilesDir -BackupRoot (Join-Path $profilesDir 'FullBackup') -StateRoot $stateRoot -ConfirmRemoval
        $result.Status | Should -Be 'RolledBack'
        $result.Detail | Should -Match 'EmulatorType changed'
        Test-Path -LiteralPath $hook -PathType Leaf | Should -BeTrue
    }
    It "rechecks profile metadata immediately before deletion" {
        $root = Join-Path $TestDrive 'rr-del'; $profilesDir = Join-Path $root 'UserProfiles'; $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        $game = Join-Path $root 'game.exe'; $hook = Join-Path $root 'dxgi.dll'; [IO.File]::WriteAllText($game, 'game'); [IO.File]::WriteAllText($hook, 'owned')
        $profilePath = Join-Path $profilesDir 'DeleteRecheck.xml'
        $defaultXml = '<GameProfile><GamePath>' + $game + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>'
        [IO.File]::WriteAllText($profilePath, $defaultXml)
        $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash
        $ownership = Get-TpmReShadeProfileOwnershipPath -GameId DeleteRecheck -StateRoot $stateRoot
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$hook; ExpectedSHA256=$hash; ActualSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path $ownership
        $scan = Get-TpmReShadeRemovalScan -UserProfilesDir $profilesDir -StateRoot $stateRoot
        $script:reshadeMutation = $false
        $script:reshadeMutationProfile = $profilePath
        $script:reshadeMutationXml = $defaultXml.Replace('<EmulatorType>Default</EmulatorType>','<EmulatorType>BudgieLoader</EmulatorType>')
        Mock Copy-Item {
            param($LiteralPath, $Destination)
            [IO.File]::Copy($LiteralPath, $Destination, $true)
            if (-not $script:reshadeMutation -and [IO.Path]::GetFileName($Destination) -eq 'ownership.json') {
                $script:reshadeMutation = $true
                [IO.File]::WriteAllText($script:reshadeMutationProfile, $script:reshadeMutationXml)
            }
        }
        $result = Remove-TpmReShadeOwnedDeployment -ScanRecord @($scan.Records | Where-Object { $_.Status -eq 'Removable' })[0] -UserProfilesDir $profilesDir -BackupRoot (Join-Path $profilesDir 'FullBackup') -StateRoot $stateRoot -ConfirmRemoval
        $result.Status | Should -Be 'RolledBack'
        $result.Detail | Should -Match 'EmulatorType changed'
        $script:reshadeMutation | Should -BeTrue
        Test-Path -LiteralPath $hook -PathType Leaf | Should -BeTrue
        Test-Path -LiteralPath $ownership -PathType Leaf | Should -BeTrue
    }

    It "cancel after the preview leaves files and ownership unchanged" {
        $root = Join-Path $TestDrive 'reshade-removal-cancel'; $profilesDir = Join-Path $root 'UserProfiles'; $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        $game = Join-Path $root 'game.exe'; $hook = Join-Path $root 'dxgi.dll'; [IO.File]::WriteAllText($game, 'game'); [IO.File]::WriteAllText($hook, 'owned')
        [IO.File]::WriteAllText((Join-Path $profilesDir 'Cancel.xml'), '<GameProfile><GamePath>' + $game + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>')
        $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash
        $ownership = Get-TpmReShadeProfileOwnershipPath -GameId Cancel -StateRoot $stateRoot
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$hook; ExpectedSHA256=$hash; ActualSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path $ownership
        $script:cancelPrompt = 0
        Mock Read-HostSafe { if ($script:cancelPrompt++ -eq 0) { 'A' } else { '' } }
        $result = Invoke-TpmReShadeRemoval -UserProfilesDir $profilesDir -StateRoot $stateRoot -BackupRoot (Join-Path $profilesDir 'FullBackup')
        $result.Cancelled | Should -BeTrue
        Test-Path -LiteralPath $hook -PathType Leaf | Should -BeTrue
        Test-Path -LiteralPath $ownership -PathType Leaf | Should -BeTrue
    }
    It "rolls back removed files and ownership when manifest commit fails" {
        $root = Join-Path $TestDrive 'reshade-removal-rollback'; $profilesDir = Join-Path $root 'UserProfiles'; $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        $game = Join-Path $root 'game.exe'; $hook = Join-Path $root 'dxgi.dll'; $keep = Join-Path $root 'user.ini'; [IO.File]::WriteAllText($game, 'game'); [IO.File]::WriteAllText($hook, 'owned'); [IO.File]::WriteAllText($keep, 'keep')
        [IO.File]::WriteAllText((Join-Path $profilesDir 'Rollback.xml'), '<GameProfile><GamePath>' + $game + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>')
        $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash; $keepHash = (Get-FileHash -LiteralPath $keep -Algorithm SHA256).Hash
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@(
            [pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$hook; ExpectedSHA256=$hash; ActualSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' },
            [pscustomobject]@{ RelativeSource='user.ini'; DestinationPath=$keep; ExpectedSHA256=$keepHash; ActualSHA256=$keepHash; TPMManaged=$false; Kind='ReShadePreset' }
        ) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId Rollback -StateRoot $stateRoot)
        $script:reshadeRemovalRollbackProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:reshadeRemovalRollbackProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
        }
        $scan = Get-TpmReShadeRemovalScan -UserProfilesDir $profilesDir -StateRoot $stateRoot
        # With no ReShade runtime entry left the product deletes the manifest instead of saving it, so fail both writers.
        $script:reshadeRollbackManifestPath = Get-TpmReShadeProfileOwnershipPath -GameId Rollback -StateRoot $stateRoot
        Mock Save-TpmReShadeOwnershipManifest { throw 'simulated manifest commit failure' }
        Mock Remove-Item { throw 'simulated manifest commit failure' } -ParameterFilter { $LiteralPath -eq $script:reshadeRollbackManifestPath }
        $result = Remove-TpmReShadeOwnedDeployment -ScanRecord @($scan.Records | Where-Object { $_.Status -eq 'Removable' })[0] -UserProfilesDir $profilesDir -BackupRoot (Join-Path $profilesDir 'FullBackup') -StateRoot $stateRoot -ConfirmRemoval
        $result.Status | Should -Be 'RolledBack'
        Test-Path -LiteralPath $hook -PathType Leaf | Should -BeTrue
        Test-Path -LiteralPath $keep -PathType Leaf | Should -BeTrue
        (Read-TpmReShadeOwnershipManifest -Path (Get-TpmReShadeProfileOwnershipPath -GameId Rollback -StateRoot $stateRoot)).Files.Count | Should -Be 2
        @($script:reshadeRemovalRollbackProgress | Where-Object { $_.Label -eq 'ReShade removal rollback' -and $_.Current -eq 1 -and $_.Total -eq 1 -and -not $_.Complete }).Count | Should -Be 1
        @($script:reshadeRemovalRollbackProgress | Where-Object { $_.Label -eq 'ReShade removal rollback' -and $_.Complete }).Count | Should -Be 1
    }
    It "wires the ReShade mode action to the end-to-end removal path" {
        $source = $script:ProductionSource
        $source | Should -Match 'Invoke-TpmReShadeRemoval -UserProfilesDir \$userProfilesDir'
        $source | Should -Match 'Type REMOVE to back up and remove verified TeknoParrot Manager-owned files'
        $source | Should -Match 'Remove-TpmReShadeOwnedDeployment'
        $source | Should -Match 'REMOVE \{0\}: \{1\} \[\{2\}\]'
        $source | Should -Match 'Removed effects from'
        $source | Should -Match 'Protected bundled/preinstalled'
        $source | Should -Match 'Protected ambiguous/needs review'
        $source | Should -Match 'Skipped missing path'
        $source | Should -Match 'ReShade removal preview REMOVE'
        $source | Should -Match 'ReShade removal preview KEEP protected'
        $source | Should -Match 'ReShade removal preview KEEP changed'
    }
    It "supports multiple explicit filtered chooser selections" {
        $root = Join-Path $TestDrive 'reshade-multiple-chooser'; [IO.Directory]::CreateDirectory($root) | Out-Null
        foreach ($name in @('A','B','C')) { [IO.File]::WriteAllText((Join-Path $root ($name + '.xml')), '<GameProfile />') }
        $filtered = @(Get-ChildItem -LiteralPath $root -Filter '*.xml' -File | Where-Object BaseName -in @('A','C'))
        $script:chooserInput = New-Object 'System.Collections.Generic.Queue[string]'
        foreach ($value in @('L','1','2','D')) { $script:chooserInput.Enqueue($value) }
        Mock Read-HostSafe { $script:chooserInput.Dequeue() }
        $selected = @(Select-RegisteredGamesInteractive -UserProfilesDir $root -Profiles $filtered)
        @($selected | ForEach-Object BaseName) | Should -Be @('A','C')
    }
    It "removes all selected filtered games only after one confirmation" {
        $root = Join-Path $TestDrive 'reshade-removal-all'; $profilesDir = Join-Path $root 'UserProfiles'; $stateRoot = Join-Path $root 'state'
        [IO.Directory]::CreateDirectory($profilesDir) | Out-Null
        foreach ($name in @('One','Two')) {
            $gameDir = Join-Path $root $name; [IO.Directory]::CreateDirectory($gameDir) | Out-Null
            $game = Join-Path $gameDir 'game.exe'; $hook = Join-Path $gameDir 'dxgi.dll'; [IO.File]::WriteAllText($game, 'game'); [IO.File]::WriteAllText($hook, $name)
            [IO.File]::WriteAllText((Join-Path $profilesDir ($name + '.xml')), '<GameProfile><GamePath>' + $game + '</GamePath><EmulatorType>Default</EmulatorType></GameProfile>')
            $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash
            Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='ReShadeProfile.CleanSharp'; PinnedRevision='TPM-PROFILE'; Files=@([pscustomobject]@{ RelativeSource='dxgi.dll'; DestinationPath=$hook; ExpectedSHA256=$hash; ActualSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }) }) -Path (Get-TpmReShadeProfileOwnershipPath -GameId $name -StateRoot $stateRoot)
        }
        $script:allRemovePrompt = 0
        Mock Read-HostSafe { if ($script:allRemovePrompt++ -eq 0) { 'A' } else { 'REMOVE' } }
        $result = Invoke-TpmReShadeRemoval -UserProfilesDir $profilesDir -StateRoot $stateRoot -BackupRoot (Join-Path $profilesDir 'FullBackup')
        $result.Removed | Should -Be 2
        $result.Results.Count | Should -Be 2
        @($result.Results | Where-Object Status -eq 'Removed').Count | Should -Be 2
        Test-Path -LiteralPath (Join-Path $root 'One\dxgi.dll') -PathType Leaf | Should -BeFalse
        Test-Path -LiteralPath (Join-Path $root 'Two\dxgi.dll') -PathType Leaf | Should -BeFalse
        $result.Failed | Should -Be 0
    }
}


Describe "ReShade custom preset validation" {
    It "returns null for blank or whitespace input without probing the path" {
        Mock Test-Path { throw 'path probe must not occur' }
        Resolve-ReShadeCustomPresetPath -InputPath '   ' | Should -BeNullOrEmpty
        Should -Invoke Test-Path -Times 0
    }

    It "rejects cancel, invalid extension, and missing files" {
        Resolve-ReShadeCustomPresetPath -InputPath $null | Should -BeNullOrEmpty
        Resolve-ReShadeCustomPresetPath -InputPath 'preset.txt' | Should -BeNullOrEmpty
        Mock Test-Path { $false }
        Resolve-ReShadeCustomPresetPath -InputPath 'missing.ini' | Should -BeNullOrEmpty
    }

    It "returns a trimmed existing ini path for Advanced custom flow" {
        Mock Test-Path { $true }
        Resolve-ReShadeCustomPresetPath -InputPath '  C:\Temp\look.ini  ' | Should -Be 'C:\Temp\look.ini'
        Should -Invoke Test-Path -ParameterFilter { $LiteralPath -eq 'C:\Temp\look.ini' -and $PathType -eq 'Leaf' } -Times 1
    }
}

Describe "Approved ReShade profile catalog" {
    BeforeAll {
        # FIX51: the only profiles that carry a per-effect parameter table, with the section file and the exact key=value lines in order.
        # Uniform names come from the pinned .fx files; 640x480 is the usual arcade picture size, screen and frame sizes are set equal; CRT-Geom
        # needs interlace_toggle=5 (else a 480-line frame is treated as interlaced and flickers) and CRT-Easymode needs SCANLINE_CUTOFF=1000
        # (else its scanlines switch off for frames of 400+ lines). The real look on a game is not measured.
        $script:Fix51ExpectedSections = @{
            CurvedArcadeMonitor = @{ File = 'CRTGeom.fx'; Lines = @('texture_sizeX=640', 'texture_sizeY=480', 'video_sizeX=640', 'video_sizeY=480', 'CURVATURE=1', 'cornersize=0.05', 'DOTMASK=0.3', 'scanline_weight=0.3', 'interlace_toggle=5', 'OVERSAMPLE=1') }
            SharpApertureGrille = @{ File = 'CRTAperture.fx'; Lines = @('resX=640', 'resY=480', 'video_sizeX=640', 'video_sizeY=480', 'SHARPNESS_IMAGE=1', 'SHARPNESS_EDGES=3', 'MASK_COLORS=3', 'MASK_STRENGTH=0.4', 'MASK_SIZE=1', 'GLOW_HALATION=0.1', 'BRIGHTNESS=1.5') }
            EasymodeCrt = @{ File = 'CRTEasymode.fx'; Lines = @('texture_sizeX=640', 'texture_sizeY=480', 'video_sizeX=640', 'video_sizeY=480', 'SHARPNESS_H=0.5', 'SHARPNESS_V=1', 'MASK_STRENGTH=0.3', 'SCANLINE_STRENGTH=1', 'SCANLINE_CUTOFF=1000', 'BRIGHT_BOOST=1.2') }
            HyllianCrt = @{ File = 'CRTHyllian.fx'; Lines = @('CRT_MULRES_X=1', 'CRT_MULRES_Y=1', 'texture_sizeX=640', 'texture_sizeY=480', 'video_sizeX=640', 'video_sizeY=480', 'PHOSPHOR=1', 'SCANLINES_STRENGTH=0.4', 'COLOR_BOOST=1.5', 'BEAM_MIN_WIDTH=0.86', 'BEAM_MAX_WIDTH=1', 'CRT_ANTI_RINGING=0.8') }
            FastCrt = @{ File = 'zfast_crt.fx'; Lines = @('video_sizeX=640', 'video_sizeY=480', 'FINEMASK=1', 'BLACK_OUT_BORDER=0', 'BLURSCALEX=0.3', 'LOWLUMSCAN=6', 'HILUMSCAN=8', 'BRIGHTBOOST=1.25', 'MASK_DARK=0.25', 'MASK_FADE=0.8') }
        }
    }
    It "has deterministic unique profiles without unsupported recommendations" {
        $profiles = @(Get-TpmReShadeProfiles)
        ($profiles.ProfileId | Sort-Object -Unique).Count | Should -Be $profiles.Count
        ($profiles.FriendlyName | Sort-Object -Unique).Count | Should -Be $profiles.Count
        @($profiles | Where-Object Recommended).Count | Should -Be 0
        @($profiles | Where-Object ProfileId -eq 'Original').Count | Should -Be 1
        @($profiles | Where-Object { $_.SchemaVersion -eq 2 }).Count | Should -Be $profiles.Count
    }
    # RSPS-PRESET-002, RSPS-EFFECT-005, RPSI-ORIGINAL-005
    It "defines 17 canonical profiles (Original plus 16) over 12 of the 25 effects, in arcade order, with exact effect order and parameter sections" {
        # Mutation: reorder, add or drop a profile or effect, change a profile's effect stack, or change a generated preset (Techniques, sorting, [File.fx] section lines) -> a list, count or preset check fails.
        $expected=[ordered]@{
            Original=@(); CurvedArcadeMonitor=@('RSRetroArch.CRTGeom'); ClassicCrt=@('FXShaders.CRT_Lottes'); SharpApertureGrille=@('RSRetroArch.CRTAperture')
            EasymodeCrt=@('RSRetroArch.CRTEasymode'); HyllianCrt=@('RSRetroArch.CRTHyllian'); CrtGlow=@('FXShaders.CRT_Lottes','FXShaders.ArcaneBloom')
            DetailedCrt=@('Akgunter.CRTRoyale'); FastCrt=@('RSRetroArch.CRTZFast'); LightweightCrt=@('RSRetroArch.CRTPi'); ScanlineGlow=@('RSRetroArch.CRTPi','FXShaders.ArcaneBloom')
            BrightScanlines=@('SweetFX.Levels','RSRetroArch.CRTPi'); ArcadeGlow=@('FXShaders.ArcaneBloom')
            Crisp3d=@('SweetFX.SMAA','SweetFX.Curves','SweetFX.Levels'); Crisp3dGlow=@('SweetFX.SMAA','SweetFX.Levels','FXShaders.ArcaneBloom')
            ContrastCurves=@('SweetFX.Curves'); Levels=@('SweetFX.Levels')
        }
        $profiles=@(Get-TpmReShadeProfiles)
        $profiles.Count | Should -Be 17
        @($expected.Keys).Count | Should -Be 17
        @($profiles.ProfileId) | Should -Be @('Original','CurvedArcadeMonitor','ClassicCrt','SharpApertureGrille','EasymodeCrt','HyllianCrt','CrtGlow','DetailedCrt','FastCrt','LightweightCrt','ScanlineGlow','BrightScanlines','ArcadeGlow','Crisp3d','Crisp3dGlow','ContrastCurves','Levels')
        # Effect count and profile count are different numbers: the profiles use 12 of the 25 approved effects; Original is not an effect.
        @($profiles | ForEach-Object { $_.Effects } | Sort-Object -Unique) | Should -Be @('Akgunter.CRTRoyale','FXShaders.ArcaneBloom','FXShaders.CRT_Lottes','RSRetroArch.CRTAperture','RSRetroArch.CRTEasymode','RSRetroArch.CRTGeom','RSRetroArch.CRTHyllian','RSRetroArch.CRTPi','RSRetroArch.CRTZFast','SweetFX.Curves','SweetFX.Levels','SweetFX.SMAA')
        @($profiles | ForEach-Object { $_.Effects } | Sort-Object -Unique).Count | Should -Be 12
        @(Get-TpmReShadeEffectCatalog).Count | Should -Be 25
        foreach($p in $profiles){
            $expected.Contains($p.ProfileId) | Should -BeTrue -Because $p.ProfileId
            (@($p.Effects)-join ',') | Should -Be (@($expected[$p.ProfileId])-join ',')
            $preset=New-TpmReShadePresetContent -ProfileDefinition $p
            $preset | Should -Match '(?m)^Techniques='
            $preset | Should -Match '(?m)^TechniqueSorting='
            (Test-TpmReShadePresetContent -Content $preset -ProfileDefinition $p) | Should -BeTrue
            # per-effect sections: exactly the one [File.fx] section of the five new CRT profiles, after the flat lines, with the literal key=value lines; none elsewhere
            $presetLines = @($preset -split "`r?`n")
            $headers = @($presetLines | Where-Object { $_ -match '^\[' })
            if ($script:Fix51ExpectedSections.ContainsKey([string]$p.ProfileId)) {
                $section = $script:Fix51ExpectedSections[[string]$p.ProfileId]
                $header = '[' + $section.File + ']'
                $headers.Count | Should -Be 1 -Because $p.ProfileId
                $headers[0] | Should -BeExactly $header -Because $p.ProfileId
                $start = [Array]::IndexOf($presetLines, $header)
                $start | Should -BeGreaterThan 0 -Because $p.ProfileId
                [Array]::IndexOf($presetLines, ('TechniqueSorting=' + (@($p.TechniqueOrder) -join ','))) | Should -BeLessThan $start -Because ($p.ProfileId + ': flat lines come before the section')
                (@($presetLines[($start + 1)..($presetLines.Count - 1)] | Where-Object { $_ -ne '' }) -join ',') | Should -BeExactly (@($section.Lines) -join ',') -Because $p.ProfileId
            } else {
                $headers.Count | Should -Be 0 -Because $p.ProfileId
            }
        }
        (New-TpmReShadePresetContent -ProfileDefinition (Get-TpmReShadeProfile -ProfileId 'CrtGlow'))|Should -Match '(?m)^Techniques=CRT_Lottes,ArcaneBloom\r?$'
        (New-TpmReShadePresetContent -ProfileDefinition (Get-TpmReShadeProfile -ProfileId 'CrtGlow'))|Should -Match '(?m)^TechniqueSorting=CRT_Lottes,ArcaneBloom\r?$'
        (New-TpmReShadePresetContent -ProfileDefinition (Get-TpmReShadeProfile -ProfileId 'Crisp3d'))|Should -Match '(?m)^Techniques=SMAA,Curves,Levels\r?$'
        (New-TpmReShadePresetContent -ProfileDefinition (Get-TpmReShadeProfile -ProfileId 'Crisp3d'))|Should -Match '(?m)^TechniqueSorting=SMAA,Curves,Levels\r?$'
        (New-TpmReShadePresetContent -ProfileDefinition (Get-TpmReShadeProfile -ProfileId 'CurvedArcadeMonitor'))|Should -Match '(?m)^Techniques=GeomCRT\r?$'
        (New-TpmReShadePresetContent -ProfileDefinition (Get-TpmReShadeProfile -ProfileId 'FastCrt'))|Should -Match '(?m)^TechniqueSorting=CRTZFast\r?$'
        (Get-TpmReShadeProfile -ProfileId 'Original').Effects.Count|Should -Be 0
    }
    It "uses the owner-approved friendly names, descriptions, technical names and groups verbatim" {
        # Mutation: change any approved profile's name, description, group, technique, files, cost, resolution class, fallback or parameter table (order and count of the 17 rows too).
        # id, FriendlyName, TechnicalName, Description, Group, TechniqueOrder, RequiredEffects, PerformanceClass, ResolutionSensitivity, FallbackProfileId
        $approved = @(
            @('Original','Original','','No visual processing.','','','','LOW','LOW','Original'),
            @('CurvedArcadeMonitor','Curved Arcade Monitor','CRT-Geom','Makes the game look like it is on a curved arcade cabinet monitor: bent screen edges, rounded corners, scanlines and a fine dot pattern.','Crt','GeomCRT','CRTGeom.fx','MEDIUM','UNMEASURED','LightweightCrt'),
            @('ClassicCrt','Classic Arcade CRT','CRT Lottes','Makes the game look like a classic arcade CRT screen: visible scanlines and a soft shadow-mask pattern.','Crt','CRT_Lottes','CRT_Lottes.fx,CRT_Lottes.fxh','HIGH','HIGH','LightweightCrt'),
            @('SharpApertureGrille','Sharp Aperture Grille','CRT-Aperture','A sharp, bright Trinitron-style picture: fine red, green and blue stripes, clear scanlines and a light glow; the screen stays flat.','Crt','ApertureCRT','CRTAperture.fx','MEDIUM','UNMEASURED','LightweightCrt'),
            @('EasymodeCrt','Balanced Flat CRT','CRT-Easymode','A balanced flat CRT look: clear scanlines and a gentle color mask with sharp edges and no screen curve.','Crt','EasymodeCRT','CRTEasymode.fx','MEDIUM','UNMEASURED','LightweightCrt'),
            @('HyllianCrt','Sharp Phosphor CRT','CRT-Hyllian','A sharp, vivid CRT look: crisp pixels, scanlines that fade between the lines and a fine phosphor dot pattern.','Crt','CRTHyllian','CRTHyllian.fx','MEDIUM','UNMEASURED','LightweightCrt'),
            @('CrtGlow','Arcade CRT Glow','CRT Lottes + ArcaneBloom','The classic arcade CRT look plus a soft glow around bright areas, like a bright cabinet screen.','Crt','CRT_Lottes,ArcaneBloom','CRT_Lottes.fx,CRT_Lottes.fxh,ArcaneBloom.fx,ArcaneBloom.fxh','HIGH','HIGH','ScanlineGlow'),
            @('DetailedCrt','Detailed Arcade CRT','CRT-Royale','The most detailed CRT look, with a fine phosphor mask and scanlines; it needs a strong graphics card.','Crt','CRT_Royale','crt-royale.fx','HIGH','UNMEASURED','ClassicCrt'),
            @('FastCrt','Fast CRT','CRT-ZFast','Scanlines and a light mask for a CRT look that costs very little speed, so it also runs well on slower PCs.','Crt','CRTZFast','zfast_crt.fx','LOW','UNMEASURED','Original'),
            @('LightweightCrt','Lightweight CRT','CRT-Pi','Simple scanlines for a retro arcade look that also runs well on slower PCs.','Crt','CRTPi','CRTPi.fx','LOW','UNMEASURED','Original'),
            @('ScanlineGlow','Scanline Glow','CRT-Pi + ArcaneBloom','Simple scanlines plus a soft glow around bright areas, at a lower cost than the classic CRT look.','Crt','CRTPi,ArcaneBloom','CRTPi.fx,ArcaneBloom.fx,ArcaneBloom.fxh','MEDIUM','UNMEASURED','LightweightCrt'),
            @('BrightScanlines','Bright Scanlines','Levels + CRT-Pi','Simple scanlines with deeper blacks and brighter whites, so the picture stays bright behind the scanlines.','Crt','Levels,CRTPi','Levels.fx,CRTPi.fx','LOW','UNMEASURED','LightweightCrt'),
            @('ArcadeGlow','Arcade Glow','ArcaneBloom','A soft glow around bright lights and effects, like a bright arcade cabinet screen.','Main','ArcaneBloom','ArcaneBloom.fx,ArcaneBloom.fxh','MEDIUM','UNMEASURED','Original'),
            @('Crisp3d','Crisp 3D','SMAA + Curves + Levels','Smooths jagged edges in 3D games and adds stronger contrast with deeper blacks.','Main','SMAA,Curves,Levels','SMAA.fx,SMAA.fxh,Curves.fx,Levels.fx','MEDIUM','LOW','Original'),
            @('Crisp3dGlow','Crisp 3D Glow','SMAA + Levels + ArcaneBloom','Smooths jagged edges in 3D games, deepens blacks and adds a soft glow around bright areas.','Main','SMAA,Levels,ArcaneBloom','SMAA.fx,SMAA.fxh,Levels.fx,ArcaneBloom.fx,ArcaneBloom.fxh','MEDIUM','UNMEASURED','Crisp3d'),
            @('ContrastCurves','Balanced Contrast','Curves','Stronger contrast in the midtones, so a flat-looking game gets more depth.','Main','Curves','Curves.fx','MEDIUM','LOW','Original'),
            @('Levels','Black/White Point Adjustment','Levels','Deeper blacks and brighter whites for games that look washed out or gray.','Main','Levels','Levels.fx','LOW','LOW','Original')
        )
        @(Get-TpmReShadeProfiles).Count | Should -Be $approved.Count
        $approved.Count | Should -Be 17
        @(Get-TpmReShadeProfiles | ForEach-Object { [string]$_.ProfileId }) | Should -Be @($approved | ForEach-Object { $_[0] })
        foreach ($row in $approved) {
            $profile = Get-TpmReShadeProfile -ProfileId $row[0]
            $profile | Should -Not -BeNullOrEmpty -Because $row[0]
            $profile.FriendlyName | Should -BeExactly $row[1]
            [string]$profile.TechnicalName | Should -BeExactly $row[2]
            $profile.Description | Should -BeExactly $row[3]
            [string]$profile.Group | Should -BeExactly $row[4]
            (@($profile.TechniqueOrder) -join ',') | Should -BeExactly $row[5] -Because $row[0]
            (@($profile.RequiredEffects) -join ',') | Should -BeExactly $row[6] -Because $row[0]
            $profile.PerformanceClass | Should -BeExactly $row[7] -Because $row[0]
            $profile.ResolutionSensitivity | Should -BeExactly $row[8] -Because $row[0]
            $profile.FallbackProfileId | Should -BeExactly $row[9] -Because $row[0]
            $profile.RequiresHdr | Should -BeFalse
            [string]$profile.CompatibilityNote | Should -BeExactly ''
            if ($script:Fix51ExpectedSections.ContainsKey([string]$row[0])) {
                # the five new CRT profiles carry exactly one parameter section, named after their required file, with string values in the literal order
                $section = $script:Fix51ExpectedSections[[string]$row[0]]
                @($profile.Parameters.Keys).Count | Should -Be 1 -Because $row[0]
                @($profile.Parameters.Keys)[0] | Should -BeExactly $section.File -Because $row[0]
                $row[6] | Should -BeExactly $section.File -Because $row[0]
                $table = $profile.Parameters[$section.File]
                (@($table.Keys | ForEach-Object { '{0}={1}' -f $_, $table[$_] }) -join ',') | Should -BeExactly (@($section.Lines) -join ',') -Because $row[0]
                foreach ($parameterKey in @($table.Keys)) { $table[$parameterKey] | Should -BeOfType [string] -Because ($row[0] + ' ' + $parameterKey) }
            } else {
                @($profile.Parameters.Keys).Count | Should -Be 0 -Because $row[0]
            }
        }
        @(Get-TpmReShadeProfileGroups | ForEach-Object Label) | Should -Be @('CRT Choices','Main Catalog','Advanced Alternatives','Actual HDR Setups Only')
    }
    It "removes Monochrome, Sepia, Film Grain, Vignette and Cartoon from the beginner catalog without remapping them" {
        foreach ($id in @('Cartoon','FilmGrain','Monochrome','Sepia','Vignette')) {
            Get-TpmReShadeProfile -ProfileId $id | Should -BeNullOrEmpty
            (Get-TpmReShadeRetiredProfile -ProfileId $id).ProfileId | Should -Be $id
        }
        @(Get-TpmReShadeEffectCatalog | Where-Object { $_.EffectId -match 'Cartoon|FilmGrain|Monochrome|Sepia|Vignette' }).Count | Should -Be 0
    }
    It "offers only profiles that clearly help arcade play: at least ten with effects, no sharpen-only, color-strength, subtle or HDR effect, a one-line description with a rough cost, CRT choices first" {
        # FIX46 owner rule (2026-11-02)
        $profiles = @(Get-TpmReShadeProfiles)
        $withEffects = @($profiles | Where-Object { @($_.Effects).Count -gt 0 })
        $withEffects.Count | Should -BeGreaterOrEqual 10
        $forbidden = @('SweetFX.LumaSharpen', 'SweetFX.CAS', 'CrosireLegacy.AdaptiveSharpen', 'Fubax.FilmicAnamorphSharpen', 'SweetFX.Vibrance', 'CrosireLegacy.Colourfulness', 'Glamarye.FastEffects', 'SweetFX.LiftGammaGain', 'SweetFX.Tonemap', 'Prod80.ColorBalance', 'CrosireSlim.Deband')
        $hdrEffects = @(Get-TpmReShadeEffectCatalog | Where-Object { [string]$_.Category -eq 'HDR' } | ForEach-Object { [string]$_.EffectId })
        $hdrEffects | Should -Contain 'Lilium.ToneMapping'
        $hdrEffects | Should -Contain 'Lilium.HdrBlackFloorFix'
        # every forbidden id is a real catalog effect, so the checks below cannot pass by a spelling mistake
        $catalogIds = @(Get-TpmReShadeEffectCatalog | ForEach-Object { [string]$_.EffectId })
        foreach ($effectId in $forbidden) { $catalogIds | Should -Contain $effectId }
        $costWord = @{ LOW = 'light'; MEDIUM = 'medium'; HIGH = 'heavy' }
        $menu = @(Get-TpmReShadeTerminalMenuLines -Selectable $profiles)
        foreach ($profile in $withEffects) {
            $id = [string]$profile.ProfileId
            foreach ($effectId in @($profile.Effects)) {
                $forbidden | Should -Not -Contain $effectId -Because ('{0} must not offer {1}' -f $id, $effectId)
                $hdrEffects | Should -Not -Contain $effectId -Because ('{0} must not offer the HDR effect {1}' -f $id, $effectId)
            }
            [bool]$profile.RequiresHdr | Should -BeFalse -Because $id
            [string]$profile.PerformanceClass | Should -BeIn @('LOW', 'MEDIUM', 'HIGH') -Because $id
            [string]$profile.Description | Should -Not -BeNullOrEmpty -Because $id
            [string]$profile.Description | Should -Not -Match '[\r\n]' -Because ($id + ' needs a one-line description')
            $word = Get-TpmReShadeProfileCostText -ProfileDefinition $profile
            $word | Should -BeExactly $costWord[[string]$profile.PerformanceClass] -Because $id
            $titleIndex = @(for ($i = 0; $i -lt $menu.Count; $i++) { if ($menu[$i].Kind -eq 'Title' -and $menu[$i].ProfileId -eq $id) { $i } })
            $titleIndex.Count | Should -Be 1 -Because $id
            $menu[$titleIndex[0] + 1].Text | Should -BeExactly ('      {0} Cost: {1}.' -f $profile.Description, $word) -Because $id
        }
        # Original applies no effect, so it shows no cost
        $original = Get-TpmReShadeProfile -ProfileId 'Original'
        (Get-TpmReShadeProfileCostText -ProfileDefinition $original) | Should -BeExactly ''
        $originalTitle = @(for ($i = 0; $i -lt $menu.Count; $i++) { if ($menu[$i].Kind -eq 'Title' -and $menu[$i].ProfileId -eq 'Original') { $i } })
        $menu[$originalTitle[0] + 1].Text | Should -BeExactly '      No visual processing.'
        (Get-TpmReShadePerformanceBadge -PerformanceClass 'LOW') | Should -BeExactly 'light'
        (Get-TpmReShadePerformanceBadge -PerformanceClass 'MEDIUM') | Should -BeExactly 'medium'
        (Get-TpmReShadePerformanceBadge -PerformanceClass 'HIGH') | Should -BeExactly 'heavy'
        (Get-TpmReShadePerformanceBadge -PerformanceClass 'UNMEASURED') | Should -BeExactly 'unknown'
        # best first: every CRT choice comes before every Main Catalog profile, and no other group is offered
        $groups = @($withEffects | ForEach-Object { [string]$_.Group })
        @($groups | Sort-Object -Unique) | Should -Be @('Crt', 'Main')
        $lastCrt = [Array]::LastIndexOf([string[]]$groups, 'Crt')
        $firstMain = [Array]::IndexOf([string[]]$groups, 'Main')
        $lastCrt | Should -BeLessThan $firstMain
    }
    It "keeps every non-Original profile pinned, costed and noted: at least ten profiles, 64-hex hashes with byte lengths, a cost class, and a preview note where one is required" {
        # Mutation: drop a profile's PreviewNote or PerformanceClass, delete an effect's SHA256 or ByteLengths entry (or use a lowercase/short hash), or shrink the offered list below ten profiles -> this fails.
        $profiles = @(Get-TpmReShadeProfiles)
        $catalog = @(Get-TpmReShadeEffectCatalog)
        $others = @($profiles | Where-Object { $_.ProfileId -ne 'Original' })
        $others.Count | Should -BeGreaterOrEqual 10
        $needsNote = @('CurvedArcadeMonitor', 'SharpApertureGrille', 'EasymodeCrt', 'HyllianCrt', 'DetailedCrt', 'FastCrt', 'LightweightCrt', 'ScanlineGlow', 'BrightScanlines', 'Crisp3d', 'Crisp3dGlow')
        foreach ($noted in $needsNote) { @($others | ForEach-Object { [string]$_.ProfileId }) | Should -Contain $noted }
        foreach ($profileDef in $others) {
            $id = [string]$profileDef.ProfileId
            [string]$profileDef.PerformanceClass | Should -BeIn @('LOW', 'MEDIUM', 'HIGH') -Because $id
            @($profileDef.Effects).Count | Should -BeGreaterThan 0 -Because $id
            foreach ($effectId in @($profileDef.Effects)) {
                $effect = @($catalog | Where-Object { [string]$_.EffectId -eq [string]$effectId })[0]
                $effect | Should -Not -BeNullOrEmpty -Because ($id + ' uses ' + $effectId)
                @($effect.SHA256).Count | Should -BeGreaterThan 0 -Because $effectId
                @($effect.SHA256).Count | Should -Be @($effect.RelativeFiles).Count -Because $effectId
                @($effect.ByteLengths).Count | Should -Be @($effect.RelativeFiles).Count -Because $effectId
                foreach ($hash in @($effect.SHA256)) { [string]$hash | Should -MatchExactly '^[0-9A-F]{64}$' -Because $effectId }
            }
            if ($id -in $needsNote) {
                [string]$profileDef.PreviewNote | Should -Not -BeNullOrEmpty -Because ($id + ' must carry its preview note')
                [string]$profileDef.PreviewNote | Should -Not -Match '\bTPM\b' -Because 'user-visible text names TeknoParrot Manager'
            }
        }
    }
    It "derives visible technique labels from canonical profile and effect definitions" {
        $catalog = @(Get-TpmReShadeEffectCatalog)
        foreach ($profile in @(Get-TpmReShadeProfiles)) {
            $expectedRows = @(
                foreach ($techniqueName in @($profile.TechniqueOrder)) {
                    $effectEntry = @($catalog | Where-Object { $_.TechniqueName -eq $techniqueName })[0]
                    $shaderFiles = @($effectEntry.RelativeFiles | Where-Object { [IO.Path]::GetExtension($_) -ieq '.fx' } | ForEach-Object { [IO.Path]::GetFileName($_) })
                    '{0} / {1}' -f ($shaderFiles -join ', '), $effectEntry.TechniqueName
                }
            )
            $expectedText = if ($expectedRows.Count -eq 0) { '(none; no ReShade techniques)' } else { $expectedRows -join '; ' }
            (Get-TpmReShadeProfileTechniqueDisplay -ProfileDefinition $profile) | Should -Be $expectedText
        }
    }
    It "fails closed when a profile technique is absent from the approved catalog" {
        $invalidProfile = [pscustomobject]@{ TechniqueOrder = @('UnapprovedTechnique') }
        { Get-TpmReShadeProfileTechniqueDisplay -ProfileDefinition $invalidProfile } | Should -Throw "*No approved ReShade effect catalog entry*"
    }
    It "requires measured evidence before compatibility status or recommendation is asserted" {
        $profiles = @(Get-TpmReShadeProfiles)
        $effects = @(Get-TpmReShadeEffectCatalog)
        @($profiles | Where-Object { $_.Recommended -or $_.MeasuredEvidence -or $_.CompatibilityState -eq 'VALIDATED_SINGLE' }).Count | Should -Be 0
        @($effects | Where-Object { $_.MeasuredEvidence -or $_.CompatibilityState -eq 'VALIDATED_SINGLE' }).Count | Should -Be 0
        @($profiles | Where-Object CompatibilityState -ne 'ADVISORY_UNMEASURED').Count | Should -Be 0
        @($effects | Where-Object CompatibilityState -ne 'ADVISORY_UNMEASURED').Count | Should -Be 0
    }



    It "uses approved upstream techniques in deterministic presets" {
        $profile = Get-TpmReShadeProfile -ProfileId 'Levels'
        $first = New-TpmReShadePresetContent -ProfileDefinition $profile
        $second = New-TpmReShadePresetContent -ProfileDefinition $profile
        $first | Should -Be $second
        $first | Should -Match '(?m)^Techniques=Levels\r?$'
        $first | Should -Not -Match 'TPM_'
    }
    # RSPS-PRESET-003, RPSI-CONFIG-004
    It "rejects runtime technique sorting that differs from canonical effect order" {
        $profile = Get-TpmReShadeProfile -ProfileId 'BrightScanlines'
        $content = New-TpmReShadePresetContent -ProfileDefinition $profile
        $altered = $content -replace '(?m)^TechniqueSorting=[^\r\n]*', 'TechniqueSorting=CRTPi,Levels'
        $altered | Should -Match '(?m)^TechniqueSorting=CRTPi,Levels\r?$'
        Test-TpmReShadePresetContent -Content $altered -ProfileDefinition $profile | Should -BeFalse
    }

    # RSPS-EFFECT-005, RPSI-SOURCE-001
    It "contains immutable source metadata for every approved effect" {
        $effects = @(Get-TpmReShadeEffectCatalog)
        $effects.Count | Should -Be 25
        foreach ($effect in $effects) {
            $effect.PinnedCommit | Should -Match '^[0-9a-f]{40}$'
            @($effect.RelativeFiles).Count | Should -BeGreaterThan 0
            @($effect.SHA256).Count | Should -Be @($effect.RelativeFiles).Count
            @($effect.ByteLengths).Count | Should -Be @($effect.RelativeFiles).Count
            # every file pin is a full upper-case SHA-256 and a positive byte length (a lost or shortened pin fails here)
            foreach ($hash in @($effect.SHA256)) { [string]$hash | Should -MatchExactly '^[0-9A-F]{64}$' -Because $effect.EffectId }
            foreach ($length in @($effect.ByteLengths)) { [int64]$length | Should -BeGreaterThan 0 -Because $effect.EffectId }
            $effect.AllowedHosts | Should -Contain 'raw.githubusercontent.com'
            $effect.License | Should -Not -BeNullOrEmpty
            $effect.Attribution | Should -Not -BeNullOrEmpty
        }
    }
    # RPSI-SOURCE-001
    It "pins the shared runtime header and project-authored UI compatibility include" {
        $specs = @(Get-TpmReShadeApprovedEffectFiles -EffectId 'SweetFX.Vibrance')
        $header = @($specs | Where-Object RelativePath -eq 'Shaders/TPM/ReShade.fxh')[0]
        $header.Url | Should -Be 'https://raw.githubusercontent.com/crosire/reshade-shaders/fd0022170615ce0d8162d219bff07232fa6dd84f/Shaders/ReShade.fxh'
        $header.SourceRelativePath | Should -Be 'Shaders/ReShade.fxh'
        $header.PinnedRevision | Should -Be 'fd0022170615ce0d8162d219bff07232fa6dd84f'
        $header.Repository | Should -Be 'crosire/reshade-shaders'
        $header.License | Should -Be 'CC0-1.0'
        $header.SHA256 | Should -Be '6DABFBBAF968C3871905D2EA17F96572FF7B1CEC01310B5D0E5252B66B30174F'
        $header.ByteLength | Should -Be 4250

        $ui = @($specs | Where-Object RelativePath -eq 'Shaders/TPM/ReShadeUI.fxh')[0]
        $ui.Repository | Should -Be 'TeknoParrot-Manager'
        $ui.License | Should -Be 'Project-authored'
        $hasher = [Security.Cryptography.SHA256]::Create()
        try { $uiHash = [BitConverter]::ToString($hasher.ComputeHash([byte[]]$ui.InlineBytes)).Replace('-', '') } finally { $hasher.Dispose() }
        $ui.SHA256 | Should -Be $uiHash
        $uiText = [Text.Encoding]::ASCII.GetString([byte[]]$ui.InlineBytes)
        $uiText | Should -Match '(?m)^#define __UNIFORM_SLIDER_FLOAT1 ui_type = "slider";\r?$'
        $uiText | Should -Match '(?m)^#define __UNIFORM_COLOR_FLOAT3 ui_type = "color";\r?$'
    }
    It "routes the retained pinned SweetFX shaders through selectable profiles and allowlisted acquisition" {
        $revision = '16d1a42247cb5baaf660120ee35c9a33bb94649c'
        $expected = @(
            [pscustomobject]@{ Profile='ContrastCurves'; Effect='SweetFX.Curves'; Technique='Curves'; File='Shaders/SweetFX/Curves.fx'; Length=6274; Hash='8368029D2254856505ABF7DD789342024465403DA49434DD776C6D1AF4079A98' }
            [pscustomobject]@{ Profile='Levels'; Effect='SweetFX.Levels'; Technique='Levels'; File='Shaders/SweetFX/Levels.fx'; Length=2976; Hash='C603D3EA12D6D5710F2246BB7DD446D19E561154656F1FA8D579CA7FBBEEF70E' }
        )
        $effects = @(Get-TpmReShadeEffectCatalog)
        $profiles = @(Get-TpmReShadeProfiles)
        $effects.Count | Should -Be 25
        $profiles.Count | Should -Be 17
        $license = [IO.File]::ReadAllText((Join-Path $PSScriptRoot '..\LICENSE'))
        $license | Should -Match 'Copyright \(c\) 2014 CeeJayDK'
        $license | Should -Match 'The MIT License'
        $license | Should -Match 'crosire/reshade-shaders'
        $license | Should -Match 'CC0-1.0'
        foreach ($expectedEffect in $expected) {
            $effect = @($effects | Where-Object EffectId -eq $expectedEffect.Effect)[0]
            $effect.PinnedCommit | Should -Be $revision
            $effect.RelativeFiles | Should -Be @($expectedEffect.File)
            $effect.SHA256 | Should -Be @($expectedEffect.Hash)
            $effect.ByteLengths | Should -Be @([int64]$expectedEffect.Length)
            $effect.RequiredIncludes | Should -Contain 'ReShade.fxh'
            $effect.RequiredIncludes | Should -Contain 'ReShadeUI.fxh'
            @($effect.RequiredTextures).Count | Should -Be 0
            $effect.License | Should -Be 'MIT'
            $effect.Attribution | Should -Not -BeNullOrEmpty
            $effect.TechniqueName | Should -Be $expectedEffect.Technique
            $effect.AllowedPathPrefix | Should -Be "/CeeJayDK/SweetFX/$revision/"
            $profile = Get-TpmReShadeProfile -ProfileId $expectedEffect.Profile
            @($profile.Effects) | Should -Be @($expectedEffect.Effect)
            @($profile.TechniqueOrder) | Should -Be @($expectedEffect.Technique)
            (New-TpmReShadePresetContent -ProfileDefinition $profile) | Should -Match ("(?m)^Techniques={0}\r?$" -f [regex]::Escape($expectedEffect.Technique))
            (New-TpmReShadePresetContent -ProfileDefinition $profile) | Should -Match ("(?m)^TechniqueSorting={0}\r?$" -f [regex]::Escape($expectedEffect.Technique))
            $fileSpec = @(Get-TpmReShadeApprovedEffectFiles -EffectId $expectedEffect.Effect | Where-Object { $_.Role -eq 'Effect' -or $_.RelativePath -eq $expectedEffect.File })[0]
            $fileSpec.Url | Should -Be "https://raw.githubusercontent.com/CeeJayDK/SweetFX/$revision/$($expectedEffect.File)"
            $fileSpec.SHA256 | Should -Be $expectedEffect.Hash
        }
    }
    # RSPS-PRESET-001, RSPS-CONFIG-004, RPSI-CLOSURE-002, RPSI-CONFIG-004
    It "provides a complete approved include closure and valid runtime search and preset paths for every profile" {
        $profiles = @(Get-TpmReShadeProfiles)
        foreach ($profile in $profiles) {
            $required = @(@(
                foreach ($effectId in @($profile.Effects)) {
                    $effect = @(Get-TpmReShadeEffectCatalog | Where-Object EffectId -eq $effectId)[0]
                    foreach ($include in @($effect.RequiredIncludes)) { $include }
                }
            ) | Sort-Object -Unique)
            if ($required.Count -gt 0) {
                $files = @(
                    foreach ($effectId in @($profile.Effects)) { Get-TpmReShadeApprovedEffectFiles -EffectId $effectId }
                )
                foreach ($include in $required) {
                    @($files | Where-Object { [IO.Path]::GetFileName([string]$_.RelativePath) -ieq $include }).Count | Should -BeGreaterThan 0 -Because "$($profile.ProfileId) must stage $include"
                }
            }
            $config = Update-TpmReShadeTutorialProgressText -Content (New-TpmReShadePresetContent -ProfileDefinition $profile)
            $config | Should -Match '(?m)^\[GENERAL\]\r?$'
            $config | Should -Match '(?m)^EffectSearchPaths=.*\.\\Shaders.*\.\\Shaders\\SweetFX.*\.\\Shaders\\TPM\r?$'
            $config | Should -Match '(?m)^PresetPath=\.\\ReShade\.ini\r?$'
            $config | Should -Match '(?m)^StartupPresetPath=\.\\ReShade\.ini\r?$'
            $config | Should -Match ("(?m)^Techniques={0}\r?$" -f [regex]::Escape((@($profile.TechniqueOrder) -join ',')))
            $config | Should -Match ("(?m)^TechniqueSorting={0}\r?$" -f [regex]::Escape((@($profile.TechniqueOrder) -join ',')))
        }
    }

    It "rejects CRT conflicts in either request order" {
        foreach ($ids in @(
            @('SweetFX.LumaSharpen','FXShaders.CRT_Lottes'),
            @('FXShaders.CRT_Lottes','SweetFX.LumaSharpen'),
            @('SweetFX.Vibrance','FXShaders.CRT_Lottes'),
            @('FXShaders.CRT_Lottes','SweetFX.Vibrance')
        )) {
            $result = Resolve-TpmReShadeEffectStack -EffectIds $ids
            $result.Valid | Should -BeFalse
            ($result.Errors -join ' ') | Should -Match 'conflict'
        }
    }

    It "rejects every pair of the eight CRT effects, and every CRT effect with a sharpen or color-alternative effect, in both request orders" {
        # Mutation: remove one of the five FIX51 ids (or any CRT id) from $crtIds in Get-TpmReShadeEffectCatalog -> that CRT can be stacked with another CRT, sharpening or color effect.
        $crt = @('FXShaders.CRT_Lottes', 'Akgunter.CRTRoyale', 'RSRetroArch.CRTPi', 'RSRetroArch.CRTGeom', 'RSRetroArch.CRTAperture', 'RSRetroArch.CRTEasymode', 'RSRetroArch.CRTHyllian', 'RSRetroArch.CRTZFast')
        $alternatives = @('SweetFX.LumaSharpen', 'SweetFX.CAS', 'CrosireLegacy.AdaptiveSharpen', 'Fubax.FilmicAnamorphSharpen', 'Glamarye.FastEffects', 'SweetFX.Vibrance', 'CrosireLegacy.Colourfulness')
        $catalog = @(Get-TpmReShadeEffectCatalog)
        $checked = 0
        foreach ($first in $crt) {
            $entry = @($catalog | Where-Object { [string]$_.EffectId -eq $first })[0]
            $entry | Should -Not -BeNullOrEmpty -Because $first
            foreach ($second in @($crt + $alternatives)) {
                if ($second -eq $first) { continue }
                @($entry.ConflictsWith) | Should -Contain $second -Because ($first + ' must list ' + $second)
                foreach ($ids in @(@($first, $second), @($second, $first))) {
                    $result = Resolve-TpmReShadeEffectStack -EffectIds $ids
                    $result.Valid | Should -BeFalse -Because ($ids -join ' + ')
                    ($result.Errors -join ' ') | Should -Match 'conflict' -Because ($ids -join ' + ')
                    $checked++
                }
            }
        }
        $checked | Should -Be (8 * 14 * 2)
        # the combinations the arcade profiles rely on stay valid: a CRT look with glow, black/white points or contrast
        foreach ($pair in @(@('RSRetroArch.CRTGeom', 'FXShaders.ArcaneBloom'), @('RSRetroArch.CRTAperture', 'SweetFX.Levels'), @('RSRetroArch.CRTZFast', 'SweetFX.Curves'), @('RSRetroArch.CRTPi', 'FXShaders.ArcaneBloom'))) {
            (Resolve-TpmReShadeEffectStack -EffectIds $pair).Valid | Should -BeTrue -Because ($pair -join ' + ')
        }
    }

    It "accepts LumaSharpen and Vibrance together in either order" {
        foreach ($ids in @(
            @('SweetFX.LumaSharpen','SweetFX.Vibrance'),
            @('SweetFX.Vibrance','SweetFX.LumaSharpen')
        )) {
            $result = Resolve-TpmReShadeEffectStack -EffectIds $ids
            $result.Valid | Should -BeTrue
            @($result.Effects).Count | Should -Be 2
            @($result.Effects | Select-Object -ExpandProperty EffectId -Unique).Count | Should -Be 2
            $result.Errors.Count | Should -Be 0
        }
    }

    # RPSI-STACK-009
    It "rejects unknown effects and normalizes repeated approved effects in first-seen order" {
        $unknown = Resolve-TpmReShadeEffectStack -EffectIds @('Unknown.Effect','SweetFX.Vibrance')
        $unknown.Valid | Should -BeFalse
        ($unknown.Errors -join ' ') | Should -Match 'not in the approved catalog'
        $dedup = Resolve-TpmReShadeEffectStack -EffectIds @('SweetFX.LumaSharpen','SweetFX.LumaSharpen','SweetFX.Vibrance')
        @($dedup.Effects | Select-Object -ExpandProperty EffectId).Count | Should -Be 2
        @($dedup.Effects | Select-Object -ExpandProperty EffectId -Unique).Count | Should -Be 2
        $dedup.Valid | Should -BeTrue
        (@($dedup.Effects | ForEach-Object { [string]$_.EffectId }) -join ',') | Should -Be 'SweetFX.LumaSharpen,SweetFX.Vibrance'
        (@($dedup.TechniqueOrder) -join ',') | Should -Be 'LumaSharpen,Vibrance'
    }

    It "requires explicit compatibility schema fields on every effect" {
        foreach ($effect in @(Get-TpmReShadeEffectCatalog)) {
            $effect.PSObject.Properties.Name | Should -Contain 'ConflictsWith'
            $effect.ConflictsWith.GetType().IsArray | Should -BeTrue
        }
    }
}
Describe "ReShade profile previews" {
    BeforeAll {
        $script:PreviewFixtureRoot = Join-Path $TestDrive 'landscape-preview'
        [IO.Directory]::CreateDirectory($script:PreviewFixtureRoot) | Out-Null
        Copy-Item -LiteralPath (Join-Path $PSScriptRoot '..\PreviewAssets\ReShadePreviews\TPM-preview-landscape.png') -Destination (Join-Path $script:PreviewFixtureRoot 'TPM-preview-landscape.png')
    }
    It "validates the bundled landscape identity, dimensions, and hash" {
        $reference = Get-TpmReShadePreviewReference -PreviewRoot $script:PreviewFixtureRoot
        $reference.Available | Should -BeTrue
        $reference.Identity | Should -Be 'TPM-LANDSCAPE-V1'
        $reference.Version | Should -Be '3'
        $reference.Hash | Should -Be '7203032094bfd4d174cd3125ef55c87d7b35053fc4e274914b6ae1ac43f286d8'
        $image = [Drawing.Image]::FromFile($reference.Path)
        try {
            $image.Width | Should -Be 1672
            $image.Height | Should -Be 941
        } finally {
            $image.Dispose()
        }
    }
    It "fails closed for missing and invalid landscape assets without blocking profiles" {
        $root = Join-Path $TestDrive 'previews'
        [IO.Directory]::CreateDirectory($root) | Out-Null
        (Get-TpmReShadePreviewReference -PreviewRoot $root).Available | Should -BeFalse
        [IO.File]::WriteAllText((Join-Path $root 'TPM-preview-landscape.png'), 'bad')
        (Get-TpmReShadePreviewReference -PreviewRoot $root).Reason | Should -Be 'PREVIEW_LANDSCAPE_ASSET_UNREADABLE'
        (Get-TpmReShadeProfile -ProfileId Original).ProfileId | Should -Be 'Original'
    }
}
Describe "ReShade preview renderer and cache" {
    BeforeAll {
        Add-Type -AssemblyName System.Drawing
        # The live paint handler is built by New-TpmReShadePreviewPaintHandler with GetNewClosure(), which binds it to a dynamic module whose parent is the
        # GLOBAL session state. Functions this suite defines in its BeforeAll are not global, so inside the handler they are not recognized, and the
        # handler's own catch swallows that error: nothing is drawn. This bridge binds the UNCHANGED production function texts into that module (and nothing
        # else), points the handler's Write-Log at a sink the test can inspect, and leaves the global function inventory untouched.
        function Get-TpmPaintHandlerDependencyNames {
            param([Parameter(Mandatory)][string[]]$Roots)
            $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
            $queue = New-Object System.Collections.Queue
            foreach ($root in $Roots) { $queue.Enqueue($root) }
            while ($queue.Count -gt 0) {
                $name = [string]$queue.Dequeue()
                if ($name -eq 'Write-Log' -or -not $seen.Add($name)) { continue }
                $command = Get-Command -Name $name -CommandType Function -ErrorAction SilentlyContinue
                if (-not $command) { continue }
                foreach ($call in @($command.ScriptBlock.Ast.FindAll({ param($node) $node -is [System.Management.Automation.Language.CommandAst] }, $true))) {
                    $called = $call.GetCommandName()
                    if ($called) { $queue.Enqueue($called) }
                }
            }
            @($seen | Where-Object { Get-Command -Name $_ -CommandType Function -ErrorAction SilentlyContinue })
        }
        function Connect-TpmPaintHandlerDependencies {
            param([Parameter(Mandatory)][scriptblock]$Handler)
            if ($null -eq $Handler.Module) { throw 'the paint handler is not bound to a module; this bridge only applies to a GetNewClosure() handler' }
            $log = New-Object System.Collections.ArrayList
            $sinkText = 'param($sink) $script:TpmPaintLogSink = $sink; function script:Write-Log { param([string]$Message) [void]$script:TpmPaintLogSink.Add($Message) }'
            & ($Handler.Module.NewBoundScriptBlock([scriptblock]::Create($sinkText))) $log
            foreach ($name in (Get-TpmPaintHandlerDependencyNames -Roots @('Get-TpmReShadePreviewStateValue', 'Get-TpmReShadePreviewProcessedBitmap', 'Get-TpmReShadeImageDisplayRectangle', 'Add-TpmReShadePreviewLabel', 'Get-TpmReShadeProfile'))) {
                $definition = 'function script:' + $name + ' {' + (Get-Command -Name $name -CommandType Function).ScriptBlock.ToString() + '}'
                & ($Handler.Module.NewBoundScriptBlock([scriptblock]::Create($definition)))
            }
            foreach ($required in @('Get-TpmReShadePreviewStateValue', 'Get-TpmReShadePreviewProcessedBitmap', 'Get-TpmReShadeImageDisplayRectangle', 'Add-TpmReShadePreviewLabel')) {
                $visible = & $Handler.Module { param($n) [bool](Get-Command -Name $n -CommandType Function -ErrorAction SilentlyContinue) } $required
                if (-not $visible) { throw "the paint handler cannot resolve $required after the dependency bridge" }
            }
            , $log
        }
        $script:PreviewFixtureRoot = Join-Path $TestDrive 'renderer-landscape'
        [IO.Directory]::CreateDirectory($script:PreviewFixtureRoot) | Out-Null
        Copy-Item -LiteralPath (Join-Path $PSScriptRoot '..\PreviewAssets\ReShadePreviews\TPM-preview-landscape.png') -Destination (Join-Path $script:PreviewFixtureRoot 'TPM-preview-landscape.png')
        # Executable-call evidence for the cache copy step. The product function carries an explanatory comment that names the rejected redraw API, so a text
        # search cannot tell a comment from a call. This inspects the AST of the named function only: method invocations (comments and strings are not calls).
        function Get-TpmPreviewCopyCallEvidence {
            param([Parameter(Mandatory)][string]$FunctionText, [string]$FunctionName = 'Get-TpmReShadePreviewProcessedBitmap')
            $tokens = $null; $parseErrors = $null
            $parsed = [System.Management.Automation.Language.Parser]::ParseInput($FunctionText, [ref]$tokens, [ref]$parseErrors)
            $functions = @($parsed.FindAll({ param($node) $node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $node.Name -eq $FunctionName }, $true))
            $clone = 0; $redraw = 0; $dynamic = 0
            foreach ($function in $functions) {
                $calls = @($function.Body.FindAll({ param($node) $node -is [System.Management.Automation.Language.InvokeMemberExpressionAst] }, $true))
                foreach ($call in $calls) {
                    if ($call.Member -isnot [System.Management.Automation.Language.StringConstantExpressionAst]) { $dynamic++; continue }
                    $memberName = [string]$call.Member.Value
                    if ($memberName -like 'DrawImageUnscaled*') { $redraw++ }
                    if ($memberName -eq 'Clone' -and $call.Expression.Extent.Text -ceq '$Cache.Reference') { $clone++ }
                }
            }
            return [pscustomobject]@{ ParseErrors = @($parseErrors).Count; FunctionCount = $functions.Count; CloneCalls = $clone; DrawImageUnscaledCalls = $redraw; DynamicMemberCalls = $dynamic }
        }
        # Exact pixel access for the content tests: a compact 32bpp ARGB (BGRA byte order) copy read with LockBits and the signed stride, so row padding and
        # row order cannot create differences and alpha is always compared.
        function Get-TpmPreviewBgra {
            param([Parameter(Mandatory)][Drawing.Bitmap]$Bitmap)
            $rectangle = New-Object Drawing.Rectangle -ArgumentList @(0, 0, $Bitmap.Width, $Bitmap.Height)
            $data = $Bitmap.LockBits($rectangle, [Drawing.Imaging.ImageLockMode]::ReadOnly, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
            try {
                $stride = [int]$data.Stride
                $absoluteStride = [Math]::Abs($stride)
                $length = $absoluteStride * $Bitmap.Height
                $raw = New-Object byte[] $length
                $start = if ($stride -lt 0) { [IntPtr]::Add($data.Scan0, (($Bitmap.Height - 1) * $stride)) } else { $data.Scan0 }
                [Runtime.InteropServices.Marshal]::Copy($start, $raw, 0, $length)
            } finally { $Bitmap.UnlockBits($data) }
            $compact = New-Object byte[] ($Bitmap.Width * $Bitmap.Height * 4)
            for ($y = 0; $y -lt $Bitmap.Height; $y++) {
                $rowOffset = if ($stride -ge 0) { $y * $absoluteStride } else { ($Bitmap.Height - 1 - $y) * $absoluteStride }
                [Array]::Copy($raw, $rowOffset, $compact, $y * $Bitmap.Width * 4, $Bitmap.Width * 4)
            }
            return , $compact
        }
        # Is a bitmap still usable? Probed by an explicit METHOD call. A property read such as .Width is NOT a valid probe: PowerShell suppresses an exception thrown by a
        # property getter and returns $null, so a disposed bitmap would look usable. Callers must show the probe works (live control usable, hand-disposed control unusable).
        function Test-TpmPreviewBitmapUsable {
            param($Candidate)
            if ($null -eq $Candidate) { return $false }
            try { [void]$Candidate.GetPixel(0, 0); return $true } catch { return $false }
        }
        function Get-TpmPreviewBytesHash {
            param([Parameter(Mandatory)][byte[]]$Bytes)
            $sha = [Security.Cryptography.SHA256]::Create()
            try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes)) -replace '-', '') } finally { $sha.Dispose() }
        }
        # Indices of differing pixels (any of the four bytes differs; zero tolerance). -Limit stops the scan early once enough differences are found.
        function Get-TpmPreviewDifferingPixels {
            param([Parameter(Mandatory)][byte[]]$Left, [Parameter(Mandatory)][byte[]]$Right, [int]$Limit = [int]::MaxValue)
            $found = New-Object System.Collections.Generic.List[int]
            if ($Left.Length -ne $Right.Length) { throw "buffers differ in size ($($Left.Length) versus $($Right.Length))" }
            if ((Get-TpmPreviewBytesHash -Bytes $Left) -eq (Get-TpmPreviewBytesHash -Bytes $Right)) { return , $found }
            for ($i = 0; $i -lt $Left.Length; $i += 4) {
                if ($Left[$i] -ne $Right[$i] -or $Left[$i + 1] -ne $Right[$i + 1] -or $Left[$i + 2] -ne $Right[$i + 2] -or $Left[$i + 3] -ne $Right[$i + 3]) {
                    [void]$found.Add($i / 4)
                    if ($found.Count -ge $Limit) { break }
                }
            }
            return , $found
        }
        # Content verdict used for every APPROXIMATE profile: the PROCESSED (undecorated) content must differ from the reference by more than the threshold.
        function Assert-TpmApproximationChangesContent {
            param([Parameter(Mandatory)]$Cache, [Parameter(Mandatory)]$ProfileDefinition, [int]$MinimumDifferingPixels = 1000)
            $bitmap = Get-TpmReShadePreviewProcessedBitmap -Cache $Cache -ProfileDefinition $ProfileDefinition
            $count = (Get-TpmPreviewDifferingPixels -Left (Get-TpmPreviewBgra -Bitmap $Cache.Reference) -Right (Get-TpmPreviewBgra -Bitmap $bitmap) -Limit ($MinimumDifferingPixels + 1)).Count
            if ($count -le $MinimumDifferingPixels) { throw "NO_CONTENT_CHANGE: $($ProfileDefinition.ProfileId) changed only $count pixels of the content (more than $MinimumDifferingPixels required)" }
            return $count
        }
        # Ink of a label drawn ALONE (same text, font, brush and position as the product annotation) on a black and on a white canvas. A pixel is ink if the label
        # changes it on either background, so antialiased edge pixels are included without any bounding-box slack.
        function Get-TpmPreviewLabelInk {
            param([Parameter(Mandatory)][string]$Label, [Parameter(Mandatory)][int]$Width, [Parameter(Mandatory)][int]$Height)
            $ink = New-Object 'System.Collections.Generic.HashSet[int]'
            foreach ($background in @([Drawing.Color]::Black, [Drawing.Color]::White)) {
                $blank = New-Object Drawing.Bitmap($Width, $Height)
                $graphics = [Drawing.Graphics]::FromImage($blank)
                try {
                    $graphics.Clear($background)
                    $reference = Get-TpmPreviewBgra -Bitmap $blank
                    # the product's own label routine, so the measured ink is exactly what the renderer draws (font, color, centering)
                    Add-TpmReShadePreviewLabel -Graphics $graphics -Label $Label -ImageWidth $Width
                    foreach ($index in (Get-TpmPreviewDifferingPixels -Left $reference -Right (Get-TpmPreviewBgra -Bitmap $blank))) { [void]$ink.Add([int]$index) }
                } finally { $graphics.Dispose(); $blank.Dispose() }
            }
            return , $ink
        }
    }
    It "draws every preview label horizontally centered and fully inside the image at each width (GDI+)" -ForEach @(
        @{ Width = 320; Height = 180 }
        @{ Width = 960; Height = 540 }
    ) {
        foreach ($label in @('ORIGINAL', 'AFTER', 'BEFORE  |  AFTER')) {
            $ink = Get-TpmPreviewLabelInk -Label $label -Width $Width -Height $Height
            $ink.Count | Should -BeGreaterThan 50
            $xs = @($ink | ForEach-Object { [int]($_ % $Width) })
