        $source | Should -Not -Match 'Start-CrosshairSelectionBridge|Read-CrosshairSelectionBridge|Export-CrosshairPreview|CloseMainWindow'
        $previewStart = $source.IndexOf('function Show-TpmCrosshairPreviewWindow')
        $previewEnd = $source.IndexOf("`nfunction ", $previewStart + 10)
        $previewWindow = $source.Substring($previewStart, $previewEnd - $previewStart)
        $previewWindow | Should -Match '\$button\.Add_Click\(\$buttonHandler\)'
        $previewWindow | Should -Match 'Set-TpmCrosshairPreviewSelection -Session \$state -Index \(\[int\]\$button\.Tag\)'
        $previewWindow | Should -Match '\$button\.AccessibleDescription'
        $crosshairStart = $source.IndexOf('function Invoke-CrosshairSetup')
        $crosshairEnd = $source.IndexOf("`nfunction ", $crosshairStart + 10)
        $crosshairSetup = $source.Substring($crosshairStart, $crosshairEnd - $crosshairStart)
        $crosshairSetup | Should -Not -Match 'Start-Process'
        $confirmAt = $crosshairSetup.IndexOf('$crosshairConfirm')
        $transactionAt = $crosshairSetup.IndexOf('Invoke-TpmCrosshairAssetTransaction', $confirmAt)
        $transactionAt | Should -BeGreaterThan $confirmAt
    }
    It "allows the same crosshair for P1 and P2 and rejects selections after completion" {
        $session = [hashtable]::Synchronized(@{ Paths=@('a.png','b.png'); P1Index=$null; P2Index=$null; Closed=$false })
        $first = Set-TpmCrosshairPreviewSelection -Session $session -Index 1
        $second = Set-TpmCrosshairPreviewSelection -Session $session -Index 1
        $third = Set-TpmCrosshairPreviewSelection -Session $session -Index 0
        $first.Accepted | Should -BeTrue
        $first.Player | Should -Be 'P1'
        $second.Accepted | Should -BeTrue
        $second.Player | Should -Be 'P2'
        $second.Complete | Should -BeTrue
        $session['P1Index'] | Should -Be 1
        $session['P2Index'] | Should -Be 1
        $third.Accepted | Should -BeFalse
        (Set-TpmCrosshairPreviewSelection -Session $session -Index -1).Accepted | Should -BeFalse
        (Set-TpmCrosshairPreviewSelection -Session $session -Index 2).Accepted | Should -BeFalse
    }
    It "closes and disposes only the session-owned preview and cleanup is idempotent" {
        $owned = [pscustomobject]@{ IsDisposed=$false; CloseCalls=0; DisposeCalls=0 }
        $owned | Add-Member ScriptMethod Close { $this.CloseCalls++ } -Force
        $owned | Add-Member ScriptMethod Dispose { $this.DisposeCalls++; $this.IsDisposed=$true } -Force
        $unrelated = [pscustomobject]@{ IsDisposed=$false; CloseCalls=0; DisposeCalls=0 }
        $unrelated | Add-Member ScriptMethod Close { $this.CloseCalls++ } -Force
        $unrelated | Add-Member ScriptMethod Dispose { $this.DisposeCalls++; $this.IsDisposed=$true } -Force
        $timer = [pscustomobject]@{ StopCalls=0; DisposeCalls=0; RemovedHandler=$null }
        $timer | Add-Member ScriptMethod Stop { $this.StopCalls++ } -Force
        $timer | Add-Member ScriptMethod Dispose { $this.DisposeCalls++ } -Force
        $timer | Add-Member ScriptMethod Remove_Tick { param($handler) $this.RemovedHandler=$handler } -Force
        $button = [pscustomobject]@{ RemoveCalls=0; RemovedHandler=$null }
        $button | Add-Member ScriptMethod Remove_Click { param($handler) $this.RemoveCalls++; $this.RemovedHandler=$handler } -Force
        $timerHandler = { 'timer' }
        $buttonHandler = { 'button' }
        $image = [pscustomobject]@{ DisposeCalls=0 }
        $image | Add-Member ScriptMethod Dispose { $this.DisposeCalls++ } -Force
        $session = [hashtable]::Synchronized(@{
            Form=$owned; Timer=$timer; TimerHandler=$timerHandler; ButtonHandlers=[System.Collections.Generic.List[object]]::new()
            Images=[System.Collections.Generic.List[object]]::new(); Closed=$false; CleanupCompleted=$false
        })
        [void]$session['ButtonHandlers'].Add([pscustomobject]@{ Button=$button; Handler=$buttonHandler })
        [void]$session['Images'].Add($image)

        $first = Close-TpmCrosshairPreviewSession -Session $session
        $second = Close-TpmCrosshairPreviewSession -Session $session

        $first.AlreadyClosed | Should -BeFalse
        $second.AlreadyClosed | Should -BeTrue
        $owned.CloseCalls | Should -Be 1
        $owned.DisposeCalls | Should -Be 1
        $unrelated.CloseCalls | Should -Be 0
        $unrelated.DisposeCalls | Should -Be 0
        $session['Form'] | Should -BeNullOrEmpty
        $timer.StopCalls | Should -Be 1
        $timer.DisposeCalls | Should -Be 1
        $timer.RemovedHandler | Should -Be $timerHandler
        $button.RemoveCalls | Should -Be 1
        $button.RemovedHandler | Should -Be $buttonHandler
        $image.DisposeCalls | Should -Be 1
    }
    It "runs owned-preview cleanup after success, cancel, early return, and exception" {
        $scenarios = @(
            [pscustomobject]@{ Name='success'; Action={ param($session) $session['P1Index']=0; $session['P2Index']=1; 'complete' }; Throws=$false }
            [pscustomobject]@{ Name='cancel'; Action={ param($session) $session['P1Index']=0; 'cancelled' }; Throws=$false }
            [pscustomobject]@{ Name='early return'; Action={ param($session) return 'returned' }; Throws=$false }
            [pscustomobject]@{ Name='exception'; Action={ param($session) throw 'preview fixture failure' }; Throws=$true }
        )
        foreach ($scenario in $scenarios) {
            $form = [pscustomobject]@{ IsDisposed=$false; CloseCalls=0; DisposeCalls=0 }
            $form | Add-Member ScriptMethod Close { $this.CloseCalls++ } -Force
            $form | Add-Member ScriptMethod Dispose { $this.DisposeCalls++; $this.IsDisposed=$true } -Force
            $session = [hashtable]::Synchronized(@{
                Form=$form; Timer=$null; TimerHandler=$null; ButtonHandlers=[System.Collections.Generic.List[object]]::new()
                Images=[System.Collections.Generic.List[object]]::new(); Closed=$false; CleanupCompleted=$false
                P1Index=$null; P2Index=$null
            })
            if ($scenario.Throws) {
                { Invoke-TpmCrosshairPreviewWithCleanup -Session $session -Action $scenario.Action } | Should -Throw 'preview fixture failure'
            } else {
                [void](Invoke-TpmCrosshairPreviewWithCleanup -Session $session -Action $scenario.Action)
            }
            $session['Closed'] | Should -BeTrue -Because $scenario.Name
            $session['CleanupCompleted'] | Should -BeTrue -Because $scenario.Name
            $form.CloseCalls | Should -Be 1 -Because $scenario.Name
            $form.DisposeCalls | Should -Be 1 -Because $scenario.Name
        }
    }
