Describe "ReShade eligibility display mutation guard" {
    It "keeps every display and eligibility path read-only" {
        $tokens = $null
        $parseErrors = $null
        $ast = [System.Management.Automation.Language.Parser]::ParseFile(
            (Join-Path $PSScriptRoot '..\TeknoParrot-Manager.ps1'), [ref]$tokens, [ref]$parseErrors)
        $parseErrors.Count | Should -Be 0
        $roots = @(
            'Get-TpmHardwareEnvironmentEvidence'
        )
        $functionAsts = @{}
        foreach ($candidate in @($ast.FindAll({
            $args[0] -is [System.Management.Automation.Language.FunctionDefinitionAst]
        }, $true))) {
            if (-not $functionAsts.ContainsKey($candidate.Name)) {
                $functionAsts[$candidate.Name] = $candidate
            }
        }
        $pending = New-Object 'System.Collections.Generic.Queue[string]'
        $seen = @{}
        foreach ($root in $roots) {
            $functionAsts.ContainsKey($root) | Should -BeTrue -Because $root
            if ($functionAsts.ContainsKey($root)) { $pending.Enqueue($root) }
        }
        $reachable = New-Object System.Collections.Generic.List[string]
        while ($pending.Count -gt 0) {
            $name = $pending.Dequeue()
            if ($seen.ContainsKey($name)) { continue }
            $seen[$name] = $true
            [void]$reachable.Add($name)
            $localCalls = @($functionAsts[$name].Body.FindAll({
                $args[0] -is [System.Management.Automation.Language.CommandAst]
            }, $true) | ForEach-Object { $_.GetCommandName() } | Where-Object { $_ })
            foreach ($call in $localCalls) {
                if ($functionAsts.ContainsKey($call) -and -not $seen.ContainsKey($call)) {
                    $pending.Enqueue($call)
                }
            }
        }
        $reachable.Count | Should -BeGreaterOrEqual $roots.Count
        $forbiddenCommands = @(
            'ChangeDisplaySettings', 'ChangeDisplaySettingsEx', 'SetDisplayConfig',
            'DisplaySwitch', 'SetPrimaryMonitor', 'EnableDisplay', 'DisableDisplay',
            'SetDisplayMode', 'SetRefreshRate', 'SetOrientation', 'SetWindowPos',
            'MoveWindow', 'Set-Content', 'Add-Content', 'Out-File', 'Set-ItemProperty',
            'Save-Xml', 'Save-XmlMaybe'
        )
        foreach ($name in $reachable) {
            $fn = $functionAsts[$name]
            $calls = @($fn.Body.FindAll({
                $args[0] -is [System.Management.Automation.Language.CommandAst]
            }, $true) | ForEach-Object { $_.GetCommandName() } | Where-Object { $_ })
            foreach ($command in $forbiddenCommands) { $calls | Should -Not -Contain $command -Because $name }
            $fn.Extent.Text | Should -Not -Match '(?i)\[(System\.IO\.(File|Directory))\]::(Write|Append|Create|Delete|Move|Copy)'
            $fn.Extent.Text | Should -Not -Match '(?i)\.(Save|WriteAllText|WriteAllBytes|AppendAllText|Create|Delete|Move|Copy)\s*\('
            $fn.Extent.Text | Should -Not -Match '(?i)(FullScreen|Windowed|Borderless)\s*='
        }
    }
}

Describe "Shared TPM hardware environment evidence" {
    It "returns privacy-safe subsystem-neutral fields with partial-query tolerance" {
        Mock Get-CimInstance { throw 'fixture query failure' }
        $evidence = Get-TpmHardwareEnvironmentEvidence -VolumePaths @('C:\')
        $names = @($evidence.PSObject.Properties.Name)
        $expected = @('OSVersion','OSBuild','Architecture','CpuModel','PhysicalCoreCount','LogicalProcessorCount','CpuEvidenceConfidence','Adapters','ActiveGpuConfidence','MultiGpuAmbiguous','InstalledRamBytes','AvailableRamBytes','MemoryEvidenceConfidence','RenderWidth','RenderHeight','ResolutionConfidence','DisplayCount','RefreshRate','BatteryPowered','PowerSavingActive','PowerEvidenceConfidence','Volumes','DynamicRefreshed','SensitiveIdentifiersIncluded')
        foreach ($name in $expected) { $names | Should -Contain $name }
        $names | Should -Contain 'Adapters'
        $names | Should -Contain 'Volumes'
        $names | Should -Contain 'DynamicRefreshed'
        $names | Should -Contain 'SensitiveIdentifiersIncluded'
        $evidence.SensitiveIdentifiersIncluded | Should -BeFalse
        $names | Should -Not -Contain 'SerialNumber'
        $names | Should -Not -Contain 'UUID'
        $names | Should -Not -Contain 'MacAddress'
        $evidence.ActiveGpuConfidence | Should -Be 'UNKNOWN'
    }
}

Describe "ReShade ownership classification" {
    It "distinguishes current, stale, changed-profile, unknown, bundled, malformed, and absent installs" {
        $root = Join-Path $TestDrive 'ownership-classification'
        [void][IO.Directory]::CreateDirectory($root)
        $hook = Join-Path $root 'dxgi.dll'
        [IO.File]::WriteAllText($hook, 'runtime')
        $hash = (Get-FileHash -LiteralPath $hook -Algorithm SHA256).Hash
        $clean = Get-TpmReShadeProfile -ProfileId Levels
        $entry = [pscustomobject]@{ DestinationPath=$hook; ExpectedSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }
        $currentManifest = [pscustomobject]@{ EffectId='ReShadeProfile.Levels'; RuntimeVersion='6.8.0'; RuntimeSHA256=$hash; Files=@($entry) }
        $current = Get-TpmReShadeOwnershipClassification -HookPath $hook -TargetRoot $root -ProfileDefinition $clean -CurrentRuntimeSHA256 $hash -CurrentRuntimeVersion '6.8.0' -Manifest $currentManifest
        $current.Status | Should -Be 'TPMOwnedCurrent'
        $staleManifest = [pscustomobject]@{ EffectId='ReShadeProfile.Levels'; RuntimeVersion='6.7.3'; RuntimeSHA256=$hash; Files=@($entry) }
        (Get-TpmReShadeOwnershipClassification -HookPath $hook -TargetRoot $root -ProfileDefinition $clean -CurrentRuntimeSHA256 ('f' * 64) -CurrentRuntimeVersion '6.8.0' -Manifest $staleManifest).Status | Should -Be 'TPMOwnedStaleOutdated'
        (Get-TpmReShadeOwnershipClassification -HookPath $hook -TargetRoot $root -ProfileDefinition (Get-TpmReShadeProfile -ProfileId Original) -CurrentRuntimeSHA256 $hash -CurrentRuntimeVersion '6.8.0' -Manifest $currentManifest).Status | Should -Be 'TPMOwnedChangedProfile'
        (Get-TpmReShadeOwnershipClassification -HookPath $hook -TargetRoot $root -ProfileDefinition $clean).Status | Should -Be 'UnknownUserOwnedConflict'
        $bundled = $entry | Select-Object *
        $bundled.TPMManaged = $false
        (Get-TpmReShadeOwnershipClassification -HookPath $hook -TargetRoot $root -ProfileDefinition $clean -Manifest ([pscustomobject]@{ EffectId='ReShadeProfile.Levels'; Files=@($bundled) })).Status | Should -Be 'BundledPreinstalledProtected'
        (Get-TpmReShadeOwnershipClassification -HookPath $hook -TargetRoot $root -ProfileDefinition $clean -Manifest ([pscustomobject]@{ EffectId='ReShadeProfile.Levels'; Files=@() })).Status | Should -Be 'MalformedNeedsReview'
        $missingHook = Join-Path $root 'missing.dll'
        (Get-TpmReShadeOwnershipClassification -HookPath $missingHook -TargetRoot $root -ProfileDefinition $clean).Status | Should -Be 'NoReShadePresent'
    }

    It "accepts a deployment only when every committed file identity verifies" {
        $root = Join-Path $TestDrive 'ownership-verification'
        [void][IO.Directory]::CreateDirectory($root)
        $path = Join-Path $root 'dxgi.dll'
        [IO.File]::WriteAllText($path, 'verified')
        $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
        $manifest = [pscustomobject]@{ RuntimeVersion='6.8.0'; RuntimeSHA256=$hash; Files=@([pscustomobject]@{ DestinationPath=$path; ExpectedSHA256=$hash; TPMManaged=$true; Kind='ReShadeDll' }) }
        (Test-TpmReShadeDeploymentVerified -DeploymentResult ([pscustomobject]@{ Succeeded=$true; Manifest=$manifest })) | Should -BeTrue
        [IO.File]::WriteAllText($path, 'changed')
        (Test-TpmReShadeDeploymentVerified -DeploymentResult ([pscustomobject]@{ Succeeded=$true; Manifest=$manifest })) | Should -BeFalse
    }
}

Describe "ReShade result action priority" {
    It "prioritizes ReShade actions when protected conflicts coexist with missing paths" {
        $model = Get-TpmReShadeResultActionModel -Result ([pscustomobject]@{ Protected=1; MissingPath=1; MissingDevice=0 })
        $model.Primary | Should -Be 'ReShade'
    }
    It "uses Health Check only when missing paths are the main actionable issue" {
        (Get-TpmReShadeResultActionModel -Result ([pscustomobject]@{ Protected=0; MissingPath=1; MissingDevice=0 })).Primary | Should -Be 'HealthCheck'
        (Get-TpmReShadeResultActionModel -Result ([pscustomobject]@{ Protected=1; MissingPath=0; MissingDevice=0 })).Primary | Should -Be 'ReShade'
    }
    It "returns a no-op acknowledgment for a clean result" {
        $model = Get-TpmReShadeResultActionModel -Result ([pscustomobject]@{ Protected=0; MissingPath=0; MissingDevice=0 })
        $model.Primary | Should -Be 'Acknowledge'
    }
}

Describe "ReShade approved-effect acquisition progress" {
    It "reports bounded asset progress while caching and preserving acquired bytes" {
        $root = Join-Path $TestDrive 'effect-acquisition-progress'
        $cache = Join-Path $root 'cache'
        $stage = Join-Path $root 'stage'
        [void][IO.Directory]::CreateDirectory($cache)
        [void][IO.Directory]::CreateDirectory($stage)
        $script:effectPayloads = @{ 'https://fixture/one'='asset-one'; 'https://fixture/two'='asset-two' }
        $script:effectSpecs = @(
            [pscustomobject]@{ EffectId='Fixture.Effect'; Role='EffectAsset'; RelativePath='Shaders/one.fx'; SourceRelativePath='Shaders/one.fx'; CacheRelativePath='Fixture.Effect/one.fx'; Url='https://fixture/one'; SHA256=(Get-TpmAutoSyncTextSha256 -Text 'asset-one'); ByteLength=$null; PinnedRevision=('a' * 40); Repository='Fixture/Effect'; License='MIT'; InlineBytes=$null }
            [pscustomobject]@{ EffectId='Fixture.Effect'; Role='EffectAsset'; RelativePath='SweetFX/two.fxh'; SourceRelativePath='SweetFX/two.fxh'; CacheRelativePath='Fixture.Effect/two.fxh'; Url='https://fixture/two'; SHA256=(Get-TpmAutoSyncTextSha256 -Text 'asset-two'); ByteLength=$null; PinnedRevision=('a' * 40); Repository='Fixture/Effect'; License='MIT'; InlineBytes=$null }
        )
        $script:effectAcquisitionProgress = New-Object System.Collections.Generic.List[object]
        Mock Get-TpmReShadeApprovedEffectFiles { $script:effectSpecs }
        Mock Invoke-TpmDownloadWebRequest {
            param($DownloadUrl, $TempPath, $Label)
            [IO.File]::WriteAllText($TempPath, $script:effectPayloads[$DownloadUrl])
        }
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:effectAcquisitionProgress.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete })
        }
        Mock Invoke-TpmWebRequestSilently { throw 'ReShade acquisition must use the progress-enabled download wrapper.' }

        $result = Acquire-TpmReShadeApprovedEffect -EffectId 'Fixture.Effect' -CacheRoot $cache -StagingRoot $stage

        $result.Files.Count | Should -Be 2
        (Get-Content -LiteralPath $result.Files[0].Path -Raw) | Should -Be 'asset-one'
        (Get-Content -LiteralPath $result.Files[1].Path -Raw) | Should -Be 'asset-two'
        @($script:effectAcquisitionProgress | Where-Object { $_.Label -eq 'ReShade effect acquisition' -and $_.Total -eq 2 -and -not $_.Complete }).Count | Should -Be 2
        @($script:effectAcquisitionProgress | Where-Object { $_.Label -eq 'ReShade effect acquisition' -and $_.Complete }).Count | Should -Be 1
        (Get-Content -LiteralPath (Join-Path $cache 'Fixture.Effect\one.fx') -Raw) | Should -Be 'asset-one'
        (Get-Content -LiteralPath (Join-Path $cache 'Fixture.Effect\two.fxh') -Raw) | Should -Be 'asset-two'
    }
}

Describe "Approved ReShade transactional deployment" {
    It "fails before mutation when approved staging fails" {
        $root = Join-Path $TestDrive 'stage-failure'; $dest = Join-Path $root 'ReShade'; $ownership = Join-Path $root 'ownership.json'
        $prior = [pscustomobject]@{ SchemaVersion=1; EffectId='SweetFX.Vibrance'; PinnedRevision=('a' * 40); Files=@([pscustomobject]@{ DestinationPath=(Join-Path $root 'prior.fx'); ExpectedSHA256=('0' * 64); ActualSHA256=('0' * 64); TPMManaged=$true }) }
        Save-TpmReShadeOwnershipManifest -Manifest $prior -Path $ownership
        $preBytes=[IO.File]::ReadAllBytes($ownership); $preSha=(Get-FileHash -LiteralPath $ownership -Algorithm SHA256).Hash
        Mock Acquire-TpmReShadeApprovedEffect { throw 'staging fixture failure' }
        { Install-TpmReShadeApprovedEffect -EffectId 'SweetFX.Vibrance' -CacheRoot $root } | Should -Throw '*staging fixture failure*'
        $postBytes=[IO.File]::ReadAllBytes($ownership); $postSha=(Get-FileHash -LiteralPath $ownership -Algorithm SHA256).Hash
        [Convert]::ToBase64String($postBytes) | Should -Be ([Convert]::ToBase64String($preBytes)); $postSha | Should -Be $preSha
        Test-Path -LiteralPath $dest | Should -BeFalse
    }
    It "preserves ownership bytes on staged hash failure" {
        $root=Join-Path $TestDrive 'hash-preserve'; $ownership=Join-Path $root 'ownership.json'; [void][IO.Directory]::CreateDirectory($root)
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{SchemaVersion=1;EffectId='SweetFX.Vibrance';Files=@([pscustomobject]@{DestinationPath=(Join-Path $root 'old.fx');ExpectedSHA256=('0'*64);ActualSHA256=('0'*64);TPMManaged=$true})}) -Path $ownership
        $pre=[IO.File]::ReadAllBytes($ownership); $sha=(Get-FileHash -LiteralPath $ownership -Algorithm SHA256).Hash; $stage=Join-Path $root 'stage'; [void][IO.Directory]::CreateDirectory($stage); $src=Join-Path $stage 'bad.fx'; [IO.File]::WriteAllText($src,'bad')
        Mock Acquire-TpmReShadeApprovedEffect { [pscustomobject]@{StagingRoot=$stage;Files=@([pscustomobject]@{RelativePath='Shaders/SweetFX/Vibrance.fx';Path=$src;SHA256=('0'*64)})} }
        {Install-TpmReShadeApprovedEffect -EffectId 'SweetFX.Vibrance' -CacheRoot $root} | Should -Throw '*INTEGRITY*'
        [Convert]::ToBase64String([IO.File]::ReadAllBytes($ownership)) | Should -Be ([Convert]::ToBase64String($pre)); (Get-FileHash -LiteralPath $ownership -Algorithm SHA256).Hash | Should -Be $sha
    }
    It "rejects staged content with an invalid approved hash" {
        $root = Join-Path $TestDrive 'hash-failure'; $stage = Join-Path $root 'stage'; [void][IO.Directory]::CreateDirectory($stage)
        $source = Join-Path $stage 'bad.fx'; [IO.File]::WriteAllText($source, 'bad')
        Mock Acquire-TpmReShadeApprovedEffect { [pscustomobject]@{ StagingRoot=$stage; Files=@([pscustomobject]@{ RelativePath='Shaders/SweetFX/Vibrance.fx'; Path=$source; SHA256=('0' * 64) }) } }
        { Install-TpmReShadeApprovedEffect -EffectId 'SweetFX.Vibrance' -CacheRoot $root } | Should -Throw '*INTEGRITY*'
    }
    It "supports a coherent two-file CRT manifest" {
        $manifest = [pscustomobject]@{ SchemaVersion=1; EffectId='FXShaders.CRT_Lottes'; PinnedRevision=('b' * 40); Files=@(
            [pscustomobject]@{ EffectId='FXShaders.CRT_Lottes'; PinnedRevision=('b' * 40); RelativeSource='Shaders/CRT_Lottes.fx'; DestinationPath='C:\ReShade\Shaders\CRT_Lottes.fx'; ExpectedSHA256='A'; ActualSHA256='A'; TPMManaged=$true },
            [pscustomobject]@{ EffectId='FXShaders.CRT_Lottes'; PinnedRevision=('b' * 40); RelativeSource='Shaders/CRT_Lottes.fxh'; DestinationPath='C:\ReShade\Shaders\CRT_Lottes.fxh'; ExpectedSHA256='B'; ActualSHA256='B'; TPMManaged=$true }) }
        $path = Join-Path $TestDrive 'crt-ownership.json'
        Save-TpmReShadeOwnershipManifest -Manifest $manifest -Path $path
        $loaded = Read-TpmReShadeOwnershipManifest -Path $path
        @($loaded.Files).Count | Should -Be 2
        $loaded.EffectId | Should -Be 'FXShaders.CRT_Lottes'
    }
}
Describe "Paged picker wrapping" {
    It 'reports profile discovery progress and preserves registered-game ordering' {
        $root=Join-Path $TestDrive 'registered-picker-discovery'
        New-Item -ItemType Directory -Path $root,(Join-Path $root 'FullBackup') -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'B.xml') -Value '<GameProfile />'
        Set-Content -LiteralPath (Join-Path $root 'A.xml') -Value '<GameProfile />'
        Set-Content -LiteralPath (Join-Path $root 'FullBackup\Hidden.xml') -Value '<GameProfile />'
        $script:registeredPickerDiscovery=New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress { [void]$script:registeredPickerDiscovery.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete }) }
        Mock Read-TpmChoice { 'A' }

        $selected=@(Select-RegisteredGamesInteractive -UserProfilesDir $root)

        @($selected | ForEach-Object BaseName) | Should -Be @('A','B')
        $rows=@($script:registeredPickerDiscovery | Where-Object { $_.Label -eq 'Registered-game picker profile discovery' })
        (@($rows | Where-Object { -not $_.Complete } | ForEach-Object { $_.Current }) -join ',') | Should -Be '0,1,2'
        @($rows | Where-Object { $_.Complete -and $_.Current -eq 2 -and $_.Total -eq 0 }).Count | Should -Be 1
    }
    It 'reports dgVoodoo2 picker discovery and preserves selected profile order' {
        $root=Join-Path $TestDrive 'dgvoodoo2-picker-discovery'
        New-Item -ItemType Directory -Path $root,(Join-Path $root 'FullBackup') -Force | Out-Null
        Set-Content -LiteralPath (Join-Path $root 'B.xml') -Value '<GameProfile />'
        Set-Content -LiteralPath (Join-Path $root 'A.xml') -Value '<GameProfile />'
        Set-Content -LiteralPath (Join-Path $root 'FullBackup\Hidden.xml') -Value '<GameProfile />'
        $script:dgVoodoo2PickerDiscovery=New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress { [void]$script:dgVoodoo2PickerDiscovery.Add([pscustomobject]@{ Label=$Label; Current=$Current; Total=$Total; Complete=[bool]$Complete }) }
        $script:dgVoodoo2PickerInputs=[System.Collections.Generic.Queue[string]]::new()
        @('1','D') | ForEach-Object { [void]$script:dgVoodoo2PickerInputs.Enqueue($_) }
        Mock Read-HostSafe { $script:dgVoodoo2PickerInputs.Dequeue() }

        $selected=@(Select-DgVoodoo2GamesInteractive -UserProfilesDir $root)

        @($selected | ForEach-Object BaseName) | Should -Be @('A')
        $rows=@($script:dgVoodoo2PickerDiscovery | Where-Object { $_.Label -eq 'dgVoodoo2 picker profile discovery' })
        (@($rows | Where-Object { -not $_.Complete } | ForEach-Object { $_.Current }) -join ',') | Should -Be '0,1,2'
        @($rows | Where-Object { $_.Complete -and $_.Current -eq 2 -and $_.Total -eq 0 }).Count | Should -Be 1
    }
    It "wraps next and previous navigation without clearing queue state" {
        $source = Get-Content -LiteralPath (Join-Path $PSScriptRoot '..\TeknoParrot-Manager.ps1') -Raw
        $source | Should -Match '\$page = if \(\$page -lt \(\$totalPages - 1\)\) \{ \$page \+ 1 \} else \{ 0 \}'
        $source | Should -Match '\$page = if \(\$page -gt 0\) \{ \$page - 1 \} else \{ \$totalPages - 1 \}'
        $source | Should -Match '\(\* = already in queue\)'
        $source | Should -Match '\(\* = in queue \| \[\+\] = supplementary\)'
    }
    It "does not retain the old edge error messages and keeps one-page lists stable" {
        $source = Get-Content -LiteralPath (Join-Path $PSScriptRoot '..\TeknoParrot-Manager.ps1') -Raw
        $source | Should -Not -Match 'Already on last page|Already on first page'
        $source | Should -Match '\$page = if \(\$page -lt \(\$pages - 1\)\) \{ \$page \+ 1 \} else \{ 0 \}'
        $source | Should -Match '\$page = if \(\$page -gt 0\) \{ \$page - 1 \} else \{ \$pages - 1 \}'
    }
}

Describe "Action Required report output" {
    It "Action Required report excludes raw imported notes" {
        # Mutation: include the raw imported notes in Action Required -> internal wording reaches the player.
        $actionPath = Join-Path $TestDrive 'ActionItems.txt'
        $notesPath = Join-Path $TestDrive 'GameNotes.txt'
        $manual = @{
            'Manual Racer' = [pscustomobject]@{
                ExeName = 'arcade.exe'; Reason = 'unmatched'; ClaimedBy = $null
                Profiles = 'ManualProfile'; ProfileCount = 1; BestGuess = $null; BestScore = 0
            }
        }
        $ambiguous = @([pscustomobject]@{ Code = 'Broken Racer'; Exe = 'C:\Games\Broken\pcsx2x6.exe' })
        $notFound = @([pscustomobject]@{ Code = 'Missing Racer' })
        $result = [pscustomobject]@{ Unmatched = @('TPM-ExternalFolder') }
        $compatibilityWarnings = [pscustomobject]@{
            PathTooLong = @([pscustomobject]@{ Code = 'Long Racer'; Length = 280; Limit = 260; Suggested = 'D:\TPGames\Long Racer' })
            DllMismatch = @()
            GpuIncompatible = @()
            BiosMissing = @([pscustomobject]@{
                EmulatorType = 'PCSX2X6'; ExpectedDir = 'C:\TPM\firmware'
                MissingFiles = @('bios.bin'); AffectedGames = @('TPM-ExternalGame')
            })
            ExeMissing = @([pscustomobject]@{
                EmulatorType = 'PCSX2X6'; ContractId = 'TPM.ECVF'; ContractStatus = 'VALID'
                DetectorMethod = 'contract'; DetectorSource = 'TPM source'; Confidence = 'HIGH'
                ExpectedPath = 'C:\TPM\emulator\pcsx2x6.exe'; AffectedGames = @('TPM-ExternalGame')
            })
        }
        $controls = @([pscustomobject]@{
            Code = 'Controls Racer'
            SummaryLines = @(
                'TeknoParrot Manager registered this game, but that does not prove controls work.'
                'TeknoParrotUI still owns the game setup wizard and controls configuration.'
            )
        })
        $importedNotes = @([pscustomobject]@{
            Code = 'Broken Racer'; GameName = 'Broken Racer'; SetupExe = 'setup.exe'
            Notes = 'Raw technical note: this game sucks; fuckin source text should stay out of Action Required.'
        })
        Write-TpmGameNotesReport -SetupNotes $importedNotes -NotesPath $notesPath -Quiet | Should -BeTrue
        Write-TpmActionRequiredReport -ActionPath $actionPath -ManualRegData $manual `
            -AmbiguousPaths $ambiguous -NotFound $notFound `
            -Result $result -CompatibilityWarnings $compatibilityWarnings `
            -ControlReadinessItems $controls -GameNotesPath $notesPath -Quiet | Should -BeTrue
        $action = [System.IO.File]::ReadAllText($actionPath)
        $action | Should -Match 'FIX THESE GAME PATHS IN TEKNOPARROTUI'
        $action | Should -Match 'pcsx2x6\.exe'
        $action | Should -Match 'PCSX2X6 FIRMWARE NOT INSTALLED'
        $action | Should -Match 'folder paths are too long'
        $action | Should -Match 'shorten parent folders'
        $action | Should -Match 'saved GamePath'
        $action | Should -Match 'CONTROLS NOT READY : Controls Racer'
        $action | Should -Match 'TeknoParrot Manager only checked the contract-declared path'
        $action | Should -Not -Match 'TPM only checked the contract-declared path'
        $action | Should -Not -Match 'Source notes:|Raw technical note|This game sucks|fuckin'
        $action.Contains('TPM-ExternalFolder') | Should -BeTrue
        $action.Contains('TPM.ECVF') | Should -BeTrue
        $action.Contains('C:\TPM\emulator\pcsx2x6.exe') | Should -BeTrue
    }

    It "keeps the previous ACTION REQUIRED report intact and returns false when replacing it fails (FIX29 SCAN2-07)" {
        $reportDir = Join-Path $TestDrive ('action-report-atomic-' + [guid]::NewGuid().ToString('N'))
        [void][System.IO.Directory]::CreateDirectory($reportDir)
        $actionPath = Join-Path $reportDir 'TeknoParrot-Manager-ActionItems.txt'
        [System.IO.File]::WriteAllText($actionPath, 'PREVIOUS REPORT')
        $notFound = @([pscustomobject]@{ Code = 'Missing Racer' })
        $script:fx29ReportLog = New-Object System.Collections.Generic.List[string]
        Mock Write-Log { [void]$script:fx29ReportLog.Add([string]$msg) }
        Mock Invoke-TpmAtomicFileReplace { throw 'simulated replace failure' }

        Write-TpmActionRequiredReport -ActionPath $actionPath -NotFound $notFound -Quiet | Should -BeFalse

        [System.IO.File]::ReadAllText($actionPath) | Should -BeExactly 'PREVIOUS REPORT'
        (@(Get-ChildItem -LiteralPath $reportDir -Force | ForEach-Object Name) -join '|') | Should -BeExactly 'TeknoParrot-Manager-ActionItems.txt'
        @($script:fx29ReportLog | Where-Object { $_ -like 'Action items: could not write file*' }).Count | Should -Be 1
    }

    It "replaces an existing ACTION REQUIRED report with the complete new text (FIX29 SCAN2-07)" {
        $reportDir = Join-Path $TestDrive ('action-report-replace-' + [guid]::NewGuid().ToString('N'))
        [void][System.IO.Directory]::CreateDirectory($reportDir)
        $actionPath = Join-Path $reportDir 'TeknoParrot-Manager-ActionItems.txt'
        [System.IO.File]::WriteAllText($actionPath, 'PREVIOUS REPORT')
        $notFound = @([pscustomobject]@{ Code = 'Missing Racer' })

        Write-TpmActionRequiredReport -ActionPath $actionPath -NotFound $notFound -RunId 'fx29-run' -Quiet | Should -BeTrue

        $text = [System.IO.File]::ReadAllText($actionPath)
        $text | Should -Match 'Run ID: fx29-run'
        $text | Should -Match 'Missing Racer'
        $text | Should -Not -Match 'PREVIOUS REPORT'
        (@(Get-ChildItem -LiteralPath $reportDir -Force | ForEach-Object Name) -join '|') | Should -BeExactly 'TeknoParrot-Manager-ActionItems.txt'
    }

    It "Beginner-facing reports exclude hostile source-note wording" {
        $notesPath = Join-Path $TestDrive 'GameNotes.txt'
        $notes = @([pscustomobject]@{
            Code = 'Broken Racer'; GameName = 'Broken Racer'; SetupExe = 'setup.exe'
            Notes = 'Useful technical note: use C:\TPM\profiles\broken.xml. This game sucks; fuckin devs called users useless users and sensitive snowflake.'
        })
        Write-TpmGameNotesReport -SetupNotes $notes -NotesPath $notesPath -Quiet | Should -BeTrue
        $text = [System.IO.File]::ReadAllText($notesPath)
        $text | Should -Match 'Useful technical note'
        $text | Should -Match '\[language removed\]'
        $text | Should -Match '\[insult removed\]'
        $text | Should -Not -Match '(?i)sucks?|fuck\w*|useless users|sensitive snowflake'
        $text.Contains('C:\TPM\profiles\broken.xml') | Should -BeTrue
    }

    It "Imported notes are separated from required actions" {
        $actionPath = Join-Path $TestDrive 'ActionItems-notes-only.txt'
        $notesPath = Join-Path $TestDrive 'GameNotes.txt'
        $notes = @([pscustomobject]@{
            Code = 'Notes Only'; GameName = 'Notes Only'; SetupExe = ''
            Notes = 'Technical note only: verify the TPM profile path before launch.'
        })
        Write-TpmGameNotesReport -SetupNotes $notes -NotesPath $notesPath -Quiet | Should -BeTrue
        Write-TpmActionRequiredReports -HasAnyAction:$false -ActionPath $actionPath | Should -BeFalse
        Test-Path -LiteralPath $notesPath | Should -BeTrue
        Test-Path -LiteralPath $actionPath | Should -BeFalse
        ([System.IO.File]::ReadAllText($notesPath)) | Should -Match 'Technical note only'
        ([System.IO.File]::ReadAllText($notesPath)) | Should -Match 'TPM profile path'
    }

    It "tells the user when the game notes file cannot be saved and reports no file" {
        $notes = @([pscustomobject]@{ Code = 'Notes Only'; GameName = 'Notes Only'; SetupExe = ''; Notes = 'A note.' })
        $blocked = Join-Path (Join-Path $TestDrive 'no-such-folder') 'GameNotes.txt'
        $shown = New-Object System.Collections.ArrayList
        Mock Write-Host { [void]$shown.Add([string]$Object) }
        Write-TpmGameNotesReport -SetupNotes $notes -NotesPath $blocked -Quiet | Should -BeFalse
        Test-Path -LiteralPath $blocked | Should -BeFalse
        ($shown -join "`n") | Should -Match 'could not be saved'
    }

    It "explains the Action Required screen in five plain lines with the real save path and no technical words" {
        $savePath = 'C:\TPM\Reports\TeknoParrot-Manager-ActionItems.txt'
        $lines = @(Get-TpmActionRequiredPlainLines -For Screen -SavePath $savePath)
        $lines.Count | Should -BeLessOrEqual 5
        $text = $lines -join "`n"
        $text | Should -Match 'What this is: a short to-do list of things the tool could not fix by itself\.'
        $text | Should -Match 'Why you see it: some games or files need something from you first'
        $text | Should -Match 'What to do: read each item below, fix it, then run this step again\.'
        $text | Should -Match 'saved as a text file, so you can come back to it'
        $text.Contains($savePath) | Should -BeTrue
        $text | Should -Match 'Nothing is wrong with the tool\.'
        $text | Should -Not -Match '(?i)ECVF|CRC32|ReasonCode|RunId|Run ID|\bXML\b|GamePath|contract|detector'
        $text | Should -Not -Match '[^\x20-\x7E\n]'
        (@(Get-TpmActionRequiredPlainLines -For Screen -SavePath '') -join "`n") | Should -Not -Match '\\'
    }

    It "puts a plain header at the top of the saved file and keeps the items in order" {
        $actionPath = Join-Path $TestDrive 'ActionItems-header.txt'
        $manual = @{
            'Manual Racer' = [pscustomobject]@{
                ExeName = 'arcade.exe'; Reason = 'unmatched'; ClaimedBy = $null
                Profiles = 'ManualProfile'; ProfileCount = 1; BestGuess = $null; BestScore = 0
            }
        }
        $notFound = @([pscustomobject]@{ Code = 'Missing Racer' })
        Write-TpmActionRequiredReport -ActionPath $actionPath -ManualRegData $manual -NotFound $notFound -RunId 'plain-run' -Quiet | Should -BeTrue
        $text = [System.IO.File]::ReadAllText($actionPath)
        $text.StartsWith('TeknoParrot Manager - Action Required') | Should -BeTrue
        $header = $text.IndexOf('WHAT THIS LIST IS')
        $header | Should -BeGreaterThan 0
        $text | Should -Match 'A short to-do list of things TeknoParrot Manager could not fix by itself\.'
        $text | Should -Match 'WHY IT EXISTS'
        $text | Should -Match 'Some games or files need something from you before they will work\.'
        $text | Should -Match 'WHAT TO DO'
        $text | Should -Match 'Nothing is wrong with the tool\.'
        $text | Should -Match 'NEED HELP\?'
        $text | Should -Match 'Create a support package'
        $register = $text.IndexOf('REGISTER THESE GAMES IN TEKNOPARROTUI')
        $extract = $text.IndexOf('EXTRACT THESE GAMES FIRST, THEN RE-RUN REPAIR')
        $header | Should -BeLessThan $register
        $register | Should -BeLessThan $extract
        $text | Should -Match 'Run ID: plain-run'
    }

    It "keeps machine names out of the plain Action Required wording" {
        $all = @(
            (Get-TpmActionRequiredPlainLines -For Screen -SavePath 'C:\TPM\Reports\TeknoParrot-Manager-ActionItems.txt')
            (Get-TpmActionRequiredPlainLines -For File)
        ) -join "`n"
        foreach ($name in @($env:COMPUTERNAME, $env:USERDOMAIN)) {
            if (-not [string]::IsNullOrWhiteSpace($name) -and $name.Length -ge 4) { $all.IndexOf($name, [System.StringComparison]::OrdinalIgnoreCase) | Should -Be -1 }
        }
        $all | Should -Not -Match '[^\x20-\x7E\n]'
    }

    It "saves the list to the Reports folder without opening a Save window" {
        $source = $script:ProductionSource
        $source | Should -Not -Match 'Save Action Required summary'
        $source | Should -Match 'Get-TpmActionRequiredPlainLines -For Screen -SavePath \(\[string\]\$script:TpmOwnedLayout\.ActionItemsPath\) -Preview:\$dryRunActive\)'
    }
}

Describe "Post-0909174 remediation result UX contracts" {
