        $result = [pscustomobject]@{ Outcome = 'FAILED_BEFORE_MUTATION'; Cancelled = $false; GpuVendor = 'Intel'; Updated = 0; Unchanged = 0; NotApplicable = 0; Skipped = 1; Errors = 0; MissingPath = 1; MissingDevice = 0; SkipDetails = @($skip); FailureRecords = @(); Mutation = [pscustomobject]@{ FailedItemCount = 0; UnknownItemCount = 0; UnattemptedItemCount = 0; SkippedItems = @('GameA') } }
