            [pscustomobject]@{ PSPath = 'HKLM:\ProfileList\S-1-5-OTHER'; PSChildName = 'S-1-5-OTHER' }
        )
        $script:pgCleanupEntries = @(
            [pscustomobject]@{
                DisplayName = 'PostgreSQL 8.3'
                InstallLocation = $script:PostgresInstallDir
                PSChildName = '{11111111-2222-3333-4444-555555555555}'
            },
            [pscustomobject]@{
                DisplayName = 'PostgreSQL 8.3 unrelated'
                InstallLocation = 'D:\Unrelated\PostgreSQL'
                PSChildName = '{AAAAAAAA-BBBB-CCCC-DDDD-EEEEEEEEEEEE}'
            }
        )
        $script:pgCleanupProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-Log {}
        Mock Test-PostgresInstallationsRegistry { [pscustomobject]@{ HasRecord = $false; Mismatch = $false } }
        Mock Get-ItemProperty {
            param($Path, $Name, $ErrorAction)
            if ($Name -eq 'ProfileImagePath') {
                if ($Path -eq 'HKLM:\ProfileList\S-1-5-TEST-PG') {
                    return [pscustomobject]@{ ProfileImagePath = 'C:\Users\postgres' }
                }
                return [pscustomobject]@{ ProfileImagePath = 'C:\Users\Other' }
            }
            return $script:pgCleanupEntries
        }
        Mock Get-ChildItem {
            param($Path, $ErrorAction)
            if ($Path -eq $script:pgCleanupProfileList) { return $script:pgCleanupProfileKeys }
        }
        Mock Get-Service { @() }
        Mock Get-LocalUser { $null }
        Mock Test-Path {
            param($LiteralPath)
            ($LiteralPath -eq $script:PostgresInstallDir) -or ($LiteralPath -eq 'C:\Users\postgres')
        }
        Mock Start-Process {}
        Mock Remove-Item {}
        Mock Remove-LocalUser {}
        Mock Write-TpmCompactExtractionProgress {
            [void]$script:pgCleanupProgress.Add([pscustomobject]@{
                Label = $Label; Current = $Current; Total = $Total; Complete = [bool]$Complete; Outcome = $Outcome
            })
        }

        $inventory = Get-PostgresPartialInstallInventory

        $inventory.Found | Should -BeTrue
        $descriptions = @($inventory.Objects | ForEach-Object { [string]$_.Description })
        $descriptions | Should -Contain "Installed program 'PostgreSQL 8.3' (C:\TPM-Test\PostgreSQL\8.3)"
        $descriptions | Should -Contain "Installed program 'PostgreSQL 8.3 unrelated' (D:\Unrelated\PostgreSQL)"
        $descriptions | Should -Contain "Folder 'C:\TPM-Test\PostgreSQL\8.3'"
        $descriptions | Should -Contain "User profile 'C:\Users\postgres' (registered as S-1-5-TEST-PG)"
        @($descriptions | Where-Object { $_ -like '*C:\Users\Other*' }).Count | Should -Be 0
        @($inventory.Objects | Where-Object { $_.Kind -eq 'InstalledProgram' }).Count | Should -Be 2
        Should -Invoke Start-Process -Times 0 -Exactly
        Should -Invoke Remove-Item -Times 0 -Exactly
        Should -Invoke Remove-LocalUser -Times 0 -Exactly
        $updates = @($script:pgCleanupProgress | Where-Object { -not $_.Complete -and $_.Label -eq 'PostgreSQL leftover check' -and $_.Total -eq 0 })
        (@($updates | ForEach-Object { $_.Current }) -join ',') | Should -Be '0,1,2,3,4'
        $closes = @($script:pgCleanupProgress | Where-Object { $_.Complete -and $_.Label -eq 'PostgreSQL leftover check' })
        $closes.Count | Should -Be 1
        $closes[0].Current | Should -Be 4
        $closes[0].Total | Should -Be 0
        $closes[0].Outcome | Should -Be 'Final'
    }
