        (Get-FileHash -LiteralPath $stage.Payload -Algorithm SHA256).Hash | Should -Be $memberEntry.SourceSha256
        $stage.Size | Should -Be $bytes.Length
        Remove-Item -LiteralPath $stage.Root -Recurse -Force
