    It 'selects a single build-filtered variant through production patch planning and apply' {
        $selected = [pscustomobject]@{
            Id='fixture.variant.integration-selected';ProfileId='SyntheticFixture';Executable='synthetic.exe'
            ExecutableSha256=$requiredPatchFixture.ExecutableSha256;SourceUrl='https://example.invalid/selected'
            SourceRevision=('E' * 40);ExclusiveGroup='fixture.variant-integration'
            Operations=@([pscustomobject]@{
                Type='ReplaceFile';Target='settings.ini';BeforeSha256=$requiredPatchFixture.BeforeSha256
                AfterSha256=$requiredPatchFixture.SettingsAfterSha256;Payload='settings.new'
                PayloadSha256=$requiredPatchFixture.SettingsAfterSha256
            })
        }
        $otherBuild = [pscustomobject]@{
            Id='fixture.variant.integration-other-build';ProfileId='SyntheticFixture';Executable='synthetic.exe'
            ExecutableSha256=('F' * 64);SourceUrl='https://example.invalid/other-build'
            SourceRevision=('F' * 40);ExclusiveGroup='fixture.variant-integration'
            Operations=@([pscustomobject]@{
                Type='ReplaceFile';Target='settings.ini';BeforeSha256=$requiredPatchFixture.BeforeSha256
                AfterSha256=$requiredPatchFixture.SettingsAfterSha256;Payload='settings.new'
                PayloadSha256=$requiredPatchFixture.SettingsAfterSha256
            })
        }
        $content = [pscustomobject]@{Schema=3;Entries=@($selected,$otherBuild)} | ConvertTo-Json -Depth 10
        $inputs = @{
            CatalogContent=$content;CatalogSha256=(Get-TpmPatchTextSha256 $content)
            PatchId=$selected.Id;ProfileId=$selected.ProfileId;GameRoot=$requiredPatchFixture.GameRoot
            PayloadRoot=$requiredPatchFixture.PayloadRoot;RecoveryRoot=$requiredPatchFixture.RecoveryRoot
            ProtectedRoots=@($requiredPatchFixture.ProtectedRoot)
        }

        $plan = Get-TpmPatchPlan @inputs
        $plan.Status | Should -BeExactly 'Ready'
        $plan.PatchId | Should -BeExactly $selected.Id

        $applied = Invoke-TpmCatalogPatch @inputs -Confirm:$false
        $applied.Status | Should -BeExactly 'Applied'
        [IO.File]::ReadAllText($requiredPatchFixture.Before) | Should -Be 'patched setting'

        $restored = Undo-TpmCatalogPatch @inputs -RecoveryDirectory $applied.RecoveryDirectory -Confirm:$false
        $restored.Status | Should -BeExactly 'Restored'
        [IO.File]::ReadAllText($requiredPatchFixture.Before) | Should -Be 'original setting'
    }

    It 'backs up, applies, skips exact repeat, undoes by receipt, and reapplies the same grouped recipe' {
        $replace = [pscustomobject]@{
            Type='ReplaceFile';Target='settings.ini';BeforeSha256=$requiredPatchFixture.BeforeSha256
            AfterSha256=$requiredPatchFixture.SettingsAfterSha256;Payload='settings.new'
            PayloadSha256=$requiredPatchFixture.SettingsAfterSha256
        }
        $create = [pscustomobject]@{
            Type='CreateFile';Target='BepInEx/plugins/FGBTPPlugin.dll';BeforeState='Absent'
            AfterSha256=$requiredPatchFixture.CreatedSha256;Payload='plugin.dll'
            PayloadSha256=$requiredPatchFixture.CreatedSha256
        }
        $entry = [pscustomobject]@{
            Id='fixture.apply-undo';ProfileId='SyntheticFixture';Executable='synthetic.exe'
            ExecutableSha256=$requiredPatchFixture.ExecutableSha256;SourceUrl='https://example.invalid/fixture'
            SourceRevision=('E' * 40);ExclusiveGroup='';Operations=@($replace,$create)
        }
        $content = [pscustomobject]@{Schema=3;Entries=@($entry)} | ConvertTo-Json -Depth 10
        $inputs = @{
            CatalogContent=$content;CatalogSha256=(Get-TpmPatchTextSha256 $content)
            PatchId='fixture.apply-undo';ProfileId='SyntheticFixture';GameRoot=$requiredPatchFixture.GameRoot
            PayloadRoot=$requiredPatchFixture.PayloadRoot;RecoveryRoot=$requiredPatchFixture.RecoveryRoot
            ProtectedRoots=@($requiredPatchFixture.ProtectedRoot)
        }
        (Get-TpmPatchPlan @inputs).Status | Should -Be 'Ready'
        $first = Invoke-TpmCatalogPatch @inputs -Confirm:$false
        $first.Status | Should -Be 'Applied'
        [IO.File]::ReadAllText($requiredPatchFixture.Before) | Should -Be 'patched setting'
        [IO.File]::ReadAllText($requiredPatchFixture.PluginTarget) | Should -Be 'synthetic required plugin'
        $receipt = [IO.File]::ReadAllText((Join-Path $first.RecoveryDirectory 'receipt.json')) | ConvertFrom-Json
        $backup = [string]$receipt.Operations[0].Backup
        (Get-FileHash -LiteralPath $backup -Algorithm SHA256).Hash | Should -Be $requiredPatchFixture.BeforeSha256
        (Get-TpmPatchPlan @inputs).Status | Should -Be 'AlreadyApplied'
        (Invoke-TpmCatalogPatch @inputs -Confirm:$false).Status | Should -Be 'AlreadyApplied'
        (Undo-TpmCatalogPatch @inputs -RecoveryDirectory $first.RecoveryDirectory -Confirm:$false).Status | Should -Be 'Restored'
        [IO.File]::ReadAllText($requiredPatchFixture.Before) | Should -Be 'original setting'
        Test-Path -LiteralPath $requiredPatchFixture.PluginTarget | Should -BeFalse
        (Invoke-TpmCatalogPatch @inputs -Confirm:$false).Status | Should -Be 'Applied'
        (Get-TpmPatchPlan @inputs).Status | Should -Be 'AlreadyApplied'
    }

    It 'checks path lengths before writing anything and works at the longest accepted game folder (<Name>)' -ForEach @(
        @{Name='largest game folder the engine accepts: apply, skip, undo, reapply';GameLen=194;RecoveryLen=0;LongName=$false;Expect='Works'}
        @{Name='game folder one character too long for the engine temp file names';GameLen=195;RecoveryLen=0;LongName=$false;Expect='Refuse';Pattern='A folder path is too long for Windows to patch safely \(211 characters\)\. Move TeknoParrot or the game to a folder with a shorter path\.'}
        @{Name='target file path of 260 characters';GameLen=194;RecoveryLen=0;LongName=$true;UndoCheck=$true;Expect='Refuse';Pattern='A file path is too long for Windows to patch safely \(260 characters\)\. Move TeknoParrot or the game to a folder with a shorter path\.'}
        @{Name='recovery folder whose receipt or backup names would pass 259';GameLen=0;RecoveryLen=153;LongName=$false;Expect='Refuse';Pattern='A folder path is too long for Windows to patch safely \(153 characters\)\.'}
    ) {
        # Mutation: remove the length check in Resolve-TpmPatchPath / Assert-TpmPatchFolderBudget -> the patch starts, writes backups or temp files and then fails (or succeeds only where the host allows long paths) instead of being refused up front. Host-independent: it fails on PowerShell 7 too.
        $gamePath = $requiredPatchFixture.GameRoot
        if ($GameLen -gt 0) {
            $gamePath = Join-Path $requiredPatchFixture.Root 'long'
            $gamePath = Join-Path $gamePath ('y' * ($GameLen - $gamePath.Length - 1))
            $gamePath.Length | Should -Be $GameLen
            [void][IO.Directory]::CreateDirectory((Join-Path $gamePath 'BepInEx\plugins'))
            [IO.File]::Copy($requiredPatchFixture.Executable,(Join-Path $gamePath 'synthetic.exe'))
            [IO.File]::Copy($requiredPatchFixture.Before,(Join-Path $gamePath 'settings.ini'))
        }
        $recoveryPath = $requiredPatchFixture.RecoveryRoot
        if ($RecoveryLen -gt 0) {
            $recoveryPath = Join-Path $requiredPatchFixture.Root 'rec'
            $recoveryPath = Join-Path $recoveryPath ('r' * ($RecoveryLen - $recoveryPath.Length - 1))
            [void][IO.Directory]::CreateDirectory($recoveryPath)
        }
        try {
            $createTarget = if ($LongName) { 'BepInEx/plugins/' + ('z' * 45) + '.dll' } else { 'BepInEx/plugins/FGBTPPlugin.dll' }
            $replace = [pscustomobject]@{
                Type='ReplaceFile';Target='settings.ini';BeforeSha256=$requiredPatchFixture.BeforeSha256
                AfterSha256=$requiredPatchFixture.SettingsAfterSha256;Payload='settings.new'
                PayloadSha256=$requiredPatchFixture.SettingsAfterSha256
            }
            $create = [pscustomobject]@{
                Type='CreateFile';Target=$createTarget;BeforeState='Absent'
                AfterSha256=$requiredPatchFixture.CreatedSha256;Payload='plugin.dll'
                PayloadSha256=$requiredPatchFixture.CreatedSha256
            }
            $entry = [pscustomobject]@{
                Id='fixture.long-path';ProfileId='SyntheticFixture';Executable='synthetic.exe'
                ExecutableSha256=$requiredPatchFixture.ExecutableSha256;SourceUrl='https://example.invalid/fixture'
                SourceRevision=('E' * 40);ExclusiveGroup='';Operations=@($replace,$create)
            }
            $content = [pscustomobject]@{Schema=3;Entries=@($entry)} | ConvertTo-Json -Depth 10
            $inputs = @{
                CatalogContent=$content;CatalogSha256=(Get-TpmPatchTextSha256 $content)
                PatchId='fixture.long-path';ProfileId='SyntheticFixture';GameRoot=$gamePath
                PayloadRoot=$requiredPatchFixture.PayloadRoot;RecoveryRoot=$recoveryPath
                ProtectedRoots=@($requiredPatchFixture.ProtectedRoot)
            }
            $settings = Join-Path $gamePath 'settings.ini'
            $plugin = Join-Path $gamePath ($createTarget.Replace('/','\'))
            if ($Expect -ceq 'Refuse') {
                $plan = Get-TpmPatchPlan @inputs
                $plan.Status | Should -Be 'Unavailable'
                $plan.Reason | Should -Match $Pattern
                $caught = $null
                try { [void](Invoke-TpmCatalogPatch @inputs -Confirm:$false) } catch { $caught = $_.Exception.Message }
                $caught | Should -Match $Pattern
                [IO.File]::ReadAllText($settings) | Should -Be 'original setting'
                [IO.File]::Exists($plugin) | Should -BeFalse
                @(Get-ChildItem -LiteralPath $recoveryPath -Force).Count | Should -Be 0
                if ($UndoCheck) {
                    # Undo of an already-applied patch must never be blocked by the file-length rule (it only guards new writes).
                    $undoPlan = Get-TpmPatchPlan @inputs -ForUndo
                    [string]$undoPlan.Reason | Should -Not -Match 'too long for Windows'
                    $undoCaught = $null
                    try { [void](Undo-TpmCatalogPatch @inputs -RecoveryDirectory $recoveryPath -Confirm:$false) } catch { $undoCaught = $_.Exception.Message }
                    [string]$undoCaught | Should -Not -Match 'too long for Windows'
                }
                return
            }
            (Get-TpmPatchPlan @inputs).Status | Should -Be 'Ready'
            $first = Invoke-TpmCatalogPatch @inputs -Confirm:$false
            $first.Status | Should -Be 'Applied'
            [IO.File]::ReadAllText($settings) | Should -Be 'patched setting'
            [IO.File]::ReadAllText($plugin) | Should -Be 'synthetic required plugin'
            (Get-TpmPatchPlan @inputs).Status | Should -Be 'AlreadyApplied'
            (Undo-TpmCatalogPatch @inputs -RecoveryDirectory $first.RecoveryDirectory -Confirm:$false).Status | Should -Be 'Restored'
            [IO.File]::ReadAllText($settings) | Should -Be 'original setting'
            [IO.File]::Exists($plugin) | Should -BeFalse
            (Invoke-TpmCatalogPatch @inputs -Confirm:$false).Status | Should -Be 'Applied'
            [IO.File]::ReadAllText($plugin) | Should -Be 'synthetic required plugin'
        } finally {
            foreach ($cleanup in @($gamePath,$recoveryPath)) {
                if ($cleanup -ne $requiredPatchFixture.GameRoot -and $cleanup -ne $requiredPatchFixture.RecoveryRoot -and [IO.Directory]::Exists($cleanup)) { [IO.Directory]::Delete($cleanup, $true) }
            }
        }
