    It 'does not refuse a patch because the temporary payload folder is deep, while a 260 character target is still refused with the plain sentence' {
        # Mutation: drop -Staging from the payload Resolve-TpmPatchPath in Get-TpmPatchPlan -> a 250+ character temp payload root is refused for length. Mutation: remove the pre-check before GetFullPath in Resolve-TpmPatchPath -> a joined path over 259 that normalizes shorter is no longer refused with the plain sentence.
        $deepPayload = Join-Path $requiredPatchFixture.Root 'deep-payload'
        $deepPayload = Join-Path $deepPayload ('p' * (250 - $deepPayload.Length - 1))
        $deepPayload.Length | Should -Be 250
        try {
            [void][IO.Directory]::CreateDirectory('\\?\' + $deepPayload)
            foreach ($name in @('settings.new','plugin.dll')) { [IO.File]::Copy((Join-Path $requiredPatchFixture.PayloadRoot $name),('\\?\' + (Join-Path $deepPayload $name))) }
            $replace = [pscustomobject]@{
                Type='ReplaceFile';Target='settings.ini';BeforeSha256=$requiredPatchFixture.BeforeSha256
                AfterSha256=$requiredPatchFixture.SettingsAfterSha256;Payload='settings.new'
                PayloadSha256=$requiredPatchFixture.SettingsAfterSha256
            }
            $create = [pscustomobject]@{
                Type='CreateFile';Target='BepInEx/plugins/FGBTPPlugin.dll';BeforeState='Absent'
                AfterSha256=$requiredPatchFixture.CreatedSha256;Payload='plugin.dll'
                PayloadSha256=$requiredPatchFixture.CreatedSha256
            }
            $entry = [pscustomobject]@{
                Id='fixture.deep-payload';ProfileId='SyntheticFixture';Executable='synthetic.exe'
                ExecutableSha256=$requiredPatchFixture.ExecutableSha256;SourceUrl='https://example.invalid/fixture'
                SourceRevision=('E' * 40);ExclusiveGroup='';Operations=@($replace,$create)
            }
            $content = [pscustomobject]@{Schema=3;Entries=@($entry)} | ConvertTo-Json -Depth 10
            $inputs = @{
                CatalogContent=$content;CatalogSha256=(Get-TpmPatchTextSha256 $content)
                PatchId='fixture.deep-payload';ProfileId='SyntheticFixture';GameRoot=$requiredPatchFixture.GameRoot
                PayloadRoot=$deepPayload;RecoveryRoot=$requiredPatchFixture.RecoveryRoot
                ProtectedRoots=@($requiredPatchFixture.ProtectedRoot)
            }
            $plan = Get-TpmPatchPlan @inputs
            [string]$plan.Reason | Should -Not -Match 'too long'
            $plan.Status | Should -Be 'Ready'
        } finally {
            if ([IO.Directory]::Exists('\\?\' + $deepPayload)) { [IO.Directory]::Delete('\\?\' + (Join-Path $requiredPatchFixture.Root 'deep-payload'), $true) }
        }
        # A joined path over 259 that normalizes shorter must still get the plain sentence, even where GetFullPath would throw.
        $root = $requiredPatchFixture.GameRoot
        while (($root + '\x\..').Length -le 270) { $root += '\x\..' }
        { Resolve-TpmPatchPath $root 'settings.ini' } | Should -Throw '*A file path is too long for Windows to patch safely (*characters). Move TeknoParrot or the game to a folder with a shorter path.'
    }

