        try {
            [void][IO.Directory]::CreateDirectory('\\?\' + $deep)
            $existing = Join-Path $deep 'existing.bin'
            [IO.File]::WriteAllText('\\?\' + $existing, 'long path bytes')
            $stream = Open-TpmPatchCreationFile $existing
            try { $stream.Length | Should -Be 15 } finally { $stream.Dispose() }
            $created = Join-Path $deep 'created.bin'
            $stream = Open-TpmPatchCreationFile $created -NewFile
            try { $stream.WriteByte(65) } finally { $stream.Dispose() }
            [IO.File]::Exists('\\?\' + $created) | Should -BeTrue
