            $source = Join-Path $deep 'staged.tmp'
            $destination = Join-Path $deep 'published.bin'
            $stream = Open-TpmPatchCreationFile $source -NewFile
            try {
                $stream.WriteByte(66)
                Move-TpmPatchCreationHandle -Handle $stream.SafeFileHandle -Destination $destination
            } finally { $stream.Dispose() }
            [IO.File]::Exists('\\?\' + $destination) | Should -BeTrue
            [IO.File]::Exists('\\?\' + $source) | Should -BeFalse
            $occupied = Join-Path $deep 'occupied.bin'
            [IO.File]::WriteAllText('\\?\' + $occupied, 'keep me')
