        $nvidia.ExecutableSha256 = $requiredPatchFixture.ExecutableSha256
        $amd.SourceSet = 'synthetic-cross-elysion.zip'
        $nvidia.SourceSet = 'synthetic-cross-elysion.zip'
        $amd.SourceEntry = 'synthetic/shader.AMD'
        $nvidia.SourceEntry = 'synthetic/shader.NVIDIA'
        $amd.Operations[0].Payload = 'amd.new'
        $nvidia.Operations[0].Payload = 'nvidia.new'
        $amd.Operations[0].Target = 'rom/shader.farc'
        $nvidia.Operations[0].Target = 'rom/shader.farc'

        $amdPayload = Join-Path $requiredPatchFixture.PayloadRoot 'amd.new'
        $nvidiaPayload = Join-Path $requiredPatchFixture.PayloadRoot 'nvidia.new'
        [IO.File]::WriteAllText($amdPayload,'synthetic AMD shader variant')
        [IO.File]::WriteAllText($nvidiaPayload,'synthetic NVIDIA baseline')
        $amdHash = (Get-FileHash -LiteralPath $amdPayload -Algorithm SHA256).Hash
        $nvidiaHash = (Get-FileHash -LiteralPath $nvidiaPayload -Algorithm SHA256).Hash
        $amd.SourceSize = [int](Get-Item -LiteralPath $amdPayload).Length
        $nvidia.SourceSize = [int](Get-Item -LiteralPath $nvidiaPayload).Length
        $amd.SourceSha1 = (Get-FileHash -LiteralPath $amdPayload -Algorithm SHA1).Hash
        $nvidia.SourceSha1 = (Get-FileHash -LiteralPath $nvidiaPayload -Algorithm SHA1).Hash
        $amd.SourceSha256 = $amdHash
        $nvidia.SourceSha256 = $nvidiaHash
        $amd.Operations[0].BeforeSha256 = $nvidiaHash
        $amd.Operations[0].AfterSha256 = $amdHash
        $amd.Operations[0].PayloadSha256 = $amdHash
        $nvidia.Operations[0].BeforeSha256 = $amdHash
        $nvidia.Operations[0].AfterSha256 = $nvidiaHash
        $nvidia.Operations[0].PayloadSha256 = $nvidiaHash

        $rom = Join-Path $requiredPatchFixture.GameRoot 'rom'
        [void][IO.Directory]::CreateDirectory($rom)
        $target = Join-Path $rom 'shader.farc'
        # Non-permitted synthetic state; refuse rather than assume a clean baseline.
        [IO.File]::WriteAllText($target,'synthetic ORIGINAL state')
        $content = [pscustomobject]@{Schema=3;Entries=@($amd,$nvidia)} | ConvertTo-Json -Depth 20
        $amdEvidence = [pscustomobject]@{
            Adapters=@([pscustomobject]@{Name='AMD Radeon synthetic fixture'})
            ActiveAdapterIndex=0;ActiveAdapterName='AMD Radeon synthetic fixture'
            ActiveGpuConfidence='INFERRED';MultiGpuAmbiguous=$false
        }
        $nvidiaEvidence = [pscustomobject]@{
            Adapters=@([pscustomobject]@{Name='NVIDIA GeForce synthetic fixture'})
            ActiveAdapterIndex=0;ActiveAdapterName='NVIDIA GeForce synthetic fixture'
            ActiveGpuConfidence='INFERRED';MultiGpuAmbiguous=$false
        }
        $amdInputs = @{
            CatalogContent=$content;CatalogSha256=(Get-TpmPatchTextSha256 $content)
            PatchId=$amd.Id;ProfileId=$amd.ProfileId;GameRoot=$requiredPatchFixture.GameRoot
            PayloadRoot=$requiredPatchFixture.PayloadRoot;RecoveryRoot=$requiredPatchFixture.RecoveryRoot
            ProtectedRoots=@($requiredPatchFixture.ProtectedRoot);HardwareEvidence=$amdEvidence
        }
        $nvidiaInputs = $amdInputs.Clone()
        $nvidiaInputs.PatchId = $nvidia.Id
        $nvidiaInputs.HardwareEvidence = $nvidiaEvidence
        (Get-TpmPatchPlan @amdInputs).Status | Should -Be 'Unavailable'
        (Get-TpmPatchPlan @amdInputs).Reason | Should -Match 'Target conflict'

        [IO.File]::WriteAllText($target,'synthetic NVIDIA baseline')
        (Get-TpmPatchPlan @amdInputs).Status | Should -Be 'Ready'
        (Get-TpmPatchPlan @nvidiaInputs).Status | Should -Be 'AlreadyApplied'
        $first = Invoke-TpmCatalogPatch @amdInputs -Confirm:$false
        $first.Status | Should -Be 'Applied'
        (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash | Should -Be $amdHash
        $firstReceipt = [IO.File]::ReadAllText((Join-Path $first.RecoveryDirectory 'receipt.json')) | ConvertFrom-Json
        (Get-FileHash -LiteralPath ([string]$firstReceipt.Operations[0].Backup) -Algorithm SHA256).Hash | Should -Be $nvidiaHash
        (Get-TpmPatchPlan @amdInputs).Status | Should -Be 'AlreadyApplied'
        (Get-TpmPatchPlan @nvidiaInputs).Status | Should -Be 'Unavailable'
        (Get-TpmPatchPlan @nvidiaInputs).Reason | Should -Match 'exclusive recipe is active'
        (Undo-TpmCatalogPatch @amdInputs -RecoveryDirectory $first.RecoveryDirectory -Confirm:$false).Status | Should -Be 'Restored'
        (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash | Should -Be $nvidiaHash

        $second = Invoke-TpmCatalogPatch @amdInputs -Confirm:$false
        $second.Status | Should -Be 'Applied'
        (Get-TpmPatchPlan @amdInputs).Status | Should -Be 'AlreadyApplied'
        (Undo-TpmCatalogPatch @amdInputs -RecoveryDirectory $second.RecoveryDirectory -Confirm:$false).Status | Should -Be 'Restored'
        (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash | Should -Be $nvidiaHash

        [IO.File]::WriteAllText($target,'synthetic AMD shader variant')
        (Get-TpmPatchPlan @nvidiaInputs).Status | Should -Be 'Ready'
        $third = Invoke-TpmCatalogPatch @nvidiaInputs -Confirm:$false
        $third.Status | Should -Be 'Applied'
        (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash | Should -Be $nvidiaHash
        $thirdReceipt = [IO.File]::ReadAllText((Join-Path $third.RecoveryDirectory 'receipt.json')) | ConvertFrom-Json
        (Get-FileHash -LiteralPath ([string]$thirdReceipt.Operations[0].Backup) -Algorithm SHA256).Hash | Should -Be $amdHash
        (Undo-TpmCatalogPatch @nvidiaInputs -RecoveryDirectory $third.RecoveryDirectory -Confirm:$false).Status | Should -Be 'Restored'
        (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash | Should -Be $amdHash
    }
}

Describe 'LaunchBox verified backup write restore and discovery (#335-#338)' {
    BeforeAll {
        $script:LbRealSet = ${function:Set-TpmLaunchBoxFile}
        $script:LbRealStage = ${function:New-TpmLaunchBoxStage}
        function New-LbFixture {
            $fixtureHome = Join-Path $TestDrive ([guid]::NewGuid().ToString('N'))
            $lb = Join-Path $fixtureHome 'LaunchBox'
            $profiles = Join-Path $fixtureHome 'UserProfiles'
            [void][IO.Directory]::CreateDirectory((Join-Path $lb 'Data\Platforms'))
            [void][IO.Directory]::CreateDirectory($profiles)
            [IO.File]::WriteAllText((Join-Path $lb 'Data\Emulators.xml'), '<LaunchBox><Emulator><ID>original-emulator</ID><Title>Other</Title><Notes>keep</Notes></Emulator></LaunchBox>')
            [IO.File]::WriteAllText((Join-Path $lb 'Data\Platforms.xml'), '<LaunchBox><Platform><Name>Arcade</Name><Notes>keep</Notes></Platform></LaunchBox>')
            [IO.File]::WriteAllText((Join-Path $lb 'Data\Platforms\TeknoParrot.xml'), '<LaunchBox><Game><ID>original-game</ID><ApplicationPath>unrelated.xml</ApplicationPath><Favorite>true</Favorite><PlayCount>42</PlayCount></Game></LaunchBox>')
            $exe = Join-Path $fixtureHome 'game.exe'
            [IO.File]::WriteAllText($exe,'fake executable; never run')
            $profileDoc = [xml]'<GameProfile><GamePath /><Description>Fake Game</Description></GameProfile>'
            # Join-Path returns a PSObject-wrapped string on Windows PowerShell 5.1, which XmlNode property assignment rejects.
            $profileDoc.GameProfile.SelectSingleNode('GamePath').InnerText = [string]$exe
            $profileDoc.Save((Join-Path $profiles 'Fake.xml'))
            return @{ Home=$fixtureHome; Root=$lb; Profiles=$profiles; Backups=(Join-Path $fixtureHome 'LaunchBoxBackups'); Tp=(Join-Path $fixtureHome 'TeknoParrot') }
        }
        function Invoke-LbFixtureWrite {
            Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:Lb.Tp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot') -BackupRoot $script:Lb.Backups
        }
        function Get-LbLibraryBytes {
            param([string]$Root)
            return (@(Get-ChildItem -LiteralPath (Join-Path $Root 'Data') -File -Recurse -Filter '*.xml' | Sort-Object FullName | ForEach-Object {
                (Get-RelativePath $Root $_.FullName) + ':' + [Convert]::ToBase64String([IO.File]::ReadAllBytes($_.FullName))
            }) -join '|')
        }
        function New-LbStyledXml {
            param([string]$Body)
            return ('<?xml version="1.0" standalone="yes"?>' + "`r`n" + '<LaunchBox>' + "`r`n" + $Body + '</LaunchBox>' + "`r`n")
        }
    }
    BeforeEach {
        $script:LbSavedLayout = $script:TpmOwnedLayout
        $script:TpmOwnedLayout = $null
        $script:Lb = New-LbFixture
        $script:LbCopies = 0
        $script:LbCommits = 0
        $script:LbChecks = 0
        Mock Test-LaunchBoxRunning { $false }
        # The guided pre-check (Wait-TpmForProcessClose) would block on Read-HostSafe if the machine happens to have LaunchBox or BigBox open; the fixture gates below use Test-LaunchBoxRunning.
        Mock Wait-TpmForProcessClose { $true }
        Mock Write-Log {}
        Mock Read-TpmChoice { '1' }
        Mock Read-TpmYesNo { 'Y' }
        $script:LbProgress = New-Object System.Collections.Generic.List[object]
        Mock Write-TpmCompactExtractionProgress { [void]$script:LbProgress.Add([pscustomobject]@{ Label=$Label; Complete=[bool]$Complete; Outcome=$Outcome }) }
    }
    AfterEach { $script:TpmOwnedLayout = $script:LbSavedLayout }

    It 'saves all targets with a verified complete backup and preserves existing entries' {
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'SAVED'
        @($script:LbProgress | Where-Object { $_.Label -eq 'LaunchBox backup' -and $_.Complete } | ForEach-Object { $_.Outcome }) | Should -Be @('Final')
        $r.FinalVerified | Should -BeTrue
        $r.BackupVerified | Should -BeTrue
        $snapshot = Get-TpmLaunchBoxSnapshot $r.BackupPath
        $snapshot.Items.Count | Should -Be 3
        (Get-LbLibraryBytes $r.BackupPath) | Should -Be $before
        $games = Read-Xml (Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml')
        $games.SelectSingleNode('/LaunchBox/Game[ID="original-game"]/Favorite').InnerText | Should -Be 'true'
        $games.SelectSingleNode('/LaunchBox/Game[ID="original-game"]/PlayCount').InnerText | Should -Be '42'
        $games.SelectNodes('/LaunchBox/Game').Count | Should -Be 2
        $emu = Read-Xml (Join-Path $script:Lb.Root 'Data\Emulators.xml')
        $emu.SelectSingleNode('/LaunchBox/Emulator[ID="original-emulator"]/Notes').InnerText | Should -Be 'keep'
        $second = Invoke-LbFixtureWrite
        $second.Outcome | Should -Be 'NO_CHANGES'
        $second.AttemptedPaths.Count | Should -Be 0
        $r.ChangedPaths.Count | Should -Be 3
        $r.UnrecoveredPaths.Count | Should -Be 0
        @(Get-ChildItem -LiteralPath (Join-Path $script:Lb.Root 'Data') -Recurse -File | Where-Object { $_.Extension -ne '.xml' }).Count | Should -Be 0
    }

    It 'records an intentionally absent new platform and its exact created hash' {
        $target = Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml'
        Remove-Item -LiteralPath $target
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'SAVED'
        $member = (Get-TpmLaunchBoxSnapshot $r.BackupPath).Items | Where-Object RelativePath -eq 'Data\Platforms\TeknoParrot.xml'
        $member.Exists | Should -BeFalse
        $member.CreatedHash | Should -Be (Get-FileHash -LiteralPath $target).Hash
        Test-Path -LiteralPath (Join-Path $r.BackupPath $member.RelativePath) | Should -BeFalse
    }

    It 'refuses a missing mandatory original without library writes' {
        Remove-Item -LiteralPath (Join-Path $script:Lb.Root 'Data\Emulators.xml')
        $before = Get-LbLibraryBytes $script:Lb.Root
        (Invoke-LbFixtureWrite).Outcome | Should -Be 'FAILED'
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
        Test-Path -LiteralPath $script:Lb.Backups | Should -BeFalse
    }

    It 'fails closed on backup copy <Position> in <Mode> mode' -TestCases @(
        @{Position=1; Mode='Terminating'}, @{Position=2; Mode='Terminating'}, @{Position=3; Mode='Terminating'},
        @{Position=1; Mode='Corrupt'}, @{Position=2; Mode='Corrupt'}, @{Position=3; Mode='Corrupt'}
    ) {
        param($Position,$Mode)
        $script:LbFailCopy = $Position
        $script:LbCopyMode = $Mode
        Mock Copy-Item {
            param($LiteralPath,$Destination)
            $script:LbCopies++
            if ($script:LbCopies -eq $script:LbFailCopy) {
                switch ($script:LbCopyMode) {
                    'Terminating' { throw 'injected copy failure' }
                    'Corrupt' { [IO.File]::WriteAllText($Destination,'wrong bytes'); return }
                }
            }
            [IO.File]::Copy($LiteralPath,$Destination)
        }
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        $r.AttemptedPaths.Count | Should -Be 0
        $r.BackupVerified | Should -BeFalse
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
        @(Get-ChildItem -LiteralPath $script:Lb.Backups -Directory | Where-Object Name -ne '.tpm-incomplete').Count | Should -Be 0
    }

    It 'requests a terminating error from every backup copy so a nonterminating copy failure cannot be skipped' {
        Mock Copy-Item {
            param($LiteralPath,$Destination)
            [IO.File]::Copy($LiteralPath,$Destination)
        }
        (Invoke-LbFixtureWrite).Outcome | Should -Be 'SAVED'
        Should -Invoke Copy-Item -Times 3 -Exactly -ParameterFilter { $ErrorAction -eq 'Stop' }
    }

    It 'refuses manifest serialization failure before any commit' {
        Mock ConvertTo-Json { throw 'injected manifest failure' }
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        @($script:LbProgress | Where-Object { $_.Label -eq 'LaunchBox backup' -and $_.Complete } | ForEach-Object { $_.Outcome }) | Should -Be @('Error')
        $r.AttemptedPaths.Count | Should -Be 0
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
    }

    It 'refuses an original that disappears during the backup' {
        Mock Copy-Item {
            param($LiteralPath,$Destination)
            [IO.File]::Copy($LiteralPath,$Destination)
            if ([IO.Path]::GetFileName($LiteralPath) -eq 'Emulators.xml') { [IO.File]::Delete($LiteralPath) }
        }
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        @($script:LbProgress | Where-Object { $_.Label -eq 'LaunchBox backup' -and $_.Complete } | ForEach-Object { $_.Outcome }) | Should -Be @('Error')
        $r.AttemptedPaths.Count | Should -Be 0
        $r.BackupVerified | Should -BeFalse
    }

    It 'refuses running apps at <Gate> without committing' -TestCases @(@{Gate=1},@{Gate=2},@{Gate=3}) {
        param($Gate)
        $script:LbRunningGate = $Gate
        Mock Test-LaunchBoxRunning { $script:LbChecks++; return $script:LbChecks -eq $script:LbRunningGate }
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        $r.AttemptedPaths.Count | Should -Be 0
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
    }

    It 'rehashes all originals immediately before commit and preserves an intervening edit' {
        Mock Test-LaunchBoxRunning {
            $script:LbChecks++
            if ($script:LbChecks -eq 3) { [IO.File]::WriteAllText((Join-Path $script:Lb.Root 'Data\Platforms.xml'),'<LaunchBox><Notes>concurrent</Notes></LaunchBox>') }
            return $false
        }
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        $r.BackupVerified | Should -BeTrue
        $r.AttemptedPaths.Count | Should -Be 0
        [IO.File]::ReadAllText((Join-Path $script:Lb.Root 'Data\Platforms.xml')) | Should -Match 'concurrent'
    }

    It 'rolls back a failure <When> commit <Position> with exact original bytes' -TestCases @(
        @{Position=1;When='Before'},@{Position=2;When='Before'},@{Position=3;When='Before'},
        @{Position=1;When='After'},@{Position=2;When='After'},@{Position=3;When='After'}
    ) {
        param($Position,$When)
        $script:LbFailCommit = $Position
        $script:LbFailWhen = $When
        Mock Set-TpmLaunchBoxFile {
            param($StagePath,$Path,$Exists)
            $script:LbCommits++
            if ($script:LbCommits -eq $script:LbFailCommit -and $script:LbFailWhen -eq 'Before') { throw 'injected before replace' }
            & $script:LbRealSet -StagePath $StagePath -Path $Path -Exists $Exists
            if ($script:LbCommits -eq $script:LbFailCommit -and $script:LbFailWhen -eq 'After') { throw 'injected after replace' }
        }
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        $r.RollbackVerified | Should -BeTrue
        $r.Succeeded | Should -BeFalse
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
        (Get-TpmLaunchBoxSnapshot $r.BackupPath).Items.Count | Should -Be 3
    }

    It 'reports PARTIAL rather than no changes when compensation fails' {
        Mock Set-TpmLaunchBoxFile {
            param($StagePath,$Path,$Exists)
            $script:LbCommits++
            if ($script:LbCommits -gt 1) { throw 'commit and rollback denied' }
            & $script:LbRealSet -StagePath $StagePath -Path $Path -Exists $Exists
        }
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'PARTIAL'
        $r.Succeeded | Should -BeFalse
        $r.RollbackVerified | Should -BeFalse
        $r.UnrecoveredPaths | Should -Contain 'Data\Emulators.xml'
        $r.ChangedPaths.Count | Should -Be 0
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Not -Be $before
        Test-Path -LiteralPath (Join-Path $r.BackupPath 'manifest.json') | Should -BeTrue
        Write-TpmLaunchBoxResult $r -Unattended
        Should -Invoke Write-Log -Times 1 -ParameterFilter { $msg -like '*outcome=PARTIAL*' }
    }

    It 'does not overwrite a concurrent edit while compensating' {
        Mock Set-TpmLaunchBoxFile {
            param($StagePath,$Path,$Exists)
            $script:LbCommits++
            if ($script:LbCommits -eq 2) {
                [IO.File]::WriteAllText((Join-Path $script:Lb.Root 'Data\Emulators.xml'),'<LaunchBox><Notes>user edit</Notes></LaunchBox>')
                throw 'second save failed'
            }
            & $script:LbRealSet -StagePath $StagePath -Path $Path -Exists $Exists
        }
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'PARTIAL'
        [IO.File]::ReadAllText((Join-Path $script:Lb.Root 'Data\Emulators.xml')) | Should -Match 'user edit'
    }

    It 'restores every manifest target and verifies exact bytes' {
        $before = Get-LbLibraryBytes $script:Lb.Root
        $saved = Invoke-LbFixtureWrite
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $r.Outcome | Should -Be 'SAVED'
        $r.FinalVerified | Should -BeTrue
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
        (Get-TpmLaunchBoxSnapshot $saved.BackupPath).Legacy | Should -BeFalse
    }

    It 'rolls back a restore failure at position <Position> and does not claim success' -TestCases @(@{Position=1},@{Position=2},@{Position=3}) {
        param($Position)
        $saved = Invoke-LbFixtureWrite
        $beforeRestore = Get-LbLibraryBytes $script:Lb.Root
        $script:LbFailCommit = $Position
        Mock Set-TpmLaunchBoxFile {
            param($StagePath,$Path,$Exists)
            $script:LbCommits++
            & $script:LbRealSet -StagePath $StagePath -Path $Path -Exists $Exists
            if ($script:LbCommits -eq $script:LbFailCommit) { throw 'restore copy failed after replace' }
        }
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $r.Outcome | Should -Be 'FAILED'
        $r.RollbackVerified | Should -BeTrue
        $r.Succeeded | Should -BeFalse
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $beforeRestore
    }

    It 'refuses an empty or corrupted snapshot before any destination write' -TestCases @(@{Kind='Empty'},@{Kind='HashMismatch'},@{Kind='MissingMember'},@{Kind='UnexpectedMember'}) {
        param($Kind)
        $saved = Invoke-LbFixtureWrite
        switch ($Kind) {
            'Empty' { Remove-Item -LiteralPath $saved.BackupPath -Recurse; [void][IO.Directory]::CreateDirectory($saved.BackupPath) }
            'HashMismatch' { [IO.File]::WriteAllText((Join-Path $saved.BackupPath 'Data\Emulators.xml'),'<LaunchBox />') }
            'MissingMember' { Remove-Item -LiteralPath (Join-Path $saved.BackupPath 'Data\Platforms.xml') }
            'UnexpectedMember' { [IO.File]::WriteAllText((Join-Path $saved.BackupPath 'unexpected.txt'),'unexpected') }
        }
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $r.Outcome | Should -Be 'FAILED'
        $r.AttemptedPaths.Count | Should -Be 0
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
    }

    It 'refuses denied discovery rather than accepting a partial inventory' {
        $saved = Invoke-LbFixtureWrite
        $script:LbSnapshotToDeny = Join-Path $saved.BackupPath 'Data'
        # Pester 6 fails a call that matches no filter unless a default mock exists; this one passes every other call to the real command.
        $script:LbRealGetChildItem = Get-Command -Name Get-ChildItem -CommandType Cmdlet
        Mock Get-ChildItem { & $script:LbRealGetChildItem @PesterBoundParameters }
        Mock Get-ChildItem { throw 'discovery denied' } -ParameterFilter { $LiteralPath -eq $script:LbSnapshotToDeny }
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $r.Outcome | Should -Be 'FAILED'
        $r.AttemptedPaths.Count | Should -Be 0
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
    }

    It 'restores a prior-absent created file by removal only when it is unchanged and confirmed; otherwise keeps it and reports PARTIAL' -TestCases @(@{Kind='Confirmed'},@{Kind='Declined'},@{Kind='Changed'}) {
        param($Kind)
        $target = Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml'
        $emulators = Join-Path $script:Lb.Root 'Data\Emulators.xml'
        $platforms = Join-Path $script:Lb.Root 'Data\Platforms.xml'
        $originalEmulators = [IO.File]::ReadAllBytes($emulators)
        $originalPlatforms = [IO.File]::ReadAllBytes($platforms)
        Remove-Item -LiteralPath $target
        $saved = Invoke-LbFixtureWrite
        $saved.Outcome | Should -Be 'SAVED'
        [Convert]::ToBase64String([IO.File]::ReadAllBytes($emulators)) | Should -Not -Be ([Convert]::ToBase64String($originalEmulators))
        if ($Kind -eq 'Changed') { [IO.File]::WriteAllText($target,'<LaunchBox><Notes>newer user content</Notes></LaunchBox>') }
        if ($Kind -eq 'Declined') { Mock Read-TpmYesNo { 'N' } -ParameterFilter { $Prompt -like 'Remove*' } }
        $keptBytes = if ($Kind -eq 'Confirmed') { $null } else { [IO.File]::ReadAllBytes($target) }
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        # The other members are restored byte for byte in every case, with a verified safety snapshot of their prior state.
        [Convert]::ToBase64String([IO.File]::ReadAllBytes($emulators)) | Should -Be ([Convert]::ToBase64String($originalEmulators))
        [Convert]::ToBase64String([IO.File]::ReadAllBytes($platforms)) | Should -Be ([Convert]::ToBase64String($originalPlatforms))
        $r.BackupVerified | Should -BeTrue
        @($r.ChangedPaths) | Should -Contain 'Data\Emulators.xml'
        @($r.ChangedPaths) | Should -Contain 'Data\Platforms.xml'
        if ($Kind -eq 'Confirmed') {
            $r.Outcome | Should -Be 'SAVED'
            $r.Succeeded | Should -BeTrue
            @($r.UnrecoveredPaths).Count | Should -Be 0
            @($r.KeptFiles).Count | Should -Be 0
            Test-Path -LiteralPath $target | Should -BeFalse
        } else {
            $r.Outcome | Should -Be 'PARTIAL'
            $r.Succeeded | Should -BeFalse
            $r.Summary | Should -Match 'PARTIAL'
            @($r.UnrecoveredPaths) | Should -Be @('Data\Platforms\TeknoParrot.xml')
            @($r.ChangedPaths) | Should -Not -Contain 'Data\Platforms\TeknoParrot.xml'
            @($r.KeptFiles).Count | Should -Be 1
            $r.KeptFiles[0].Path | Should -Be 'Data\Platforms\TeknoParrot.xml'
            $r.KeptFiles[0].Reason | Should -Match $(if ($Kind -eq 'Declined') { 'declined' } else { 'changed' })
            [Convert]::ToBase64String([IO.File]::ReadAllBytes($target)) | Should -Be ([Convert]::ToBase64String($keptBytes))
        }
        if ($Kind -eq 'Changed') { Should -Invoke Read-TpmYesNo -Times 0 -Exactly -ParameterFilter { $Prompt -like 'Remove*' } }
    }

    It 'reports PARTIAL with a Needs review line for a kept created file and never calls it a success' {
        $target = Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml'
        Remove-Item -LiteralPath $target
        [void](Invoke-LbFixtureWrite)
        [IO.File]::WriteAllText($target,'<LaunchBox><Notes>newer user content</Notes></LaunchBox>')
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $script:LbPrinted = New-Object System.Collections.Generic.List[string]
        Mock Write-Host { $script:LbPrinted.Add([string]$Object) }
        Write-TpmLaunchBoxResult -Result $r -Unattended
        $r.Outcome | Should -Be 'PARTIAL'
        @($script:LbPrinted | Where-Object { $_ -like '*1 LaunchBox file needs a check*' }).Count | Should -Be 1
        @($script:LbPrinted | Where-Object { $_ -like '*Data\Platforms\TeknoParrot.xml*' }).Count | Should -Be 0
        @($script:LbPrinted | Where-Object { $_ -like '*not verified back to its pre-write state*' }).Count | Should -Be 0
    }

    It 'reports PARTIAL without a library write when only the kept created file differs from the snapshot' {
        $target = Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml'
        Remove-Item -LiteralPath $target
        $saved = Invoke-LbFixtureWrite
        foreach ($member in @('Data\Emulators.xml','Data\Platforms.xml')) {
            Copy-Item -LiteralPath (Join-Path $saved.BackupPath $member) -Destination (Join-Path $script:Lb.Root $member) -Force
        }
        [IO.File]::WriteAllText($target,'<LaunchBox><Notes>newer user content</Notes></LaunchBox>')
        $before = Get-LbLibraryBytes $script:Lb.Root
        $backupCount = @(Get-ChildItem -LiteralPath $script:Lb.Backups -Directory -Exclude '.tpm-incomplete').Count
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $r.Outcome | Should -Be 'PARTIAL'
        $r.Succeeded | Should -BeFalse
        $r.NoOp | Should -BeFalse
        @($r.ChangedPaths).Count | Should -Be 0
        @($r.UnrecoveredPaths) | Should -Be @('Data\Platforms\TeknoParrot.xml')
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
        @(Get-ChildItem -LiteralPath $script:Lb.Backups -Directory -Exclude '.tpm-incomplete').Count | Should -Be $backupCount
    }

    It 'discovers and restores migrated manifest-less backups without inferring deletions' {
        $program = Join-Path $script:Lb.Home 'Program'
