        [void][IO.Directory]::CreateDirectory($layout.Backups)
        # Model the completed migration's retained bytes, not a live migration.
        [IO.Directory]::Move((Join-Path $program 'LaunchBoxBackups'),(Join-Path $layout.Backups 'LaunchBoxBackups'))
        $script:TpmOwnedLayout = $layout
        $otherFile = Join-Path $script:Lb.Root 'Data\Platforms.xml'
