    It 'adds entries without changing any other byte (BOM, CRLF, indentation, whitespace-only values, character references)' {
        $emulators = Join-Path $script:Lb.Root 'Data\Emulators.xml'
        $platforms = Join-Path $script:Lb.Root 'Data\Platforms.xml'
        $games = Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml'
        $utf8Bom = New-Object System.Text.UTF8Encoding $true
        $crlf = "`r`n"
        [IO.File]::WriteAllText($emulators,(New-LbStyledXml ('  <Emulator>' + $crlf + '    <ID>original-emulator</ID>' + $crlf + '    <Title>Other</Title>' + $crlf + '    <Notes> </Notes>' + $crlf + '    <Desc>line1&#xD;' + $crlf + 'line2</Desc>' + $crlf + '  </Emulator>' + $crlf)),$utf8Bom)
        [IO.File]::WriteAllText($platforms,(New-LbStyledXml ('  <Platform>' + $crlf + '    <Name>Arcade</Name>' + $crlf + '    <Notes>   </Notes>' + $crlf + '  </Platform>' + $crlf)),$utf8Bom)
        [IO.File]::WriteAllText($games,(New-LbStyledXml ('  <Game>' + $crlf + '    <ID>original-game</ID>' + $crlf + '    <ApplicationPath>unrelated.xml</ApplicationPath>' + $crlf + '    <Notes> </Notes>' + $crlf + '  </Game>' + $crlf)),$utf8Bom)
        $originals = @{}
        foreach ($path in @($emulators,$platforms,$games)) { $originals[$path] = [IO.File]::ReadAllBytes($path) }
        $beforeAll = Get-LbLibraryBytes $script:Lb.Root
        $tail = $utf8Bom.GetByteCount('</LaunchBox>' + $crlf)
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'SAVED'
        foreach ($path in @($emulators,$platforms,$games)) {
            $old = $originals[$path]
            $new = [IO.File]::ReadAllBytes($path)
            $new.Length | Should -BeGreaterThan $old.Length
            $split = $old.Length - $tail
            # Everything before the root end tag (BOM, declaration, CRLF, indentation, whitespace-only values, character references) is untouched.
            [Convert]::ToBase64String($new,0,$split) | Should -Be ([Convert]::ToBase64String($old,0,$split))
            # The root end tag and the file's trailing line ending are untouched.
            [Convert]::ToBase64String($new,$new.Length - $tail,$tail) | Should -Be ([Convert]::ToBase64String($old,$split,$tail))
            (@($new[0],$new[1],$new[2]) -join ',') | Should -Be '239,187,191'
        }
        $emulatorText = [IO.File]::ReadAllText($emulators)
        $emulatorText.Contains('<Notes> </Notes>') | Should -BeTrue
        $emulatorText.Contains('line1&#xD;' + $crlf + 'line2') | Should -BeTrue
        $restored = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $restored.Outcome | Should -Be 'SAVED'
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $beforeAll
    }

