    It 'records the canonical library root and operation kind and shows them with the files before the restore prompt' {
        $saved = Invoke-LbFixtureWrite
        $snapshot = Get-TpmLaunchBoxSnapshot $saved.BackupPath
        $snapshot.Root | Should -Be ([IO.Path]::GetFullPath($script:Lb.Root))
        $snapshot.Operation | Should -Be 'write'
        $script:LbHostText = New-Object System.Collections.ArrayList
        Mock Write-Host { [void]$script:LbHostText.Add([string]$Object) }
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root -BackupRoot $script:Lb.Backups
        $r.Outcome | Should -Be 'SAVED'
        (Get-TpmLaunchBoxSnapshot $r.BackupPath).Operation | Should -Be 'restore-safety'
        $shown = $script:LbHostText -join "`n"
        $shown | Should -Match ([regex]::Escape($snapshot.Root))
        $shown | Should -Match 'taken before a write'
        $shown | Should -Match ([regex]::Escape('Data\Emulators.xml'))
        Should -Invoke Read-TpmYesNo -ParameterFilter { $Prompt -like ('*' + $script:Lb.Root + '*') }
        Should -Invoke Read-TpmYesNo -Times 0 -Exactly -ParameterFilter { $Prompt -like 'This snapshot belongs*' }
    }

    It 'requires explicit confirmation before restoring a snapshot into a different library (answer <Answer>)' -TestCases @(@{Answer='N'},@{Answer='Y'}) {
        param($Answer)
        $saved = Invoke-LbFixtureWrite
        $other = New-LbFixture
        [IO.File]::WriteAllText((Join-Path $other.Root 'Data\Emulators.xml'),'<LaunchBox><Notes>other library</Notes></LaunchBox>')
        $script:LbMismatchAnswer = $Answer
        Mock Read-TpmYesNo { $script:LbMismatchAnswer } -ParameterFilter { $Prompt -like 'This snapshot belongs to a different*' }
        $before = Get-LbLibraryBytes $other.Root
        $r = Invoke-RestoreLaunchBoxBackup -lbRoot $other.Root -BackupRoot $script:Lb.Backups
        Should -Invoke Read-TpmYesNo -Times 1 -Exactly -ParameterFilter { $Prompt -like 'This snapshot belongs to a different*' }
        if ($Answer -eq 'N') {
            $r.Outcome | Should -Be 'NO_CHANGES'
            $r.Cancelled | Should -BeTrue
            (Get-LbLibraryBytes $other.Root) | Should -Be $before
        } else {
            $r.Outcome | Should -Be 'SAVED'
            (Get-TpmLaunchBoxSnapshot $r.BackupPath).Root | Should -Be ([IO.Path]::GetFullPath($other.Root))
        }
    }

    It 'canonicalizes a relative LaunchBox root once so validation and writes use the same folder' {
        Push-Location -LiteralPath $script:Lb.Home
        try { $r = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:Lb.Tp -lbRoot 'LaunchBox' -platformNames @('TeknoParrot') -BackupRoot $script:Lb.Backups }
        finally { Pop-Location }
        $r.Outcome | Should -Be 'SAVED'
        (Get-TpmLaunchBoxSnapshot $r.BackupPath).Root | Should -Be ([IO.Path]::GetFullPath($script:Lb.Root))
    }

    It 'checks both apps before staging anything next to the library' {
        Mock Test-LaunchBoxRunning { $true }
        Mock New-TpmLaunchBoxStage {}
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        Should -Invoke New-TpmLaunchBoxStage -Times 0 -Exactly
        Should -Invoke Test-LaunchBoxRunning -Times 1 -Exactly
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
    }

    It 'adds a game next to an existing entry whose path is not a valid file path' {
        $games = Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml'
        [IO.File]::WriteAllText($games,'<LaunchBox><Game><ID>steam-game</ID><ApplicationPath>steam://rungameid/1</ApplicationPath></Game></LaunchBox>')
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'SAVED'
        (Read-Xml $games).SelectNodes('/LaunchBox/Game').Count | Should -Be 2
    }

    It 'refuses a TeknoParrot emulator whose path is not a valid file path without touching the library' {
        $emulators = Join-Path $script:Lb.Root 'Data\Emulators.xml'
        [IO.File]::WriteAllText($emulators,('<LaunchBox><Emulator><ID>' + [guid]::NewGuid().ToString() + '</ID><Title>TeknoParrot</Title><ApplicationPath>"C:\bad|path"</ApplicationPath></Emulator></LaunchBox>'))
        $before = Get-LbLibraryBytes $script:Lb.Root
        $r = Invoke-LbFixtureWrite
        $r.Outcome | Should -Be 'FAILED'
        $r.Errors[0] | Should -Match 'points elsewhere'
        (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
    }

    It 'refuses a junction ancestor in the library path without any write' {
        $platformsDir = Join-Path $script:Lb.Root 'Data\Platforms'
        $elsewhere = Join-Path $script:Lb.Home 'ElsewherePlatforms'
        [IO.Directory]::Move($platformsDir,$elsewhere)
        [void](New-Item -ItemType Junction -Path $platformsDir -Target $elsewhere)
        try {
            $beforeGames = [Convert]::ToBase64String([IO.File]::ReadAllBytes((Join-Path $elsewhere 'TeknoParrot.xml')))
            $r = Invoke-LbFixtureWrite
            $r.Outcome | Should -Be 'FAILED'
            $r.AttemptedPaths.Count | Should -Be 0
            [Convert]::ToBase64String([IO.File]::ReadAllBytes((Join-Path $elsewhere 'TeknoParrot.xml'))) | Should -Be $beforeGames
            @(Get-ChildItem -LiteralPath $elsewhere -File | Where-Object { $_.Extension -ne '.xml' }).Count | Should -Be 0
        } finally { [IO.Directory]::Delete($platformsDir,$false) }
    }

    It 'keeps using the owned backup folder when it is outside the library' {
        $managed = Join-Path $script:Lb.Home 'Managed\Backups'
        $script:TpmOwnedLayout = @{ Backups=$managed }
        Mock Get-TpmLaunchBoxLocalBackupsRoot { throw 'The per-user fallback must not be used when the owned folder is outside the library.' }
        $location = Resolve-TpmLaunchBoxBackupLocation -LaunchBoxRoot $script:Lb.Root
        $location.UsesFallback | Should -BeFalse
        $location.Path | Should -Be (Join-Path $managed 'LaunchBoxBackups')
        $preview = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:Lb.Tp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot') -PlanOnly
        $preview.Reason | Should -Be 'PREVIEW'
        $preview.PSObject.Properties['BackupLocationNote'] | Should -BeNullOrEmpty
        $r = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:Lb.Tp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot')
        $r.Outcome | Should -Be 'SAVED' -Because ($r.Errors -join '; ')
        (Split-Path -Parent $r.BackupPath) | Should -Be (Join-Path $managed 'LaunchBoxBackups')
        Should -Invoke Get-TpmLaunchBoxLocalBackupsRoot -Times 0 -Exactly
    }

    Context 'TeknoParrot installed under the library (LaunchBox\Emulators\TeknoParrot)' {
        BeforeAll {
            # The documented per-library key: first 16 hex characters of the SHA-256 of the lower-cased full library root.
            function Get-LbExpectedBackupKey {
                param([string]$Root)
                $sha = [Security.Cryptography.SHA256]::Create()
                try { $digest = $sha.ComputeHash([Text.Encoding]::UTF8.GetBytes([IO.Path]::GetFullPath($Root).TrimEnd('\').ToLowerInvariant())) } finally { $sha.Dispose() }
                return [BitConverter]::ToString($digest).Replace('-','').Substring(0,16).ToLowerInvariant()
            }
        }
        BeforeEach {
            $script:LbNestedTp = Join-Path $script:Lb.Root 'Emulators\TeknoParrot'
            [void][IO.Directory]::CreateDirectory($script:LbNestedTp)
            $script:LbNestedOwned = Join-Path $script:LbNestedTp 'TeknoParrotManager\Backups'
            $script:TpmOwnedLayout = @{ Backups=$script:LbNestedOwned }
            # Never the real per-user folder: the fixture's local data root is outside the fixture library. The name is
            # deliberately short; the nested backup staging path must stay under MAX_PATH when TestDrive itself is long.
            $script:LbLocalBackups = Join-Path $script:Lb.Home 'LB'
            Mock Get-TpmLaunchBoxLocalBackupsRoot { $script:LbLocalBackups }
            $script:LbFallback = Join-Path $script:LbLocalBackups (Get-LbExpectedBackupKey $script:Lb.Root)
        }

        It 'resolves the default backup folder outside the library while the owned folder is inside it' {
            $location = Resolve-TpmLaunchBoxBackupLocation -LaunchBoxRoot $script:Lb.Root
            (Test-PathInside -child $location.OwnedPath -parent $script:Lb.Root) | Should -BeTrue
            $location.OwnedPath | Should -Be ([IO.Path]::GetFullPath((Join-Path $script:LbNestedOwned 'LaunchBoxBackups')))
            $location.UsesFallback | Should -BeTrue
            $location.Path | Should -Be $script:LbFallback
            (Test-PathInside -child $location.Path -parent $script:Lb.Root) | Should -BeFalse
            (Get-TpmLaunchBoxBackupRoot -LaunchBoxRoot $script:Lb.Root) | Should -Be $script:LbFallback
        }

        It 'keys the per-user folder by library so two libraries never share one' {
            $other = New-LbFixture
            $first = Get-TpmLaunchBoxFallbackBackupRoot -LaunchBoxRoot $script:Lb.Root
            $second = Get-TpmLaunchBoxFallbackBackupRoot -LaunchBoxRoot $other.Root
            $first | Should -Not -Be $second
            (Split-Path -Parent $first) | Should -Be $script:LbLocalBackups
            (Split-Path -Parent $second) | Should -Be $script:LbLocalBackups
            (Split-Path -Leaf $first) | Should -MatchExactly '^[0-9a-f]{16}$'
            (Split-Path -Leaf $second) | Should -Be (Get-LbExpectedBackupKey $other.Root)
            # Spelling the same library differently selects the same folder.
            (Get-TpmLaunchBoxFallbackBackupRoot -LaunchBoxRoot ($script:Lb.Root.ToUpperInvariant() + '\')) | Should -Be $first
        }

        It 'creates a verified backup outside the library with the default backup folder' {
            $source = Join-Path $script:Lb.Root 'Data\Emulators.xml'
            $items = @([pscustomobject]@{ RelativePath='Data\Emulators.xml'; Before=(Get-TpmLaunchBoxFileState $source); AfterHash=$null })
            $backup = Backup-LaunchBoxFiles -lbRoot $script:Lb.Root -Items $items
            $backup.Verified | Should -BeTrue
            (Test-PathInside -child $backup.Path -parent $script:Lb.Root) | Should -BeFalse
            (Split-Path -Parent $backup.Path) | Should -Be $script:LbFallback
            [IO.File]::ReadAllText((Join-Path $backup.Path 'Data\Emulators.xml')) | Should -Be ([IO.File]::ReadAllText($source))
            (Get-TpmLaunchBoxSnapshot $backup.Path).Items.Count | Should -Be 1
            Test-Path -LiteralPath (Join-Path $script:LbNestedOwned 'LaunchBoxBackups') | Should -BeFalse
        }

        It 'writes end to end and restores from the per-library folder' {
            $before = Get-LbLibraryBytes $script:Lb.Root
            $r = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:LbNestedTp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot')
            $r.Outcome | Should -Be 'SAVED' -Because ($r.Errors -join '; ')
            $r.BackupVerified | Should -BeTrue
            $r.FinalVerified | Should -BeTrue
            (Test-PathInside -child $r.BackupPath -parent $script:Lb.Root) | Should -BeFalse
            (Split-Path -Parent $r.BackupPath) | Should -Be $script:LbFallback
            (Get-LbLibraryBytes $r.BackupPath) | Should -Be $before
            (Read-Xml (Join-Path $script:Lb.Root 'Data\Platforms\TeknoParrot.xml')).SelectNodes('/LaunchBox/Game').Count | Should -Be 2
            Test-Path -LiteralPath (Join-Path $script:LbNestedOwned 'LaunchBoxBackups') | Should -BeFalse
            $restored = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root
            $restored.Outcome | Should -Be 'SAVED' -Because ($restored.Errors -join '; ')
            (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
            (Split-Path -Parent $restored.BackupPath) | Should -Be $script:LbFallback
            (Get-TpmLaunchBoxSnapshot $restored.BackupPath).Operation | Should -Be 'restore-safety'
        }

        It 'shows only the name of the backup folder in the preview, and the full folder under Details, without writing anything' {
            $script:LbShown = New-Object System.Collections.Generic.List[string]
            Mock Write-Host { [void]$script:LbShown.Add([string]$Object) }
            Mock Test-TpmInteractiveInput { -not [bool]$Unattended }
            Mock Read-HostSafe { 'D' }
            $before = Get-LbLibraryBytes $script:Lb.Root
            $preview = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:LbNestedTp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot') -PlanOnly
            $preview.Reason | Should -Be 'PREVIEW'
            [int]$preview.WouldChangeFiles | Should -BeGreaterThan 0
            $preview.BackupLocationNote.Contains($script:LbFallback) | Should -BeTrue
            $preview.BackupLocationPath | Should -Be $script:LbFallback
            Write-TpmLaunchBoxResult -Result $preview -Unattended
            @($script:LbShown | Where-Object { $_.Contains($script:LbFallback) }).Count | Should -Be 0
            @($script:LbShown | Where-Object { $_.Contains((Split-Path -Leaf $script:LbFallback)) }).Count | Should -Be 1
            $script:LbShown.Clear()
            Write-TpmLaunchBoxResult -Result $preview
            (($script:LbShown -join '') -replace '\s', '').Contains(($script:LbFallback -replace '\s', '')) | Should -BeTrue
            (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
            Test-Path -LiteralPath $script:LbLocalBackups | Should -BeFalse
        }

        It 'still lists and restores a snapshot kept in the owned folder, with the safety snapshot outside the library' {
            $saved = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:LbNestedTp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot')
            $saved.Outcome | Should -Be 'SAVED' -Because ($saved.Errors -join '; ')
            $ownedSnapshot = Join-Path $script:LbNestedOwned 'LaunchBoxBackups\2000-01-01_00-00-00'
            [void][IO.Directory]::CreateDirectory((Join-Path $ownedSnapshot 'Data'))
            [IO.File]::WriteAllText((Join-Path $ownedSnapshot 'Data\Emulators.xml'),'<LaunchBox><Notes>historical snapshot</Notes></LaunchBox>')
            $script:LbShown = New-Object System.Collections.Generic.List[string]
            Mock Write-Host { [void]$script:LbShown.Add([string]$Object) }
            # Newest first: 1 is the write snapshot in the per-user folder, 2 is the older owned snapshot.
            Mock Read-TpmChoice { '2' }
            $r = Invoke-RestoreLaunchBoxBackup -lbRoot $script:Lb.Root
            Should -Invoke Read-TpmChoice -Times 1 -Exactly -ParameterFilter { @($Choices) -contains '2' -and @($Choices) -notcontains '3' }
            $shown = $script:LbShown -join "`n"
            $shown | Should -Match ([regex]::Escape((Split-Path -Leaf $saved.BackupPath)))
            $shown | Should -Match '2000-01-01_00-00-00'
            $r.Outcome | Should -Be 'SAVED' -Because ($r.Errors -join '; ')
            $r.LegacySnapshot | Should -BeTrue
            [IO.File]::ReadAllText((Join-Path $script:Lb.Root 'Data\Emulators.xml')) | Should -Match 'historical snapshot'
            (Split-Path -Parent $r.BackupPath) | Should -Be $script:LbFallback
            [IO.File]::ReadAllText((Join-Path $ownedSnapshot 'Data\Emulators.xml')) | Should -Match 'historical snapshot'
        }

        It 'refuses a per-user backup folder that would be inside the library' {
            $script:LbLocalBackups = Join-Path $script:Lb.Root 'LocalBackups'
            $before = Get-LbLibraryBytes $script:Lb.Root
            $r = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:LbNestedTp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot')
            $r.Outcome | Should -Be 'FAILED'
            $r.AttemptedPaths.Count | Should -Be 0
            ($r.Errors -join ' ') | Should -Match 'inside the LaunchBox library'
            (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
            Test-Path -LiteralPath $script:LbLocalBackups | Should -BeFalse
        }

        It 'still refuses an explicit backup folder inside the library' {
            $inside = Join-Path $script:Lb.Root 'Backups'
            $before = Get-LbLibraryBytes $script:Lb.Root
            $r = Invoke-LaunchBoxDirectWrite -userProfilesDir $script:Lb.Profiles -tpRoot $script:LbNestedTp -lbRoot $script:Lb.Root -platformNames @('TeknoParrot') -BackupRoot $inside
            $r.Outcome | Should -Be 'FAILED'
            $r.AttemptedPaths.Count | Should -Be 0
            ($r.Errors -join ' ') | Should -Match 'must be outside the library root'
            (Get-LbLibraryBytes $script:Lb.Root) | Should -Be $before
            Test-Path -LiteralPath $inside | Should -BeFalse
            Test-Path -LiteralPath $script:LbLocalBackups | Should -BeFalse
        }
    }
}

# FIX403: a multi-file release ZIP is installed whole (see Fix403.UpdateMultiFile.Tests.ps1), but a package with a file
# name that points outside the program folder is refused before anything is extracted. Uses the full function set loaded
# by this file's BeforeAll because the update transaction depends on many helpers.
Describe 'Invoke-ManagerUpdateInstall multi-file package with an unsafe file name' {
    It 'refuses it before extraction and leaves the target script bytes unchanged' {
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue
        $root = Join-Path $TestDrive ('mf' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        [void][System.IO.Directory]::CreateDirectory($root)
        $script:fix16aMultiFileZip = Join-Path $root 'rel.zip'
        $zip = [System.IO.Compression.ZipFile]::Open($script:fix16aMultiFileZip, [System.IO.Compression.ZipArchiveMode]::Create)
        try {
            $entryTexts = [ordered]@{
                'TeknoParrot-Manager.ps1' = "# TeknoParrot Manager`n`$ScriptVersion = `"0.99.99`"`n"
                'scripts\x.ps1' = "# module`n"
                '..\evil.ps1' = "# not allowed`n"
            }
            foreach ($entryName in $entryTexts.Keys) {
                $writer = New-Object System.IO.StreamWriter($zip.CreateEntry($entryName).Open())
                try { $writer.Write($entryTexts[$entryName]) } finally { $writer.Dispose() }
            }
        } finally {
            $zip.Dispose()
        }

        $targetDir = Join-Path $root 'app'
        [void][System.IO.Directory]::CreateDirectory($targetDir)
        $path = Join-Path $targetDir 'TeknoParrot-Manager.ps1'
        [System.IO.File]::WriteAllText($path, '$ScriptVersion = "0.0.1"')
        $originalBytes = [System.IO.File]::ReadAllBytes($path)

        Mock Invoke-TpmDownload {
            param($DownloadUrl, $DestinationPath, $ExpectedBytes, $Label, $Version)
            Copy-Item -LiteralPath $script:fix16aMultiFileZip -Destination $DestinationPath -Force
            return $true
        }
        Mock Expand-ManagerUpdateAsset { throw 'Expand-ManagerUpdateAsset must not run for a multi-file package.' }
        $release = [pscustomobject]@{
            TagName     = 'v0.99.99'
            Name        = 'v0.99.99 BETA'
            Body        = 'Test release notes.'
            AssetName   = 'TeknoParrot.Manager.v0.99.99.BETA.zip'
            DownloadUrl = 'https://github.com/Jumpstile/teknoparrot-manager/releases/download/v0.99.99/TeknoParrot.Manager.v0.99.99.BETA.zip'
            SizeBytes   = 1
            Digest = ('sha256:' + (Get-FileHash -LiteralPath $script:fix16aMultiFileZip -Algorithm SHA256).Hash)
        }

        $result = Invoke-ManagerUpdateInstall -ScriptPath $path -Release $release

        (Test-TpmTransactionResult -Result $result) | Should -BeTrue
        $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
        $result.ReasonCode | Should -Be 'UPDATE_PACKAGE_BAD_ENTRY'
        $result.Installed | Should -BeFalse
        [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($path)) | Should -Be ([Convert]::ToBase64String($originalBytes))
        Should -Invoke Invoke-TpmDownload -Times 1 -Exactly
        Should -Invoke Expand-ManagerUpdateAsset -Times 0 -Exactly
    }
}

# FIX18A: the ReShade ownership manifest and FFB ownership/evidence writers used a predictable '<file>.tmp'
# (or '.rollback.tmp') written with WriteAllText/WriteAllBytes, which writes through a pre-existing file or link
# at that name (the ASTRA-03 defect class). They now publish through a unique CreateNew temp.
Describe 'ReShade and FFB state writers never write through a predictable temp name' {
    BeforeAll {
        function Get-Fix18aListing([string]$Directory) {
            return (@(Get-ChildItem -LiteralPath $Directory -Force | ForEach-Object { $_.Name } | Sort-Object) -join '|')
        }
    }

    It 'Save-TpmReShadeOwnershipManifest leaves a planted ownership.json.tmp untouched and replaces the manifest' {
        $root = Join-Path $TestDrive ('rsom' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        [void][System.IO.Directory]::CreateDirectory($root)
        $path = Join-Path $root 'ownership.json'
        $planted = $path + '.tmp'
        [System.IO.File]::WriteAllText($planted, 'planted-bytes')
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='First'; Files=@([pscustomobject]@{ DestinationPath='a.fx'; TPMManaged=$true }) }) -Path $path
        Save-TpmReShadeOwnershipManifest -Manifest ([pscustomobject]@{ SchemaVersion=1; EffectId='Second'; Files=@([pscustomobject]@{ DestinationPath='b.fx'; TPMManaged=$true }) }) -Path $path
        (Read-TpmReShadeOwnershipManifest -Path $path).EffectId | Should -Be 'Second'
        [System.IO.File]::ReadAllText($planted) | Should -BeExactly 'planted-bytes'
        Get-Fix18aListing $root | Should -Be 'ownership.json|ownership.json.tmp'
    }

    It 'Write-FFBPluginOwnership leaves a planted ownership .tmp untouched and replaces the manifest' {
        $cache = Join-Path $TestDrive ('ffbo' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        [void][System.IO.Directory]::CreateDirectory($cache)
        $path = Get-FFBPluginOwnershipPath -CacheDir $cache
        $planted = $path + '.tmp'
        [System.IO.File]::WriteAllText($planted, 'planted-bytes')
        Write-FFBPluginOwnership -CacheDir $cache -Entries @([pscustomobject]@{ ProfileCode='First' })
        Write-FFBPluginOwnership -CacheDir $cache -Entries @([pscustomobject]@{ ProfileCode='Second' })
        @((Get-Content -LiteralPath $path -Raw | ConvertFrom-Json).Entries)[0].ProfileCode | Should -Be 'Second'
        [System.IO.File]::ReadAllText($planted) | Should -BeExactly 'planted-bytes'
        Get-Fix18aListing $cache | Should -Be 'TPM-FFB-Plugin-Ownership.json|TPM-FFB-Plugin-Ownership.json.tmp'
    }

    It 'Write-FFBPluginEvidence leaves a planted evidence .tmp untouched on success and on a refused write' {
        $reports = Join-Path $TestDrive ('ffbe' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        [void][System.IO.Directory]::CreateDirectory($reports)
        $evidencePath = Join-Path $reports 'TPM-FFB-Plugin-Evidence.json'
        $planted = $evidencePath + '.tmp'
        [System.IO.File]::WriteAllText($planted, 'planted-bytes')
        Write-FFBPluginEvidence -EvidencePath $evidencePath -Evidence ([ordered]@{ SchemaVersion=1; Phase='Final' })
        (Get-Content -LiteralPath $evidencePath -Raw | ConvertFrom-Json).Phase | Should -Be 'Final'
        $publishedBytes = [System.IO.File]::ReadAllBytes($evidencePath)
        Mock Assert-TpmNoReparseWriteTarget { throw 'simulated unsafe write target' }
        { Write-FFBPluginEvidence -EvidencePath $evidencePath -Evidence ([ordered]@{ SchemaVersion=1; Phase='Refused' }) } | Should -Throw '*simulated unsafe write target*'
        [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($evidencePath)) | Should -Be ([Convert]::ToBase64String($publishedBytes))
        [System.IO.File]::ReadAllText($planted) | Should -BeExactly 'planted-bytes'
        Get-Fix18aListing $reports | Should -Be 'TPM-FFB-Plugin-Evidence.json|TPM-FFB-Plugin-Evidence.json.tmp'
    }

    It 'Restore-FFBPluginOwnershipSnapshot restores exact bytes, leaves a planted .rollback.tmp untouched, and removes only its own temp on failure' {
        $cache = Join-Path $TestDrive ('ffbr' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        [void][System.IO.Directory]::CreateDirectory($cache)
        $path = Get-FFBPluginOwnershipPath -CacheDir $cache
        $planted = $path + '.rollback.tmp'
        [System.IO.File]::WriteAllText($planted, 'planted-bytes')
        [System.IO.File]::WriteAllText($path, 'current-manifest')
        $snapshotBytes = [byte[]](@(0xEF, 0xBB, 0xBF) + [System.Text.Encoding]::ASCII.GetBytes('{"SchemaVersion":1,"Entries":[]}'))
        Restore-FFBPluginOwnershipSnapshot -CacheDir $cache -Snapshot ([pscustomobject]@{ Path=$path; Exists=$true; Bytes=$snapshotBytes })
        [Convert]::ToBase64String([System.IO.File]::ReadAllBytes($path)) | Should -Be ([Convert]::ToBase64String($snapshotBytes))
        [System.IO.File]::ReadAllText($planted) | Should -BeExactly 'planted-bytes'
        Get-Fix18aListing $cache | Should -Be 'TPM-FFB-Plugin-Ownership.json|TPM-FFB-Plugin-Ownership.json.rollback.tmp'

        [System.IO.File]::WriteAllText($path, 'current-manifest')
        Mock Assert-TpmNoReparseWriteTarget { throw 'simulated unsafe write target' }
        { Restore-FFBPluginOwnershipSnapshot -CacheDir $cache -Snapshot ([pscustomobject]@{ Path=$path; Exists=$true; Bytes=$snapshotBytes }) } | Should -Throw '*simulated unsafe write target*'
        [System.IO.File]::ReadAllText($path) | Should -BeExactly 'current-manifest'
        [System.IO.File]::ReadAllText($planted) | Should -BeExactly 'planted-bytes'
        Get-Fix18aListing $cache | Should -Be 'TPM-FFB-Plugin-Ownership.json|TPM-FFB-Plugin-Ownership.json.rollback.tmp'
    }

    It 'Restore-FFBPluginOwnershipSnapshot never removes a pre-existing file that made its CreateNew temp fail' {
        $cache = Join-Path $TestDrive ('ffbc' + [guid]::NewGuid().ToString('N').Substring(0, 8))
        [void][System.IO.Directory]::CreateDirectory($cache)
        $path = Get-FFBPluginOwnershipPath -CacheDir $cache
        [System.IO.File]::WriteAllText($path, 'current-manifest')
        $fixedGuid = '11111111-2222-3333-4444-555555555555'
        $collision = $path + '.' + ([guid]$fixedGuid).ToString('N') + '.rollback.tmp'
        [System.IO.File]::WriteAllText($collision, 'not-owned-by-this-call')
        $snapshot = [pscustomobject]@{ Path=$path; Exists=$true; Bytes=[System.Text.Encoding]::ASCII.GetBytes('snapshot') }
        # Run in a fresh runspace with no enclosing try anywhere: there a failed constructor is not terminating, which is
        # the context in which a cleanup keyed only on "the temp path exists" would delete the colliding file.
        $names = @('Get-FFBPluginOwnershipPath','Test-TpmNoReparsePath','Assert-TpmNoReparseWriteTarget','Restore-FFBPluginOwnershipSnapshot')
        $definitions = @($names | ForEach-Object { "function $_ {`r`n$((Get-Command -Name $_ -CommandType Function).Definition)`r`n}" })
        $childScript = ($definitions -join "`r`n") + "`r`nfunction New-Guid { [guid]'$fixedGuid' }`r`n" + 'Restore-FFBPluginOwnershipSnapshot -CacheDir $args[0] -Snapshot $args[1]'
        $child = [powershell]::Create()
        try {
            [void]$child.AddScript($childScript).AddArgument($cache).AddArgument($snapshot)
            $childError = $null
            try { [void]$child.Invoke() } catch { $childError = $_.Exception }
            $childFailed = ($null -ne $childError) -or $child.HadErrors
        } finally { $child.Dispose() }
        $childFailed | Should -BeTrue
        [System.IO.File]::ReadAllText($collision) | Should -BeExactly 'not-owned-by-this-call'
        [System.IO.File]::ReadAllText($path) | Should -BeExactly 'current-manifest'
        Get-Fix18aListing $cache | Should -Be ('TPM-FFB-Plugin-Ownership.json|' + [System.IO.Path]::GetFileName($collision))
    }
}

# Next version: RPCS3 firmware (the emulator unpacks the player's own firmware file), the Play! game file, and the new menu layout.
# Everything is made up under TestDrive: no real emulator is started (Start-Process is replaced by a small stand-in that writes
# files the way the real one does and "crashes" on close), and nothing is downloaded.
Describe 'Next version: firmware, Play! game file and menu layout' {
    BeforeAll {
        $script:NfProductionSource = [System.IO.File]::ReadAllText((Resolve-Path (Join-Path $PSScriptRoot '..\TeknoParrot-Manager.ps1')).Path)
        $nfAst = [System.Management.Automation.Language.Parser]::ParseInput($script:NfProductionSource, [ref]$null, [ref]$null)
        $nfAssignment = @($nfAst.EndBlock.Statements | Where-Object { $_ -is [System.Management.Automation.Language.AssignmentStatementAst] -and $_.Left.Extent.Text -eq '$EmulatorBiosRequirements' })
        $script:NfPreviousTable = $script:EmulatorBiosRequirements
        $script:EmulatorBiosRequirements = & ([scriptblock]::Create($nfAssignment[0].Right.Extent.Text))
        $script:RawThrillsPathLimits = @{}
        $script:FileVersionPins = @{}
        $script:GpuIncompatibleGames = @{}
        Add-Type -AssemblyName System.IO.Compression
        Add-Type -AssemblyName System.IO.Compression.FileSystem

        $script:NfPupBytes = [System.Text.Encoding]::ASCII.GetBytes('synthetic firmware file, made up for the test ' * 20)
        $script:NfZipName = '[EMU] Sony PlayStation 3 Firmware [TP]'

        function New-NfZip {
            param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][hashtable]$Entries)
            $fs = [System.IO.File]::Create($Path)
            $za = New-Object System.IO.Compression.ZipArchive($fs, [System.IO.Compression.ZipArchiveMode]::Create)
            try {
                foreach ($key in $Entries.Keys) {
                    $stream = $za.CreateEntry([string]$key).Open()
                    try { $bytes = [byte[]]$Entries[$key]; $stream.Write($bytes, 0, $bytes.Length) } finally { $stream.Dispose() }
                }
            } finally { $za.Dispose(); $fs.Dispose() }
        }

        # A DAT with one [EMU] set that lists one file the way the real list does: size and every hash.
        function New-NfDat {
            param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$SetName, [Parameter(Mandatory)][string]$FileName, [Parameter(Mandatory)][byte[]]$Bytes)
            $temp = Join-Path $TestDrive ('nf-hash-' + [guid]::NewGuid().ToString('N') + '.bin')
            [System.IO.File]::WriteAllBytes($temp, $Bytes)
            $rom = '<rom name="{0}" size="{1}" crc="{2}" md5="{3}" sha1="{4}" />' -f $FileName, $Bytes.Length, (Get-Crc32 -Path $temp).ToLowerInvariant(), (Get-FileHash -LiteralPath $temp -Algorithm MD5).Hash.ToLowerInvariant(), (Get-FileHash -LiteralPath $temp -Algorithm SHA1).Hash.ToLowerInvariant()
            Remove-Item -LiteralPath $temp -Force
            [System.IO.File]::WriteAllText($Path, ('<?xml version="1.0"?><datafile><game name="{0}">{1}</game></datafile>' -f $SetName, $rom), (New-Object System.Text.UTF8Encoding $false))
        }

        # A TeknoParrot root with one registered game of the given emulator type and the emulator folder (with a stand-in program).
        function New-NfRoot {
            param([Parameter(Mandatory)][string]$EmulatorType, [Parameter(Mandatory)][string]$Folder, [string]$Program = '', [string]$ExecutableName = '')
            $root = Join-Path $TestDrive ('nf-' + [guid]::NewGuid().ToString('N'))
            $profiles = Join-Path $root 'UserProfiles'
            $emulator = Join-Path $root $Folder
            New-Item -ItemType Directory -Path $profiles, $emulator -Force | Out-Null
            $exeXml = if ($ExecutableName) { '<ExecutableName>' + $ExecutableName + '</ExecutableName>' } else { '' }
            [System.IO.File]::WriteAllText((Join-Path $profiles 'SOMEGAME.xml'), ('<?xml version="1.0" encoding="utf-8"?><GameProfile><EmulatorType>{0}</EmulatorType>{1}<GamePath>C:\Games\game.exe</GamePath></GameProfile>' -f $EmulatorType, $exeXml))
            if ($Program) { [System.IO.File]::WriteAllBytes((Join-Path $emulator $Program), [byte[]]@(77, 90)) }
            return [pscustomobject]@{ Root = $root; Profiles = $profiles; Emulator = $emulator; Flash = (Join-Path $emulator 'dev_flash'); Arcadedefs = (Join-Path $emulator 'arcadedefs') }
        }

        # A collection folder; the DAT file is written only when a DAT set name is given.
        function New-NfCollection {
            param([hashtable]$ZipEntries = $null, [string]$ZipName = '', [string]$LooseName = '', [byte[]]$LooseBytes = $null, [string]$DatSet = '', [string]$DatFile = '', [byte[]]$DatBytes = $null)
            $folder = Join-Path $TestDrive ('nf-coll-' + [guid]::NewGuid().ToString('N'))
            New-Item -ItemType Directory -Path $folder -Force | Out-Null
            if ($ZipName) { New-NfZip -Path (Join-Path $folder ($ZipName + '.zip')) -Entries $ZipEntries }
            if ($LooseName) { [System.IO.File]::WriteAllBytes((Join-Path $folder $LooseName), $LooseBytes) }
            $dat = Join-Path $folder 'Supplementary.dat'
            if ($DatSet) { New-NfDat -Path $dat -SetName $DatSet -FileName $DatFile -Bytes $DatBytes }
            return [pscustomobject]@{ Folder = $folder; Dat = $(if ($DatSet) { $dat } else { '' }) }
        }

        function Get-NfPlan {
            param([Parameter(Mandatory)]$Fixture, [Parameter(Mandatory)]$Collection)
            $warning = @((Get-CompatibilityWarnings -UserProfilesDir $Fixture.Profiles -TeknoParrotRoot $Fixture.Root).BiosMissing)
            $dat = Get-TpmEmuDatRomSets -SupplementaryDatPath $Collection.Dat
            return [pscustomobject]@{ Warning = $warning; Plan = $(if ($warning.Count -gt 0) { Get-TpmPrerequisiteFixPlan -Warning $warning[0] -SearchFolders @($Collection.Folder) -DatRoms $dat -TeknoParrotRoot $Fixture.Root } else { $null }) }
        }

        function Get-NfStagingLeft {
            param([Parameter(Mandatory)]$Fixture)
            return (Test-Path -LiteralPath (Join-Path $Fixture.Root 'TeknoParrotManager\Temp\prerequisite-stage'))
        }
    }

    AfterAll { $script:EmulatorBiosRequirements = $script:NfPreviousTable }

    BeforeEach {
        Mock Write-Log { }
        Mock Write-Host { }
        Mock Write-TpmText { }
        Mock Start-Sleep { }
        $script:nfCall = $null
        $script:nfBehavior = { param($flash) }
        # The stand-in for "rpcs3.exe --headless --installfw <file>": records how it was started, writes files like the real one, and
        # reports a crash exit code, because the real one crashes as it closes.
        Mock Start-Process {
            $pup = [string](@($ArgumentList)[-1]).Trim('"')
            $script:nfCall = [pscustomobject]@{ File = $FilePath; Args = @($ArgumentList); Style = [string]$WindowStyle; PupBytes = $(if (Test-Path -LiteralPath $pup) { [System.IO.File]::ReadAllBytes($pup) } else { $null }) }
            & $script:nfBehavior (Join-Path $WorkingDirectory 'dev_flash')
            return [pscustomobject]@{ HasExited = $true; ExitCode = -1073741819; Id = 0 }
        }
    }

    Context 'RPCS3 firmware' {
        It 'has a table entry, and a game of type RPCS3 is reported as needing firmware' {
            $script:EmulatorBiosRequirements.ContainsKey('RPCS3') | Should -BeTrue
            $script:EmulatorBiosRequirements['RPCS3'].ContainsKey('InstallVia') | Should -BeTrue
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $warning = @((Get-CompatibilityWarnings -UserProfilesDir $fixture.Profiles -TeknoParrotRoot $fixture.Root).BiosMissing)
            $warning.Count | Should -Be 1
            $warning[0].EmulatorType | Should -Be 'RPCS3'
            @($warning[0].MissingFiles) | Should -Be @('liblv2.sprx')
            @($warning[0].AffectedGames) | Should -Be @('SOMEGAME')
            (Get-TpmGameNeedsLine -ProfilePath (Join-Path $fixture.Profiles 'SOMEGAME.xml')) | Should -Match 'PlayStation 3 style arcade firmware \(RPCS3\)'
        }

        It 'finds the firmware file in the player''s archive and accepts it only when the DAT lists the same size and hashes' {
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $collection = New-NfCollection -ZipName $script:NfZipName -ZipEntries @{ 'PS3UPDAT.PUP' = $script:NfPupBytes } -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $script:NfPupBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $found.Plan.AllInstallable | Should -BeTrue
            @($found.Plan.Items)[0].Name | Should -Be 'PS3UPDAT.PUP'
            @($found.Plan.Items)[0].Source | Should -Be 'Archive'
        }

        It 'refuses a firmware file that is not the one the DAT lists (<Case>), changes nothing and starts nothing' -ForEach @(
            @{ Case = 'wrong size'; DatBytes = [byte[]](1..10) }
            @{ Case = 'right size, wrong content'; DatBytes = $null }
        ) {
            $datBytes = if ($null -ne $DatBytes) { $DatBytes } else { [byte[]]@($script:NfPupBytes | ForEach-Object { [byte](($_ + 1) % 256) }) }
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $collection = New-NfCollection -ZipName $script:NfZipName -ZipEntries @{ 'PS3UPDAT.PUP' = $script:NfPupBytes } -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $datBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
            $result.Complete | Should -BeFalse
            @($result.Refused) | Should -Be @('PS3UPDAT.PUP')
            Should -Invoke Start-Process -Times 0 -Exactly
            (Test-Path -LiteralPath $fixture.Flash) | Should -BeFalse
            (Get-NfStagingLeft -Fixture $fixture) | Should -BeFalse
        }

        It 'installs with no window: the emulator gets the checked file, the marker and the file count decide, and the staging folder is gone' {
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $collection = New-NfCollection -ZipName $script:NfZipName -ZipEntries @{ 'PS3UPDAT.PUP' = $script:NfPupBytes } -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $script:NfPupBytes
            $script:nfBehavior = {
                param($flash)
                $external = Join-Path $flash 'sys\external'
                New-Item -ItemType Directory -Path $external -Force | Out-Null
                [System.IO.File]::WriteAllText((Join-Path $external 'liblv2.sprx'), 'x')
                1..600 | ForEach-Object { [System.IO.File]::WriteAllText((Join-Path $flash ('f{0}.bin' -f $_)), 'x') }
            }
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Outcome | Should -Be 'SUCCEEDED'
            $result.Complete | Should -BeTrue
            @($result.Installed) | Should -Be @('PS3UPDAT.PUP')
            $script:nfCall.Args[0] | Should -Be '--headless'
            $script:nfCall.Args[1] | Should -Be '--installfw'
            $script:nfCall.Style | Should -Be 'Hidden'
            $script:nfCall.PupBytes | Should -Be $script:NfPupBytes
            (Test-Path -LiteralPath (Join-Path $fixture.Flash 'sys\external\liblv2.sprx')) | Should -BeTrue
            (Get-NfStagingLeft -Fixture $fixture) | Should -BeFalse
            @((Get-CompatibilityWarnings -UserProfilesDir $fixture.Profiles -TeknoParrotRoot $fixture.Root).BiosMissing).Count | Should -Be 0
        }

        It 'fails when the emulator leaves <Case>, whatever the exit code says; a folder this run created is removed, one that was there is kept' -ForEach @(
            @{ Case = 'no marker file'; Marker = $false; Files = 600; Existed = $false }
            @{ Case = 'too few files'; Marker = $true; Files = 20; Existed = $false }
            @{ Case = 'too few files in a folder that was already there'; Marker = $true; Files = 20; Existed = $true }
        ) {
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $collection = New-NfCollection -ZipName $script:NfZipName -ZipEntries @{ 'PS3UPDAT.PUP' = $script:NfPupBytes } -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $script:NfPupBytes
            if ($Existed) {
                New-Item -ItemType Directory -Path $fixture.Flash -Force | Out-Null
                [System.IO.File]::WriteAllText((Join-Path $fixture.Flash 'mine.txt'), 'the player''s own file')
            }
            $script:nfMarker = $Marker
            $script:nfFiles = $Files
            $script:nfBehavior = {
                param($flash)
                $external = Join-Path $flash 'sys\external'
                New-Item -ItemType Directory -Path $external -Force | Out-Null
                if ($script:nfMarker) { [System.IO.File]::WriteAllText((Join-Path $external 'liblv2.sprx'), 'x') }
                1..$script:nfFiles | ForEach-Object { [System.IO.File]::WriteAllText((Join-Path $flash ('f{0}.bin' -f $_)), 'x') }
            }
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Complete | Should -BeFalse
            $result.Outcome | Should -Be 'FAILED_AFTER_MUTATION'
            $result.ReasonCode | Should -Be 'FIRMWARE_INSTALL_INCOMPLETE'
            if ($Existed) {
                [System.IO.File]::ReadAllText((Join-Path $fixture.Flash 'mine.txt')) | Should -Be 'the player''s own file'
            } else {
                (Test-Path -LiteralPath $fixture.Flash) | Should -BeFalse
            }
            (Get-NfStagingLeft -Fixture $fixture) | Should -BeFalse
        }

        It 'tells the player no window opens, and the prompt says to install what was found' {
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $collection = New-NfCollection -ZipName $script:NfZipName -ZipEntries @{ 'PS3UPDAT.PUP' = $script:NfPupBytes } -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $script:NfPupBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            (Get-TpmPrerequisiteScreenLines -Warning $found.Warning[0] -Plan $found.Plan).Plain -join ' ' | Should -Match 'no window opens'
            $script:nfPrompt = ''
            Mock Read-TpmChoice { $script:nfPrompt = $Prompt; return 'N' }
            [void](Invoke-TpmPrerequisiteReview -Warnings $found.Warning -TpRoot $fixture.Root -SearchFolders @($collection.Folder) -SupplementaryDatPath $collection.Dat -Interactive)
            $script:nfPrompt | Should -Match 'install what was found'
            Should -Invoke Start-Process -Times 0 -Exactly
        }

        It 'when no firmware archive is found, says the archive must be in the player''s own collection' {
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $collection = New-NfCollection -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $script:NfPupBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $found.Plan.AnySource | Should -BeFalse
            $text = (Get-TpmPrerequisiteScreenLines -Warning $found.Warning[0] -Plan $found.Plan).Plain -join ' '
            $text | Should -Match 'PlayStation 3 style hardware'
            $text | Should -Match 'Supplementary or main ZIP folder'
            $text | Should -Not -Match 'put the missing files'
        }

        It 'asks once for the Supplementary folder, saves it, and installs the firmware with one Y; a skipped question names the missing file' {
            # Mutation: no folder question, a second question, the folder not saved, or no "Missing" line in the report -> this fails.
            $script:zipSourceSupplementary = $null
            $script:TpmSupplementaryFolderAsked = $false
            $script:nfScreen = New-Object System.Collections.Generic.List[string]
            Mock Write-TpmText { [void]$script:nfScreen.Add([string]$Text) }
            Mock Save-Config { $true }
            Mock Read-TpmYesNo { throw 'must not ask a second time' }
            $script:nfMarker = $true
            $script:nfFiles = 600
            $script:nfBehavior = {
                param($flash)
                $external = Join-Path $flash 'sys\external'
                New-Item -ItemType Directory -Path $external -Force | Out-Null
                [System.IO.File]::WriteAllText((Join-Path $external 'liblv2.sprx'), 'x')
                1..$script:nfFiles | ForEach-Object { [System.IO.File]::WriteAllText((Join-Path $flash ('f{0}.bin' -f $_)), 'x') }
            }
            # Skipped: nothing found, the missing file is named, nothing is saved, no install is offered.
            $skipFixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $empty = New-NfCollection -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $script:NfPupBytes
            $skipWarning = @((Get-CompatibilityWarnings -UserProfilesDir $skipFixture.Profiles -TeknoParrotRoot $skipFixture.Root).BiosMissing)
            Mock Read-PathWithBrowse { '' }
            $script:nfOffered = $null
            Mock Read-TpmChoice { $script:nfOffered = @($Choices); 'N' }
            [void](Invoke-TpmPrerequisiteReview -Warnings $skipWarning -TpRoot $skipFixture.Root -SupplementaryDatPath $empty.Dat -Interactive)
            $script:nfOffered | Should -Not -Contain 'Y'
            ($script:nfScreen -join "`n") | Should -Match 'Missing: PS3UPDAT\.PUP'
            Should -Invoke Save-Config -Times 0 -Exactly
            # Chosen: the folder is saved, the firmware is installed without a window, and the question is not asked again.
            $script:TpmSupplementaryFolderAsked = $false
            $fixture = New-NfRoot -EmulatorType 'RPCS3' -Folder 'RPCS3' -Program 'rpcs3.exe'
            $collection = New-NfCollection -ZipName $script:NfZipName -ZipEntries @{ 'PS3UPDAT.PUP' = $script:NfPupBytes } -DatSet $script:NfZipName -DatFile 'PS3UPDAT.PUP' -DatBytes $script:NfPupBytes
            $warning = @((Get-CompatibilityWarnings -UserProfilesDir $fixture.Profiles -TeknoParrotRoot $fixture.Root).BiosMissing)
            Mock Read-PathWithBrowse { $collection.Folder }
            Mock Read-TpmChoice { 'Y' }
            $review = Invoke-TpmPrerequisiteReview -Warnings $warning -TpRoot $fixture.Root -SupplementaryDatPath $collection.Dat -Interactive
            $review.FixedAny | Should -BeTrue
            $script:zipSourceSupplementary | Should -Be $collection.Folder
            Should -Invoke Save-Config -Times 1 -Exactly
            $script:nfCall.Args | Should -Contain '--headless'
            $script:nfCall.Args | Should -Contain '--installfw'
            $script:nfCall.PupBytes | Should -Be $script:NfPupBytes
            ($script:nfScreen -join "`n") | Should -Match 'Installed: PS3UPDAT\.PUP'
            Remove-Item -LiteralPath $fixture.Flash -Recurse -Force
            [void](Invoke-TpmPrerequisiteReview -Warnings @((Get-CompatibilityWarnings -UserProfilesDir $fixture.Profiles -TeknoParrotRoot $fixture.Root).BiosMissing) -TpRoot $fixture.Root -SearchFolders @($script:zipSourceSupplementary) -SupplementaryDatPath $collection.Dat -Interactive)
            # One call for the skipped run, one for the chosen run; the third review asks nothing because the folder is saved.
            Should -Invoke Read-PathWithBrowse -Times 2 -Exactly
        }
    }

    Context 'Play! game file' {
        BeforeAll {
            $script:NfPlaySet = '[EMU] Play! working arcadedefs for Namco System 246 [TP]'
            $script:NfPlayBytes = [System.Text.Encoding]::ASCII.GetBytes('synthetic play arcadedef settings, made up for the test')
            # The player's arcadedefs archive (holding the given file) and a DAT that lists the given file with the given bytes.
            function New-NfPlayCollection {
                param([string]$InArchive = 'akaievo.arcadedef', [byte[]]$ArchiveBytes = $null, [string]$InDat = 'akaievo.arcadedef', [byte[]]$DatBytes = $null)
                $zipName = if ($null -ne $ArchiveBytes) { $script:NfPlaySet } else { '' }
                $entries = if ($null -ne $ArchiveBytes) { @{ ('Play/arcadedefs/' + $InArchive) = $ArchiveBytes } } else { $null }
                $datSet = if ($null -ne $DatBytes) { $script:NfPlaySet } else { '' }
                return (New-NfCollection -ZipName $zipName -ZipEntries $entries -DatSet $datSet -DatFile ('Play/arcadedefs/' + $InDat) -DatBytes $DatBytes)
            }
        }

        It 'copies the game''s arcadedef from the player''s archive into arcadedefs, after the DAT check' {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName 'akaievo.zip'
            $collection = New-NfPlayCollection -ArchiveBytes $script:NfPlayBytes -DatBytes $script:NfPlayBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $found.Warning.Count | Should -Be 1
            @($found.Warning[0].MissingFiles) | Should -Be @('akaievo.arcadedef')
            $found.Warning[0].ExpectedDir | Should -Be $fixture.Arcadedefs
            $found.Plan.AllInstallable | Should -BeTrue
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Outcome | Should -Be 'SUCCEEDED'
            $result.Complete | Should -BeTrue
            [System.IO.File]::ReadAllBytes((Join-Path $fixture.Arcadedefs 'akaievo.arcadedef')) | Should -Be $script:NfPlayBytes
            (Get-NfStagingLeft -Fixture $fixture) | Should -BeFalse
            @((Get-CompatibilityWarnings -UserProfilesDir $fixture.Profiles -TeknoParrotRoot $fixture.Root).BiosMissing).Count | Should -Be 0
        }

        It 'reports nothing when the arcadedef is already there, and when the profile names no plain zip (<Case>)' -ForEach @(
            @{ Case = 'already there'; Name = 'akaievo.zip'; Present = $true }
            @{ Case = 'not a zip'; Name = 'game.exe'; Present = $false }
            @{ Case = 'a path, not a file name'; Name = '..\outside.zip'; Present = $false }
            @{ Case = 'two alternatives'; Name = 'a.zip;b.zip'; Present = $false }
        ) {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName $Name
            if ($Present) {
                New-Item -ItemType Directory -Path $fixture.Arcadedefs -Force | Out-Null
                [System.IO.File]::WriteAllBytes((Join-Path $fixture.Arcadedefs 'akaievo.arcadedef'), $script:NfPlayBytes)
            }
            @((Get-CompatibilityWarnings -UserProfilesDir $fixture.Profiles -TeknoParrotRoot $fixture.Root).BiosMissing).Count | Should -Be 0
        }

        It 'says so in plain words and copies nothing when the archive does not hold the file' {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName 'akaievo.zip'
            $collection = New-NfPlayCollection -InArchive 'other.arcadedef' -ArchiveBytes $script:NfPlayBytes -DatBytes $script:NfPlayBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $found.Plan.AnySource | Should -BeFalse
            $found.Plan.AllInstallable | Should -BeFalse
            $text = (Get-TpmPrerequisiteScreenLines -Warning $found.Warning[0] -Plan $found.Plan).Plain -join ' '
            $text | Should -Match 'did not find the file akaievo\.arcadedef in your game collection'
            $text | Should -Not -Match '\.zip'
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Complete | Should -BeFalse
            (Test-Path -LiteralPath (Join-Path $fixture.Arcadedefs 'akaievo.arcadedef')) | Should -BeFalse
        }

        It 'lists only the Play! games whose own file is missing' {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName 'akaievo.zip'
            [System.IO.File]::WriteAllText((Join-Path $fixture.Profiles 'FINEGAME.xml'), '<?xml version="1.0" encoding="utf-8"?><GameProfile><EmulatorType>Play</EmulatorType><ExecutableName>fine.zip</ExecutableName><GamePath>C:\Games\game.exe</GamePath></GameProfile>')
            New-Item -ItemType Directory -Path $fixture.Arcadedefs -Force | Out-Null
            [System.IO.File]::WriteAllBytes((Join-Path $fixture.Arcadedefs 'fine.arcadedef'), $script:NfPlayBytes)
            $result = Get-CompatibilityWarnings -UserProfilesDir $fixture.Profiles -TeknoParrotRoot $fixture.Root
            @($result.BiosMissing).Count | Should -Be 1
            @($result.BiosMissing[0].AffectedGames) | Should -Be @('SOMEGAME')
            $screen = Get-TpmPrerequisiteScreenLines -Warning $result.BiosMissing[0]
            ($screen.Plain -join ' ') | Should -Match 'this game will not start: SOMEGAME\.'
            ($screen.Plain -join ' ') | Should -Not -Match 'FINEGAME'
        }

        It 'refuses an arcadedef that is not the file the DAT lists' {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName 'akaievo.zip'
            $collection = New-NfPlayCollection -ArchiveBytes ([System.Text.Encoding]::ASCII.GetBytes('some other file with the same name')) -DatBytes $script:NfPlayBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Outcome | Should -Be 'FAILED_BEFORE_MUTATION'
            @($result.Refused) | Should -Be @('akaievo.arcadedef')
            (Test-Path -LiteralPath (Join-Path $fixture.Arcadedefs 'akaievo.arcadedef')) | Should -BeFalse
            (Get-NfStagingLeft -Fixture $fixture) | Should -BeFalse
        }

        It 'does not copy an arcadedef the DAT does not list' {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName 'akaievo.zip'
            $collection = New-NfPlayCollection -ArchiveBytes $script:NfPlayBytes -InDat 'other.arcadedef' -DatBytes $script:NfPlayBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $found.Plan.AnySource | Should -BeTrue
            $found.Plan.AllInstallable | Should -BeFalse
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Complete | Should -BeFalse
            (Test-Path -LiteralPath (Join-Path $fixture.Arcadedefs 'akaievo.arcadedef')) | Should -BeFalse
        }

        It 'never copies the game zip, even when it sits in the collection' {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName 'akaievo.zip'
            $collection = New-NfCollection -LooseName 'akaievo.zip' -LooseBytes $script:NfPlayBytes -DatSet '[EMU] Play! working arcadedefs for Namco System 246 [TP]' -DatFile 'Play/arcadedefs/akaievo.zip' -DatBytes $script:NfPlayBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $found.Plan.AnySource | Should -BeFalse
            $result = Invoke-TpmPrerequisiteInstall -Plan $found.Plan -TpRoot $fixture.Root
            $result.Complete | Should -BeFalse
            (Test-Path -LiteralPath (Join-Path $fixture.Arcadedefs 'akaievo.zip')) | Should -BeFalse
            (Test-Path -LiteralPath (Join-Path $fixture.Arcadedefs 'akaievo.arcadedef')) | Should -BeFalse
        }

        It 'uses the same screens: the player answers Y and sees the Done line' {
            $fixture = New-NfRoot -EmulatorType 'Play' -Folder 'Play' -ExecutableName 'akaievo.zip'
            $collection = New-NfPlayCollection -ArchiveBytes $script:NfPlayBytes -DatBytes $script:NfPlayBytes
            $found = Get-NfPlan -Fixture $fixture -Collection $collection
            $script:nfHost = New-Object System.Collections.Generic.List[string]
            Mock Write-Host { [void]$script:nfHost.Add([string]$Object) }
            Mock Read-TpmChoice { 'Y' }
            $review = Invoke-TpmPrerequisiteReview -Warnings $found.Warning -TpRoot $fixture.Root -SearchFolders @($collection.Folder) -SupplementaryDatPath $collection.Dat -Interactive
            $review.FixedAny | Should -BeTrue
            ($script:nfHost -join "`n") | Should -Match 'Done\. 1 file was copied and checked'
            (Test-Path -LiteralPath (Join-Path $fixture.Arcadedefs 'akaievo.arcadedef')) | Should -BeTrue
        }
    }

    Context 'Main menu layout' {
        It 'shows PostgreSQL setup as 12 and Required game patches as 13 under Game Requirements, and 14 and 15 under Maintenance and Recovery' {
            $sections = @(Get-MainMenuSections)
            $requirements = @($sections | Where-Object { $_.Header -like 'Game Requirements*' })
            $requirements.Count | Should -Be 1
            @($requirements[0].Items | ForEach-Object { '{0}={1}' -f $_.Number, $_.Mode }) | Should -Be @('12=PostgresSetup', '13=RequiredPatch')
            $maintenance = @($sections | Where-Object { $_.Header -like 'Maintenance and Recovery*' })
            $maintenance.Count | Should -Be 1
            @($maintenance[0].Items | ForEach-Object { '{0}={1}' -f $_.Number, $_.Mode }) | Should -Be @('14=HealthCheck', '15=Restore')
            # What the player sees, top to bottom, on a small console: the header, then the numbered lines.
            $geometry = Get-MainMenuGeometry -Tier 'Compact' -ViewportWidth 100 -ViewportHeight 80
            $shown = @(Get-MainMenuBodyRows -Sections $sections -Geometry $geometry | ForEach-Object { $_.Text.Trim() } | Where-Object { $_ })
            $headerAt = [array]::FindIndex($shown, [Predicate[string]]{ param($t) $t -like 'GAME REQUIREMENTS*' })
            $headerAt | Should -BeGreaterOrEqual 0
            $shown[$headerAt + 1] | Should -Be '12) Postgres setup'
            $shown[$headerAt + 2] | Should -Be '13) Required game patches'
            $shown[$headerAt + 3] | Should -BeLike 'MAINTENANCE AND RECOVERY*'
            $shown[$headerAt + 4] | Should -Be '14) Library health check'
            $shown[$headerAt + 5] | Should -Be '15) Restore backup'
        }
    }
}
